#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

struct Node {
    LogEntry entry;
    struct Node* next;
};

void initLinkedList(struct Node** head, FILE* file) {
    *head = NULL;
}

LogEntry* createLogEntry(time_t timestamp, int logLevel, const char* message) {
    LogEntry* newEntry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!newEntry) {
        return NULL;
    }
    newEntry->timestamp = timestamp;
    newEntry->logLevel = logLevel;
    newEntry->message = strdup(message);
    if (!newEntry->message) {
        free(newEntry);
        return NULL;
    }
    return newEntry;
}

void printLinkedList(struct Node* head, FILE* file) {
    while (head) {
        fprintf(file, "%ld %d: %s\n", head->entry.timestamp, head->entry.logLevel, head->entry.message);
        head = head->next;
    }
}

void freeLinkedList(struct Node** head) {
    struct Node* current = *head;
    struct Node* next;
    while (current) {
        next = current->next;
        if (current->entry.message) {
            free(current->entry.message);
        }
        free(current);
        current = next;
    }
    *head = NULL;
}

void destroyLinkedList(struct Node** head, FILE* file) {
    printLinkedList(*head, file);
    freeLinkedList(head);
}
