typedef struct {
    int key;
    long offset;
} record;

record* create_records(int max_size) {
    int num_records = 0;
    record *records = NULL, *new_records = NULL;
    long *offsets = NULL, *new_offsets = NULL;
    int *keys = NULL, *new_keys = NULL;
    int threshold = 100;
    int min_key = 1, max_key = 10;

    srand(time(NULL));

    while (num_records < max_size) {
        if ((records = realloc(records, sizeof(record) * ++num_records)) == NULL || 
            (offsets = realloc(offsets, sizeof(long) * num_records)) == NULL || 
            (keys = realloc(keys, sizeof(int) * num_records)) == NULL) {
            for (int i = 0; i < num_records; i++) {
                free(&records[i]);
            }
            free(records);
            free(offsets);
            free(keys);
            return NULL;
        }

        records[num_records - 1].key = rand() % (max_key - min_key + 1) + min_key;
        offsets[num_records - 1] = num_records * 1000L;

        if ((new_offsets = realloc(new_offsets, sizeof(long) * ++num_records)) == NULL || 
            (new_keys = realloc(new_keys, sizeof(int) * num_records)) == NULL) {
            for (int i = 0; i < num_records - 1; i++) {
                free(&records[i]);
            }
            free(records);
            free(offsets);
            free(keys);
            return NULL;
        }

        offsets[num_records - 1] = new_offsets[num_records - 2];
        new_offsets[num_records - 2] = num_records * 1000L;
    }

    int total_key = 0;

    for (int i = 0; i < num_records; i++) {
        total_key += records[i].key;
    }

    if (total_key > threshold) {
        while (total_key > threshold) {
            if ((new_records = realloc(new_records, sizeof(record) * ++num_records)) == NULL || 
                (new_offsets = realloc(new_offsets, sizeof(long) * num_records)) == NULL || 
                (new_keys = realloc(new_keys, sizeof(int) * num_records)) == NULL) {
                for (int i = 0; i < num_records - 1; i++) {
                    free(&records[i]);
                }
                free(records);
                free(offsets);
                free(keys);
                return NULL;
            }

            records[num_records - 2].key += rand() % (max_key - min_key + 1) + min_key;
            total_key = 0;

            for (int i = 0; i < num_records; i++) {
                total_key += records[i].key;
            }
        }
    }

    return records;
