#include <stdio.h>
#include <stdlib.h>

int find_max(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

void read_and_print_max() {
    int n;
    printf("Enter the number of integers (max 1000): ");
    scanf("%d", &n);

    if (n < 1 || n > 1000) {
        printf("Invalid input. Please enter a value between 1 and 1000.\n");
        return;
    }

    int* arr = (int*)malloc(n * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < n; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &arr[i]);

        // Check for invalid input
        if (!scanf("%*s") && feof(stdin)) {
            free(arr);
            printf("Invalid input format. Program terminated.\n");
            return;
        }
    }

    int max = find_max(arr, n);
    printf("The largest integer is: %d\n", max);

    free(arr);
}

int main() {
    read_and_print_max();
    return 0;
}
