typedef struct {
    int size;
    char* entries[MAX_LOG_ENTRIES];
} LogBuffer;

LogBuffer* log_buffer = NULL;
int log_entry_index = 0;

void conditionalLog(const char* condition, ...) {
    if (log_buffer == NULL) {
        pthread_mutex_lock(&mutex);
        if (log_buffer == NULL) {
            log_buffer = malloc(sizeof(LogBuffer));
            log_buffer->size = 0;
            for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
                log_buffer->entries[i] = NULL;
            }
        }
        pthread_mutex_unlock(&mutex);
    }

    if (!strcmp(condition, "true")) {
        va_list args;
        char buffer[LOG_ENTRY_SIZE];

        vsnprintf(buffer, LOG_ENTRY_SIZE - 1, buffer, condition);

        if (log_buffer->size < MAX_LOG_ENTRIES) {
            log_buffer->entries[log_entry_index] = strdup(buffer);
            log_buffer->size++;
            log_entry_index = (log_entry_index + 1) % MAX_LOG_ENTRIES;
        } else {
            for (int i = 0; i < MAX_LOG_entries - 1; i++) {
                free(log_buffer->entries[i]);
            }
            log_buffer->size = 1;
            log_entry_index = 0;
            log_buffer->entries[log_entry_index] = strdup(buffer);
        }

        va_end(args);
    }
}
