    cache->items = (CacheItem**)malloc((capacity+1)*sizeof(CacheItem*));
    return cache;
}

void cache_add(Cache *cache, void *key, void *value) {
    pthread_mutex_lock(&cache->lock);
    CacheItem *item = (CacheItem*)malloc(sizeof(CacheItem));
    item->key = key;
    item->value = value;
    int i;
    for(i=0; i<=cache->size; i++) {
        if(cache->items[i] == NULL) {
            cache->items[i] = item;
            break;
        }
    }
    if(i==cache->size) {
        CacheItem **new_items = (CacheItem**)malloc((cache->size+1)*sizeof(CacheItem*));
        memcpy(new_items, cache->items, cache->size*sizeof(CacheItem*));
        free(cache->items);
        cache->items = new_items;
    }
    pthread_mutex_unlock(&cache->lock);
}

void* cache_get(Cache *cache, void *key) {
    pthread_mutex_lock(&cache->lock);
    int i;
    for(i=0; i<cache->size; i++) {
        if(cache->items[i]->key == key) {
            void *value = cache->items[i]->value;
            pthread_mutex_unlock(&cache->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void cache_evict(Cache *cache) {
    pthread_mutex_lock(&cache->lock);
    CacheItem **new_items = (CacheItem**)malloc((cache->size-1)*sizeof(CacheItem*));
    int i, j;
    for(i=0, j=0; i<cache->size; i++) {
        if(cache->items[i] != NULL) {
            new_items[j++] = cache->items[i];
        }
    }
    free(cache->items);
    cache->items = new_items;
    cache->size--;
    pthread_mutex_unlock(&cache->lock);
}

void cache_destroy(Cache *cache) {
    pthread_mutex_lock(&cache->lock);
    int i;
    for(i=0; i<cache->size; i++) {
        free(cache->items[i]);
    }
    free(cache->items);
    pthread_mutex_unlock(&cache->lock);
}
