    auto on_request = [&client, &interface_table](const boost::beast::http::request<boost::beast::http::string_body>& req) {
        try {
            // Send a GET request to the server
            client.send(req);

            // Verify response matches expected values within a specified tolerance range
            boost::beast::http::response(boost::beast::http::status::ok, "OK") == req.result();
        } catch (const std::exception& e) {
            // Handle timeouts gracefully and log the error
            std::cerr << "Error: " << e.what() << std::endl;
        }
    };

    // Set up a backoff strategy for failed requests
    auto on_failure = [&client](boost::beast::error_code ec) {
        // Implement a dynamic adjustment mechanism to adjust the backoff interval based on the frequency of timeout events
        if (ec == boost::beast::errc::connection_refused) {
            // Adjust the backoff interval for connection timeouts
            client.backoff_interval *= 2;
        } else {
            // Reset the backoff interval for other types of failures
            client.backoff_interval = 1000;
        }
    };

    // Set up a configurable number of concurrent requests
    size_t concurrency = 5;

    // Send a series of GET requests to the server under varying network conditions
    for (int i = 0; i < 10; ++i) {
        auto req = boost::beast::http::request<boost::beast::http::string_body>("GET", "/api/v1/data");
        req.version(11);
        req.set(boost::beast::http::field::host, "localhost:8080");
        ctx.post([on_request, &req]() {
            on_request(req);
        });

        // Manage a configurable number of concurrent requests
        if (concurrency > 0) {
            --concurrency;
        }
    }

    // Print out the total number of requests sent, successful responses, proxy sessions established, internal errors, and a summary of request timeouts
    std::cout << "Total requests: " << client.get_total_requests() << std::endl;
    std::cout << "Successful responses: " << client.get_successful_responses() << std::endl;
