namespace Logging {

    class Logger {
    public:
        enum LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

        static std::shared_ptr<Logger> instance;

        Logger() : core_(boost::log::add_common_attributes()) {
            if (!instance) {
                instance.reset(this);
            }
        }

        ~Logger() {
            for (auto& file_log_sink : file_log_sinks_) {
                boost::log::core::get()->remove_sink(file_log_sink);
            }
            for (auto& console_log_sink : console_log_sinks_) {
                boost::log::core::get()->remove_sink(console_log_sink);
            }
        }

        static void set_output_level(LogLevel level) {
            output_level_ = level;
        }

        template<typename... Args>
        void log(LogLevel level, const char* message, Args&&... args) {
            if (level <= output_level_) {
                switch (level) {
                    case DEBUG:
                        BOOST_LOG_SEV(core_, boost::log::trivial::debug) << message << " " << std::forward<Args>(args)...;
                        break;
                    case INFO:
                        BOOST_LOG_SEV(core_, boost::log::trivial::info) << message << " " << std::forward<Args>(args)...;
                        break;
                    case WARN:
                        BOOST_LOG_SEV(core_, boost::log::trivial::warning) << message << " " << std::forward<Args>(args)...;
                        break;
                    case ERROR:
                        BOOST_LOG_SEV(core_, boost::log::trivial::error) << message << " " << std::forward<Args>(args)...;
                        break;
                    case FATAL:
                        BOOST_LOG_SEV(core_, boost::log::trivial::fatal) << message << " " << std::forward<Args>(args)...;
                        break;
                }
            }
        }

    private:
        static Logger* instance_;
        boost::log::core:: Ptr core_;
        LogLevel output_level_ = INFO;

        std::vector<boost::shared_ptr<boost::log::sinks::file_sink>> file_log_sinks_;
        std::vector<boost::shared_ptr<boost::log::sinks::text_file_backend>> console_log_sinks_;

        void set_logging_config() {
            if (output_level_ == FATAL) {
                // Set logging configuration for fatal level
            } else if (output_level_ == ERROR) {
                // Set logging configuration for error level
            } else if (output_level_ == WARN) {
                // Set logging configuration for warn level
            } else if (output_level_ == INFO) {
                // Set logging configuration for info level
            } else {
                // Set logging configuration for debug level
            }
        }

        void set_file_log_sink() {
            boost::log::add_common_attributes();
            auto file_sink = boost::make_shared<boost::log::sinks::file_sink>("log.txt");
            file_sink->set_pattern("%d %F %t [%P] [%l] %m");
            core_->add_sink(file_sink);
            file_log_sinks_.push_back(file_sink);
        }

        void set_console_log_sink() {
            boost::log::add_common_attributes();
            auto console_sink = boost::make_shared<boost::log::sinks::text_file_backend>();
            console_sink->set_pattern("%d %F %t [%P] [%l] %m");
            core_->add_sink(console_sink);
            console_log_sinks_.push_back(console_sink);
        }
    };

    std::shared_ptr<Logger::LogLevel> Logger::instance_ = nullptr;

} // namespace Logging']

