public async Task<TransformSummary> ProcessTransformationsAsync(List<InputData> inputData, SqlConnection connection, params Func/InputData, TransformFunction>[] transformations)
{
    var successfulTransforms = new List<InputData>();
    var failedTransforms = new List<InputData>();

    await foreach (var input in inputData.AsParallel().SelectAwaitable(transform => transformAsync(transform, connection, transformations)))
    {
        if (input == null)
            failedTransforms.Add(input);
        else
            successfulTransforms.Add(input);
    }

    return new TransformSummary(successfulTransforms.Count, failedTransforms.Count);

    async Task<InputData?> transformAsync(InputData input, SqlConnection connection, params Func<InputData, InputData, Task>[] transformations)
    {
        foreach (var transformation in transformations)
        {
            try
            {
                input = await transformation(input);
                if (input != null) // optional database write
                    await connection.ExecuteAsync("INSERT INTO intermediate_results VALUES (@Id, @Value)", new { Id = input.Id, Value = input.Value });
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Transformation failed: {ex.Message}");
                return null;
            }
        }

        return input;
    }
}

public class TransformSummary
{
    public int SuccessfulTransforms { get; set; }
    public int FailedTransforms { get; set; }

    public TransformSummary(int successful, int failed)
    {
        SuccessfulTransforms = successful;
        FailedTransforms = failed;
    }
}
