    public class ConfigurationLoader
    {
        private const string SettingsFile = "game_settings.config";
        private Dictionary<string, object> _settings;

        public void LoadSettings()
        {
            _settings = new Dictionary<string, object>();

            if (!File.Exists(SettingsFile))
                return; // no file found, use default settings

            try
            {
                XmlDocument doc = new XmlDocument();
                doc.Load(SettingsFile);

                foreach (XmlNode node in doc.SelectNodes("//setting"))
                {
                    string key = node["key"].InnerText;
                    int value = Convert.ToInt32(node["value"].InnerText);
                    _settings.Add(key, value);
                }
            }
            catch (Exception ex)
            {
                // log error and use default settings
                Console.WriteLine("Error loading settings: " + ex.Message);
            }
        }

        public int GetPlayerHealthPoints()
        {
            return (int)_settings["player_health_points"];
        }

        public int GetMaxLives()
        {
            return (int)_settings["max_lives"];
        }

        public DifficultyLevel GetDifficultyLevel()
        {
            string level = _settings["difficulty_level"].ToString();
            switch (level)
            {
                case "easy": return DifficultyLevel.Easy;
                case "medium": return DifficultyLevel.Medium;
                case "hard": return DifficultyLevel.Hard;
                default: throw new Exception("Invalid difficulty level");
            }
        }

        public void UpdateDifficultyLevel(DifficultyLevel level)
        {
            _settings["difficulty_level"] = level.ToString();
        }
    }

    public enum DifficultyLevel
    {
        Easy,
        Medium,
        Hard
    }
}
