using System;
using System.IO;
using System.Xml;
using System.Linq;

public class XPathParser
{
    public static Tuple<List<XmlElement>, List<string>> ParseXml(string xmlFile, string xpathQuery, string attributeName, int? defaultAttributeValue)
    {
        List<XmlElement> result = new List<XmlElement>();
        List<string> attributeValues = new List<string>();

        using (FileStream stream = File.OpenRead(xmlFile))
        {
            XmlTextReader reader = new XmlTextReader(stream);
            reader.WhitespaceHandling = WhitespaceHandling.None;

            while (reader.Read())
            {
                if (reader.NodeType == XmlNodeType.Element && reader.Name == xpathQuery)
                {
                    string attributeValue = null;
                    foreach (XmlAttribute attribute in reader.Attributes)
                    {
                        if (attribute.Name == attributeName)
                        {
                            attributeValue = attribute.Value;
                            break;
                        }
                    }

                    if (defaultAttributeValue.HasValue && (attributeValue == null || !attributeValue.Equals(defaultAttributeValue.ToString(), StringComparison.OrdinalIgnoreCase)))
                    {
                        continue;
                    }

                    result.Add((XmlElement)reader);
                }
            }
        }

        return new Tuple<List<XmlElement>, List<string>>(result, attributeValues);
    }
}
