import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ForkJoinPool;

public class MD5BatchProcessor {

    private static final int MAX_BATCH_SIZE = 1000;
    private static final long MEMORY_THRESHOLD_IN_MEGABYTES = 50;

    public String[] processMD5Hashes(String[] inputStrings, boolean useSHA256) throws Exception {
        ExecutorService executor = ForkJoinPool.commonPool();
        MessageDigest messageDigest = getMessageDigest(useSHA256);

        String[][] batches = splitIntoBatches(inputStrings);
        String[] result = new String[inputStrings.length];

        for (int i = 0; i < batches.length; i++) {
            int batchStartIndex = i * MAX_BATCH_SIZE;
            int batchSize = Math.min(MAX_BATCH_SIZE, inputStrings.length - batchStartIndex);

            byte[][] hashValues = executor.invokeAll(
                    generateHashTasks(messageDigest, batches[i], batchSize)
            ).stream()
                    .map(task -> task.join().getResult())
                    .toArray(byte[][]::new);

            for (int j = 0; j < batchSize; j++) {
                result[batchStartIndex + j] = bytesToHex(hashValues[j]);
            }
        }

        return result;
    }

    private MessageDigest getMessageDigest(boolean useSHA256) throws NoSuchAlgorithmException {
        if (useSHA256) {
            return MessageDigest.getInstance("SHA-256");
        } else {
            return MessageDigest.getInstance("MD5");
        }
    }

    private String[][] splitIntoBatches(String[] inputStrings) {
        int batchSize = MAX_BATCH_SIZE;
        int numBatches = (int) Math.ceil(inputStrings.length / (double) batchSize);
        String[][] batches = new String[numBatches][];

        for (int i = 0; i < numBatches; i++) {
            int batchStartIndex = i * batchSize;
            int batchSizeInThisBatch = Math.min(batchSize, inputStrings.length - batchStartIndex);

            batches[i] = new String[batchSizeInThisBatch];
            System.arraycopy(inputStrings, batchStartIndex, batches[i], 0, batchSizeInThisBatch);
        }

        return batches;
    }

    private Iterable<Callable<Object>> generateHashTasks(MessageDigest messageDigest, String[] batch, int batchSize) {
        return IntStream.range(0, batchSize)
                .mapToObj(i -> () -> processString(messageDigest, batch[i]))
                .collect(Collectors.toList());
    }

    private Object processString(MessageDigest messageDigest, String inputString) throws Exception {
        byte[] hashValue = messageDigest.digest(inputString.getBytes("UTF-8"));
        return hashValue;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder builder = new StringBuilder();
        for (byte b : bytes) {
            builder.append(String.format("%02x", b));
        }
        return builder.toString();
    }
}
