import java.io.*;
import java.util.logging.*;

public class StateLoader {

    private static final Logger logger = Logger.getLogger(StateLoader.class.getName());

    public MoSTState loadState(String filePath) {
        if (!isValidFilePath(filePath)) {
            return null;
        }

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            Object obj = ois.readObject();
            ois.close();

            if (!(obj instanceof MoSTState)) {
                return null;
            }

            MoSTState state = (MoSTState) obj;

            // Check timestamp
            if (state.getTimestamp() < System.currentTimeMillis() / 1000 - 3600) { // 1 hour old
                logger.warning("Loaded outdated object");
                return null;
            }

            return state;
        } catch (IOException | ClassNotFoundException e) {
            logger.severe("Failed to load state: " + filePath);
            return null;
        }
    }

