                options.Password.RequireLowercase = true;
                options.Password.RequireNonAlphanumeric = false;
                options.Password.RequireUppercase = true;
                options.Password.RequiredLength = 6;
                options.Lockout.DefaultAction = LockoutActions.Fail;
                options.Lockout.MaxAttempts = 5;
                options.Lockout.NormalAuthMaxAge = TimeSpan.FromMinutes(30);
            });

            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = "Local";
                options.DefaultChallengeScheme = "Local";
