const fs = require('fs').promises;
const path = require('path');
const loggingSystem = require('./loggingSystem');

function readFileSync(filePath, options) {
  const { logLevel, defaultDirs, allowedFileTypes } = options;

  async function getFilePath(filePath) {
    if (!filePath.includes('/')) return filePath;
    for (let dir of defaultDirs) {
      if (path.isAbsolute(filePath)) continue;
      filePath = path.join(dir, filePath);
      break;
    }
    return filePath;
  }

  async function validateFileExistenceAndType(filePath) {
    try {
      const stats = await fs.stat(filePath);
      if (!stats.isFile()) throw new Error('Not a file');
      if (!allowedFileTypes.includes(path.extname(filePath).toLowerCase())) 
        throw new Error(`Invalid file type: ${path.extname(filePath)}`);
    } catch (error) {
      loggingSystem.log(logLevel, `Error validating file existence and type: ${error.message}`);
      return null;
    }
    return filePath;
  }

  async function readAndLogFileContent(filePath) {
    try {
      const content = await fs.readFile(filePath);
      loggingSystem.log(logLevel, `Read file content: ${filePath}`);
      return content.toString();
    } catch (error) {
      loggingSystem.log(logLevel, `Error reading file content: ${error.message}`);
      return null;
    }
  }

  async function readAndValidateFile(filePath, options) {
    filePath = await getFilePath(filePath);
    const validatedFilePath = await validateFileExistenceAndType(filePath);
    if (!validatedFilePath) return null;
    try {
      const fileContent = await readAndLogFileContent(validatedFilePath);
      return fileContent;
    } catch (error) {
      loggingSystem.log(logLevel, `Error reading and validating file: ${error.message}`);
      return null;
    }
  }

  exports.readAndValidateFile = readAndValidateFile;
}

module.exports = readFileSync;
