async function runModuleTests(moduleName, testCases, mockResetInterval) {
  try {
    // Dynamically load the module
    const module = await import(`./${moduleName}.js`);

    for (const testCase of testCases) {
      console.log(`Running test: ${testCase.name} for module ${moduleName}`);
      let retries = 0;

      async function runTest() {
        while (true) {
          try {
            // Run the test
            await testCase.function(module);

            // Test passed, reset mocking library and log success
            setTimeout(() => blueslip.reset(), mockResetInterval);
            console.log(`Test ${testCase.name} for module ${moduleName} passed`);
            return;
          } catch (error) {
            if (retries >= 3) {
              // Maximum retries exceeded, report failure and log stack trace
              console.error(`Test ${testCase.name} for module ${moduleName} failed after ${retries} retries`);
              console.error(error.stack);
              return;
            }

            // Test failed, retry with a delay to avoid overwhelming the network
            await new Promise(resolve => setTimeout(() => resolve(), 500));
            retries++;
          }
        }
      }

      // Run the test and wait for it to complete
      await runTest();
    }
  } catch (error) {
    // Handle errors gracefully, providing meaningful error messages
    console.error(`Error running tests for module ${moduleName}: ${error.message}`);
    console.error(error.stack);
  }
}
