const bibleBooks = require('./bible-books.json');
const api = require('./bible-api');

function analyzeBiblicalReferences(text) {
  const results = [];
  const regexPatterns = [
    /the\s+(book|book\s+of)\s+(\w+)/i, // Indirect references (e.g., "the Book of Kings")
    /\b(\w+)\b/i, // Simple book names (e.g., "Kings", "Genesis")
    /\b(\w+)\s+of\s+(\w+)\b/i, // Compound book names (e.g., "Song of Solomon")
  ];

  for (const regexPattern of regexPatterns) {
    const matches = text.match(regexPattern);
    if (!matches) continue;

    for (const match of matches) {
      const bookName = match[3] || match[2];
      const referenceCount = (results.find((result) => result.book === bookName)) ? results.find((result) => result.book === bookName).count : 0;
      referenceCount++;

      let contextList = [];
      let variationList = [];

      // Check for variations in book names
      if (match[1]) {
        const fullName = `${match[2]} of ${match[3]}`;
        const shortenedName = match[2];
        const translatedName = api.translateBookName(bookName);

        if (fullName !== bookName) variationList.push({ full: fullName, shortened: shortenedName, translated: translatedName });
      }

      // Check for unique contexts
      const contextMatch = text.match(new RegExp(`.*${bookName}.*`, 'i'));
      if (contextMatch) {
        contextList = contextMatch.map((line) => line.trim());
      }

      results.push({ book: bookName, count: referenceCount, contexts: [...new Set(contextList)], variations: variationList });
    }
  }

  return results;
}

module.exports = analyzeBiblicalReferences;
