function generateSettingsPanel(configs) {
  let html = '';
  for (const config of configs) {
    switch (config.type) {
      case 'text':
        html += `<label>${config.label}</label><input type="text" value="${config.value}">`;
        break;
      case 'checkbox':
        html += `<label>${config.label}</label><input type="checkbox" ${config.value ? 'checked' : ''}>`;
        break;
      case 'select':
        html += `<label>${config.label}</label><select ${config.value ? 'selected' : ''}>`;
        for (const option of config.options) {
          html += `<option value="${option}">${option}</option>`;
        }
        html += '</select>';
        break;
    }
  }
  return html;
}
