function manageDataStream(dataStream) {
  let dataArray = [];
  let paused = false;

  dataStream.on('data', (chunk) => {
    if (!paused) {
      dataArray.push(chunk);
    }
  });

  dataStream.on('pause', () => {
    paused = true;
  });

  dataStream.on('resume', () => {
    paused = false;
  });

  function addRandomVerticesAndEdgesToGraph(graph, numVertices, numEdges) {
    for (let i = 0; i < numVertices; i++) {
      const vertexId = Math.random().toString();
      graph.addVertex(vertexId);
      Object.defineProperty(graph[vertexId], 'randomProperty', { value: Math.random() });
    }

    for (let i = 0; i < numEdges; i++) {
      const edgeId = Math.random().toString();
      const vertex1 = Math.floor(Math.random() * graph.size());
      const vertex2 = Math.floor(Math.random() * graph.size());
      graph.addEdge(edgeId, vertex1, vertex2);
      Object.defineProperty(graph[edgeId], 'randomProperty', { value: Math.random() });
    }
  }

  function verifyAddedVerticesAndEdgesInGraph(graph) {
    for (let vertex in graph) {
      if (graph[vertex].hasOwnProperty('randomProperty')) {
        console.log(`Vertex ${vertex} has been added to the graph with random property ${graph[vertex].randomProperty}`);
      }
    }

    for (let edge in graph.edges()) {
      if (edge.hasOwnProperty('randomProperty')) {
        console.log(`Edge ${edge} has been added to the graph with random property ${edge.randomProperty}`);
      }
    }
  }

  return {
    dataArray,
    addRandomVerticesAndEdgesToGraph,
    verifyAddedVerticesAndEdgesInGraph
  };
}
