function copyBytes(chunks, bytesToCopy) {
  const totalChunks = chunks.length;
  let bytesRead = 0;
  let outputBuffer = Buffer.alloc(Math.ceil(bytesToCopy / chunkSize));

  for (let i = 0; i < totalChunks && bytesRead < bytesToCopy; i++) {
    const chunk = chunks[i];
    const chunkBytes = chunk.byteLength;
    const copyChunkBytes = Math.min(chunkBytes, bytesToCopy - bytesRead);

    if (!chunk.copy(outputBuffer, bytesRead, copyChunkBytes)) {
      throw new Error("Error copying chunk");
    }

    bytesRead += copyChunkBytes;
  }

  return outputBuffer.slice(0, bytesRead);
}

function chunkSize(chunks) {
  let totalChunks = chunks.length;
  let totalBytes = 0;

  for (let i = 0; i < totalChunks; i++) {
    const chunk = chunks[i];
    totalBytes += chunk.byteLength;
  }

  return Math.ceil(totalBytes / totalChunks);
}
