function generateReport(rootElement, selectors, batchSize = 1000) {
  const batches = [];
  let currentBatch = [];

  function traverse(element, parent) {
    currentBatch.push({
      selector: parent ? parent.nodeName : '',
      attributes: [...element.attributes].reduce((acc, attr) => ({ ...acc, [attr.name]: attr.value }), {}),
      textContent: element.textContent,
    });

    for (const selector of selectors) {
      const elements = element.querySelectorAll(selector);
      for (const element of elements) {
        if (currentBatch.length >= batchSize) {
          batches.push(currentBatch);
          currentBatch = [];
        }
        traverse(element, parent);
      }
    }
  }

  traverse(rootElement);
  batches.push(currentBatch);

  function filterReport(report, selector, value) {
    return report.filter((element) => {
      if (selector === 'attributes') {
        return Object.values(element.attributes).some((attributeValue) => attributeValue === value);
      } else if (selector === 'textContent') {
        return element.textContent.includes(value);
      }
      return false;
    });
  }

  function getReport() {
    const filteredReport = filterReport(batches.flat(), 'attributes', '');
    return JSON.stringify(filteredReport, null, 2);
  }

  console.log(getReport());
}
