const fs = require('fs');
const path = require('path');

class ModuleLoader {
  constructor(options) {
    this.options = options;
    this.loadedModules = [];
    this.loadQueue = [];
  }

  async loadScript(filename, dependencies) {
    return new Promise((resolve, reject) => {
      if (!this.loadQueue.includes(filename)) {
        this.loadQueue.push(filename);
        fs.readFile(path.join(this.options.scriptDir, filename), (err, data) => {
          if (err) {
            reject(new Error(`Failed to load script ${filename}: ${err.message}`));
          } else {
            try {
              const module = new Function('module', 'exports', `return ${data.toString()};`)({
                module,
                exports: {},
              });
              this.loadedModules.push(module);
              resolve();
              if (dependencies) {
                for (const dependency of dependencies) {
                  await this.loadScript(dependency, null);
                }
              }
            } catch (e) {
              reject(new Error(`Failed to execute script ${filename}: ${e.message}`));
            } finally {
              this.loadQueue.splice(this.loadQueue.indexOf(filename), 1);
            }
          }
        });
      }
    });
  }

  async loadScripts(scriptOrder) {
    for (const script of scriptOrder) {
      await this.loadScript(script, null);
    }
  }

  getLoadedModules() {
    return [...this.loadedModules];
  }

  getLoadQueue() {
    return [...this.loadQueue];
  }

  logFeedback(message) {
    console.log(message);
  }

  async load() {
    try {
      await this.loadScripts(this.options.scriptOrder);
      this.logFeedback('Script loading completed successfully!');
    } catch (e) {
      this.logFeedback(`Error during script loading: ${e.message}`);
    }
  }
}

module.exports = ModuleLoader;
