import java.util.*;

public class Scheduler {
    public static Map<Integer, List<Request>> scheduleRequests(List<Request> requests) {
        Map<Integer, List<Request>> scheduledRequests = new HashMap<>();
        Request[] sortedRequests = requests.toArray(new Request[0]);
        Arrays.sort(sortedRequests);

        int currentDeadline = 0;
        for (Request request : sortedRequests) {
            if (request.getDeadline() > currentDeadline) {
                currentDeadline = request.getDeadline();
                scheduledRequests.put(currentDeadline, new ArrayList<>());
            }
            scheduledRequests.get(currentDeadline).add(request);
        }

        return scheduledRequests;
    }

    public static class Request implements Comparable<Request> {
        private int id;
        private int deadline;
        private int duration;

        public Request(int id, int deadline, int duration) {
            this.id = id;
            this.deadline = deadline;
            this.duration = duration;
        }

        public int getId() {
            return id;
        }

        public int getDeadline() {
            return deadline;
        }

        public int getDuration() {
            return duration;
        }

        @Override
        public int compareTo(Request o) {
            if (this.deadline < o.deadline) {
                return -1;
            }
            if (this.deadline > o.deadline) {
                return 1;
            }
            return 0;
        }
    }
}']

