public class ConnectionPool {
    private static final int MAX_CONNECTIONS = 1000;
    private static final ConcurrentHashMap<String, SocketChannel> pool = new ConcurrentHashMap<>();
    private static final AtomicInteger connectionsInUse = new AtomicInteger(0);

    public static void managePool() throws IOException {
        while (true) {
            if (connectionsInUse.get() < MAX_CONNECTIONS / 2) {
                String address = getAvailableAddress();
                if (address != null) {
                    SocketChannel channel = SocketChannel.open();
                    channel.connect(new java.net.InetSocketAddress(address, 80));
                    pool.putIfAbsent(address, channel);
                    connectionsInUse.incrementAndGet();
                }
            } else {
                try {
                    Thread.sleep(1000); // Wait for some time
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        }
    }

    public static void releaseConnection(String address) {
        pool.remove(address);
        connectionsInUse.decrementAndGet();
    }

    private static String getAvailableAddress() {
