class VideoCacher {
    private Map<String, List<VideoFrame>> frameCache = new HashMap<>();
    private VideoCodecProfile defaultProfile;

    public void init() {
        if (defaultProfile == null) {
            defaultProfile = new H264Profile();
        }
    }

    public void cacheVideoFrames(String videoId, List<VideoFrame> frames) {
        frameCache.put(videoId, frames);
        for (VideoFrame frame : frames) {
            recycleOldFrames(frame);
        }
    }

    private void recycleOldFrames(VideoFrame newFrame) {
        int maxAge = 5; // in seconds
        long now = System.currentTimeMillis();
        List<VideoFrame> toRecycle = new ArrayList<>();
        for (List<VideoFrame> frames : frameCache.values()) {
            for (int i = frames.size() - 1; i >= 0; i--) {
                VideoFrame frame = frames.get(i);
                if (now - frame.getTimestamp() > maxAge * 1000) {
                    toRecycle.add(frame);
                }
            }
        }
        for (VideoFrame oldFrame : toRecycle) {
            frames.remove(oldFrame);
        }
    }

    public void decodeAndCache(String videoId, byte[] compressedData) {
        VideoCodecProfile profile = defaultProfile;
        List<VideoFrame> decodedFrames = new ArrayList<>();
        VideoDecoder decoder = new H264Decoder(profile);
        while (decoder.decode(compressedData)) {
            VideoFrame frame = decoder.getDecodedFrame();
            decodedFrames.add(frame);
        }
        cacheVideoFrames(videoId, decodedFrames);
    }

    public List<VideoFrame> getVideoFrames(String videoId) {
        return frameCache.getOrDefault(videoId, Collections.emptyList());
    }
}

