import java.util.*;
import java.util.concurrent.*;

public class CacheService {

    private final ConcurrentHashMap<String, String> cache;
    private final int capacity;

    public CacheService(int capacity) {
        this.capacity = capacity;
        this.cache = new ConcurrentHashMap<>();
    }

    public void start() {
        Thread thread = new Thread(() -> {
            try {
                while (true) {
                    Random random = new Random();
                    TimeUnit.SECONDS.sleep(random.nextInt(5) + 1);
                    insert("key" + System.nanoTime(), "value");
                }
            } catch (InterruptedException e) {
                stop();
            }
        });
        thread.start();
    }

    public void stop() {
        try {
            Thread.sleep(1000); // wait for a second
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
        System.out.println("Stopping Cache Service");
        // send message to messaging system
        System.exit(0);
    }

    public void insert(String key, String value) {
        while (true) {
            if (!cache.containsKey(key)) {
                if (cache.size() >= capacity) {
                    removeLRU();
                }
                cache.put(key, value);
                break;
            }
        }
    }

    private void removeLRU() {
        List<Map.Entry<String, String>> entries = new ArrayList<>(cache.entrySet());
        Map.Entry<String, String> leastRecentlyUsed = null;
        for (Map.Entry<String, String> entry : entries) {
            if (leastRecentlyUsed == null || entry.getValue().compareTo(leastRecentlyUsed.getValue()) < 0) {
                leastRecentlyUsed = entry;
            }
        }
        cache.remove(leastRecentlyUsed.getKey());
    }

    public void retrieve(String key) {
        while (true) {
            if (!cache.containsKey(key)) {
                break;
            }
            String value = cache.get(key);
            // do something with the retrieved value
            break;
        }
    }
}

public class ServiceManagement {

    private final CacheService cacheService;

    public ServiceManagement(CacheService cacheService) {
        this.cacheService = cacheService;
    }

    public void start() {
        cacheService.start();
    }

    public void stop() {
        cacheService.stop();
    }
}
