    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query(['location' => $location]));
    $weather_data = curl_exec($ch);
    curl_close($ch);

    file_put_contents($cachefile, $weather_data);
