use reqwest::{get, put, post, delete};
use std::time::Duration;
use tokio::retry;

async fn make_request(url: &str, method: &str, body: &str) -> Result<String, String> {
    let mut client = reqwest::Client::builder()
        .timeout(Duration::from_secs(5)) // 5 seconds
        .dangerously_allow_url_connections(true)
        .build()?;

    let request = match method.as_ref() {
        "GET" => get(url),
        "PUT" => put(url).body(body.to_string()),
        "POST" => post(url).body(body.to_string()),
        "DELETE" => delete(url),
        _ => return Err("Invalid HTTP method".to_string()),
    };

    if let Some(cert) = &Some(/* your certificate */) {
        client = reqwest::ClientBuilder::new().cert(cert);
    }

    let result = retry::retries(3).execute(|| async {
        match request.send().await {
            Ok(response) => Ok(format!("{:?}", response)),
            Err(err) if err.is_timeout() || err.is_connection_closed() => {
                // transient error, retry
                await!(retry::retries(3).execute(|| async {
                    await!(request.send().await);
                }));
                Ok("Request failed due to transient error".to_string())
            }
            Err(err) => Err(format!("Error: {:?}", err)),
        }
    });

    match result {
        Ok(result) => Ok(result),
        Err(err) => Err(err),
    }
}
