def update_cache(user_id: int, metadata: dict) -> dict:
    import datetime
    from collections import defaultdict

    cache = {}

    def invalidate_cache():
        nonlocal cache
        cache[user_id] = {'last_accessed': None, 'sessions': defaultdict(list)}

    def update_timestamp(metadata):
        return {'last_accessed': datetime.datetime.now()}

    def add_session(metadata):
        sessions = metadata.get('sessions', [])
        sessions.append({'timestamp': datetime.datetime.now()})
        return {'sessions': sessions}

    if user_id in cache:
        invalidate_cache()
    else:
        cache[user_id] = {'last_accessed': None, 'sessions': defaultdict(list)}

    updated_metadata = {**metadata, **update_timestamp(metadata), **add_session(metadata)}

    return {
        'status': 'updated',
        'metrics': {
            'cache_hits': 0,
            'cache_misses': 1
        }
    }"]

