    DECLARE @query NVARCHAR(MAX);
    SET @query = 'SELECT E.EmployeeName, E.City, E.Address FROM Employees E WHERE E.SupervisorID = @supervisorID';

    INSERT INTO @result
    EXEC sp_executesql @query, N'@supervisorID INT', @supervisorID;
END

CREATE PROCEDURE sp_ConnectAndExecuteQuery
    @supervisorID INT,
    @result TABLE (EmployeeName VARCHAR(50), City VARCHAR(50), Address VARCHAR(100))
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @connection SQLConnection;
    SET @connection = NEW SQLConnection();

    SET @connection.ConnectionString = 'Server=localhost;Database=YourDB;User ID=YourUsername;Password=YourPassword;';

    EXEC sp_OpenConnection @connection;

    SET @query = 'SELECT E.EmployeeName, E.City, E.Address FROM Employees E WHERE E.SupervisorID = @supervisorID';

    INSERT INTO @result
    EXEC sp_ExecuteQuery @connection, @query, N'@supervisorID INT', @supervisorID;

    EXEC sp_CloseConnection @connection;
END"]

