<?php

class SecureRandomizer {
    private $allowedHashAlgorithms = ['sha256', 'sha512'];
    private $defaultHashAlgorithm;
    private $defaultCharacterSet;

    public function __construct($config = null) {
        if ($config !== null) {
            $this->defaultHashAlgorithm = array_key_exists('hash_algorithm', $config) ? $config['hash_algorithm'] : 'sha256';
            $this->defaultCharacterSet = array_key_exists('character_set', $config) ? $config['character_set'] : 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
        }
    }

    public function generateRandomString($length, $characterSet = null) {
        if ($characterSet === null) {
            $characterSet = $this->defaultCharacterSet;
        }
        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $characterSet[rand(0, strlen($characterSet) - 1)];
        }
        return $randomString;
    }

    public function hashPassword($password, $algorithm = null) {
        if ($algorithm === null) {
            $algorithm = $this->defaultHashAlgorithm;
        } elseif (!in_array($algorithm, $this->allowedHashAlgorithms)) {
            throw new Exception('Invalid hash algorithm');
        }
        return hash($algorithm, $password);
    }

    public function checkEntropy($string, $minEntropy = 128) {
        $entropy = 0;
        $charSetLength = strlen($this->defaultCharacterSet);
        for ($i = 0; $i < strlen($string); $i++) {
            $charIndex = strpos($this->defaultCharacterSet, $string[$i]);
            if ($charIndex !== false) {
                $entropy += log2($charSetLength / (1 << $charIndex));
            } else {
                return 0;
            }
        }
        return $entropy >= log2(2) ** $minEntropy ? true : false;
    }
}

