import re
import datetime
from multiprocessing import Pool

def parse_entry(entry):
    match = re.match(r'\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (.*)', entry)
    if match:
        timestamp, sequence_number = match.groups()
        return (datetime.datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S'), int(sequence_number))
    else:
        return None

def process_log_file(file_name):
    entries = []
    with open(file_name, 'r') as file:
        for line in file:
            entry = parse_entry(line)
            if entry is not None:
                entries.append(entry)

    entries.sort(key=lambda x: x[0])
    latest_entry = entries[-1]
    return latest_entry

def main():
    pool_size = 4
    files_to_process = ['log_file_1.log', 'log_file_2.log', ...]  # List of log file names to process

    with Pool(processes=pool_size) as pool:
        results = pool.starmap(process_log_file, [(file, ) for file in files_to_process])

    for result in results:
        latest_sequence_number = result[1]
        print(f"Latest sequence number: {latest_sequence_number}")

if __name__ == "__main__":
    main()
