#include <stdio.h>
#include <stdlib.h>

// Define a structure for states
typedef struct State {
    int state;
    int* transitions;
    int numTransitions;
    int refCount;
} State;

// Define a structure for FSA
typedef struct FSA {
    int states;
    State** stateList;
    int lastStateIndex;
} FSA;

// Function to create linked list of states from a given finite state automaton (FSA)
State* constructLinkedList(int* states, int numStates, FSA* fsa, int lastStateIndex) {
    if (!states || !fsa) return NULL; // Check for invalid inputs

    State* head = NULL;
    State** current = &head;

    for (int i = 0; i < numStates; i++) {
        State* newNode = (State*)malloc(sizeof(State));
        if (!newNode) return NULL; // Memory allocation failed, return NULL
        newNode->state = states[i];
        newNode->transitions = fsa->stateList[i]->transitions;
        newNode->numTransitions = fsa->stateList[i]->numTransitions;
        newNode->refCount = 1;

        *current = newNode;
        current = &(newNode)->next; // Move to the next node
    }

    return head;
}
