#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    int id;
    int count;
    Transaction *transactions;
    time_t oldest;
} IDContext;

int process_transactions(Transaction *trans, int trans_count) {
    static IDContext id_contexts[10000]; // Assuming maximum 10,000 unique IDs
    static double max_weight = 0;
    static int max_id = -1;
    time_t now = time(NULL);

    for (int i = 0; i < trans_count; i++) {
        Transaction *t = &trans[i];
        IDContext *id_context;

        // Find or create the context for this transaction ID
        for (int j = 0; j < 10000; j++) {
            if (id_contexts[j].id == t->id) {
                id_context = &id_contexts[j];
                break;
            }
        }

        // If we reached here, it means the ID was not found, so create a new context
        if (j == 10000) {
            id_context = id_contexts + j;
            id_context->id = t->id;
            id_context->count = 0;
            id_context->transactions = NULL;
            id_context->oldest = now - 5; // Initialize the oldest timestamp to 5 seconds ago
        }

        // Check if this transaction is within the age criteria (less than 5 seconds)
        if (t->timestamp > id_context->oldest) {
            // Check if there are more than 5 transactions for this ID in the past 3 seconds
            if (id_context->count <= 4 || t->timestamp >= now - 3) {
                // Add transaction to the list and update the count and oldest timestamp
                id_context->transactions = realloc(id_context->transactions, (id_context->count + 1) * sizeof(Transaction));
                id_context->transactions[id_context->count++] = *t;
                if (id_context->oldest > t->timestamp) {
                    id_context->oldest = t->timestamp;
                }

                // Check the weighted sum of this transaction
                double weight_sum = 0.0;
                for (int j = 0; j < id_context->count; j++) {
                    Transaction *transaction = &id_context->transactions[j];
                    weight_sum += transaction->weight;
                }
                if (weight_sum > 100) {
                    // Update the maximum weighted sum and corresponding ID
                    max_weight = weight_sum;
                    max_id = t->id;
                }
            }
        }
    }

    return max_id;
}
