#include <random>

class Character {
private:
    int cooldownTime;
    bool isCooldownActive;
    std::random_device rd;
    std::mt19937 gen;

public:
    Character() : cooldownTime(5), isCooldownActive(false) {}

    void selectAbility() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (isCooldownActive) {
            std::cout << "Ability cannot be used at this time. Cooldown period active." << std::endl;
            return;
        }

        if (!cooldownTimer().expired()) {
            isCooldownActive = true;
            cooldownTime = 5;
            std::this_thread::sleep_for(std::chrono::milliseconds(cooldownTime));
            return;
        }

        int ability = gen() % 2; // 0 or 1
        std::cout << "Ability " << ability << " used." << std::endl;

        isCooldownActive = true;
        cooldownTimer();
    }

private:
    std::mutex mutex_;
    std::chrono::steady_clock::time_point cooldownTimePoint;

    std::chrono::milliseconds cooldownTimer() {
        if (!isCooldownActive) {
            cooldownTimePoint = std::chrono::steady_clock::now() + std::chrono::milliseconds(cooldownTime);
            return cooldownTime;
        } else {
            while (std::chrono::steady_clock::now() < cooldownTimePoint) {}
            isCooldownActive = false;
            return cooldownTime;
        }
    }
};

