using System;
using System.Security.Cryptography;

public class RandomValueGenerator
{
    private RNGCryptoServiceProvider _rng;
    private int _minValue;
    private bool _inclusiveMin;
    private int _maxValue;
    private bool _inclusiveMax;

    public RandomValueGenerator(int minValue, bool inclusiveMin, int maxValue, bool inclusiveMax)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Invalid range");

        _rng = new RNGCryptoServiceProvider();
        _minValue = minValue;
        _inclusiveMin = inclusiveMin;
        _maxValue = maxValue;
        _inclusiveMax = inclusiveMax;
    }

    public float GenerateFloat()
    {
        double value = (double)_rng.NextDouble() * (_maxValue - _minValue);
        if (_inclusiveMin)
            value += _minValue;
        else
            value += (_minValue + 1);

        return (float)(value * (_inclusiveMax ? 1 : 0.99999));
    }

    public int GenerateInt()
    {
        byte[] randomBytes = new byte[4];
        _rng.GetBytes(randomBytes);
        long value = BitConverter.ToInt32(randomBytes, 0) % (_maxValue - _minValue + (_inclusiveMin ? 1 : 0));

        return (int)(value + _minValue);
    }

    public void AdjustRange(int minValue, bool inclusiveMin, int maxValue, bool inclusiveMax)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Invalid range");

        _minValue = minValue;
        _inclusiveMin = inclusiveMin;
        _maxValue = maxValue;
        _inclusiveMax = inclusiveMax;
    }

    public override string ToString()
    {
        return $"Range: ({_minValue}{(_inclusiveMin ? "" : "<=")} , {_maxValue}{(_inclusiveMax ? "" : "<=}")]";
    }

    public void Reset()
    {
        _rng.GetBytes(new byte[4]);
    }
}
