async function asyncReduce(arr, initialValue, callback) {
  if (!Array.isArray(arr)) throw new Error('Input must be an array');
  if (typeof callback !== 'function') throw new Error('Callback must be a function');

  let result = initialValue;
  for await (const num of arr) {
    try {
      result = callback(result, num);
    } catch (error) {
      console.error('Error during reduction:', error);
      return undefined;
    }
  }

  const fetchValues = async () => {
    try {
      const response = await fetch('https://example.com/values');
      const data = await response.json();
      return data;
    } catch (error) {
      console.error('Error fetching values:', error);
      return [];
    }
  };

  const remoteData = await fetchValues();

  if (!remoteData.length) return result;

  for await (const value of remoteData) {
    try {
      result = callback(result, value);
    } catch (error) {
      console.error('Error during reduction:', error);
      return undefined;
    }
  }

  return result;
}

