#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "json-c/json.h"
#include "yaml.h"
#include "toml.h"

int load_resource_bundle(const char* path) {
    int items_count = 0;
    FILE* file = fopen(path, "r");
    if (file == NULL) return -1; // error opening file

    char buffer[1024];
    while (fscanf(file, "%1023s", buffer) == 1) { // read line by line
        buffer[strcspn(buffer, "\r\n")] = '\0'; // remove newline and cr
        if (strchr(buffer, '#')) { // skip comments
            buffer[strcspn(buffer, "#")] = '\0';
        }

        // check file format
        if (strcasestr(buffer, "json")) {
            json_object *obj;
            obj = json_object_from_string(buffer);
            items_count += json_object_get_array_length(obj);
            json_object_put(obj);
        } else if (strcasestr(buffer, "yaml") || strcasestr(buffer, "yml")) {
            yaml_event_t event;
            yaml_parser_t* parser = yaml_parser_new();
            yaml_parser_reset(parser);
            yaml_parser_set_input_string(parser, buffer);
            while (1) {
                yaml_parser_scan(parser);
                if (!yaml_parser_check_event(parser, &event)) break;
                yaml_event_delete(&event);
            }
            items_count += yaml_get_block_length(yaml_get_node(parser));
            yaml_parser_delete(parser);
        } else if (strcasestr(buffer, "toml")) {
            TOMLTable* table = toml_parse_string(buffer);
            items_count += toml_table_size(table);
            toml_free_table(table);
        }
    }

    fclose(file);

    return items_count;
}
