char* append_slash(const char* str, size_t limit, char** buffer) {
    size_t len = strlen(str);
    if (len + 1 > limit) {
        *buffer = malloc(len + 2);
        if (*buffer == NULL) return NULL;
        memcpy(*buffer, str, len);
        (**buffer)++ = '/';
        return *buffer;
    } else {
        char* result = realloc(NULL, len + 2);
        if (result == NULL) return NULL;
        strcpy(result, str);
        ((char*)result)[len] = '/';
        ((char*)result)[len+1] = '\0';
        return result;
    }
}
