#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>

#define LOG_LEVEL 1
#define MAX_LINE_LENGTH 1024

void log_message(int level, const char *format, ...) {
    va_list(ap);
    if (level <= LOG_LEVEL) {
        vprintf(format, ap);
        printf("\n");
    }
    va_end(ap);
}

int main(int argc, char **argv) {
    int i;
    FILE *files[argc];
    for (i = 1; i < argc; i++) {
        files[i - 1] = fopen(argv[i], "r");
        if (!files[i - 1]) {
            log_message(0, "Error opening file %s: %s", argv[i], strerror(errno));
            return 1;
        }
    }

    char *line = NULL;
    size_t line_len = 0;

    for (i = 0; i < argc; i++) {
        while (fscanf(files[i], "%1024s\n", line) == 1) {
            int len = strlen(line);
            if (len > 0 && line[len - 1] != '\n') {
                // Read entire line
                for (; i + 1 < argc; i++) {
                    if (fscanf(files[i + 1], "%1024s\n", &line[len]) == 1) {
                        len += strlen(&line[len]);
                    } else {
                        break;
                    }
                }
            }
            double avg = 0.0;
            int num_fields = 0;

            // Process fields
            char *token = strtok(line, ",");
            while (token && ++num_fields) {
                if (sscanf(token, "%lf", &avg) == 1) {
                    break;
                } else if (!strchr(token, ',')) {
                    log_message(0, "Invalid data format: %s", line);
                    free(line);
                    for (int j = i; j < argc; j++) {
                        fclose(files[j]);
                    }
                    return 1;
                }
                token = strtok(NULL, ",");
            }

            // Process last two fields
            token = strtok(token, ",");
            if (!token) {
                log_message(0, "Invalid data format: %s", line);
                free(line);
                for (int j = i; j < argc; j++) {
                    fclose(files[j]);
                }
                return 1;
            }

            char *end = strchr(token, ',');
            if (end) {
                token = end + 1;
            } else {
                end = token + strlen(token);
            }

            // Convert last two fields to double and calculate average
            double val1, val2;
            if (sscanf(token, "%lf", &val1) == 1 && sscanf(end, "%lf", &val2) == 1) {
                avg = (val1 + val2) / 2.0;
            } else {
                log_message(0, "Invalid data format: %s", line);
                free(line);
                for (int j = i; j < argc; j++) {
                    fclose(files[j]);
                }
                return 1;
            }

            // Print output
            printf("%s,", line);

            if (num_fields > 2) {
                printf("%.2f", avg);
            }

            printf("\n");

            free(line);
            line = NULL;
            line_len = 0;

            for (i = 0; i < argc; i++) {
                if (files[i] && fseek(files[i], 0, SEEK_SET) != 0) {
                    log_message(0, "Error seeking file %s: %s", argv[i + 1], strerror(errno));
                    return 1;
                }
            }

        }
    }

    for (i = 0; i < argc; i++) {
        if (files[i] && fclose(files[i]) != 0) {
            log_message(0, "Error closing file %s: %s", argv[i + 1], strerror(errno));
            return 1;
        }
    }

    return 0;
}
