#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* modify_filename(char* filename, int file_type, int max_length) {
    char* new_filename = NULL;
    size_t length = strlen(filename);

    // Calculate the sequence of digits based on the filename's character count and specified file type
    int sequence_len = (file_type + 1) * length % 10;

    if ((new_filename = (char*)malloc(max_length + sequence_len + 1)) == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for new filename.\n");
        return NULL;
    }

    sprintf(new_filename, "%.*s", (int)(max_length - sequence_len), filename);

    // Append the sequence of digits
    char* ptr = &new_filename[max_length];
    for (int i = 0; i < sequence_len; i++) {
        *ptr++ = '0' + (i % 10);
    }
    *--ptr = '\0'; // Null-terminate the new filename

    return new_filename;
}
