// Function to initialize AES-256-CBC cipher with given password and custom hashing scheme
EVP_CIPHER_CTX* setup_aes_cipher(const char* password, const char* salt) {
    EVP_PKEY* pkey;
    const unsigned char* pass = (const unsigned char*)password;
    int password_len = strlen(password);

    // Generate a random IV
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Set key length and IV length to fixed values
    EVP_CIPHER_CTX_set_key_length(ctx, 32); // 256 bits (32 bytes)
    EVP_CIPHER_CTX_set_iv_length(ctx, AES_BLOCK_SIZE);

    // Derive the encryption key from the password using PBKDF2
    const unsigned char* salt_bytes = (const unsigned char*)salt;
    int salt_len = strlen(salt);
    uint64_t cost = 100000; // adjust to your needs

    EVP_PKEY* pkey_out = PBKDF2(pass, pass_len, salt_bytes, salt_len, iv, AES_BLOCK_SIZE, cost, &pkey);
    if (!pkey) {
        ERR_error_fp(stderr, "Error during key derivation");
        return NULL;
    }

    // Initialize the cipher with the derived key
    if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, pkey->pkey, iv)) {
        ERR_error_fp(stderr, "Error initializing AES cipher");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Enable the cipher and return a pointer to the cipher context
    if (1 != EVP_CipherStart(ctx)) {
        ERR_error_fp(stderr, "Error starting AES cipher");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CipherStop(ctx); // Stop the cipher if it's still running
        EVP_CIPHER_CTX_free(ctx);
    }
}
