#include <sys/stat.h>

int convert_images(const char *dir_path, const char *target_file_type, const char *output_dir) {
    DIR *dp;
    struct dirent *entry;
    int error = 0;

    if (!(dp = opendir(dir_path))) {
        perror("opendir");
        return 1;
    }

    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[1024];
        sprintf(full_path, "%s/%s", dir_path, entry->d_name);

        struct stat sb;
        if (stat(full_path, &sb) == -1) {
            perror("stat");
            error = 1;
            continue;
        }

        if (!S_ISDIR(sb.st_mode)) { // not a directory
            char command[1024];
            sprintf(command, "convert '%s' %s/%s", full_path, output_dir, target_file_type);
            system(command);
        } else {
            int status = system(command);
            if (status) error = 1;
        }
    }

    closedir(dp);

    return error;
}
