#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <string.h>

#define MAX_CONCURRENT_INVOCATIONS 100
#define RETRY_LIMIT 3
#define LOG_FILE "command_log.txt"
#define ROOT_EXECUTION_ENV_VAR "EXECUTE_AS_ROOT"

int log_status(const char* status, const char* command) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) return -1;
    fprintf(file, "%s: %s\n", status, command);
    fclose(file);
    return 0;
}

void sigchild_handler(int signal) {
    int status;
    wait(&status);
}

int run_command(const char* command, const char* args[], size_t argc) {
    pid_t pid = fork();
    if (pid == -1) return -1;

    if (pid == 0) {
        // Child process
        if (getenv(ROOT_EXECUTION_ENV_VAR)) {
            setuid(geteuid());
        }
        execvp(command, args);
        exit(127); // Failed to execute
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);

        if (WIFEXITED(status)) {
            log_status("Success", command);
            return 0;
        } else {
            log_status("Failure", command);
            for (int i = 0; i < RETRY_LIMIT && !WIFEXITED(status); i++) {
                pid = fork();
                if (pid == -1) return -1;

                if (pid == 0) {
                    // Child process
                    if (getenv(ROOT_EXECUTION_ENV_VAR)) {
                        setuid(geteuid());
                    }
                    execvp(command, args);
                    exit(127); // Failed to execute
                } else if (pid > 0) {
                    // Parent process
                    waitpid(pid, &status, 0);
                }

                if (!WIFEXITED(status)) {
                    log_status("Failure", command);
                }
            }

            return -1;
        }
    } else {
        // Error occurred during fork()
        return -1;
    }
}

void pause_command() {
    // Pause the command execution
}

void resume_command() {
    // Resume the command execution
}

int main(int argc, char** argv) {
    // Initialize signal handler to ensure parent process does not become a zombie
    signal(SIGCHLD, sigchild_handler);

    for (size_t i = 0; i < MAX_CONCURRENT_INVOCATIONS; i++) {
        run_command(argv[1], &argv[2], argc - 3);
    }

    // Terminate all background processes spawned by this function when the program exits
    kill(0, SIGTERM);

    return 0;
}
