        if (!File.Exists(webConfigPath))
        {
            Logger.LogInformation("Web.config file is missing. Skipping website addition.");
            return;
        }

        try
        {
            using (Process process = new Process())
            {
                process.StartInfo.FileName = "iisreset.exe";
                process.StartInfo.Arguments = "/startw3svc /i ";
                process.StartInfo.WorkingDirectory = directoryPath;

                try
                {
                    process.Start();
                    process.WaitForExit(30000); // timeout after 30 seconds
                }
                catch (Exception ex)
                {
                    Logger.LogError($"Failed to start website: {ex.Message}");
                    throw;
                }

                if (!process.ExitCode.HasValue || process.ExitCode.Value != 0)
                {
                    Logger.LogError("Website startup failed.");
                    return;
                }

                Logger.LogInformation("Website added and started successfully.");
            }
        }
        catch (Exception ex)
        {
            Logger.LogError($"Error adding website: {ex.Message}");
            throw;
        }
    }
