import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class ShellCommandsExecutor {

    private static final int DEFAULT_COMMAND_TIMEOUT = 3000; // 3 seconds
    private static final int DEFAULT_RETRY_COUNT = 3;

    private File fileToDelete;
    private List<String> commands;
    private Runtime runtime;
    private long commandTimeout;
    private int retryCount;
    private LogService logService;

    public ShellCommandsExecutor(File fileToDelete, List<String> commands) {
        this.fileToDelete = fileToDelete;
        this.commands = commands;
        this.runtime = Runtime.getRuntime();
        this.commandTimeout = DEFAULT_COMMAND_TIMEOUT;
        this.retryCount = DEFAULT_RETRY_COUNT;
        this.logService = new LogService(); // Initialize log service
    }

    public void executeCommands() throws InterruptedException, IOException {
        for (String command : commands) {
            if (!fileToDelete.delete()) {
                logService.error("Failed to delete file: " + fileToDelete.getName());
            }
            String[] cmdArray = command.split(" ");
            Process process = runtime.exec(cmdArray);

            new Thread(() -> executeCommand(process, command)).start();
        }
    }

    private void executeCommand(Process process, String command) {
        try (BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
             BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

            int timeout = 0;
            while (!process.waitFor(timeout)) {
                if (timeout >= commandTimeout) {
                    logService.error("Command timed out: " + command);
                    executeCommandRetry(process, command);
                    break;
                }
                timeout += 100; // Wait for 100 ms
            }

            String output = readStream(stdInput);
            String error = readStream(stdError);

            logService.info(command + ": Output - " + output + ", Error - " + error);
        } catch (IOException e) {
            logService.error("Error executing command: " + command, e);
        }
    }

    private void executeCommandRetry(Process process, String command) throws InterruptedException {
        for (int i = 0; i < retryCount; i++) {
            try {
                process.waitFor();
                return;
            } catch (InterruptedException | IOException e) {
                logService.error("Error while retrying command: " + command, e);
            }
        }
    }

    private String readStream(BufferedReader reader) throws IOException {
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }
        return output.toString();
    }
}

class LogService {

    public void info(String message) {
        // Implement your logging service here
        System.out.println("INFO - " + message);
    }

    public void error(String message, Throwable t) {
        // Implement your logging service here
        System.out.println("ERROR - " + message + ": " + t.getMessage());
    }
}
