int json_token_validate(const char *json_str) {
    json_object *token = json_object_from_string(json_str);
    if (!token) {
        return 0; // JSON parsing failed
    }

    if (json_object_object_get_ex(token, "access_token", NULL) == NULL || strlen(json_object_get_string(token, "access_token")) == 0) {
        json_object_put(token);
        return 0;
    }

    int expires_in = json_object_get_int(token, "expires_in");
    if (expires_in <= 0 || expires_in > 3600) {
        json_object_put(token);
        return 0;
    }

    const char *token_type = json_object_get_string(token, "token_type");
    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(token);
        return 0;
    }

    if (json_object_object_get_ex(token, "refresh_token", NULL) != NULL && strlen(json_object_get_string(token, "refresh_token")) == 0) {
        json_object_put(token);
        return 0;
    }

    json_object_put(token);
    return 1; // Token is valid
}
