using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class Md5Hasher
{
    public async Task<string[]> ProcessBatch(string[] batch)
    {
        const int batchSize = 1000; // process in chunks to avoid excessive memory usage
        var results = new List<string>();

        foreach (var chunk in batch.Chunk(batchSize))
        {
            try
            {
                var hashes = await ComputeHashes(chunk);
                results.AddRange(hashes);
            }
            catch (Exception ex)
            {
                // handle errors gracefully, e.g., log and re-try
                Console.WriteLine("Error processing chunk: " + ex.Message);
            }
        }

        return results.ToArray();
    }

    private async Task<string[]> ComputeHashes(string[] strings)
    {
        var hashes = new List<string>();

        using (var md5 = MD5.Create())
        {
            foreach (var s in strings)
            {
                byte[] bytes = Encoding.UTF8.GetBytes(s);
                byte[] hashBytes = md5.ComputeHash(bytes);
                string hash = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
                hashes.Add(hash);
            }
        }

        return hashes.ToArray();
    }
}
