using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class Decryptor
{
    public static byte[] Decrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = key;
            switch (key.Length)
            {
                case 16:
                    aes.BlockSize = 128;
                    break;
                case 24:
                    aes.BlockSize = 192;
                    break;
                case 32:
                    aes.BlockSize = 256;
                    break;
                default:
                    throw new ArgumentException("Invalid key size. Only 128, 192, and 256 bits are supported.");
            }
            aes.Mode = CipherMode CBC;
            aes.IV = iv;

            using (var encryptor = aes.CreateDecryptor())
            {
                using (var memoryStream = new MemoryStream(ciphertext))
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Read))
                    {
                        var decryptedBytes = new byte[cryptoStream.Length];
                        int bytesRead;
                        while ((bytesRead = cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length)) > 0)
                        {
                            // Pad the decrypted data to match the original ciphertext length
                            if (ciphertext.Length > bytesRead)
                            {
                                var padding = new byte[ciphertext.Length - bytesRead];
                                cryptoStream.Read(padding, 0, padding.Length);
                                decryptedBytes = Encoding.ASCII.GetString(decryptedBytes).PadRight(ciphertext.Length, Convert.ToChar(Encoding.ASCII.GetBytes(" ")[0])).ToByteArray();
                            }
                        }

                        return decryptedBytes;
                    }
                }
            }
        }
    }

    public static byte[] VerifyAndDecrypt(byte[] ciphertext, byte[] key, byte[] iv)
    {
        try
        {
            var decryptedBytes = Decrypt(ciphertext, key, iv);

            using (var hmac = HMACSHA256.Create())
            {
                hmac.Key = key;
                var hmacBytes = hmac.ComputeHash(decryptedBytes);
                if (!HMACEquals(hmacBytes, ciphertext))
                {
                    throw new InvalidOperationException("Decrypted data integrity validation failed.");
                }

                return decryptedBytes;
            }
        }
        catch (Exception ex)
        {
            throw;
        }
    }

    private static byte[] HMACSHA256(byte[] key, byte[] data)
    {
        using (var hmac = HMACSHA256.Create())
        {
            hmac.Key = key;
            return hmac.ComputeHash(data);
        }
    }

    private static bool HMACEquals(byte[] hmacBytes1, byte[] hmacBytes2)
    {
        return BitConverter.ToString(hmacBytes1).ToLower() == BitConverter.ToString(hmacBytes2).ToLower();
    }

    private static byte[] ToByteArray(string str)
    {
        return Encoding.ASCII.GetBytes(str);
    }
}

public class Aes
{
    public int BlockSize { get; set; }
    public CipherMode Mode { get; set; }
    public IV IV { get; set; }

    public ICryptoTransform CreateEncryptor()
    {
        // Not implemented for simplicity, as it's the same algorithm
        return CreateDecryptor();
    }

    public ICryptoStream CreateCipherStream(Stream stream)
    {
        using (var encryptor = CreateEncryptor())
        {
            return new CryptoStream(stream, encryptor, CryptoStreamMode.Write);
        }
    }
}

public class HMACSHA256
{
    public static SHA256 hmacAlgorithm { get; set; }

    public static HMACSHA256 Create()
    {
        hmacAlgorithm = SHA256.Create();
        return this;
    }

    public byte[] ComputeHash(byte[] data)
    {
        using (var hmac = hmacAlgorithm)
        {
            var hashValue = hmac.ComputeHash(data);
            return hashValue;
        }
    }
}

public class SHA256
{
    public static SHA256 sha256Algorithm { get; set; }

    public static SHA256 Create()
    {
        sha256Algorithm = new SHA256CryptoServiceProvider();
        return this;
    }
