public static T LoadCompressedData<T>(string filePath) where T : class
{
    using (FileStream fileStream = File.OpenRead(filePath))
    {
        using (GZipStream gzipStream = new GZipStream(fileStream, CompressionMode.Decompress))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            try
            {
                return (T)formatter.Deserialize(gzipStream);
            }
            catch
            {
                fileStream.Position = 0;
                using (ZipInputStream zipStream = new ZipInputStream(fileStream))
                {
                    try
                    {
                        return (T)formatter.Deserialize(zipStream);
                    }
                    catch
                    {
                        throw new InvalidOperationException("Failed to decompress the data");
                    }
                }
            }
        }
    }
