const { spawn } = require('child_process');
const fs = require('fs');

function executeShellCommand(command) {
  if (!command || typeof command !== 'string') {
    throw new Error('Invalid command input');
  }

  const sanitizedCommand = command.replace(/[^a-zA-Z0-9\s\/\\]/g, '');
  const shellCommand = `bash -c "${sanitizedCommand}"`;

  return new Promise((resolve, reject) => {
    spawn('bash', ['-c', shellCommand])
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => console.error(`Error: ${data.toString()}`))
      .on('close', (code) => {
        if (code !== 0) {
          reject(new Error(`Shell command failed with code ${code}`));
        }
      });
  });
}

module.exports = executeShellCommand;
