        self.processing_time = 0

    def add_vertex(self, vertex_id, properties):
        with self.lock:
            if vertex_id not in self.vertices:
                self.vertices[vertex_id] = {'properties': properties}
            else:
                raise VertexAlreadyExistsError

    def add_edge(self, source_id, target_id, edge_type, properties):
        with self.lock:
            if source_id not in self.vertices or target_id not in self.vertices:
                raise EdgeInvalidError
            self.edges.append({'source': source_id, 'target': target_id, 'type': edge_type, 'properties': properties})

    def bulk_add_vertices(self, vertices):
        with self.lock:
            for vertex in vertices:
                if vertex['id'] not in self.vertices:
                    self.vertices[vertex['id']] = {'properties': vertex['properties']}
                else:
                    raise VertexAlreadyExistsError

