use std::env;
use std::fs;
use log::{info, error};

pub fn manage_directory(directory: &str, config_path: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let mut path = env::var("DIRECTORY_PATH").ok().map(|s| s.to_string()).unwrap_or_default();

    if let Some(config_dir) = config_path {
        if let Ok(dir) = fs::read_dir(config_dir) {
            for entry in dir {
                let entry = entry?;
                let path = entry.path();
                if path.file_name().is_some() && path.file_name().unwrap().to_string_lossy().eq("settings") {
                    info!("Overriding directory with configuration settings");
                    path = path.parent().unwrap().to_path_buf();
                    break;
                }
            }
        } else {
            error!("Error reading config directory: {}", config_dir);
            return Err(From::from(format!("Failed to read config directory: {}", config_dir)));
        }
    }

    if let Some(path) = &path {
        if path.is_empty() || path.as_path().file_name().is_none() {
            error!("Invalid directory path");
            return Err(From::from("Invalid directory path"));
        }

        if fs::create_dir_all(&path).is_ok() {
            info!("Directory created successfully: {}", path.display());
            env::set_var("DIRECTORY_PATH", &path.to_string_lossy().to_string());
        } else {
            error!("Failed to create directory: {}", path.display());
            return Err(From::from(format!("Failed to create directory: {}", path.display())));
        }
    }

    Ok(())
}
