import json
import abc
from collections import defaultdict

class AbstractDataModel(abc.ABC):
    @abc.abstractmethod
    def to_json(self):
        pass

class DataModelFactory:
    _data_models = {}
    _factory_map = {}

    @classmethod
    def register_data_model(cls, model_id, factory_func):
        cls._data_models[model_id] = None
        cls._factory_map[model_id] = factory_func

    @classmethod
    def get_data_model(cls, model_id):
        if model_id not in cls._data_models:
            raise ValueError(f"Unknown data model ID: {model_id}")
        return cls._factory_map[model_id]()

class DynamicDataModel(AbstractDataModel):
    _data = None

    def __init__(self, data):
        self._data = data

    @property
    def data(self):
        return self._data

    def to_json(self):
        return json.dumps(self._data)

class DataSerializationManager:
    @classmethod
    def serialize_data_model(cls, data_model: AbstractDataModel) -> str:
        if not isinstance(data_model, AbstractDataModel):
            raise ValueError("Invalid data model")
        return data_model.to_json()

# Example usage:
class Person(DynamicDataModel):
    pass

DataModelFactory.register_data_model("person", lambda: Person({"name": "", "age": 0}))

# Create and serialize a person data model
person = DataModelFactory.get_data_model("person")({"name": "John", "age": 30})
serialized_person = DataSerializationManager.serialize_data_model(person)

print(serialized_person)  # Output: '{"name": "John", "age": 30}'
