#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int val;
} record;

record* allocateRecords(int n) {
    record* records = (record*)malloc(n * sizeof(record));
    if (!records) {
        return NULL;
    }
    for (int i = 0; i < n; i++) {
        records[i].val = 0;
    }
    return records;
}

void sortOffsets(int** offsets, int n) {
    int* temp = (int*)malloc(n * sizeof(int));
    if (!temp) {
        return;
    }
    for (int i = 0; i < n; i++) {
        temp[i] = (*offsets)[i];
    }
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (temp[i] > temp[j]) {
                int t = temp[i];
                temp[i] = temp[j];
                temp[j] = t;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        (*offsets)[i] = temp[i];
    }
    free(temp);
}

void resizeAndReinitArrays(record** records, int** offsets, int* keys, int newCapacity) {
    *records = (record*)realloc(*records, newCapacity * sizeof(record));
    if (!*records) {
        return;
    }
    for (int i = 0; i < newCapacity; i++) {
        (*records)[i].val = 0;
    }
    *offsets = (int*)realloc(*offsets, newCapacity * sizeof(int));
    if (!*offsets) {
        return;
    }
}

void manageMemoryArrays(record** records, int** offsets, int n, int maxThreshold, int keyThreshold) {
    if (!records || !offsets) {
        printf("Error: Input pointers are NULL.\n");
        return;
    }

    // Initialize arrays and sort offsets
    for (int i = 0; i < n; i++) {
        (*records)[i].val = 0;
    }
    sortOffsets(offsets, n);

    int totalKeys = 0;
    for (int i = 0; i < n; i++) {
        totalKeys += (*keys)[i];
    }

    if (totalKeys > keyThreshold) {
        printf("Error: Total keys exceed threshold.\n");
        return;
    }

    // Resize and reinit arrays if necessary
    int newCapacity = n + 1;
    while (newCapacity > maxThreshold) {
        newCapacity /= 2;
    }
    resizeAndReinitArrays(records, offsets, keys, newCapacity);
}
