namespace GameConfigLoader
{
    public class ConfigLoader : IConfigLoader
    {
        private const string CONFIG_FILE_NAME = "game.config";
        private const string RESOURCES_FILE_NAME = "Resources.resx";

        private Dictionary<string, object> _configValues;
        private ResourceManager _resourceManager;

        public ConfigLoader()
        {
            _configValues = new Dictionary<string, object>();
            _resourceManager = new ResourceManager(typeof(GameConfigLoader));
        }

        public void LoadConfig()
        {
            string configFilePath = Path.Combine(Application.StartupPath, CONFIG_FILE_NAME);
            if (!File.Exists(configFilePath))
                return;

            XmlDocument doc = new XmlDocument();
            doc.Load(configFilePath);

            foreach (XmlNode node in doc.SelectNodes("//setting"))
            {
                string key = node.Attributes["key"].Value;
                object value = ConvertType(node.InnerText, GetPropertyType(key));
                _configValues[key] = value;
            }
        }

        private Type GetPropertyType(string propertyName)
        {
            if (propertyName == "playerHealthPoints")
                return typeof(int);
            else if (propertyName == "maximumLives")
                return typeof(int);
            else if (propertyName == "difficultyLevel")
                return typeof(double);

            throw new ArgumentException("Unknown property name: " + propertyName);
        }

        private object ConvertType(string value, Type type)
        {
            if (type == typeof(int))
                return int.Parse(value);
            else if (type == typeof(double))
                return double.Parse(value);

            throw new ArgumentException("Unsupported data type: " + type.Name);
        }
    }

    public class ConfigUIController
    {
        private IConfigLoader _configLoader;
        private GameUISettings _gameSettings;

        public ConfigUIController(IConfigLoader configLoader)
        {
            _configLoader = configLoader;
            _gameSettings = new GameUISettings();
        }

        public void UpdateGameSettings()
        {
            if (_configLoader == null || _gameSettings == null)
                return;

            playerHealthPointsLabel.Text = $"Player Health Points: {_configLoader.GetConfigValue("playerHealthPoints")}";
            maximumLivesLabel.Text = $"Maximum Lives: {_configLoader.GetConfigValue("maximumLives")}";
            difficultyLevelLabel.Text = $"Difficulty Level: {_configLoader.GetConfigValue("difficultyLevel")}";

            _gameSettings.SetPlayerHealthPoints((int)_configLoader.GetConfigValue("playerHealthPoints"));
            _gameSettings.SetMaximumLives((int)_configLoader.GetConfigValue("maximumLives"));
            _gameSettings.SetDifficultyLevel((double)_configLoader.GetConfigValue("difficultyLevel"));
        }
    }

