import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.io.UnsupportedEncodingException;
import java.security.KeyException;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class StringProcessor {
    private static final int MAX_BATCH_SIZE = 1000;
    private static final int MEMORY_LIMIT_MB = 50;
    private static final String DEFAULT_HASHING_ALGORITHM = "MD5";

    public List<String> processStrings(List<String> strings, boolean useSHA256) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        List<String> result = new ArrayList<>();

        for (String str : strings) {
            executor.submit(() -> {
                try {
                    String hash;
                    if (useSHA256) {
                        hash = sha256Hash(str);
                    } else {
                        hash = md5Hash(str);
                    }
                    synchronized (result) {
                        result.add(hash);
                    }
                } catch (Exception e) {
                    System.out.println("Error processing string: " + str);
                    System.out.println(e.getMessage());
                }
            });
        }

        executor.shutdown();
        while (!executor.isTerminated()) {
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        return result;
    }

    private String md5Hash(String str) throws Exception {
        Mac mac = Mac.getInstance("MD5");
        SecretKeySpec secretKey = new SecretKeySpec(new byte[mac.getBlockSize()], "MAC");
        mac.init(secretKey);
        byte[] hashBytes = mac.doFinal(str.getBytes());
        return bytesToHex(hashBytes);
    }

    private String sha256Hash(String str) throws Exception {
        Mac mac = Mac.getInstance("SHA-256");
        SecretKeySpec secretKey = new SecretKeySpec(new byte[mac.getBlockSize()], "MAC");
        mac.init(secretKey);
        byte[] hashBytes = mac.doFinal(str.getBytes());
        return bytesToHex(hashBytes);
    }

    private String bytesToHex(byte[] b) {
        StringBuilder sb = new StringBuilder();
        for (byte x : b) {
            sb.append(String.format("%02X", x));
        }
        return sb.toString();
    }
}
