#include <stdio.h>
#include <stdlib.h>
#include <string.h>

extern char* API_KEY;

void modifyWeatherFile(const char* filename) {
    // Initialize variables
    FILE *file = fopen(filename, "w");
    char buffer[1024];
    int attempts = 0;
    int maxAttempts = 5;

    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        return "Error opening file";
    }

    // Load API credentials
    char* apiKey = getenv("API_KEY");
    if (!apiKey) {
        perror("Error loading API key");
        fclose(file);
        return "Error loading API key";
    }

    // Construct API request URL
    char url[256];
    sprintf(url, "https://api.weather.example.com/current?location=%s&key=%s", filename, apiKey);

    // Make API request
    for (int i = 0; i < maxAttempts; i++) {
        if ((http_get(url, buffer, sizeof(buffer))) != 0) {
            attempts++;
            if (attempts >= maxAttempts) {
                perror("Error making API request");
                fclose(file);
                return "Error making API request";
            }
        } else {
            break;
        }
    }

    // Parse JSON response
    int len = strlen(buffer);
    char* jsonStart = strstr(buffer, "{\"current\": {");
    if (!jsonStart) {
        perror("Invalid JSON response");
        fclose(file);
        return "Error parsing JSON";
    }
    char* jsonEnd = strstr(jsonStart + 1, "}}");
    int jsonDataLen = strlen(jsonStart) - strlen(jsonEnd) + 1;

    // Write JSON data to file
    fwrite(buffer, 1, len - jsonDataLen, file);
    fwrite(jsonStart + 1, 1, jsonDataLen, file);

    // Modify filename extension
    char newFilename[256];
    strcpy(newFilename, filename);
    sprintf(newFilename, "%s%02d", newFilename, strlen(filename));

    // Change file type to JSON or XML
    if (strlen(newFilename) > 4 && strcasecmp(&newFilename[strlen(newFilename)-3], "json") == 0)
        strcat(newFilename, ".json");
    else
        strcat(newFilename, ".xml");

    fclose(file);
    return newFilename;
}
