            raise FileNotFoundError(f"File {file_path} not found")
        with open(file_path, 'rb') as f:
            file_data = f.read()
        upload_options = {'chunk_size': 1024 * 1024, 'concurrency_level': 5}
        return self.storage.upload(file_data, **upload_options)

    def download(self, file_path: str) -> io.BytesIO:
        with io.BytesIO() as f:
            download_options = {'chunk_size': 1024 * 1024, 'concurrency_level': 5}
            self.storage.download(f, file_path, **download_options)
        return f

class UploadManager:
    def __init__(self):
        self.config = {}

    def set_config(self, config: Dict[str, Any]):
        self.config.update(config)

    def upload_file(self, cloud_storage: CloudStorage, file_path: str) -> Dict[str, Any]:
