#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>

// Define a struct to hold the encryption module's state
typedef struct {
    // Store the derived key and IV
    unsigned char *key;
    unsigned char *iv;

    // Keep track of whether the module is initialized
    int initialized;
} EncryptionModuleState;

// Function to initialize the encryption module with a password
int EncryptionModuleInit(EncryptionModuleState *module, const char *password, size_t password_len) {
    if (!module || !password || password_len == 0) {
        return -1; // Invalid input
    }

    if (module->initialized) {
        return -2; // Module already initialized
    }

    // Derive the key and IV using PBKDF2 with SHA-256
    unsigned char *derived_key = (unsigned char *)malloc(AES_KEY_LENGTH + 1);
    unsigned char *iv = (unsigned char *)malloc(AES_BLOCK_SIZE);

    if (!derived_key || !iv) {
        return -3; // Memory allocation failed
    }

    // Initialize the PBKDF2 context with SHA-256 and a salt value of zero
    PBKDF2_CTX ctx;
    PBKDF2_init(&ctx, (const unsigned char *)password, password_len, NULL, 0);

    // Derive the key using PBKDF2 with SHA-256
    int iterations = 100000; // Adjustable iteration count for password hashing
    PBKDF2_keygen(&ctx, derived_key, &iterations);
    derived_key[AES_KEY_LENGTH] = '\0';

    // Generate a random initialization vector (IV)
    RAND_bytes(iv, AES_BLOCK_SIZE);

    // Store the derived key and IV in the module's state
    module->key = derived_key;
    module->iv = iv;
    module->initialized = 1;

    return 0; // Initialization successful
}

// Function to encrypt data using AES-256-CBC encryption
int EncryptionModuleEncrypt(EncryptionModuleState *module, const char *data, size_t data_len, unsigned char *encrypted_data) {
    if (!module || !data || data_len == 0 || !encrypted_data) {
        return -1; // Invalid input
    }

    if (!module->initialized) {
        return -2; // Module not initialized
    }

    // Initialize the AES-256-CBC context with the derived key and IV
    AES_CTX aes_ctx;
    AES_init(&aes_ctx, module->key, module->iv, AES_256_CBC);

    // Encrypt the data using AES-256-CBC
    int encrypted_len = AES_encrypt(&aes_ctx, (const unsigned char *)data, data_len, encrypted_data);
    if (encrypted_len < 0) {
        return -3; // Encryption failed
    }

    return encrypted_len;
}

// Function to reset the encryption module's state
void EncryptionModuleReset(EncryptionModuleState *module) {
    if (!module || !module->initialized) {
        return; // Module not initialized or already reset
    }

    // Free the derived key and IV
    free(module->key);
    free(module->iv);

    // Reset the module's state
    module->initialized = 0;
}

// Example usage:
int main() {
    EncryptionModuleState module;
    const char *password = "your_password";
    size_t password_len = strlen(password);
    const char *data = "Hello, World!";
    size_t data_len = strlen(data);

    if (EncryptionModuleInit(&module, password, password_len) < 0) {
        // Handle initialization error
    }

    unsigned char *encrypted_data = (unsigned char *)malloc(data_len + AES_BLOCK_SIZE);
    int encrypted_len = EncryptionModuleEncrypt(&module, data, data_len, encrypted_data);

    if (encrypted_len < 0) {
        // Handle encryption error
    } else {
        printf("Encrypted data: %s\n", encrypted_data);
    }

    EncryptionModuleReset(&module);

    return 0;
}
