    struct dirent* ent;
    int max_concurrent = 5; // adjust this value based on system resource constraints
    int ongoing_conversions = 0;

    // initialize log file for debugging purposes
    FILE* log_file = fopen("audio_pipeline.log", "w");
    if (log_file == NULL) {
        return FAILURE;
    }

    dir = opendir(source_dir);
    if (dir == NULL) {
        fclose(log_file);
        return FAILURE; // failed to open directory
    }

    while ((ent = readdir(dir)) != NULL) {
        char file_path[256];
        sprintf(file_path, "%s/%s", source_dir, ent->d_name);

        // skip directories and non-audio files
        if (strcmp(ent->d_type, "dir") == 0 || !strchr(file_path, '.') || strcmp(strrchr(file_path, '.'), ".")) {
            continue;
        }

        char* file_format = strrchr(file_path, '.');
        *file_format = '\0';
        char converted_file[256];
        sprintf(converted_file, "%s_%s.%s", output_dir, ent->d_name, target_ext);

        // batch conversions to prevent resource exhaustion
        if (ongoing_conversions < max_concurrent) {
            ongoing_conversions++;
            // launch external tool for conversion
            system(sprintf("audio_converter %s %s > /dev/null && mv %s %s", file_path, converted_file, file_path, converted_file));
            ongoing_conversions--;
        } else {
            printf("Waiting for concurrent conversions to complete...\n");
        }
    }

    closedir(dir);
    fclose(log_file);

    return SUCCESS;
}
