void organizeFiles(char* srcDir, char* targetDir, const FileRule rules[], int numRules) {
    DIR* dir = opendir(srcDir);
    if (dir == NULL) {
        fprintf(stderr, "Error opening source directory: %s\n", srcDir);
        return;
    }

    struct dirent* entry;
