        char filepath[MAX_FILENAMES];
        sprintf(filepath, "%s/%s", srcDir, entry->d_name);

        MediaType file_type = getFileType(entry->d_name);
        int resolution = -1; // placeholder for resolution detection

        for (int i = 0; i < numRules; i++) {
            if (strcmp(rule(extension).extension, entry->d_name + strlen(entry->d_name) - 4) == 0) {
                resolution = rule(i).minResolution;
                break;
            }
        }

        char* targetPath = malloc(strlen(targetDir) + strlen(rules[file_type].targetDir) + 1);
        strcpy(targetPath, targetDir);
        strcat(targetPath, rules[file_type].targetDir);

        // perform parallel file operations using POSIX threads
        pthread_t thread;
        pthread_create(&thread, NULL, moveFileToTarget, (void*)filepath);
        pthread_join(thread, NULL);

        free(targetPath);
    }

    closedir(dir);
}

