#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <pthread.h>

// Define the possible file types
typedef enum {
    FILE_TYPE_AUDIO,
    FILE_TYPE_VIDEO,
    FILE_TYPE_IMAGE
} FileType;

// Function to categorize and migrate files based on schema
int migrate_files(const char *source_dir, const char *target_dir) {
    // Initialize status code for success
    int status = 0;

    // Initialize threads array
    pthread_t threads[10]; // Assuming maximum of 10 concurrent threads

    // Create target directories if they don't exist
    mkdir(target_dir, S_IRWXU | S_IRGRP | S_IROTH);
    char *audio_dir = (char*)malloc(strlen(target_dir) + strlen("Audio") + 1);
    strcpy(audio_dir, target_dir);
    strcat(audio_dir, "/Audio");
    mkdir(audio_dir, S_IRWXU | S_IRGRP | S_IROTH);
    free(audio_dir);

    char *video_dir = (char*)malloc(strlen(target_dir) + strlen("Video") + 1);
    strcpy(video_dir, target_dir);
    strcat(video_dir, "/Video");
    mkdir(video_dir, S_IRWXU | S_IRGRP | S_IROTH);
    free(video_dir);

    char *image_dir = (char*)malloc(strlen(target_dir) + strlen("Image") + 1);
    strcpy(image_dir, target_dir);
    strcat(image_dir, "/Image");
    mkdir(image_dir, S_IRWXU | S_IRGRP | S_IROTH);
    free(image_dir);

    // Iterate through files in source directory
    DIR *dir = opendir(source_dir);
    if (dir == NULL) {
        status = -1;
    } else {
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            // Determine file type based on extension
            FileType file_type;
            char *extension = strrchr(ent->d_name, '.');
            if (extension != NULL) {
                if (strcmp(extension + 1, "mp3") == 0 || strcmp(extension + 1, "wav") == 0)
                    file_type = FILE_TYPE_AUDIO;
                else if (strcmp(extension + 1, "mp4") == 0 || strcmp(extension + 1, "avi") == 0)
                    file_type = FILE_TYPE_VIDEO;
                else if (strcmp(extension + 1, "jpg") == 0 || strcmp(extension + 1, "png") == 0)
                    file_type = FILE_TYPE_IMAGE;
                else {
                    status = -2; // Unexpected file type
                    continue;
                }
            } else {
                status = -3; // No extension found
                continue;
            }

            // Create a thread for each file to avoid blocking main thread
            pthread_create(&threads[status++], NULL, (void*)file_migration_thread, ent->d_name);
        }
        closedir(dir);
    }

    // Wait for all threads to finish
    for (int i = 0; i < status; i++)
        pthread_join(threads[i], NULL);

    return status;
}

// Function to handle file migration thread
void* file_migration_thread(void *file_name) {
    char *full_file_path = (char*)malloc(strlen(source_dir) + strlen((char*)file_name) + 1);
    strcpy(full_file_path, source_dir);
    strcat(full_file_path, "/");
    strcat(full_file_path, (char*)file_name);

    // Check if file exists
    struct stat file_stat;
    if (stat(full_file_path, &file_stat) == -1)
        return NULL; // File not found

    char *target_file_path = (char*)malloc(strlen(target_dir) + strlen("/Audio" / "Video" / "Image") + strlen((char*)file_name) + 1);
    if (file_stat.st_size > 1000000) { // Large file, consider moving to another directory
        strcpy(target_file_path, target_dir);
        strcat(target_file_path, "/Large");
    } else {
        char *audio_target_dir = (char*)malloc(strlen(target_dir) + strlen("/Audio") + 1);
        strcpy(audio_target_dir, target_dir);
        strcat(audio_target_dir, "/Audio");
        if (file_type == FILE_TYPE_AUDIO)
            strcpy(target_file_path, audio_target_dir);
        else if (file_type == FILE_TYPE_VIDEO)
            strcpy(target_file_path, target_dir);
        else
            strcpy(target_file_path, image_dir);

        free(audio_target_dir);
    }

    // Perform file copy or move based on schema
    if (rename(full_file_path, target_file_path) != 0) {
        return NULL; // Error during file migration
    }
    free(full_file_path);
    free(target_file_path);
}
