#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    char* key;
    void* value;
    int expireTime; // expiration time in seconds
} CacheItem;

typedef struct {
    int capacity;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int size;
    CacheItem** items;
    pthread_cond_t expiredCond;
} Cache;

Cache* cacheCreate(int capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->items = (CacheItem**)calloc(capacity, sizeof(CacheItem*));
    pthread_mutex_init(&cache->lock, NULL);
    pthread_cond_init(&cache->cond, NULL);
    pthread_cond_init(&cache->expiredCond, NULL);
    return cache;
}

void cacheDestroy(Cache* cache) {
    for(int i = 0; i < cache->size; i++) {
        free(cache->items[i]->key);
        free(cache->items[i]->value);
        free(cache->items[i]);
    }
    free(cache->items);
    pthread_mutex_destroy(&cache->lock);
    pthread_cond_destroy(&cache->cond);
    pthread_cond_destroy(&cache->expiredCond);
    free(cache);
}

void cacheAdd(Cache* cache, char* key, void* value, int expireTime) {
    CacheItem* item = (CacheItem*)malloc(sizeof(CacheItem));
    item->key = strdup(key);
    item->value = value;
    item->expireTime = expireTime;
    pthread_mutex_lock(&cache->lock);
    cache->items[cache->size] = item;
    cache->size++;
    if(cache->size > cache->capacity) {
        CacheItem* evictItem = cache->items[0];
        for(int i = 1; i < cache->size; i++) {
            cache->items[i-1] = cache->items[i];
        }
        pthread_mutex_unlock(&cache->lock);
        pthread_cond_signal(&cache->expiredCond);
    } else {
        pthread_mutex_unlock(&cache->lock);
    }
}

void* cacheGet(Cache* cache, char* key) {
    for(int i = 0; i < cache->size; i++) {
        if(strcmp(cache->items[i]->key, key) == 0) {
            return cache->items[i]->value;
        }
    }
    return NULL;
}

void cacheExpire(Cache* cache, int expireTime) {
    for(int i = 0; i < cache->size; i++) {
        if(cache->items[i]->expireTime <= expireTime) {
            free(cache->items[i]->key);
            free(cache->items[i]->value);
            free(cache->items[i]);
            pthread_mutex_lock(&cache->lock);
            for(int j = i; j < cache->size-1; j++) {
                cache->items[j] = cache->items[j+1];
            }
            cache->size--;
            pthread_mutex_unlock(&cache->lock);
        }
    }
}

void* cacheNotifyExpired(Cache* cache) {
    pthread_cond_signal(&cache->expiredCond);
}
