#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>

// Configuration settings
#define BATCH_SIZE 5
#define MAX_RETRIES 3
#define LOG_FILE "conversion_log.txt"

typedef enum {
    SUCCESS,
    FAILURE,
    PARTIAL_SUCCESS
} status_code;

status_code process_audio_files(const char *source_dir, const char *target_ext, const char *output_dir) {
    DIR *dir;
    struct dirent *ent;
    int file_count = 0;
    int retry_count = 0;
    FILE *log_file;

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        return FAILURE; // Log initialization failed
    }

    // Process files in the source directory
    dir = opendir(source_dir);
    if (dir == NULL) {
        fprintf(log_file, "Error: Unable to open directory '%s'\n", source_dir);
        fclose(log_file);
        return FAILURE;
    }

    while ((ent = readdir(dir)) != NULL) {
        char file_path[256];
        sprintf(file_path, "%s/%s", source_dir, ent->d_name);

        // Check if the file is an audio file
        if (strrchr(ent->d_name, '.') && strstr(ent->d_name, ".wav")) {
            file_count++;

            for (int i = 0; i < BATCH_SIZE && file_count > 0; i++) {
                // Convert each file to target format using external tool
                int status = convert_file(file_path, target_ext, output_dir);
                if (status == FAILURE) {
                    retry_count++;
                    continue;
                }

                if (status != SUCCESS) {
                    partial_success++;
                }
            }
        }
    }

    closedir(dir);

    // Handle any remaining files after batch processing
    for (int i = 0; i < file_count % BATCH_SIZE && file_count > 0; i++) {
        int status = convert_file(file_path, target_ext, output_dir);
        if (status == FAILURE) {
            retry_count++;
        }
    }

    fclose(log_file);

    // Handle any retries
    for (int i = 0; i < MAX_RETRIES && retry_count > 0; i++) {
        int status = convert_file(file_path, target_ext, output_dir);
        if (status == FAILURE) {
            retry_count--;
        }
    }

    return (retry_count > 0) ? PARTIAL_SUCCESS : SUCCESS;
}

int convert_file(const char *file_path, const char *target_ext, const char *output_dir) {
    // Execute external audio processing tool
    int status = system("ffmpeg -i file.wav file.mp3");

    if (status != 0) {
        return FAILURE; // Conversion failed
    }

    // Check for partial success (e.g., some files not converted)
    if (!file_path || !target_ext || !output_dir) {
        return PARTIAL_SUCCESS;
    }

    return SUCCESS;
}

int main() {
    status_code result = process_audio_files("input", "wav", "output");
    printf("Conversion status: %s\n", (result == SUCCESS) ? "Successful" : (result == PARTIAL_SUCCESS) ? "Partial Success" : "Failed");

    return 0;
}
