#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

class MemoryManager {
public:
    MemoryManager(int maxRecords = 1000, int keyThreshold = 10000)
        : maxRecords_(maxRecords), keyThreshold_(keyThreshold) {}

    bool allocateMemory(int numRecords, int* keys, long* offsets) {
        if (numRecords > maxRecords_ || numRecords < 1) return false;

        for (int i = 0; i < numRecords; ++i) {
            if (keys[i] > keyThreshold_) return false;
        }

        // Dynamic memory allocation based on maximum size
        if (numRecords > maxRecords_) {
            maxRecords_ = numRecords;
            keys_ = new int[maxRecords_];
            offsets_ = new long[maxRecords_];

            std::copy(keys, keys + numRecords, keys_);
            std::sort(offsets_, offsets + numRecords);

            return true;
        }

        // Static memory allocation for less than maximum size
        if (numRecords <= maxRecords_) {
            keys_ = new int[numRecords];
            offsets_ = new long[numRecords];

            std::copy(keys, keys + numRecords, keys_);
            std::sort(offsets_, offsets + numRecords);

            return true;
        }

        return false;
    }

    bool validateSum(int* keys) {
        int sum = 0;

        for (int i = 0; i < maxRecords_; ++i) {
            sum += keys[i];
        }

        if (sum > keyThreshold_) {
            // Reallocation based on the new sum
            int newMaxRecords = sum / 100 + 1;
            int* newKeys = new int[newMaxRecords];
            long* newOffsets = new long[newMaxRecords];

            std::copy(keys, keys + maxRecords_, newKeys);
            std::sort(newOffsets, newOffsets + maxRecords_);
            delete[] keys_;
            delete[] offsets_;

            keys_ = newKeys;
            offsets_ = newOffsets;

            return true;
        }

        return false;
    }

    void freeMemory() {
        if (keys_) delete[] keys_;
        if (offsets_) delete[] offsets_;
    }

private:
    int maxRecords_, keyThreshold_;
    int* keys_ = nullptr;
    long* offsets_ = nullptr;
