#include <math.h>

double calcMean(double* arr, int n) {
    double sum = 0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }
    return sum / n;
}

double calcStdDev(double* arr, int n, double mean) {
    double variance = 0;
    for (int i = 0; i < n; i++) {
        variance += pow(arr[i] - mean, 2);
    }
    return sqrt(variance / n);
}

void printStats(double* arr, int n) {
    if (n == 0) {
        printf("No data available.\n");
    } else {
        double mean = calcMean(arr, n);
        double stdDev = calcStdDev(arr, n, mean);
        printf("Mean: %.2f\n", mean);
        printf("Standard Deviation: %.2f\n", stdDev);
    }
}

int main() {
    int n;
    scanf("%d", &n);

    if (n < 1 || n > 1000) {
        printf("Invalid input. Please enter a value between 1 and 1000.\n");
        return 1;
    }

    double* arr = (double*)malloc(n * sizeof(double));
    if (!arr) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    for (int i = 0; i < n; i++) {
        scanf("%lf", &arr[i]);
    }

    printStats(arr, n);

    free(arr);
    return 0;
}
