int log_ingestion(char* src_dir, char* db_conn_str, char* schema_name) {
    // Initialize variables
    int batch_size = 100;
    int retries = 3;

    // Establish database connection
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, db_conn_str, NULL)) {
        printf("Failed to connect to the database: %s\n", mysql_error(conn));
        return -1;
    }

    // Initialize batch
    char **batch = (char **)malloc(batch_size * sizeof(char *));
    int batch_count = 0;

    // Iterate over files in source directory
    DIR *dir = opendir(src_dir);
    if (dir == NULL) {
        printf("Failed to open the directory: %s\n", src_dir);
        return -1;
    }
    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        // Check file type and format
        if (ent->d_type == DT_REG && strcmp(ent->d_name + strlen(ent->d_name) - 4, ".log") == 0) {
            char *file_path = malloc(strlen(src_dir) + strlen(ent->d_name) + 1);
            sprintf(file_path, "%s/%s", src_dir, ent->d_name);

            // Parse log file
            FILE *fp = fopen(file_path, "r");
            if (fp == NULL) {
                printf("Failed to open the file: %s\n", file_path);
                continue;
            }
            char line[1024];
            while (fgets(line, sizeof(line), fp)) {
                // Extract specific fields for indexing
                // ...

                // Add event to batch
                if (batch_count < batch_size) {
                    batch[batch_count] = malloc(strlen(line) + 1);
                    strcpy(batch[batch_count], line);
                    batch_count++;
                }
            }
            fclose(fp);
            free(file_path);

            // Commit batch and handle errors
            int i;
            for (i = 0; i < batch_count; i++) {
                if (!mysql_query(conn, "INSERT INTO table_name SET ...")) {
                    printf("Inserted %d events into the database\n", i + 1);
                } else {
                    printf("Failed to insert event: %s\n", mysql_error(conn));
                    // Retry failed insertion
                    for (int j = 0; j < retries && !mysql_query(conn, "INSERT INTO table_name SET ...")); {
                        if (!mysql_query(conn, "INSERT INTO table_name SET ...")) break;
                    }
                    if (j == retries) {
                        printf("Failed to insert event after %d retries: %s\n", retries, mysql_error(conn));
                        return -1;
                    }
                }
            }

            // Clear batch
            for (i = 0; i < batch_count; i++) {
                free(batch[i]);
            }
            free(batch);
            batch_count = 0;
        }
    }
    closedir(dir);

    // Commit remaining batch and handle errors
    for (int i = 0; i < batch_count; i++) {
        if (!mysql_query(conn, "INSERT INTO table_name SET ...")) {
            printf("Inserted %d events into the database\n", i + 1);
        } else {
            printf("Failed to insert event: %s\n", mysql_error(conn));
            // Retry failed insertion
            for (int j = 0; j < retries && !mysql_query(conn, "INSERT INTO table_name SET ...")); {
                if (!mysql_query(conn, "INSERT INTO table_name SET ...")) break;
            }
            if (j == retries) {
                printf("Failed to insert event after %d retries: %s\n", retries, mysql_error(conn));
                return -1;
            }
        }
    }

    // Close database connection
    mysql_close(conn);

    return 0;
}
