Status organizeAndModifyMediaFiles(std::forward_list<std::string>& mediaFileList, const std::string& sourceDirectory, const std::string& targetDirectory, const std::vector<std::pair<std::string, std::string>>& rules, const std::string& specificFileName, const std::string& desiredInsertionPoint) {
