            // Organize and modify media files
            for (int j = i; j < std::min(i + numThreads, mediaFileList.size()); ++j) {
                const std::string& filePath = mediaFileList[j];
                if (!filePath.empty()) {
                    try {
                        // Categorize and organize the media files
