import os
import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
from queue import Queue

class FileHashingSystem:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.queue = Queue()
        self.threads = []
        self.hash_results = {}
        self.total_files = 0
        self.completed_files = 0
        self.start_time = None
        self.concurrent_threads = 10

    def start(self, file_paths):
        if not isinstance(file_paths, list) or len(file_paths) == 0:
            return

        for path in file_paths:
            if os.path.isfile(path):
                self.queue.put((path, 0))
            elif os.path.isdir(path):
                self.logger.warning(f"Skipping directory: {path}")
            else:
                self.logger.warning(f"File not found: {path}")

        with ThreadPoolExecutor(max_workers=self.concurrent_threads) as executor:
            futures = []
            for _ in range(self.concurrent_threads):
                self.threads.append(executor.submit(self.hash_file))

            while True:
                done, _ = waiting_done = as_completed(futures, timeout=1)
                for future in done:
                    file_path, offset = future.result()
                    if file_path not in self.hash_results:
                        self.hash_results[file_path] = None
                    self.completed_files += 1
                    self.logger.info(f"Completed hashing: {file_path}")

                    if len(self.threads) == 0 and len(self.queue.empty()):
                        break

                if len(self.threads) == 0 and self.queue.empty():
                    break

            self.start_time = None

    def hash_file(self):
        file_path, offset = self.queue.get()
        self.logger.info(f"Hashing: {file_path}")

        try:
            with open(file_path, 'rb') as f:
                md5 = hashlib.md5()
                chunk_size = 1024 * 1024
                while True:
                    chunk = f.read(chunk_size)
                    if not chunk:
                        break

                    md5.update(chunk)

                self.hash_results[file_path] = md5.hexdigest()

        except OSError as e:
            self.logger.error(f"Error reading file: {file_path}, {e}")

        finally:
            self.queue.task_done()

    def stop(self):
        for thread in self.threads:
            thread.cancel()
        self.queue.join()
        self.logger.info("File hashing system stopped.")

    def get_progress(self):
        if not self.start_time:
            self.start_time = time.time()

        total_seconds = time.time() - self.start_time
        estimated_time_remaining = (total_files - completed_files) / completed_files * total_seconds

        return {
            "completed_files": completed_files,
            "total_files": total_files,
            "estimated_time_remaining": str(timedelta(seconds=estimated_time_remaining))
