```python
import hashlib
import threading
import time
from functools import lru_cache

class HashCalculator:
    def __init__(self, max_concurrent_threads=5):
        self.max_concurrent_threads = max_concurrent_threads
        self.cache = {}
        self.thread_pool = threading.ThreadPool(self.max_concurrent_threads)

    @lru_cache(maxsize=None)
    def calculate_hash(self, file_path):
        if not isinstance(file_path, str) or not file_path.endswith('.md5'):
            raise ValueError("Invalid file path")
        try:
            hash_object = hashlib.md5()
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    hash_object.update(chunk)
            return hash_object.hexdigest()
        except Exception as e:
            print(f"Error calculating hash for {file_path}: {str(e)}")
            return None

    def calculate_hashes_concurrently(self, file_paths):
        results = []
        threads = []

        for file_path in file_paths:
            thread = self.thread_pool.apply_async(self.calculate_hash, (file_path,))
            threads.append(thread)

        for thread in threads:
            result = thread.get()
            if result is not None:
                results.append(result)

        return results

    def close(self):
        self.thread_pool.join()

class PerformanceMonitor:
    def __init__(self):
        self.start_time = time.time()

    def update(self, elapsed_time=None):
        if elapsed_time is None:
            elapsed_time = time.time() - self.start_time
        print(f"Elapsed time: {elapsed_time:.2f} seconds")

# Example usage:
calculator = HashCalculator()
file_paths = ['path/to/file1.md5', 'path/to/file2.md5', ...]
results = calculator.calculate_hashes_concurrently(file_paths)
print(results)

monitor = PerformanceMonitor()
monitor.update()  # monitor the performance
calculator.close()

```

