    private readonly int _cacheSize;
    private readonly DataTable[] _dataTables;
    private readonly object _lock = new object();

    public HashCalculator(int maxConcurrentThreads, int cacheSize)
    {
        _maxConcurrentThreads = maxConcurrentThreads;
        _cacheSize = cacheSize;
        _dataTables = new DataTable[maxConcurrentThreads];
    }

    public void CalculateHashes(byte[][] byteArrays)
    {
        var tasks = new List<Task>();

        foreach (var byteArray in byteArrays)
        {
            Task task = Task.Run(() =>
            {
                try
                {
                    using (var ms = new MemoryStream(byteArray))
                    {
                        using (var sr = new StreamReader(ms))
                        {
                            string query = sr.ReadLine();
                            using (var conn = GetConnection())
                            {
                                using (var cmd = new SqlCommand(query, conn))
                                {
                                    using (var reader = cmd.ExecuteReader(CommandBehavior.CloseConnection))
                                    {
                                        // Process the result
                                        DataTable dt = _dataTables[Task.Current.Id % _maxConcurrentThreads];
                                        if (dt != null)
