using System;
using System.IO;
using System.Security.Cryptography;
using Microsoft.Azure.Services.AppConfiguration;

public class BatchHasher
{
    private readonly AppConfiguration _appConfig;
    private readonly string _cacheFile = "hash_cache.json";
    private readonly string _logLevel = "ERROR";

    public (string, string) CalculateHashes(byte[][] batches)
    {
        var md5Provider = new MD5CryptoServiceProvider();
        var sha256Provider = new SHA256CryptoServiceProvider();

        foreach (var batch in batches)
        {
            using (var ms = new MemoryStream())
            {
                using (var cryptoStream = new CryptoStream(ms, md5Provider))
                {
                    foreach (var chunk in batch)
                    {
                        cryptoStream.Write(chunk, 0, chunk.Length);
                    }
                }

                var md5Hash = BitConverter.ToString(md5Provider.Hash).Replace("-", "").ToLower();
                var sha256Hash = BitConverter.ToString(sha256Provider.ComputeHash(ms.ToArray())).Replace("-", "").ToLower();

                _appConfig.Logger.Log(_logLevel, "Hashed batch");
            }
        }

        return (md5Hash, sha256Hash);
    }
}
