import aiohttp

async def compute_md5(file_path):
    md5_hash = hashlib.md5()

    chunk_size = 4096  # adjust dynamically based on file size and resources

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            md5_hash.update(chunk)

