require_once 'vendor/autoload.php';

use GuzzleHttp\Client;

function getRealTimeWeatherData($location) {
    $apiUrl = 'https://weather-api.com/data/v1/current';
    $apiKey = getenv('WEATHER_API_KEY');

    // Handle rate limiting and exponential backoff
    $maxAttempts = 5;
    for ($attempts = 0; $attempts < $maxAttempts; $attempts++) {
        try {
            $client = new Client();
            $response = $client->request('GET', $apiUrl, [
                'query' => ['location' => $location],
                'headers' => ['Authorization' => "Bearer $apiKey"],
            ]);

            if ($response->getStatusCode() == 200) {
                // Parse and return weather data
                $weatherData = json_decode($response->getBody()->getContents(), true);
                return $weatherData;
            } elseif ($response->getStatusCode() == 429 || $response->getStatusCode() == 503) {
                // Handle rate limiting or service outage
                sleep(pow(2, $attempts));
            } else {
                // Handle unexpected server response
                throw new Exception("Unexpected server response: " . $response->getStatusCode());
            }
        } catch (GuzzleHttp\Exception\RequestException $e) {
            // Handle network errors and connection issues
            if ($e->getCode() == 429 || $e->getCode() == 503) {
                sleep(pow(2, $attempts));
            } else {
                throw $e;
            }
        }
    }

    // If all attempts fail, return an error message
    return 'Failed to retrieve weather data';
}

function batchProcessLocations($locations) {
    $batchResults = [];
    foreach ($locations as $location) {
        $weatherData = getRealTimeWeatherData($location);
        $batchResults[] = $weatherData;
    }

    return $batchResults;
}

// Example usage
$location = 'New York';
$weatherData = getRealTimeWeatherData($location);
var_dump($weatherData);

$locations = ['Los Angeles', 'Chicago', 'Houston'];
$batchResults = batchProcessLocations($locations);
var_dump($batchResults);
