import concurrent.futures
import logging
import os
import requests
from typing import Dict

class Downloader:
    def __init__(self):
        self.log = logging.getLogger(__name__)
        self.lock = concurrent.futures.Lock()

    def download(self, urls: list[str], directory: str, max_concurrent_threads: int = None) -> Dict[str, str]:
        results = {}
        if max_concurrent_threads is None:
            max_concurrent_threads = min(len(urls), os.cpu_count() or 1)
        with concurrent.futures.ThreadPoolExecutor(max_workers=max_concurrent_threads) as executor:
            futures = {executor.submit(self._download, url, directory): url for url in urls}
            for future in concurrent.futures.as_completed(futures):
                try:
                    results[future.result()] = f"{directory}/{futures[future]}"
                except Exception as e:
                    self.log.error(f"Error downloading {futures[future]}: {str(e)}")
        return results

    def _download(self, url: str, directory: str) -> str:
        try:
            response = requests.get(url, stream=True, timeout=5)
            if 200 <= response.status_code < 300:
                filename = os.path.basename(url)
                with open(os.path.join(directory, filename), 'wb') as file:
                    for chunk in response.iter_content(chunk_size=8192):
                        file.write(chunk)
                return url
            elif response.status_code == 301 or response.status_code == 302:
                self.log.warning(f"Redirect detected: {url} -> {response.url}")
                return f"{directory}/{os.path.basename(response.url)}"
        except requests.exceptions.IOError as e:
            self.log.error(f"I/O error downloading {url}: {str(e)}")
        except requests.exceptions.RequestException as e:
            self.log.error(f"Error downloading {url}: {str(e)}")
        return f"{url} - Download failed"

    def _streaming_download(self, url: str, directory: str, offset: int = 0) -> None:
        try:
            response = requests.get(url, stream=True, timeout=5)
            if 200 <= response.status_code < 300:
                filename = os.path.basename(url)
                with open(os.path.join(directory, filename), 'ab') as file:
                    for chunk in response.iter_content(chunk_size=8192):
                        file.write(chunk)
        except requests.exceptions.IOError as e:
            self.log.error(f"I/O error downloading {url}: {str(e)}")
        except requests.exceptions.RequestException as e:
            self.log.error(f"Error downloading {url}: {str(e)}")

    def _resume_download(self, url: str, directory: str, offset: int) -> None:
        try:
            response = requests.get(url, stream=True, timeout=5)
            if 200 <= response.status_code < 300:
                filename = os.path.basename(url)
                with open(os.path.join(directory, filename), 'ab') as file:
                    file.seek(offset)
                    for chunk in response.iter_content(chunk_size=8192):
                        file.write(chunk)
        except requests.exceptions.IOError as e:
            self.log.error(f"I/O error downloading {url}: {str(e)}")
        except requests.exceptions.RequestException as e:
            self.log.error(f"Error downloading {url}: {str(e)}")

    def _download_progress(self, total_urls: int, completed_urls: int) -> None:
        print(f"Completed downloads: {completed_urls}/{total_urls} ({(completed_urls / total_urls * 100):.2f}%), Estimated time remaining: ")
