#include <stdio.h>
#include <stdlib.h>
#include <math.h>

// Function to calculate mean and standard deviation
void calculateStatistics(float* numbers, int size) {
    float sum = 0;
    float mean = 0;
    float variance = 0;

    // Calculate the mean
    for (int i = 0; i < size; i++) {
        sum += numbers[i];
    }
    mean = sum / size;

    // Calculate the variance and standard deviation
    for (int i = 0; i < size; i++) {
        float diff = numbers[i] - mean;
        variance += pow(diff, 2);
    }
    float stdDev = sqrt(variance / size);

    printf("Mean: %.2f\n", mean);
    printf("Standard Deviation: %.2f\n", stdDev);
}

// Function to process the input and calculate statistics
void processInput(int maxElements) {
    int count = 0;
    float* numbers = NULL;

    while (1) {
        float num;
        if (~scanf("%f", &num)) {
            // Handle malformed input
            fprintf(stderr, "Error: Invalid input format.\n");
            continue;
        }

        // Validate the number and adjust it to be within the specified range
        if (num < -10000) {
            num = -10000;
        } else if (num > 10000) {
            num = 10000;
        }

        // Dynamically allocate memory for the array
        numbers = realloc(numbers, (count + 1) * sizeof(float));
        numbers[count] = num;

        count++;

        if (count >= maxElements) {
            break;
        }
    }

    // Process the input data
    calculateStatistics(numbers, count);

    // Free dynamically allocated memory
    free(numbers);
}

int main() {
    processInput(1000);

    return 0;
}
