import hashlib
import logging
import os

def calculate_file_hash(file_path):
    md5 = hashlib.md5()
    file_size = os.path.getsize(file_path)
    chunk_size = 1024 * 1024  # 1MB chunks for large files
    with open(file_path, 'rb') as f:
        start_time = logging.getLogger().info(f"Hash generation started at {file_path}")
        progress = 0
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            md5.update(chunk)
            progress += len(chunk)
            logger.info(f"{progress / file_size * 100:.2f}% complete")
    end_time = logging.getLogger().info(f"Hash generation completed at {file_path}")
    try:
        checksum = int(input("Enter the expected checksum: "))
        if checksum != int.from_bytes(md5.digest(), 'big'):
            raise ValueError("Checksum mismatch")
    except ValueError as e:
        logger.error(str(e))
        raise
    return md5.hexdigest()
```

