['Here is the Python code for calculating SHA-256 hash of multiple files concurrently using a thread pool with a configurable maximum number of concurrent threads:

```python
import os
import hashlib
import threading
from queue import Queue
import logging

class Hasher:
    def __init__(self, max_threads=10):
        self.max_threads = max_threads
        self.cache = {}
        self.lock = threading.Lock()
        self.queue = Queue()

    def add_file(self, file_path):
        if not os.path.exists(file_path):
            return False
        with self.lock:
            if file_path in self.cache:
                return True
        self.queue.put((file_path, hashlib.sha256()))

    def start_hashing(self):
        for _ in range(self.max_threads):
            thread = threading.Thread(target=self.hash_file)
            thread.start()

    def hash_file(self):
        while not self.queue.empty():
            file_path, sha256 = self.queue.get()
            try:
                with open(file_path, 'rb') as file:
                    content = file.read()
                    hashed_content = sha256.update(content)
                    with self.lock:
                        self.cache[file_path] = str(hashed_content.hex())
            except Exception as e:
                logging.error(f"Error hashing {file_path}: {str(e)}")

    def get_hash(self, file_path):
        if not os.path.exists(file_path):
            return None
        with self.lock:
            if file_path in self.cache:
                return self.cache[file_path]
        return None

# Example usage:
hasher = Hasher()
hasher.add_file("file1.txt")
hasher.add_file("file2.txt")
hasher.start_hashing()

