import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ForkJoinPool;

public class FileHashCalculator {

    public static Map<String, String> calculateFileHashes(List<String> filePaths, int minFileSize) {
        ExecutorService executor = Executors.newWorkStealingPool();
        ForkJoinPool forkJoinPool = new ForkJoinPool();

        Map<String, String> fileHashes = new HashMap<>();
        long totalSize = 0;

        for (String filePath : filePaths) {
            File file = new File(filePath);
            if (!file.exists() || !file.isFile()) {
                continue;
            }
            if (!file.canRead()) {
                System.out.println("Warning: cannot read file " + filePath);
                continue;
            }

            long fileSize = file.length();
            if (fileSize < minFileSize) {
                continue;
            }

            totalSize += fileSize;

            TryToCalculateFileHash task = new TryToCalculateFileHash(filePath, file);
            try {
                String hash = forkJoinPool.submit(task).get();
                fileHashes.put(filePath, hash);
            } catch (ExecutionException | InterruptedException e) {
                System.out.println("Error processing file " + filePath + ": " + e.getMessage());
            }
        }

        executor.shutdown();

        // Report progress
        int progressStep = (int) Math.ceil(totalSize / 10.0);
        for (long i = 0; i <= totalSize; i += progressStep) {
            System.out.print("\rProcessing... " + String.format("%.1f%%", (i * 100) / totalSize));
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                break;
            }
        }
        System.out.println();

        return fileHashes;
    }

    private static class TryToCalculateFileHash implements ForkJoinTask<String> {

        private final String filePath;
        private final File file;

        public TryToCalculateFileHash(String filePath, File file) {
            this.filePath = filePath;
            this.file = file;
        }

        @Override
        public String getRawResult() throws ExecutionException, InterruptedException {
            try (FileInputStream fis = new FileInputStream(file)) {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                return bytesToHex(md.digest());
            } catch (IOException e) {
                throw new ExecutionException(e);
            }
        }

        @Override
        public String join() {
            return getRawResult();
        }
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder builder = new StringBuilder();
        for (byte b : bytes) {
            builder.append(String.format("%02x", b));
        }
        return builder.toString();
    }
}
