#include <string.h>
#include <json-c/json.h>

typedef struct {
    int id;
    double value;
    struct item* next;
} item;

item* allocate_item() {
    item* temp = (item*)malloc(sizeof(item));
    if(temp == NULL) {
        return NULL;
    }
    temp->next = NULL;
    return temp;
}

void free_list(item** head_ref) {
    item* current = *head_ref;
    item* next_temp;

    while(current != NULL) {
        next_temp = current->next;
        free(current);
        current = next_temp;
    }

    *head_ref = NULL;
}

int parse_json(char* json_file, item** head_ref) {
    json_object* obj;
    int id;
    double value;

    if((obj = json_object_from_file(json_file)) == NULL) {
        return -1; // error parsing JSON
    }

    json_object_iter* iter;
    for(iter = json_object_iter(obj); iter != NULL; iter = json_object_iter_next(obj, iter)) {
        id = json_object_get_int(iter->value);
        value = json_object_get_double(iter->value);

        item* temp = allocate_item();
        if(temp == NULL) {
            return -1; // memory allocation failed
        }
        temp->id = id;
        temp->value = value;

        if(*head_ref == NULL) {
            *head_ref = temp;
        } else {
            item* last = *head_ref;
            while(last->next != NULL) {
                last = last->next;
            }
            last->next = temp;
        }
    }

    json_object_put(obj);
    return 0; // success
}

int check_performance_condition(item* head, double threshold) {
    double sum = 0.0;
    int count = 0;

    item* current = head;
    while(current != NULL) {
        sum += current->value;
        count++;
        current = current->next;
    }

    if(count > 0 && sum / count >= threshold) {
        return 1; // condition met
    } else {
        return 0; // condition not met
    }
}

void log_event(int event, char* message) {
    static int count = 0;
    static char buffer[1024];

    if(event == 1) {
        sprintf(buffer, "Performance condition met (id: %d): %s", ++count, message);
    } else {
        sprintf(buffer, "Error: %s", message);
    }

    va_list ap;
    va_start(ap, message);
    vsnprintf(buffer + strlen(buffer), 1024 - strlen(buffer), buffer + strlen(buffer), ap);
    va_end(ap);

    printf("%s\n", buffer);
}

int main() {
    item* head = NULL;

    if(parse_json("data.json", &head) != 0) {
        return -1; // error parsing JSON
    }

    int condition_met = check_performance_condition(head, 2.5);

    if(condition_met) {
        log_event(1, "The average value exceeded the threshold.");
    } else {
        log_event(0, "No issues detected.");
    }

    free_list(&head);
    return 0;
}
