void* malloc_checked(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

item* create_item(int id, float value) {
    item* new_item = (item*)malloc_checked(sizeof(item));
    new_item->id = id;
    new_item->value = value;
    new_item->next = NULL;
    return new_item;
}

void free_list(item** head_ref) {
    item* current = *head_ref;
    item* next_temp;

    while (current != NULL) {
        next_temp = current->next;
        free(current);
        current = next_temp;
    }

    *head_ref = NULL;
}

int update_ids(item** head_ref, float threshold) {
    int updated_count = 0;
    float average_value = 0.0;

    item* current = *head_ref;
    while (current != NULL) {
        average_value += current->value;
        if (average_value > threshold) {
            current->id++;
            updated_count++;
        }
        current = current->next;
    }

    printf("Updated %d items\n", updated_count);

    return 0;
}

int main() {
    json_object* root = json_object_from_file("data.json");

    item* head = NULL;

    // Initialize the list with data from the JSON file
    json_object_iterator* iter = json_object_iterate(root, "items");
    while (iter) {
        int id = json_object_get_int(iter->key);
        float value = json_object_get_double(iter->key + "/value");
        head = create_item(id, value);
        iter = json_object_iterate(root, NULL);
    }

    // Update the list based on a performance-critical condition
    if (update_ids(&head, 10.0f)) {
        printf("Error updating IDs\n");
    }

    free_list(&head);

    return 0;
}

