```python
import hashlib
import os

def calculate_md5_large_file(file_path):
    chunk_size = 1024 * 1024  # default to 1MB chunks
    file_size = os.path.getsize(file_path)

    md5_hash = hashlib.md5()

    with open(file_path, 'rb') as f:
        for i, chunk in enumerate(iter(lambda: f.read(chunk_size), b'')):
            if (i + 1) * chunk_size >= file_size:
                remaining_bytes = file_size % chunk_size
                md5_hash.update(chunk[:remaining_bytes])
