import mmap
import logging

def process_large_file(file_path, target_file_size, chunk_size):
    with open(file_path, 'r+b') as file:
        mm = mmap.mmap(file.fileno(), 0, access=mmap.ACCESS_READ)

        if target_file_size < 0:
            raise ValueError("Target file size must be non-negative.")

        if chunk_size <= 0:
            raise ValueError("Chunk size must be positive.")

        transformation_function = None

        logging_level = logging.INFO
        log_every_n_percent = 10

        bytes_processed = 0
        total_bytes = len(mm)

        while bytes_processed < target_file_size and mm.tell() < total_bytes:
            chunk = mm.read(min(chunk_size, total_bytes - mm.tell()))

            if transformation_function is not None:
                chunk = transformation_function(chunk)

            bytes_written = 0

            while bytes_written < len(chunk):
                file.seek(mm.tell())
                file.write(chunk[bytes_written:bytes-written + min(len(chunk) - bytes_written, chunk_size)])
                bytes_written += min(len(chunk) - bytes_written, chunk_size)

            bytes_processed += len(chunk)

            if (bytes_processed / total_bytes) * 100 % log_every_n_percent == 0:
                logging.log(logging_level, f"Processed {bytes_processed / total_bytes * 100}% of the file.")

        mm.close()
        file.close()

        return bytes_processed
