import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.function.Function;

public class FileProcessor {
    public static long transformAndProcessFile(String filePath, long targetFileSize, int chunkSize) throws IOException {
        if (targetFileSize < 0) {
            throw new IllegalArgumentException("Target file size must be non-negative.");
        }

        if (chunkSize <= 0) {
            throw new IllegalArgumentExeption("Chunk size must be positive.");
        }

        Function<byte[], byte[]> transformationFunction = null;

        int logEveryNPercent = 10;
        int loggingLevel = Integer.parseInt(System.getProperty("logging.level", "INFO"));

        long bytesRead = 0;
        long totalBytes = Files.size(Paths.get(filePath));

        try (java.nio.file.FileChannel fileChannel = java.nio.file.Files.channel(Files.readAllBytes(Paths.get(filePath)))) {
            while (bytesRead < targetFileSize && fileChannel.position() < totalBytes) {
                byte[] chunk = new byte[Math.min(chunkSize, (int) (totalBytes - fileChannel.position()))];
                fileChannel.read(chunk);

                if (transformationFunction != null) {
                    chunk = transformationFunction.apply(chunk);
                }

                long bytesWritten = 0;

                while (bytesWritten < chunk.length) {
                    fileChannel.position(fileChannel.position() + bytesWritten);
                    fileChannel.write(chunk, 0, Math.min(chunk.length - bytesWritten, chunkSize));
                    bytesWritten += Math.min(chunk.length - bytesWritten, chunkSize);
                }

                bytesRead += chunk.length;

                if ((bytesRead / totalBytes) * 100 % logEveryNPercent == 0) {
                    System.out.println("Processed " + (bytesRead / totalBytes * 100) + "% of the file.");
                }
            }
        }

        return bytesRead;
    }
}
