import requests
from datetime import datetime
from collections import defaultdict
from threading import Lock
import logging

RATE_LIMITING_ALGORITHMS = ['fixed_rate', 'token_bucket']

class RateLimiter:
    def __init__(self, algorithm='fixed_rate', rate=100, burst=10):
        self.algorithm = algorithm
        self.rate = rate
        self.burst = burst
        self.lock = Lock()
        if self.algorithm == 'fixed_rate':
            self.requests_made = defaultdict(int)
        elif self.algorithm == 'token_bucket':
            self.tokens = rate

    def _process_request(self, ip):
        with self.lock:
            if self.algorithm == 'fixed_rate':
                remaining_requests = self.rate - self.requests_made[ip]
                self.requests_made[ip] += 1
                return remaining_requests > 0
            elif self.algorithm == 'token_bucket':
                self.tokens -= 1
                return self.tokens >= 0

    def _log_request_processing_time(self, start_time):
        end_time = datetime.now()
        processing_time = (end_time - start_time).microseconds / 1000.0
        logging.info(f'Request processed in {processing_time} ms')

    def rate_limit(self, ip):
        if self._process_request(ip):
            return True
        else:
            logging.warning('Rate limit exceeded for IP: ' + ip)
            return False

def process_request(ip, start_time):
    rate_limiter = RateLimiter()
    if rate_limiter.rate_limit(ip):
        # Process request here
        end_time = datetime.now()
        processing_time = (end_time - start_time).microseconds / 1000.0
        logging.info(f'Request processed in {processing_time} ms')
    else:
        print('Rate limit exceeded for IP: ' + ip)
