using System;
using System.Collections.Generic;
using System.Threading;

public enum RateLimitingAlgorithm { FixedRate, TokenBucket }

public class RequestThrottler
{
    private readonly object _lock = new object();
    private readonly Dictionary<string, long> _requestsMade = new Dictionary<string, long>();
    private readonly Dictionary<string, long> _tokens = new Dictionary<string, long>();
    private readonly RateLimitingAlgorithm _algorithm;
    private readonly int _rate;
    private readonly int _burst;

    public RequestThrottler(RateLimitingAlgorithm algorithm, int rate, int burst)
    {
        _algorithm = algorithm;
        _rate = rate;
        _burst = burst;
    }

    public bool RateLimit(string ip)
    {
        lock (_lock)
        {
            if (_algorithm == RateLimitingAlgorithm.FixedRate)
            {
                long remainingRequests = _rate - _requestsMade[ip];
                _requestsMade[ip] += 1;
                return remainingRequests > 0;
            }
            else if (_algorithm == RateLimitingAlgorithm.TokenBucket)
            {
                _tokens[ip]--;
                return _tokens[ip] >= 0;
            }
        }
    }

    public void LogRequestProcessingTime(DateTime startDateTime)
    {
        DateTime endDateTime = DateTime.Now;
        TimeSpan processingTime = endDateTime - startDateTime;
        Console.WriteLine($"Request processed in {processingTime.TotalMilliseconds} ms");
    }

    public void ProcessRequest(string ip, DateTime startDateTime)
    {
        if (RateLimit(ip))
        {
            // Process request here
            LogRequestProcessingTime(startDateTime);
        }
        else
        {
            Console.WriteLine("Rate limit exceeded for IP: " + ip);
        }
    }
}
