$config = parse_ini_file('config.ini', true);

file_put_contents($outputFile, '');
$fp = fopen($inputFile, 'rb');
$contents = fread($fp, filesize($inputFile));
fclose($fp);

$parsedContents = explode("\n", trim($contents));

foreach($parsedContents as $line) {
    $transformedLine = '';
    foreach(explode(' ', $rules) as $rule) {
        if(strncmp($rule, 'SUBSTITUTE:', 12) === 0) {
            $transformedLine .= str_replace(substr($rule, 12), '', $line) . "\n";
        } elseif(strncmp($rule, 'INSERT:', 7) === 0) {
            $transformedLine .= substr($rule, 7) . "\n";
        }
    }
    file_put_contents($outputFile, $transformedLine, FILE_APPEND);
}

