#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

typedef struct DLLNode {
    LogEntry entry;
    struct DLLNode* prev;
    struct DLLNode* next;
} DLLNode;

typedef struct DoublyLinkedList {
    DLLNode* head;
    DLLNode* tail;
    pthread_mutex_t mutex;
    int count;
    size_t total_size;
    double average_length;
} DoublyLinkedList;

DoublyLinkedList* dll_init() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->count = 0;
    list->total_size = 0;
    list->average_length = 0.0;
    return list;
}

void dll_insert(DoublyLinkedList* list, LogEntry entry) {
    DLLNode* node = (DLLNode*)malloc(sizeof(DLLNode));
    node->entry = entry;
    node->prev = NULL;
    node->next = list->head;

    if(list->head != NULL)
        list->head->prev = &node->entry;
    else
        list->tail = &node->entry;
    list->head = &node->entry;

    pthread_mutex_lock(&list->mutex);
    list->count++;
    list->total_size += strlen(entry.message) + 1; // Add 1 for null termination
    if(list->average_length == 0.0)
        list->average_length = (double)strlen(entry.message);
    else
        list->average_length = (list->total_size - (list->count - 1) * strlen(entry.message)) / (double)list->count;
    pthread_mutex_unlock(&list->mutex);
}

void dll_free(DoublyLinkedList* list) {
    DLLNode* current = list->head;
    while(current != NULL) {
        DLLNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void dll_print_to_file(DoublyLinkedList* list, int fd) {
    pthread_mutex_lock(&list->mutex);
    DLLNode* current = list->head;
    while(current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void dll_gc(DoublyLinkedList* list) {
    // Implement garbage collection logic here
}

int main() {
    DoublyLinkedList* list = dll_init();

    // Example usage:
    LogEntry entry1 = {1643723400, 1, strdup("Hello")};
    LogEntry entry2 = {1643723410, 2, strdup("World")};
    LogEntry entry3 = {1643723420, 1, strdup("Goodbye")};

    dll_insert(list, entry1);
    dll_insert(list, entry2);
    dll_insert(list, entry3);

    int fd = open("log.bin", O_RDWR | O_CREAT, 0644);
    dll_print_to_file(list, fd);
    close(fd);

    // More usage...

    dll_free(list);

    return 0;
}
