    size_t memoryUsage;
    char* description;
} ResourceUsage;

ResourceUsage* initDoublyLinkedList(int threshold, int argc, char** argv) {
    // Initialize linked list head
    ResourceUsage* head = NULL;
    ResourceUsage* current = NULL;

    // Parse command-line options
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--output")) {
            char* filePath = argv[i + 1];
            // Output file path processing
        }
    }

    // Initialize linked list tail
    ResourceUsage* tail = NULL;

    // Iterate over processes, initialize and add to list
    for (int i = 0; i < some_process_count; i++) {
        ResourceUsage* node = (ResourceUsage*)malloc(sizeof(ResourceUsage));
        if (!node) {
            perror("Memory allocation failed");
            exit(1);
        }

        // Initialize process data
        node->processID = some_process_id;
        node->memoryUsage = some_memory_usage;

        // Dynamically allocate and initialize description string
        size_t descLen = strlen(some_description) + 1; // Include null-terminator
        char* desc = (char*)malloc(descLen);
        if (!desc) {
            perror("Memory allocation failed");
            exit(1);
        }
        strcpy(desc, some_description);
        node->description = desc;

        // Add to list
        if (head == NULL) {
            head = current = node;
        } else {
            tail->next = node;
            node->prev = tail;
            tail = node;
        }
    }

    // Total memory usage calculation
    size_t totalMemoryUsage = 0;
    for (ResourceUsage* curr = head; curr != NULL; curr = curr->next) {
        if (curr->memoryUsage > threshold)
            totalMemoryUsage += curr->memoryUsage;
    }

    return head;
}

void destroyDoublyLinkedList(ResourceUsage* head) {
    ResourceUsage* current = head;
    while (current != NULL) {
        ResourceUsage* next = current->next;
        // Free memory for description string
        free(current->description);
        free(current);
        current = next;
    }
}
