#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the LogEntry structure
typedef struct {
    long timestamp;
    int level;
    char* message;
} LogEntry;

// Define the Doubly-Linked List Node
typedef struct _ListNode {
    LogEntry* entry;
    struct _ListNode* prev;
    struct _ListNode* next;
} ListNode;

// Function to initialize a doubly-linked list of LogEntry structures
LogEntry* log_list = NULL;
int log_list_size = 0;
pthread_mutex_t log_list_lock = PTHREAD_MUTEX_INITIALIZER;

void init_log_list() {
    log_list = (ListNode*)malloc(sizeof(ListNode));
    log_list->entry = NULL;
    log_list->prev = NULL;
    log_list->next = NULL;
}

// Function to add a new LogEntry to the end of the list
void add_log_entry(LogEntry* entry) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->entry = entry;
    new_node->prev = log_list;
    new_node->next = log_list->next;

    if(log_list->next != NULL)
        log_list->next->prev = new_node;
    else
        log_list->next = new_node;

    log_list = new_node;
    log_list_size++;
}

// Function to free the memory allocated for the list
void destroy_log_list() {
    ListNode* curr = log_list;
    while(curr != NULL) {
        ListNode* next = curr->next;
        if(curr->entry != NULL)
            free(curr->entry->message);
        free(curr);
        curr = next;
    }
}

// Function to iterate over the list and print all entries
void print_log_entries(int fd) {
    pthread_mutex_lock(&log_list_lock);
    ListNode* curr = log_list;
    while(curr != NULL) {
        LogEntry* entry = curr->entry;
        if(entry != NULL)
            fprintf(fd, "%ld %d %s\n", entry->timestamp, entry->level, entry->message);
        curr = curr->next;
    }
    pthread_mutex_unlock(&log_list_lock);
}

// Function to serialize the log list to a binary format
void serialize_log_list(char* file_name) {
    FILE* file = fopen(file_name, "wb");
    if(file == NULL)
        return;

    // Serialize the log entries
    ListNode* curr = log_list;
    while(curr != NULL) {
        LogEntry* entry = curr->entry;
        fwrite(&entry->timestamp, sizeof(long), 1, file);
        fwrite(&entry->level, sizeof(int), 1, file);
        size_t message_len = strlen(entry->message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(entry->message, 1, message_len, file);
        curr = curr->next;
    }

    fclose(file);
}

// Function to deserialize the log list from a binary format
void deserialize_log_list(char* file_name) {
    FILE* file = fopen(file_name, "rb");
    if(file == NULL)
        return;

    // Deserialize the log entries
    ListNode* new_head = (ListNode*)malloc(sizeof(ListNode));
    new_head->entry = NULL;
    new_head->prev = NULL;
    new_head->next = NULL;
    log_list = new_head;
    log_list_size = 0;

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    while(fread(&entry->timestamp, sizeof(long), 1, file) == 1 &&
          fread(&entry->level, sizeof(int), 1, file) == 1) {
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char* new_message = (char*)malloc(message_len + 1);
        fread(new_message, 1, message_len, file);
        new_message[message_len] = '\0';
        add_log_entry(entry);
        free(entry);
        entry = (LogEntry*)malloc(sizeof(LogEntry));
    }

    fclose(file);
}

int main() {
    // Initialize the log list
    init_log_list();

    // Add some log entries
    LogEntry* entry1 = (LogEntry*)malloc(sizeof(LogEntry));
    entry1->timestamp = 1643723400;
    entry1->level = 1;
    char* message1 = "This is a sample log message";
    add_log_entry(entry1);

    LogEntry* entry2 = (LogEntry*)malloc(sizeof(LogEntry));
    entry2->timestamp = 1643723410;
    entry2->level = 2;
    char* message2 = "This is another sample log message";
    add_log_entry(entry2);

    // Print the log entries
    int fd = open("log.txt", O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR);
    print_log_entries(fd);
    close(fd);

    // Serialize and deserialize the log list
    serialize_log_list("log.bin");
    deserialize_log_list("log.bin");

    return 0;
}
