import hashlib
import os
import time
from functools import wraps
from logging import getLogger

logger = getLogger(__name__)

def retry(wait=1, max_retries=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_retries:
                        time.sleep(wait * (2 ** attempt))
                    else:
                        raise
        return wrapper
    return decorator

def calculate_md5(file_path):
    md5_hash = hashlib.md5()

    @retry(max_retries=3, wait=1)
    def read_file_and_update_hash(file_path):
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(1024 * 1024)  # Read in chunks of 1MB
                if not chunk:
                    break
                md5_hash.update(chunk)

    try:
        read_file_and_update_hash(file_path)
    except FileNotFoundError:
        logger.error(f"File {file_path} not found")
        return None
    except PermissionError:
        logger.error(f"No permission to access file {file_path}")
        return None
    except Exception as e:
        logger.error(f"An error occurred: {e}")
        return None

    return md5_hash.hexdigest()
