import hashlib
import os
import time
from functools import wraps

def retry(max_attempts=3, delay=1):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, max_attempts+1):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt < max_attempts:
                        time.sleep(delay * (2 ** (attempt - 1)))
                    else:
                        raise
        return wrapper

    return decorator

def log_progress(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        progress = 0
        for chunk in func(*args, **kwargs):
            yield chunk
            progress += len(chunk) / (os.path.getsize(args[0]) * 0.15)
            print(f"Hashing {progress*100:.2f}% complete")
    return wrapper

@retry(max_attempts=5, delay=2)
@log_progress
def compute_sha256_hash(file_path):
    chunk_size = 2 * (1024 ** 2)  # 2MB chunks
    with open(file_path, 'rb') as file:
        hash_object = hashlib.sha256()
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            hash_object.update(chunk)
    return hash_object.hexdigest()

result = compute_sha256_hash('path_to_your_file')
