import hashlib
import logging
from concurrent.futures import ThreadPoolExecutor
from functools import partial

class ThreadSafeSession:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(ThreadSafeSession, cls).__new__(cls)
        return cls._instance

    def set_access_token(self, token):
        self.access_token = token

    def get_access_token(self):
        return self.access_token


def authenticate_user(oauth_client, access_token_file_path):
    try:
        with open(access_token_file_path, 'r') as f:
            access_token = f.read()
    except FileNotFoundError:
        logging.error("Access token file not found.")
        return None

    session = ThreadSafeSession()
    session.set_access_token(access_token)

    # Replace with your OAuth client implementation
    user_info = oauth_client.get_user_info(session.get_access_token())

    return session, user_info


def calculate_md5_hash(file_path):
    md5_hash = hashlib.md5()

    try:
        with open(file_path, 'rb') as f:
            chunk_size = 1024 * 1024  # 1MB chunks
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                md5_hash.update(chunk)

        progress_percentage = int((f.tell() / f.size()) * 100) if f.size() > 0 else 0

        if progress_percentage % 10 == 0 and progress_percentage != 0:
            logging.info(f"Progress: {progress_percentage}%")

    except FileNotFoundError:
        logging.error("File not found.")
        return None
    except Exception as e:
        logging.error(f"Error reading file: {str(e)}")
        return None

    return md5_hash.hexdigest()


def main(file_path, access_token_file_path):
    session, user_info = authenticate_user(partial(), access_token_file_path)
    if session is None or user_info is None:
        return None, None

    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = [executor.submit(calculate_md5_hash, file_path)]
        for future in futures:
            md5_hash_hexdigest = future.result()
            break

    return md5_hash_hexdigest, user_info


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    md5_hash_hexdigest, user_info = main('path_to_your_file.txt', 'path_to_your_access_token.txt')
    if md5_hash_hexdigest is None or user_info is None:
        print("Authentication failed. Please check the access token file.")
    else:
        print(f"MD5 hash: {md5_hash_hexdigest}")
        print(f"User information: {user_info}")
