import logging
from threading import Lock
import time

class HashCalculator:
    def __init__(self):
        self.md5_hash = hashlib.md5()
        self.sha256_hash = hashlib.sha256()
        self.hash_lock = Lock()

    def update_hashes(self, chunk):
        with self.hash_lock:
            self.md5_hash.update(chunk)
            self.sha256_hash.update(chunk)

    def get_hashes(self):
        return self.md5_hash.hexdigest(), self.sha256_hash.hexdigest()

