import requests
import threading
import queue
import time
from functools import wraps
from logging import getLogger

logger = getLogger()

class RequestProcessor:
    def __init__(self, api_endpoint, timeout=10, error_threshold=0.5):
        self.api_endpoint = api_endpoint
        self.timeout = timeout
        self.error_threshold = error_threshold
        self.request_queue = queue.Queue()
        self.response_cache = {}
        self.concurrent_requests = 0

    def process_request(self, request_id):
        @wraps(requests.get)
        def retry_request(func, *args, **kwargs):
            for attempt in range(3):
                try:
                    response = func(*args, **kwargs)
                    if response.status_code < 200 or response.status_code >= 300:
                        raise Exception(f"Request {request_id} failed with status code {response.status_code}")
                    return response
                except requests.exceptions.RequestException as e:
                    if attempt == 2:
                        logger.error(f"Request {request_id} failed after 3 attempts: {e}")
                    time.sleep(2 ** attempt)
            raise Exception(f"Request {request_id} failed after 3 attempts")

        retry_request(requests.get, self.api_endpoint)

    def run(self):
        while True:
            request = self.request_queue.get()
            if request is None:
                break
            try:
                start_time = time.time()
                response = self.process_request(request)
                end_time = time.time()
                logger.info(f"Request {request} completed in {end_time - start_time:.2f} seconds")
                if response.status_code < 200 or response.status_code >= 300:
                    self.response_cache[request] = None
                else:
                    self.response_cache[request] = response.json()
            except Exception as e:
                logger.error(f"Request {request} failed: {e}")
            finally:
                self.concurrent_requests -= 1

    def add_request(self, request_id):
        self.request_queue.put(request_id)

    def get_response(self, request_id):
        return self.response_cache.get(request_id)
