    int num_strings = 0;
    char buffer[1048576]; // 1MB chunk size
    SHA256_CTX ctx;
    unsigned char hash[SHA256_DIGEST_LENGTH];
    process_result* result = malloc(sizeof(process_result));

    // Read file and calculate SHA-256 hash in chunks
    fseek(STDIN_FILENO, 0L, SEEK_END);
    int file_size = ftell(STDIN_FILENO);
    rewind(STDIN_FILENO);

    int chunk_count = (file_size + 1048575) / 1048576;
    for(int i = 0; i < chunk_count; i++) {
        fread(buffer, 1, 1048576, STDIN_FILENO);
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, buffer, 1048576);
        SHA256_Final(hash, &ctx);
        // Log progress every 5%
        if((i % (chunk_count / 20)) == 0) {
            printf("\rProgress: %.2f%%", (i * 100.0) / chunk_count);
            fflush(stdout);
        }
    }

    // Convert hash to hexadecimal
    char* hash_hex = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
