        self.cache = {}

    def add_vertex(self, vertex_id):
        if vertex_id not in self.graph_db:
            self.graph_db[vertex_id] = {
                'properties': {'random_property': random.randint(0, 100)},
                'edges': []
            }
            self.log.info(f'Added vertex {vertex_id} at {datetime.now()}')

    def add_edge(self, vertex1, vertex2):
        if vertex1 in self.graph_db and vertex2 in self.graph_db:
            edge = {'vertex1': vertex1, 'vertex2': vertex2}
            self.graph_db[vertex1]['edges'].append(edge)
            self.graph_db[vertex2]['edges'].append(edge)
            self.log.info(f'Added edge between {vertex1} and {vertex2} at {datetime.now()}')

    def generate_random_graph(self):
        for _ in range(1000):  # adjust this number to control graph size
            vertex_id = random.randint(0, 10000)  # adjust this number to control vertex ID range
            self.add_vertex(vertex_id)
            for _ in range(random.randint(1, 10)):  # adjust this number to control edge count
                neighbor_id = random.randint(0, 10000)  # adjust this number to control edge neighbor ID range
                self.add_edge(vertex_id, neighbor_id)

    def fetch_api_data(self, vertex_id):
        if vertex_id in self.graph_db:
            weather_response = Api().get_weather_data(self.api_credentials['weather_api_key'], vertex_id)
            geolocation_response = Api().get_geolocation_data(self.api_credentials['geolocation_api_key'], vertex_id)
            air_quality_response = Api().get_air_quality_data(self.api_credentials['air_quality_api_key'], vertex_id)
            self.graph_db[vertex_id]['properties'].update({
                'weather': weather_response,
                'geolocation': geolocation_response,
                'air_quality': air_quality_response
            })

    def cache_api_responses(self):
        for vertex_id in self.graph_db:
            if not self.cache.get(vertex_id):
                self.fetch_api_data(vertex_id)
                self.cache[vertex_id] = True

    def run_concurrent_operations(self, num_threads=4):
        threads = []
        for _ in range(num_threads):
            thread = threading.Thread(target=self.generate_random_graph)
            thread.start()
            threads.append(thread)

        for thread in threads:
            thread.join()

    def analyze_addition_process(self):
        start_time = time.time()
        for _ in range(1000):  # adjust this number to control graph size
            vertex_id = random.randint(0, 10000)  # adjust this number to control vertex ID range
            self.add_vertex(vertex_id)
            time.sleep(random.uniform(0.01, 1))  # simulate adding vertices at different rates

        addition_interval_stats = [time.time() - start_time]
        memory_usage_stats = []

        while True:
            try:
                stats = resource.getrusage(resource.RUSAGE_SELF)
                addition_interval_stats.append(time.time() - start_time)
                memory_usage_stats.append(stats.ru_maxrss)
                time.sleep(1)  # simulate adding vertices at different rates
            except KeyboardInterrupt:
                break

        self.log.info(f'Addition process completed in {mean(addition_interval_stats)} seconds')
        self.log.info(f'Maximum memory usage: {max(memory_usage_stats)} MB')

    def detect_anomalies(self):
        for vertex_id, props in self.graph_db.items():
            if abs(props['random_property'] - mean([props['properties'][key] for key in props['properties'].keys()])) > 2 * std_dev:
                self.log.warning(f'Anomaly detected at vertex {vertex_id} with property value: {props["random_property"]}')

    def run(self):
        self.generate_random_graph()
        self.cache_api_responses()
        self.run_concurrent_operations()
        self.analyze_addition_process()
        self.detect_anomalies()

if __name__ == '__main__':
    RandomGraphGenerator().run()
