import hashlib
import time
from queue import Queue
import threading

class MD5Processor:
    def __init__(self):
        self.md5_hash = hashlib.md5()
        self.request_queue = Queue()
        self.lock = threading.Lock()

    def process_request(self, file_path):
        try:
            with open(file_path, 'rb') as file:
                chunk = file.read(1024 * 1024)  # Read in chunks of 1MB
                while chunk:
                    self.md5_hash.update(chunk)
                    chunk = file.read(1024 * 1024)
            return self.md5_hash.hexdigest()
        except Exception as e:
            print(f"Error processing request: {str(e)}")
            return None

    def process_requests(self, requests):
        threads = []
        for _ in range(len(requests)):
            t = threading.Thread(target=self.request_handler)
            t.start()
            threads.append(t)

        for t in threads:
            t.join()

    def request_handler(self):
        while True:
            file_path = self.request_queue.get()
            if file_path is None:
                break
            result = self.process_request(file_path)
            print(f"Hashed file {file_path} with result {result}")
            self.request_queue.task_done()

    def start_processing(self, requests):
        for request in requests:
            self.request_queue.put(request)

    def stop_processing(self):
        for _ in range(self.request_queue.qsize()):
            self.request_queue.get()
        self.request_queue.join()


def main():
    processor = MD5Processor()
    requests = ["file1.txt", "file2.txt", "file3.txt"]
    processor.start_processing(requests)
    # process other tasks
    processor.stop_processing()


if __name__ == "__main__":
    main()

