typedef enum {
    ESTABLISHED,
    CLOSE_WAIT,
    LAST_ACK
} ConnectionState;

typedef struct {
    int id;
    time_t last_activity;
    ConnectionState status;
} TCPConnectionState;

TCPConnectionState **connections = NULL;
int connections_count = 0;
int max_connections = 10; // default capacity

TCPConnectionState *create_connection(int id) {
    TCPConnectionState *new_conn = (TCPConnectionState *)malloc(sizeof(TCPConnectionState));
    new_conn->id = id;
    time_t now = time(NULL);
    new_conn->last_activity = now;
    new_conn->status = ESTABLISHED;
    return new_conn;
}

void add_connection(int id) {
    if (connections_count >= max_connections) {
        // resize the array
        max_connections *= 2;
        connections = (TCPConnectionState **)realloc(connections, sizeof(TCPConnectionState *) * max_connections);
    }
    connections[connections_count] = create_connection(id);
    connections_count++;
}

void update_last_activity(int id) {
    for (int i = 0; i < connections_count; i++) {
        if (connections[i]->id == id) {
            connections[i]->last_activity = time(NULL);
            return;
        }
    }
}

void mark_as_closed(int id) {
    for (int i = 0; i < connections_count; i++) {
        if (connections[i]->id == id) {
            connections[i]->status = LAST_ACK;
            return;
        }
    }
}
