def calculate_md5(file_path, chunk_size=1024*1024):
    md5_hash = hashlib.md5()

    try:
        with open(file_path, 'rb') as file:
            chunk = file.read(chunk_size)
            while chunk:
                md5_hash.update(chunk)
                logging.info(f"Hashing progress: {int((os.path.getsize(file_path) - len(chunk)) / os.path.getsize(file_path) * 100)}%")
                chunk = file.read(chunk_size)

        logging.info("MD5 hashing completed")

    except FileNotFoundError:
        logging.error(f"Error: File '{file_path}' not found.")
    except PermissionError:
        logging.error(f"Error: Insufficient permissions to access file '{file_path}'.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

    return md5_hash.hexdigest()

def calculate_checksum(chunk):
    md5_hash = hashlib.md5()
    md5_hash.update(chunk)
    return md5_hash.hexdigest()

def parallel_md5(file_path, chunk_size=1024*1024, num_processes=4):
    md5_hash = hashlib.md5()

    try:
        with open(file_path, 'rb') as file:
            chunks = []
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                chunks.append(chunk)

        pool = Pool(num_processes)
        results = [pool.apply_async(calculate_checksum, (chunk,)) for chunk in chunks]

        checksums = [result.get() for result in results]
        logging.info(f"Checksums: {', '.join(checksums)}")

    except FileNotFoundError:
        logging.error(f"Error: File '{file_path}' not found.")
    except PermissionError:
        logging.error(f"Error: Insufficient permissions to access file '{file_path}'.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

    return md5_hash.hexdigest()

def main(file_path):
    logging.basicConfig(filename='md5_log.txt', level=logging.INFO)

    start_time = time.time()
    hexdigest = calculate_md5(file_path)
    elapsed_time = time.time() - start_time

    logging.info(f"MD5 hash: {hexdigest}")
    logging.info(f"Elapsed time: {elapsed_time} seconds")
    logging.info(f"Total chunks processed: {os.path.getsize(file_path) // 1024*1024}")

if __name__ == "__main__":
    file_path = "path_to_your_file"
