import os
import hashlib
import logging
from multiprocessing import Pool

def calculate_md5(file_path, chunk_size=1024*1024):
    md5 = hashlib.md5()

    try:
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                md5.update(chunk.encode())

                checksum = hashlib.md5(chunk.encode()).hexdigest()
                logging.info(f"Chunk processed: {file.name} - Checksum: {checksum}")
    except (FileNotFoundError, IOError) as e:
        logging.error(f"Error processing file: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")

    return md5.hexdigest()

def parallel_calculate_md5(file_path, chunk_size=1024*1024, num_processes=4):
    chunks = []
    try:
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                chunks.append((file.name, chunk))

                checksum = hashlib.md5(chunk.encode()).hexdigest()
                logging.info(f"Chunk processed: {file.name} - Checksum: {checksum}")
    except (FileNotFoundError, IOError) as e:
        logging.error(f"Error processing file: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")

    if chunks:
        with Pool(processes=num_processes) as pool:
            results = list(pool.map(calculate_md5_chunk, [(file.name, chunk) for file_name, chunk in chunks]))

        return ''.join(results)
    else:
        return calculate_md5(file_path)

def calculate_md5_chunk(args):
    _, chunk = args
    md5 = hashlib.md5()
    md5.update(chunk.encode())

    checksum = hashlib.md5(chunk.encode()).hexdigest()
    logging.info(f"Chunk processed - Checksum: {checksum}")

    return md5.hexdigest()

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    file_path = "path_to_your_file.txt"
    chunk_size = 1024*1024
    num_processes = 4

    md5_hash = parallel_calculate_md5(file_path, chunk_size, num_processes)
    logging.info(f"MD5 Hash: {md5_hash}")
