#include <condition_variable>
#include <fstream>

namespace RandomNumberGenerator {
    class RandomNumberGenerator {
    public:
        RandomNumberGenerator(size_t chunkSize, size_t threadCount) : m_chunkSize(chunkSize), m_threadCount(threadCount), m_mt(std::mt19937()),
            m_currentSegment(0), m_generationState(false) {}

        ~RandomNumberGenerator() {
            // Ensure proper cleanup and resource management
            if (m_generationState) {
                StopGeneration();
            }
        }

        void StartGeneration(size_t sequenceLength, const std::string& metadata) {
            // Initialize the generation process with the given parameters
            m_sequenceLength = sequenceLength;
            m_metadata = metadata;

            // Start the parallel generation process
            m_generationState = true;
            m_generationThread = std::thread(&RandomNumberGenerator::GenerateNumbers, this);

            // Log progress every 10% completion
            CheckProgress();
        }

        void StopGeneration() {
            // Signal the generation thread to stop
            m_generationState = false;

            // Wait for the thread to finish
            if (m_generationThread.joinable()) {
                m_generationThread.join();
            }
        }

        std::vector<uint8_t> GetRandomNumbers(size_t chunkSize) {
            // Generate a random number sequence of the specified size
            std::vector<uint8_t> numbers;
            for (size_t i = 0; i < chunkSize; ++i) {
                numbers.push_back(m_mt() % 256);
            }
            return numbers;
        }

    private:
        void GenerateNumbers() {
            while (m_generationState) {
                // Break the generation process into multiple parts
                size_t remainingChunks = m_sequenceLength / m_chunkSize;
                if (remainingChunks == 0) {
                    remainingChunks = m_sequenceLength % m_chunkSize;
                }

                for (size_t i = 0; i < remainingChunks; ++i) {
                    // Hash each part concurrently using parallel processing
                    std::vector<std::pair<size_t, uint8_t>> hashes(m_threadCount);
                    size_t chunkStart = i * m_chunkSize;
                    size_t chunkEnd = (i + 1) * m_chunkSize;

                    if (chunkEnd > m_sequenceLength) {
                        chunkEnd = m_sequenceLength;
                    }

                    std::vector<std::thread> workerThreads;
                    for (size_t j = 0; j < m_threadCount; ++j) {
                        size_t start = chunkStart + j * (m_chunkSize / m_threadCount);
                        size_t end = start + m_chunkSize / m_threadCount;

                        if (end > chunkEnd) {
                            end = chunkEnd;
                        }

                        workerThreads.emplace_back([&this, &hashes, start, end]() {
                            for (size_t k = start; k < end; ++k) {
                                hashes[j].first = k;
                                hashes[j].second = m_mt() % 256;
                            }
                        });
                    }

                    // Wait for the worker threads to finish
                    for (auto& thread : workerThreads) {
                        thread.join();
                    }

                    // Combine the hash values and store them in a file
                    std::string hashFile = "hashes.txt";
                    std::ofstream file(hashFile, std::ios::app);
                    for (const auto& pair : hashes) {
                        file << pair.first << " " << pair.second << "\n";
                    }
                    file.close();

                    // Log progress every 10% completion
                    CheckProgress();
                }

                // Resume generation if interrupted or reach the end of the sequence
                if (m_currentSegment < m_sequenceLength / m_chunkSize) {
                    ++m_currentSegment;
                } else {
                    break;
                }
            }
        }

        void CheckProgress() {
            size_t progress = static_cast<size_t>(m_currentSegment * 100.0f / (m_sequenceLength / m_chunkSize));
            if (progress % 10 == 0) {
                // Log progress
                std::cout << "Progress: " << progress << "%\n";
            }
        }

    private:
        size_t m_chunkSize;
        size_t m_threadCount;
        std::mt19937 m_mt;
        size_t m_currentSegment;
        bool m_generationState;
        std::thread m_generationThread;
        size_t m_sequenceLength;
        std::string m_metadata;
    };
}
