import os
import hashlib
import threading
from queue import Queue
from time import perf_counter
import logging

class Hasher:
    def __init__(self, num_threads=10):
        self.num_threads = num_threads
        self.hash_queue = Queue()
        self.threads = []

    def calculate_hash(self, file_path, offset=0, chunk_size=2**20):
        md5 = hashlib.md5()

        with open(file_path, 'rb') as f:
            if offset > 0:
                f.seek(offset)

            while True:
                data = f.read(min(chunk_size, os.path.getsize(file_path) - offset))
                if not data:
                    break
                md5.update(data)

        return md5.hexdigest()

    def process_file(self, file_path):
        try:
            logging.info(f"Processing {file_path}...")
            file_hash = self.calculate_hash(file_path)
            logging.info(f"{file_path}: {file_hash}")
        except FileNotFoundError as e:
            logging.error(f"File not found: {e.filename}")
        except IsADirectoryError as e:
            logging.warning(f"Skipping directory: {e.path}")
        except Exception as e:
            logging.error(f"Error processing file: {str(e)}")

    def start(self, files):
        logging.info("Starting hash calculation...")
        self.hash_queue = Queue()

        for file in files:
            if os.path.isdir(file):
                logging.warning(f"Skipping directory: {file}")
            else:
                self.hash_queue.put((file, 0))

        threads = []
        for _ in range(self.num_threads):
            t = threading.Thread(target=self.thread_worker)
            t.start()
            threads.append(t)

        for file in files:
            while not self.hash_queue.empty():
                item = self.hash_queue.get()
                if item[1] == 0 and len(threads) < self.num_threads:
                    break
                self.hash_queue.put(item)

            for thread in threads[:self.num_threads]:
                thread.join()

        logging.info("Hash calculation completed.")

    def thread_worker(self):
        while True:
            file, offset = self.hash_queue.get()
            try:
                if not os.path.exists(file):
                    continue
                hash_value = self.calculate_hash(file, offset)
                self.hash_queue.task_done()
            except Exception as e:
                logging.error(f"Error processing {file}: {str(e)}")

    def get_status(self):
        status = {
            "completed_files": 0,
            "total_files": len(files),
            "estimated_time_remaining": None
        }
        return status

    def update_status(self, status):
        if self.hash_queue.empty():
            status["estimated_time_remaining"] = None
        else:
            estimated_time_remaining = (self.num_threads * status["completed_files"] + 
                                         self.hash_queue.qsize()) / self.hash_queue.qsize() * 1.5
            status["estimated_time_remaining"] = estimated_time_remaining

    def get_status(self):
        return self.status

def main():
    files = ["file1.txt", "file2.txt", "directory1", "file3.txt"]
    hasher = Hasher()
    start_time = perf_counter()

    try:
        files_to_process = []
        for file in files:
            if os.path.isdir(file):
                continue
            files_to_process.append(file)

        hasher.start(files_to_process)

        while True:
            status = hasher.get_status()
            print(f"Completed: {status['completed_files']}/{status['total_files']} - Est. Time Remaining: {status['estimated_time_remaining']}")
            if self.hash_queue.empty():
                break

    except KeyboardInterrupt as e:
        logging.error("Hash calculation interrupted.")
    finally:
        end_time = perf_counter()
        elapsed_time = end_time - start_time
        logging.info(f"Total time taken: {elapsed_time:.2f} seconds")

if __name__ == "__main__":
    main()
