package FileCompressor;

import org.xerial.snappy.Snappy;
import java.io.*;
import java.util.concurrent.*;

public class SnappyCompressor {

    private static final int CHUNK_SIZE = 1024 * 1024; // 1MB
    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors();
    private static final long ALERT_THRESHOLD_CPU_USAGE = 0.8f;

    private File file;
    private FileOutputStream fos;
    private FileInputStream fis;
    private BufferedOutputStream bos;
    private byte[] buffer = new byte[CHUNK_SIZE];
    private ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);

    public SnappyCompressor() {
        // Constructor
    }

    @Override
    protected void finalize() throws Throwable {
        super.finalize();
        closeResources();
    }

    public void compress(File file) throws IOException {
        this.file = file;
        fis = new FileInputStream(file);
        bos = new BufferedOutputStream(new GZIPOutputStream(new FileOutputStream(getCompressedFile()), true));

        long fileSize = file.length();

        long lastCheckpoint = 0;

        for (long segmentStart = 0; segmentStart < fileSize; segmentStart += CHUNK_SIZE) {
            long segmentEnd = Math.min(segmentStart + CHUNK_SIZE - 1, fileSize - 1);

            Future<?> future = executor.submit(() -> compressSegment(fileSize, segmentStart, segmentEnd));

            try {
                Thread.sleep(10); // Checkpoint every 10%
                lastCheckpoint = segmentEnd;
                System.out.println("Completed " + (int) ((segmentEnd / (float) fileSize) * 100) + "%");
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException("Interrupted compression process", e);
            }

            if (future.isDone()) {
                try {
                    future.get(); // Wait for the segment to finish
                } catch (ExecutionException e) {
                    throw new IOException("Failed to compress a segment", e);
                }
            }
        }

        bos.close();
    }

    private void closeResources() {
        try {
            fos.close();
            fis.close();
            bos.close();
        } catch (IOException e) {
            System.err.println("Error closing resources: " + e.getMessage());
        }
    }

    private File getCompressedFile() {
        // Generate the compressed file name
    }

    private void compressSegment(long fileSize, long segmentStart, long segmentEnd) throws IOException {
        int readBytes;
        int writtenBytes = 0;

        while (segmentStart <= segmentEnd) {
            if ((readBytes = fis.read(buffer)) > 0) {
                byte[] compressedBuffer = new byte[buffer.length];
                Snappy.compress(buffer, 0, readBytes, compressedBuffer);

                bos.write(compressedBuffer);
                writtenBytes += readBytes;
            } else {
                break; // End of file reached
            }
        }

        System.out.println("Compressed " + (int) ((segmentEnd / (float) fileSize) * 100) + "%");

        // Verify the segment with checksum
    }

    private void monitorSystemResourceUsage() throws IOException {
        Runtime runtime = Runtime.getRuntime();
        long initMemory, totalMemory, freeMemory;
        int availableProcessors = MAX_THREADS;

        while (true) {
            try {
                Thread.sleep(1000); // Check every 1 second
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IOException("Interrupted system resource monitoring", e);
            }

            initMemory = runtime.totalMemory();
            totalMemory = Runtime.getRuntime().totalMemory();
            freeMemory = Runtime.getRuntime().freeMemory();

            if (getCPUUsage() > ALERT_THRESHOLD_CPU_USAGE) {
                System.out.println("CPU usage exceeded threshold. Alerting!");
                // Raise an alert
            }
        }
    }

    private float getCPUUsage() {
        // Calculate the CPU usage
    }
}
