    char CRC_INDICATION_REL8_TAG[13];
} NFAPI_CRC_INDICATION_PDU_T;

void* xmalloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int num_users) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)xmalloc(num_users * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_users; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG[16] = '\0';
        sprintf(crc_indications[i].RX_UE_INFORMATION_TAG, "RX_UE_INFO_%d", i);
        crc_indications[i].RNTI = i;

        char* random_crcflag = (char*)xmalloc(1);
        *random_crcflag = 'a' + rand() % 26;
        strcpy(crc_indications[i].CRC_INDICATION_REL8_TAG, "CRCFLAG_");
        strcat(crc_indications[i].CRC_INDICATION_REL8_TAG, random_crcflag);

        free(random_crcflag);
    }

    return crc_indications;
}

unsigned char* compute_md5_hash(const char* input_string) {
    unsigned int hash_len = MD5_DIGEST_LENGTH;
    unsigned char* md5_hash = (unsigned char*)xmalloc(hash_len + 1);

    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input_string, strlen(input_string));
    MD5_Final(md5_hash, &ctx);

    md5_hash[hash_len] = '\0';

    return md5_hash;
}

int main() {
    int num_users = 100; // adjust this value to change the number of structures generated
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = generate_crc_indications(num_users);

    for (int i = 0; i < num_users; i++) {
        printf("RX_UE_INFORMATION_TAG: %s\n", crc_indications[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", crc_indications[i].RNTI);
        printf("CRC_INDICATION_REL8_TAG: %s\n\n", crc_indications[i].CRC_INDICATION_REL8_TAG);
