#include <sys/types.h>
#include <sys/stat.h>

typedef struct {
    int timestamp;
    int log_level;
    char* message;
} LogEntry;

// Doubly-linked list node
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

Node* init_node(LogEntry entry) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    if (!new_node) {
        return NULL;
    }
    new_node->entry = entry;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Doubly-linked list
typedef struct LogList {
    Node* head;
    Node* tail;
} LogList;

LogList* init_log_list() {
    LogList* log_list = (LogList*) malloc(sizeof(LogList));
    if (!log_list) {
        return NULL;
    }
    log_list->head = NULL;
    log_list->tail = NULL;
    return log_list;
}

// Print all entries in the list to a file descriptor
void print_log_list(LogList* log_list, int fd) {
    Node* current = log_list->head;
    while (current) {
        fwrite(&current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
}

// Synchronize access to the linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Serialize the linked list to a binary file
void serialize_log_list(LogList* log_list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        return;
    }
    Node* current = log_list->head;
    while (current) {
        fwrite(&current->entry, sizeof(LogEntry), 1, file);
        current = current->next;
    }
    fclose(file);
}

// Deserialize the linked list from a binary file
LogList* deserialize_log_list(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return NULL;
    }
    LogList* log_list = init_log_list();
    Node* current = (Node*) malloc(sizeof(Node));
    while (fread(&current->entry, sizeof(LogEntry), 1, file)) {
        // Add the node to the list
        if (!log_list->head) {
            log_list->head = current;
            log_list->tail = current;
        } else {
            current->prev = log_list->tail;
            log_list->tail->next = current;
            log_list->tail = current;
        }
    }
    fclose(file);
    free(current);
    return log_list;
}

// Garbage collector
void garbage_collect(LogList* log_list) {
    // Reclaim unused memory
}

int main() {
    LogList* log_list = init_log_list();
    // Add entries to the list
    Node* new_node = init_node(/* initialize LogEntry structure */);
    if (new_node) {
        pthread_mutex_lock(&lock);
        if (!log_list->head) {
            log_list->head = new_node;
            log_list->tail = new_node;
        } else {
            new_node->prev = log_list->tail;
            log_list->tail->next = new_node;
            log_list->tail = new_node;
        }
        pthread_mutex_unlock(&lock);
    }

    // Print all entries in the list to a file descriptor
    print_log_list(log_list, 1);

    // Serialize and deserialize the linked list
    serialize_log_list(log_list, "log.bin");
    LogList* deserialized_log_list = deserialize_log_list("log.bin");

    return 0;
}
