#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

#include "api_client.h"
#include "process_common.h"

#define CHUNK_SIZE_DEFAULT (1024 * 1024)
#define MAX_CHUNK_SIZE (1024 * 1024 * 10)

typedef struct {
    pthread_mutex_t lock;
    unsigned char hash[16];
} md5_ctx;

md5_ctx* md5_init() {
    md5_ctx* ctx = malloc(sizeof(md5_ctx));
    if (!ctx) return NULL;
    pthread_mutex_init(&ctx->lock, NULL);
    return ctx;
}

void md5_update(md5_ctx* ctx, const unsigned char* data, size_t len) {
    pthread_mutex_lock(&ctx->lock);
    MD5_Update(ctx->hash, data, len);
    pthread_mutex_unlock(&ctx->lock);
}

void md5_finalize(md5_ctx* ctx) {
    pthread_mutex_lock(&ctx->lock);
    unsigned char digest[16];
    MD5_Final(digest, ctx->hash);
    pthread_mutex_unlock(&ctx->lock);

    // Convert the MD5 hash to hexadecimal
    char hex_hash[33];
    for (int i = 0; i < 16; ++i) {
        sprintf(hex_hash + i * 2, "%02x", digest[i]);
    }
}

void* process_file(void* arg) {
    int* file_fd = arg;
    md5_ctx* ctx = md5_init();
    if (!ctx || !file_fd) return NULL;

    size_t chunk_size = CHUNK_SIZE_DEFAULT;
    unsigned char buffer[1024];

    off_t file_size = lseek(*file_fd, 0, SEEK_END);
    lseek(*file_fd, 0, SEEK_SET);

    while (1) {
        ssize_t read_len = pread(*file_fd, buffer, sizeof(buffer), ftell(*file_fd));
        if (read_len < 0) break;
        md5_update(ctx, buffer, read_len);

        off_t current_pos = ftell(*file_fd);
        size_t remaining_bytes = file_size - current_pos;

        while (remaining_bytes > chunk_size) {
            md5_update(ctx, buffer, chunk_size);
            current_pos += chunk_size;
            remaining_bytes -= chunk_size;
        }
    }

    md5_finalize(ctx);

    // Free resources
    free(ctx);
    close(*file_fd);

    return NULL;
}

int main() {
    int file_fd = open("path/to/file", O_RDONLY);
    if (file_fd < 0) return -1;

    pthread_t thread;
    pthread_create(&thread, NULL, process_file, &file_fd);

    // Wait for the processing to complete
    pthread_join(thread, NULL);

    return 0;
}

