#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>

#include "config_api.h"
#include "file_processor.h"

int process_file(const char *file_path, int max_memory) {
    struct stat file_stat;
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    fstat(fd, &file_stat);

    size_t chunk_size = 1024 * 1024; // 1MB
    size_t total_chunks = file_stat.st_size / chunk_size + 1;

    void *file_map = mmap(NULL, file_stat.st_size, PROT_READ | PROT_WRITE,
                            MAP_PRIVATE | MAP_NORESERVE, fd, 0);
    if (file_map == MAP_FAILED) {
        perror("Error mapping file");
        close(fd);
        return 2;
    }

    for (size_t i = 0; i < total_chunks; i++) {
        size_t chunk_start = i * chunk_size;
        size_t chunk_end = ((i + 1) * chunk_size > file_stat.st_size)
                            ? file_stat.st_size
                            : (i + 1) * chunk_size;

        // Process the chunk
        process_chunk(file_map + chunk_start, chunk_end - chunk_start);

        // Update MD5 hash
        update_md5_hash(file_map + chunk_start, chunk_end - chunk_start);
    }

    munmap(file_map, file_stat.st_size);
    close(fd);
    return 0;
}

// C implementation of the largest integer function
int largest_integer(int *numbers, int size) {
    int max = numbers[0];
    for (int i = 1; i < size; i++) {
        if (numbers[i] > max)
            max = numbers[i];
    }
    return max;
}

// Python implementation of the file processing and MD5 hashing
import hashlib
import mmap

def process_file(file_path, chunk_size=1024 * 1024):
    with open(file_path, 'rb') as f:
        md5_hash = hashlib.md5()
        mmapped_file = mmap.mmap(f.fileno(), 0, access=mmap.ACCESS_READ)

        for i in range(0, len(mmapped_file), chunk_size):
            chunk = mmapped_file[i:i+chunk_size]
            md5_hash.update(chunk)

    return md5_hash.hexdigest()

def main():
