#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    void (*func)(void *);
    void *arg;
} ThreadTask;

void* thread_func(void* arg) {
    ThreadTask* task = (ThreadTask*)arg;
    task->func(task->arg);
    return NULL;
}

int create_thread_pool(int num_threads) {
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, thread_func, NULL) != 0) {
            perror("Error creating thread");
            return -1;
        }
    }
    return 0;
}

void destroy_thread_pool(int num_threads, pthread_t* threads) {
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

// Thread-safe image processing function
void process_image(void *image_data) {
    // Process the image data
    // ...
}

int main() {
    int num_threads = 4;
    pthread_t threads[num_threads];

    create_thread_pool(num_threads, threads);

    // Start processing images in parallel
    for (int i = 0; i < num_threads; i++) {
        ThreadTask task;
        task.func = process_image;
        task.arg = image_data[i];
        pthread_create(&threads[i], NULL, thread_func, &task);
    }

    // Wait for all threads to finish
    destroy_thread_pool(num_threads, threads);

    return 0;
}
