typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

struct Node {
    LogEntry entry;
    struct Node* next;
};

void freeNode(struct Node** nodeRef) {
    if (*nodeRef != NULL) {
        struct Node* oldNode = *nodeRef;
        *nodeRef = oldNode->next;
        free(oldNode);
    }
}

void printLogEntries(int fd, struct Node* head) {
    for (struct Node* node = head; node != NULL; node = node->next) {
        fwrite(&node->entry, sizeof(LogEntry), 1, fd);
    }
}

LogEntry* initializeLogEntry() {
    LogEntry* logEntry = malloc(sizeof(LogEntry));
    logEntry->timestamp = time(NULL);
    logEntry->logLevel = -1; // default level
    logEntry->message = NULL;
    return logEntry;
}

void destroyLogEntry(LogEntry** entryRef) {
    if (*entryRef != NULL) {
        free((*entryRef)->message);
        free(*entryRef);
        *entryRef = NULL;
    }
}

struct Node* addNode(struct Node** headRef, LogEntry* newEntry) {
    struct Node* newNode = malloc(sizeof(struct Node));
    newNode->entry = *newEntry;
    newNode->next = *headRef;
    *headRef = newNode;
    return *headRef;
}

void destroyLogList(struct Node** headRef) {
    struct Node* current = *headRef;
    struct Node* nextNode = NULL;
    while (current != NULL) {
        nextNode = current->next;
        freeNode(&current);
        current = nextNode;
    }
}
