async def process_urls(urls, cache_dir):
    logger = Logger("WebPageProcessor")

    async def download_and_analyze(url):
        async with aiohttp.ClientSession() as session:
            try:
                async with session.get(url) as response:
                    content = await response.text()
                    # Extract structured data (article title, publication date, author name)
                    data = extract_structured_data(content)

                    if data is None:
                        return

                    # Cache the downloaded content
                    cache_file = f"{cache_dir}/{url}.html"
                    with open(cache_file, "w") as file:
                        file.write(content)

                    logger.info(f"Processed {url} - Start: {datetime.now()}")
                    yield data
                    logger.info(f"Processed {url} - Completion: {datetime.now()}")

            except asyncio.TimeoutError:
                # Retry download with exponential backoff strategy
                await asyncio.sleep(1)
                return await download_and_analyze(url)

    async with aiohttp.ClientSession() as session:
        tasks = []
        for url in urls:
            task = download_and_analyze(url)
            tasks.append(task)

        results = await asyncio.gather(*tasks, return_exceptions=True)

        logger.info("Processing complete")

# Example usage
