public async Task<DataTableReader> ProcessUrls(string urlsJson, string config)
{
    dynamic json = JsonConvert.DeserializeObject(urlsJson);
    var dtReader = new DataTableReader();

    foreach (var url in json.urls)
    {
        try
        {
            using (var httpClient = new HttpClient())
            {
                var response = await httpClient.GetAsync(url);
                response.EnsureSuccessStatusCode();

                // Extract structured data (article title, publication date, author name)
