                if (data == null)
                    continue;

                dtReader.AddRow(data.ArticleTitle, data.PublicationDate, data.AuthorName);
            }
        }
        catch (HttpRequestException ex)
        {
            // Handle HTTP errors
            await Task.Delay(1000); // Exponential backoff strategy for transient network issues
            throw;
        }
