['```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    void* key;
    void* value;
} cache_item;

typedef struct {
    int capacity;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    list_head items;
} cache;

cache* create_cache(int capacity) {
    cache* c = (cache*)malloc(sizeof(cache));
    c->capacity = capacity;
    c->size = 0;
    pthread_mutex_init(&c->lock, NULL);
    pthread_cond_init(&c->cond, NULL);
    list_head_init(&c->items);
    return c;
}

void add_item_to_cache(cache* cache, void* key, void* value) {
    // add item to the end of the list
    cache_item* item = (cache_item*)malloc(sizeof(cache_item));
    item->key = key;
    item->value = value;
    pthread_mutex_lock(&cache->lock);
    list_tail_insert(&cache->items, item);
    cache->size++;
    if (cache->size > cache->capacity) {
        // evict LRU item
        cache_item* lru = list_head_remove(&cache->items);
        free(lru);
    }
    pthread_mutex_unlock(&cache->lock);
}

void get_item_from_cache(cache* cache, void* key, void** value) {
    // find the item in the list
    pthread_mutex_lock(&cache->lock);
    for (cache_item* item = list_head(&cache->items); item; item = item->next) {
        if (item->key == key) {
            *value = item->value;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

void evict_item_from_cache(cache* cache, void** value) {
    // find the LRU item and remove it
    pthread_mutex_lock(&cache->lock);
    if (list_head_remove(&cache->items)) {
        *value = ((cache_item*)list_tail(&cache->items))->value;
    }
    pthread_mutex_unlock(&cache->lock);
}

void cleanup_cache(cache* cache) {
    // free all items in the list
    for (cache_item* item = list_head(&cache->items); item; ) {
        cache_item* next = item->next;
        free(item);
        item = next;
    }
    pthread_mutex_unlock(&cache->lock);
}

void notify_eviction(cache* cache, void** value) {
    // send notification to the client application
    printf("Item %p evicted due to expiration\n", *value);
}
