from logging import getLogger
from datetime import timedelta

class MD5Hasher:
    def __init__(self, max_concurrent_threads=10):
        self.max_concurrent_threads = max_concurrent_threads
        self.chunk_size = 4096
        self.cache = {}
        self.logger = getLogger(__name__)

    def compute_md5(self, files):
        with requests.Session() as session:
            with ThreadPoolExecutor(max_workers=self.max_concurrent_threads) as executor:
                results = []
                for file in files:
                    future = executor.submit(self.compute_md5_file, file)
                    results.append(future)

                for result in results:
                    md5_hash = result.result()
                    self.upload_hash(session, md5_hash)
                    self.cache[file] = md5_hash

    def compute_md5_file(self, file):
        with open(file, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                chunk = f.read(self.chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
        return md5.hexdigest()

    def upload_hash(self, session, md5_hash):
        try:
            response = session.post('https://your-storage-service.com/upload', json={'hash': md5_hash})
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Error uploading hash: {e}")
            # retry up to 3 times with exponential backoff
            for i in range(1, 4):
                time.sleep(pow(2, i - 1) * timedelta(seconds=30))
                response = session.post('https://your-storage-service.com/upload', json={'hash': md5_hash})
                if response.status_code == 200:
                    break

    def validate_uploaded_hash(self, session, file):
        try:
            response = session.get(f'https://your-storage-service.com/check/{file}')
            response.raise_for_status()
            uploaded_hash = response.json()['hash']
            computed_hash = self.cache[file]
            if uploaded_hash != computed_hash:
                raise ValueError("Hash mismatch")
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Error validating hash: {e}")

    def start(self):
        while True:
            try:
                files = input("Enter file paths (separated by comma): ")
                files = [file.strip() for file in files.split(',')]
                self.compute_md5(files)
                break
            except ValueError as e:
                print(f"Invalid input: {e}")

if __name__ == '__main__':
