public class Md5Hasher
{
    private readonly int _maxConcurrentThreads;
    private readonly int _chunkSize;
    private readonly DataTableReader[] _results;
    private readonly ConnectionPool _connectionPool;
    private readonly Logger _logger;

    public Md5Hasher(int maxConcurrentThreads = 10)
    {
        _maxConcurrentThreads = maxConcurrentThreads;
        _chunkSize = 4096;
        _results = new DataTableReader[0];
        _connectionPool = new ConnectionPool();
        _logger = Logger.Instance;
    }

    public void ComputeMd5(byte[][] byteArrays)
    {
        var threads = new List<Thread>();
        foreach (var byteArray in byteArrays)
        {
            Thread thread = new Thread(() => ComputeMd5File(byteArray));
            threads.Add(thread);
            thread.Start();
        }
        foreach (var thread in threads)
        {
            thread.Join();
        }
    }

    private void ComputeMd5File(byte[] byteArray)
    {
        using var md5 = MD5.Create();
        using var ms = new MemoryStream(byteArray);
        ms.Position = 0;
        using var sr = new StreamReader(ms);
        string fileContent;
        do
        {
            fileContent = sr.ReadLine();
            if (!string.IsNullOrEmpty(fileContent))
            {
                md5.TransformFinalBlock(Encoding.UTF8.GetBytes(fileContent), 0, fileContent.Length * Encoding.UTF8.GetByteCount(fileContent));
            }
        } while (fileContent != null);
        var hash = BitConverter.ToString(md5.Hash).Replace("-", "").ToLower();
        _results.Add(new DataTableReader(hash));
    }

    public void Start()
    {
        using var dbConnection = _connectionPool.GetConnection();
        try
        {
            foreach (var result in _results)
            {
                string query = "SELECT * FROM your_database WHERE hash = @hash";
                using var cmd = new SqlCommand(query, dbConnection);
                cmd.Parameters.AddWithValue("@hash", result.Hash);
                DataTable dataTable = new DataTable();
                using var da = new SqlDataAdapter(cmd);
                da.Fill(dataTable);
                if (dataTable.Rows.Count > 0)
                {
                    // handle query results
                }
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex);
        }
        finally
        {
            _connectionPool.ReleaseConnection(dbConnection);
        }
    }
}
