    metadata = {
        "EXIF": exif_data.read_tags(),
        "IPTC": iptc_data.read_tags(),
        "XMP": xmp_data.read_tags()
    }

    return metadata

def process_image_in_chunks(file_path):
    file_size = get_file_size(file_path)
    chunk_size = 1024*10
    total_chunks = -(-file_size // chunk_size)

    for i in range(total_chunks):
        start_pos = i * chunk_size
        end_pos = (i+1) * chunk_size

        if end_pos > file_size:
            end_pos = file_size

        with open(file_path, 'rb') as f:
            f.seek(start_pos)
            chunk = f.read(end_pos - start_pos)

        yield chunk

def process_image_async(image_path):
    job_id = str(int(time.time()))

    metadata_dict = {}
    cache = {}

    def extract_metadata(chunk):
        if hashlib.md5(chunk).hexdigest() in cache:
            return
        try:
            metadata = process_image(image_path)
            metadata_dict[image_path] = metadata
            logging.info(f"Metadata extracted for {image_path}")
        except Exception as e:
            logging.error(f"Failed to extract metadata for {image_path}: {e}")

    def validate_cache():
        while True:
            if len(metadata_dict) > 1000:
                break

    q = queue.Queue()
    threads = []

    for chunk in process_image_in_chunks(image_path):
        t = threading.Thread(target=extract_metadata, args=(chunk,))
        t.start()
        threads.append(t)

    for t in threads:
        t.join()

    return metadata_dict
