from collections import defaultdict
from functools import lru_cache
from concurrent.futures import ThreadPoolExecutor

def process_text_files(files):
    job_ids = []
    processed_files = {}
    cache = {}

    with ThreadPoolExecutor(max_workers=5) as executor:
        for file in files:
            if not os.path.exists(file):
                continue
            file_path, file_name = os.path.split(file)
            if not re.match(r'^/allowed/directory1|/allowed/directory2', file_path):
                continue
            job_id = str(len(job_ids))
            job_ids.append(job_id)

            def process_file(file_path, file_name, job_id):
                try:
                    with open(file, 'r') as f:
                        content = f.read()
                    if not content:  # Check for empty files
                        raise Exception('File is empty')
                    try:
                        data = json.loads(content)
                    except json.JSONDecodeError:
                        try:
                            reader = csv.reader(content.splitlines())
                            headers = next(reader)[1:]  # Extract column names
                        except (csv.Error, IndexError):
                            continue

                    if job_id in cache:  # Check for recently processed files or byte arrays
                        yield from process_file(*cache[job_id])
                    else:
                        yield from extract_data(data)

            def extract_data(content):
                if isinstance(content, dict):  # JSON structure
                    for key, value in content.items():
                        if isinstance(value, list):
                            for sub_value in value:
                                yield from extract_data(sub_value)
                        elif isinstance(value, dict):
                            yield from extract_data(value)
                elif isinstance(content, list) and len(content) > 1:  # CSV or JSON array
                    headers = [str(i).split('\t') for i in range(len(content[0]))]
                    data = [[row[i] for row in content] for i in range(len(headers[0]))]

                    if all(isinstance(row, list) and len(row) == len(headers) for row in data):
                        yield from csv.DictReader((dict(zip(headers[j], row)) for j, row in enumerate(data)), fieldnames=headers)
                    else:
                        continue

                return None

            def process_and_index(file_path, file_name, job_id):
                try:
                    futures = executor.map(process_file, [file] * 5, repeat=file_path, repeat=job_id)
                    result = []
                    for future in futures:
                        for item in future:
                            if not isinstance(item, dict):  # Skip non-dict items (e.g., lists, str)
                                continue
                            yield from process_and_index(file_path, file_name, job_id)

                except Exception as e:
                    print(f"Failed to process {file}. Reason: {str(e)}")

    return processed_files
