    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        if (!regexec(&re, line, 0, NULL, 0)) {
            fwrite(line, strlen(line), 1, op_fp);
        }
    }

    regfree(&re);
    fclose(fp);
    fclose(op_fp);
