                using (var reader = await command.ExecuteReaderAsync())
                {
                    return reader;
                }
            }
            catch (Exception ex)
            {
                // Log or handle the exception as needed
                throw;
            }
        }
    }

    public static async Task<DataTableReader> SendByteArrayToDatabaseAsynchronous(byte[] byteArray, string connectionString, int chunkSize = 8192)
    {
        using (var connection = new MySqlConnection(connectionString))
        {
            try
            {
                await connection.OpenAsync();
                var command = new MySqlCommand("SELECT * FROM YourTable", connection);
                using (var reader = await command.ExecuteReaderAsync())
                {
                    return await ReadDataTableReaderAsynchronous(reader, byteArray, chunkSize);
                }
            }
            catch (Exception ex)
            {
                // Log or handle the exception as needed
                throw;
            }
        }
    }

    private static async Task<DataTableReader> ReadDataTableReaderAsynchronous(IDataReader reader, byte[] byteArray, int chunkSize)
    {
        var bytesRead = 0;
        while (bytesRead < byteArray.Length)
        {
            var chunk = byteArray.Substring(bytesRead, Math.Min(chunkSize, byteArray.Length - bytesRead));
            await reader.ReadAsync();
            bytesRead += chunk.Length;
        }
        return reader;
    }
}
