def calculate_md5_hash(file_path: str, chunk_size: int = 8192) -> str:
    md5 = hashlib.md5()
    with open(file_path, 'rb') as file:
        file_size = file.seek(0, 1)
        for offset in range(0, file_size, chunk_size):
            file.seek(offset)
            chunk = file.read(min(chunk_size, file_size - offset))
            md5.update(chunk)
            if (offset % (file_size // 10) == 0 and offset != 0) or offset == file_size:
