import csv
from collections import defaultdict
import threading

class WordFrequencyGenerator:
    def __init__(self, cache_size=1000):
        self.cache_size = cache_size
        self.word_freq = defaultdict(int)
        self.cache = {}
        self.lock = threading.Lock()
        self.background_thread = None

    def start_background_thread(self):
        if not self.background_thread:
            self.background_thread = threading.Thread(target=self.flush_cache)
            self.background_thread.start()

    def flush_cache(self):
        while True:
            with self.lock:
                for word, count in list(self.cache.items()):
                    if len(self.cache) > self.cache_size:
                        del self.cache[word]
                self.word_freq = {word: count for word, count in self.word_freq.items() if word in self.cache}
            time.sleep(60)  # flush cache every minute

    def process_csv_file(self, file_path):
        with open(file_path, 'r') as csvfile:
            reader = csv.reader(csvfile)
            for row in reader:
                for word in row:
                    word = word.lower()
                    if word not in self.cache:
                        self.cache[word] = 0
                    self.cache[word] += 1
                    self.word_freq[word] += 1
        return self.word_freq

# Example usage:
gf = WordFrequencyGenerator()
gf.start_background_thread()
word_freq = gf.process_csv_file('large_data.csv')
print(word_freq)
