import hashlib
import os
from urllib.parse import urlparse
import concurrent.futures

class MD5Hasher:
    def __init__(self, max_file_size=1024*1024*10, skip_small_files=False):
        self.max_file_size = max_file_size
        self.skip_small_files = skip_small_files

    def get_hash(self, file_path):
        try:
            if not os.path.exists(file_path):
                raise FileNotFoundError(f"{file_path} does not exist")
            file_size = os.path.getsize(file_path)
            if self.skip_small_files and file_size < self.max_file_size:
                return "File too small to hash"
            with open(file_path, 'rb') as f:
                md5_hash = hashlib.md5()
                for chunk in iter(lambda: f.read(4096), b""):
                    md5_hash.update(chunk)
                return md5_hash.hexdigest()
        except Exception as e:
            print(f"Error hashing {file_path}: {e}")
            return None

    def get_hashes(self, file_paths):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.get_hash, path): path for path in file_paths}
            results = {}
            for future in concurrent.futures.as_completed(futures):
                file_path = futures[future]
                result = future.result()
                if isinstance(result, str):
                    print(f"Skipping {file_path}: {result}")
                else:
                    results[file_path] = result
        return results

    def process_remote_files(self, file_paths):
        for file_path in file_paths:
            parsed_url = urlparse(file_path)
            if parsed_url.scheme != '':  # Remote file
                try:
                    with requests.get(file_path) as response:
                        if response.status_code == 200:
                            md5_hash = self.get_hash(response.content)
                            print(f"Hashed {file_path}: {md5_hash}")
                        else:
                            raise Exception(f"Failed to access {file_path} ({response.status_code})")
                except requests.exceptions.RequestException as e:
                    print(f"Error accessing {file_path}: {e}")

# Example usage
hasher = MD5Hasher(max_file_size=1024*1024, skip_small_files=True)
file_paths = ['local/file1.txt', 'remote/file2.txt']
md5_hashes = hasher.get_hashes(file_paths)
print(md5_hashes)

