import hashlib
import os
import logging
from concurrent.futures import ThreadPoolExecutor

def calculate_md5(file_path: str, max_size_limit: int = 1024 * 1024 * 1000, min_file_size: int = 10 * 1024 * 1024):
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        logging.error(f"Invalid file path: {file_path}")
        return None

    try:
        file_size = os.path.getsize(file_path)
        if file_size < min_file_size:
            logging.info("File size is below the minimum threshold, skipping hashing.")
            return None

        chunk_size = 1024 * 1024
        if file_size > max_size_limit:
            with ThreadPoolExecutor() as executor:
                chunks = [file_path[i:i + chunk_size] for i in range(0, file_size, chunk_size)]
                futures = {executor.submit(os.open, path, os.O_RDONLY) for path in chunks}
                hashes = []
                for future in futures:
                    file_hash = hashlib.md5()
                    with open(future.result(), 'rb') as f:
                        while True:
                            data = f.read(chunk_size)
                            if not data:
                                break
                            file_hash.update(data)
                    hashes.append(file_hash.hexdigest())
            return ''.join(hashes)

        file_hash = hashlib.md5()
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                file_hash.update(data)
        return file_hash.hexdigest()

    except Exception as e:
        logging.error(f"Error occurred during hashing: {e}")
        return None

def log_progress(file_path, progress):
    logging.info(f"Hashing {file_path}... ({progress:.0%})")

if __name__ == "__main__":
    logging.basicConfig(filename='md5_hash.log', level=logging.INFO)

    file_path = "path_to_your_file.txt"
    md5_hash = calculate_md5(file_path)

    if md5_hash:
        print(f"MD5 Hash: {md5_hash}")
    else:
        print("Failed to generate MD5 hash.")
