import hashlib
import os
import requests
import time
from concurrent.futures import ThreadPoolExecutor
from logging import getLogger

logger = getLogger()

def calculate_md5(file_path):
    md5_hash = hashlib.md5()

    chunk_size = 8192

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)

            if not chunk:
                break

            md5_hash.update(chunk)

    return md5_hash.hexdigest()

def calculate_md5_in_chunks(file_path, chunk_size):
    md5_hash = hashlib.md5()

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)

            if not chunk:
                break

            md5_hash.update(chunk)

    return md5_hash.hexdigest()

def verify_and_upload_md5_to_cloud(file_path):
    try:
        cloud_response = requests.post(
            'https://cloud-storage-service.com/api/upload',
            data={'file': open(file_path, 'rb')}
        )

        if cloud_response.status_code == 200:
            return True
        else:
            return False
    except (requests.exceptions.RequestException, FileNotFoundError):
        logger.error(f"Error uploading file {file_path} to the cloud storage service: {cloud_response.text}")
        return None

def calculate_md5_for_multiple_files(file_paths, chunk_size):
    with ThreadPoolExecutor() as executor:
        results = list(executor.map(calculate_md5_in_chunks, file_paths, [chunk_size]*len(file_paths)))

    return results

def track_progress(file_paths):
    total_size = sum(os.path.getsize(path) for path in file_paths)

    for i, file_path in enumerate(file_paths):
        percentage = int((i+1)/len(file_paths)*100)

        if percentage % 10 == 0:
            print(f"Processing {percentage}%...")

def process_file(file_path):
    try:
        md5_hash = calculate_md5(file_path)

        print(f"File {file_path} processed. MD5 hash: {md5_hash}")

        verify_and_upload_md5_to_cloud(file_path)

        track_progress([file_path])

    except Exception as e:
        logger.error(f"Error processing file {file_path}: {str(e)}")

def main():
    file_paths = ['path1', 'path2', ...]  # List of file paths
    chunk_size = 8192

    with ThreadPoolExecutor() as executor:
        results = list(executor.map(process_file, file_paths))

if __name__ == "__main__":
    main()
