    file_size_limit = 1024 * 1024 * 100  # 100MB
    skip_small_files = True
    max_concurrent_chunks = 10

    if not file_path:
        raise ValueError("File path is required")

    try:
        with open(file_path, 'rb') as f:
            file_size = f.seek(0, 2)
            if skip_small_files and file_size < file_size_limit:
                return {"hash": "", "report": f"Skipped small file {file_path}"}

            logging.info(f"Hashing file {file_path} of size {file_size}")

            with ThreadPoolExecutor(max_workers=max_concurrent_chunks) as executor:
                futures = []
                for i in range(0, file_size, chunk_size):
                    f.seek(i)
                    future = executor.submit(process_chunk, f, md5_hash, chunk_size)
                    futures.append(future)

                total_chunks = (file_size + chunk_size - 1) // chunk_size
                processed_chunks = 0

                for future in futures:
                    try:
                        _ = future.result()
                        processed_chunks += 1
                    except Exception as e:
                        logging.error(f"Error processing chunk: {str(e)}")

                    if processed_chunks % (total_chunks / 10) == 0:
                        logging.info(f"Hashing progress: {(processed_chunks / total_chunks) * 100}%")

                md5_hash = hashlib.md5()
            return {"hash": md5_hash.hexdigest(), "report": f"File {file_path} hashed successfully"}
    except FileNotFoundError:
        raise ValueError(f"The file '{file_path}' was not found")
    except PermissionError:
        raise PermissionError(f"No permission to access the file '{file_path}'")
