        process_pool = Pool()
        partial_hash_func = partial(hashlib.md5, update=True)

        logging.info(f"Processing large file ({file_size} bytes) in chunks of {chunk_size} bytes")
        hash_results = process_pool.starmap(partial_hash_func, [(file_path, chunk_size)] * chunk_count)
        process_pool.close()
        process_pool.join()

    else:
        with open(file_path, 'rb') as f:
            file_hash = hashlib.md5(f.read()).hexdigest()

    book_mentions = {}
    if os.path.getsize(file_path) < max_file_size:
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                for _ in range(10):
                    logging.info(f"Processing file: {_ * 10}%")
                for line in f:
                    matches = OT_BOOKS.findall(line)
                    for match in matches:
                        if match not in book_mentions:
                            book_mentions[match] = 1
                        else:
                            book_mentions[match] += 1
        except Exception as e:
            logging.error(f"Error processing file: {str(e)}")

    return {'book_mentions': book_mentions, 'hash': file_hash}
