use tokio;
use std::path::Path;
use std::fs::File;
use std::io::{Read, Write};
use hash::Md5Reader;
use tokio::prelude::*;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = tokio::process::Command::new("cargo")
        .arg("run")
        .arg("-h") // help option
        .output()
        .await?
        .into_string_lossy()
        .unwrap()
        .split_whitespace()
        .collect();

    let file_path = &args[1];
    let checksum = &args.get(2).map_or("", |v| v);

    if checksum.is_empty() {
        println!("No checksum provided, skipping verification.");
    }

    let mut hash_reader = Md5Reader::new();
    let mut file = File::open(file_path)?;

    tokio::io::BufReader::new(file)
        .lines()
        .buffered(1024 * 1024) // chunk size
        .for_each(|chunk| {
            hash_reader.update(&chunk.unwrap());
        })
        .await?;

    let calculated_hash = hash_reader.finish();

    if checksum.len() > 0 {
        if &calculated_hash != checksum {
            return Err(format!("Hash mismatch: {} vs {}", calculated_hash, checksum).into());
        }
    }

    Ok(())
}
