use tokio::runtime;
use std::path::Path;
use std::fs::File;
use std::io::{Read, BufReader};
use md5::{Md5, Md5Context};
use async_std::prelude::*;
use futures::future;

async fn calculate_md5(path: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut file = File::open(path)?;
    let chunk_size = 4096; // Adjust dynamically based on available memory
    let mut md5_ctx = Md5Context::new();
    let mut chunk = [0u8; chunk_size];
    let mut total_chunks = 0;

    while let Ok(n) = file.read(&mut chunk) {
        if n == 0 {
            break;
        }
        md5_ctx.update(&chunk[..n]);
        total_chunks += 1;
    }

    let hash = format!("{:x}", md5_ctx.finalize());
    println!("Calculated MD5 for {}: {}", path, hash);

    Ok(hash)
}

async fn verify_checksums(path: &str, checksums: Vec<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let expected_hash = calculate_md5(path).await?;
    if !checksums.iter().any(|&cs| cs.to_uppercase() == expected_hash.to_uppercase()) {
        return Err(format!("Checksum mismatch for {}: {}", path, expected_hash).into());
    }
    Ok(())
}

