public async Task<RemoteServiceResponse> SendRequestAsync(byte[] data)
{
    try
    {
        using (var client = new HttpClient())
        {
            client.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));

            var request = new HttpRequestMessage(HttpMethod.Post, "https://remote-api.com/service");
            request.Content = new ByteArrayContent(data);

            HttpResponseMessage response = await client.SendAsync(request);

            if (response.IsSuccessStatusCode)
            {
                string responseBody = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<RemoteServiceResponse>(responseBody);
            }
            else
            {
                throw new Exception($"Failed to send request. Status code: {response.StatusCode}");
            }
        }
    }
