import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor

def calculate_md5(file_path: str):
    chunk_size = 1024 * 1000  # 1MB chunks for performance
    md5_hash = hashlib.md5()

    if not os.path.exists(file_path):
        raise ValueError(f"File does not exist: {file_path}")

    with open(file_path, 'rb') as file:
        while chunk := file.read(chunk_size):
            md5_hash.update(chunk)

    return md5_hash.hexdigest()

def calculate_md5_batch(files_paths: list):
    progress = 0
    hashes = {}

    with ThreadPoolExecutor() as executor:
        futures = {executor.submit(calculate_md5, path): path for path in files_paths}

        for future in futures:
            file_path = future.result()
            md5_hash = calculate_md5(file_path)
            hashes[file_path] = md5_hash
            progress += 1
            print(f"Hashed: {file_path}, Progress: {(progress / len(files_paths)) * 100:.2f}%")

    return hashes

def verify_checksum(md5_hash, checksum):
    if md5_hash == checksum:
        return True
    else:
        return False, md5_hash, None

def pause_resume(file_path, pause_time=1):
    while True:
        print(f"Press Enter to resume: {file_path}")
        input()
        time.sleep(pause_time)

def main():
    file_paths = ["path1", "path2"]
    batch_hashes = calculate_md5_batch(file_paths)

    for file_path, md5_hash in batch_hashes.items():
        checksum = "checksum_string"
        match, calculated_hash, progress = verify_checksum(md5_hash, checksum)

        if not match:
            print(f"MD5 mismatch: {file_path}. Expected: {checksum}, Calculated: {calculated_hash}")

    pause_resume(file_paths[0])

if __name__ == "__main__":
