import hashlib
import os
import time
from threading import Thread

def batch_md5_hash(structures):
    if not isinstance(structures, list) or len(structures) > 1000:
        raise ValueError("Invalid number of structures")

    def calculate_md5(file_path):
        md5 = hashlib.md5()
        file_size = os.path.getsize(file_path)
        chunk_size = 1024 * 1024  # 1MB chunks

        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                md5.update(data)

        return md5.hexdigest()

    def hash_file_progress(file_path):
        start_time = time.time()
        file_size = os.path.getsize(file_path)
        chunk_size = 1024 * 1024  # 1MB chunks

        with open(file_path, 'rb') as f:
            progress = 0
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                md5.update(data)
                progress += len(data) / file_size * 100
                print(f"Hashing {file_path} ({progress:.2f}%): {time.time() - start_time:.2f}s")
        return progress

    def verify_checksum(file_path, checksum):
        with open(file_path, 'rb') as f:
            md5 = hashlib.md5()
            while True:
                data = f.read(1024 * 1024)  # 1MB chunks
                if not data:
                    break
                md5.update(data)
        return md5.hexdigest() == checksum

    def string_md5(s):
        try:
            s.encode('utf-8')
        except UnicodeError as e:
            raise ValueError(f"Invalid character in the string: {e}")

        md5 = hashlib.md5()
        md5.update(s.encode('utf-8'))
        return md5.hexdigest()

    result = []
    for file_path, checksum in structures:
        try:
            if os.path.isfile(file_path):
                if checksum:
                    verified = verify_checksum(file_path, checksum)
                else:
                    verified = None
                progress = hash_file_progress(file_path)
                calculated_hash = calculate_md5(file_path)
                result.append((calculated_hash, verified, progress))
            elif isinstance(file_path, str):
                try:
                    s = file_path.encode('utf-8')
                except UnicodeError as e:
                    raise ValueError(f"Invalid character in the string: {e}")
                calculated_hash = string_md5(s)
                result.append((calculated_hash, None, 0))
            else:
                raise ValueError("Invalid input structure")
        except Exception as e:
            print(f"Error hashing file {file_path}: {str(e)}")

    return tuple(result)

# Example usage:
