import xml.etree.ElementTree as ET
from io import StringIO
from typing import Tuple, Dict

def validate_xml_file(file_path: str, schema_version: int, schema_file: str = None) -> Tuple[bool, Dict]:
    try:
        with open(file_path, 'rb') as file:
            chunk_size = 1024 * 50  # read in chunks of 50 MB
            xml_string = b''
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                xml_string += chunk

    except FileNotFoundError:
        return False, {'error': 'File not found'}
    except PermissionError:
        return False, {'error': 'Permission denied'}

    try:
        root = ET.parse(StringIO(xml_string.decode())).getroot()
    except ET.ParseError as e:
        return False, {'error': str(e)}

    if schema_file and schema_version > 0:
        try:
            schema_root = ET.parse(schema_file).getroot()
        except ET.ParseError:
            return False, {'error': 'Invalid schema file'}

        if not ET.iselement(root):
            return False, {'error': 'Root element not found'}

        # Validate against the schema
        try:
            ET.XSLTProcessor().parse(schema_root).transform(root)
        except ET.ParseError as e:
            return False, {'error': str(e)}

    return True, {}
