using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;

public class LoadState
{
    public static MoSTState? Load(string filePath)
    {
        try
        {
            using (FileStream fs = File.Open(filePath, FileMode.Open))
            {
                using (BinaryReader br = new BinaryReader(fs))
                {
                    // Read the file header
                    byte[] header = new byte[4];
                    br.Read(header, 0, 4);

                    // Check the version number in the header
                    int version = BitConverter.ToInt32(header, 0);
                    MoSTState? mostState = null;

                    switch (version)
                    {
                        case 1:
                            // Deserialize the file contents into a MoSTState object
                            mostState = (MoSTState?)BinaryFormatter.Deserialize(new MemoryStream(br.ReadBytes((int)br.BaseStream.Length)));
                            break;
                        case 2:
                            // LegacyState is being loaded; handle this type separately
                            br.BaseStream.Seek(0, SeekOrigin.Begin);
                            LegacyState? legacyState = (LegacyState?)BinaryFormatter.Deserialize(new MemoryStream(br.ReadBytes((int)br.BaseStream.Length)));
                            break;
                        case 3:
                            // EnhancedState is being loaded; handle this type separately
                            br.BaseStream.Seek(0, SeekOrigin.Begin);
                            EnhancedState? enhancedState = (EnhancedState?)BinaryFormatter.Deserialize(new MemoryStream(br.ReadBytes((int)br.BaseStream.Length)));
                            mostState = enhancedState;
                            break;
                    }

                    return mostState;
                }
            }
        }
        catch (Exception ex)
        {
            // Log the error
            File.AppendAllText("error.log", DateTime.Now.ToString() + " - Error loading state: " + ex.Message + Environment.NewLine);

            // Maintain a count of failed attempts to load each type
            int mostStateCount = File.ReadAllLines("most_state_count.txt").Length;
            int legacyStateCount = File.ReadAllLines("legacy_state_count.txt").Length;
            int enhancedStateCount = File.ReadAllLines("enhanced_state_count.txt").Length;

            // If the deserialization fails, continue attempting to load the next type
            if (ex is FormatException)
                return LoadState.Load(filePath);
            else if (mostStateCount > 0 || legacyStateCount > 0 || enhancedStateCount > 0)
                File.AppendAllText("error.log", "Failed attempt to load state: " + ex.Message + Environment.NewLine);

            return null;
        }
    }
}
