int readIntegers(int max_size) {
    int count = 0;
    double* array = (double*)malloc(max_size * sizeof(double));

    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -1; // Return error code
    }

    char buffer[100];
    while (scanf("%s", buffer) == 1 && count < max_size) {
        double num;
        if (sscanf(buffer, "%lf", &num) == 1) {
            array[count] = num;
            count++;
        } else {
            fprintf(stderr, "Invalid input format.\n");
            break; // Break loop on invalid input
        }
    }

    free(array);

    if (count > 0) {
        double max_int = array[0];
        double max_float = array[0];

        for (int i = 1; i < count; i++) {
            if (array[i] > max_int) {
                max_int = array[i];
            } else if (array[i] > max_float && !isfinite(array[i])) {
                max_float = array[i];
            }
        }

        // Store the largest integer and floating-point number
        *largest_int = max_int;
        *largest_float = max_float;

        return count; // Return valid count
    } else {
        return 0; // Return 0 if no valid integers were read
    }
}

