int read_ints(int* n) {
    int* ints = (int*)malloc(MAX_INTS * sizeof(int));
    int i = 0;
    while (i < MAX_INTS && scanf("%d", &ints[i]) == 1) {
        i++;
    }
    *n = i;
    return ints;
}

void print_largest(floats, n_floats, ints, n_ints) {
    printf("Largest integer: %d\n", *(int*)max_array(ints, n_ints));
    printf("Largest floating-point number: %lf\n", *(double*)max_array(floats, n_floats));
    printf("Smallest floating-point number: %lf\n", *(double*)min_array(floats, n_floats));
}

int max_array(arr, n) {
    int i;
    int max = arr[0];
    for (i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

double* min_array(arr, n) {
    int i;
    double min = arr[0];
    for (i = 1; i < n; i++) {
        if (arr[i] < min)
            min = arr[i];
    }
    double* result = (double*)malloc(sizeof(double));
    *result = min;
    free(arr);
    return result;
}

int main() {
    int n_ints, n_floats;
    double* floats = read_floats(&n_floats);
    int* ints = read_ints(&n_ints);

