#include <pthread.h>

#define MAX_THREADS 10

typedef struct {
    int verbose;
    char* output_file;
} config_t;

config_t config = {0, NULL};

void* process_file(void* file_data) {
    FILE* file = (FILE*)file_data;
    int lines = 0;

    // Additional processing on each line
    while(fgets(line, sizeof(line), file)) {
        lines++;

        if(config.verbose)
            printf("%s", line);

        // Perform some other operations...
    }

    fclose(file);

    return NULL;
}

void print_usage() {
    printf("Usage: ./program [options] file1 [file2 ...]\n");
    printf("Options:\n");
    printf("-cs, --stats\n");
    printf("-o output_file\n");
    printf("--verbose\n");
}

int main(int argc, char* argv[]) {
    int num_threads = 0;
    pthread_t threads[MAX_THREADS];

    for(int i = 1; i < argc; i++) {
        if(strcmp(argv[i], "-cs") == 0 || strcmp(argv[i], "--stats") == 0)
            config.verbose++;
        else if(strcmp(argv[i], "-o") == 0) {
            config.output_file = argv[i + 1];
            i++;
        }
    }

    for(int i = 1; i < argc; i++) {
        if(strncmp(argv[i], "--", 2) == 0)
            continue;

        FILE* file = fopen(argv[i], "r");
        if(file == NULL) {
            perror(argv[i]);
            continue;
        }

        pthread_create(&threads[num_threads++], NULL, process_file, (void*)file);
    }

    for(int i = 0; i < num_threads; i++)
        pthread_join(threads[i], NULL);

    printf("Processed %d files.\n", num_threads);

    return 0;
}
