#include <stdio.h>
#include <stdarg.h>
#include <string.h>

#define LOG_MAX_SIZE 1024
#define LOG_MAX_ENTRIES 1000
#define LOG_BUFFER_SIZE (LOG_MAX_ENTRIES * sizeof(char*))

typedef struct {
    char** buffer;
    int head, tail, size;
} LogBuffer;

void conditionalLog(LogBuffer* logBuffer, const char* level, va_list args) {
    static char message[LOG_MAX_SIZE];
    vsnprintf(message, LOG_MAX_SIZE, message, args);

    if (logBuffer->size >= LOG_MAX_ENTRIES) {
        // Rotate the buffer if it's full
        for (int i = 0; i < logBuffer->head; i++) {
            free(logBuffer->buffer[(i + 1) % LOG_MAX_ENTRIES]);
        }
        logBuffer->head = logBuffer->tail = 0;
        logBuffer->size = 0;
    }

    // Add the new entry to the buffer
    if (logBuffer->size < LOG_MAX_ENTRIES) {
        logBuffer->buffer[logBuffer->tail % LOG_MAX_ENTRIES] = malloc(LOG_MAX_SIZE);
        strcpy(logBuffer->buffer[logBuffer->tail++], message);

        logBuffer->size++;
    }
}

LogBuffer* createLogBuffer() {
    LogBuffer* buffer = (LogBuffer*)malloc(sizeof(LogBuffer));
    buffer->buffer = (char**)malloc(LOG_BUFFER_SIZE);
    buffer->head = buffer->tail = 0;
    buffer->size = 0;

    return buffer;
}
