void userSessions_init(UserSession** sessions, int* size) {
    *size = 0;
    *sessions = NULL;
}

void userSessions_append(UserSession*** sessions, int* size, int userId, const char* ip, time_t startTime) {
    if (*size == 0 || *size % 16 == 0) {
        *sessions = realloc(*sessions, sizeof(UserSession*) * ((*size + 16) / 16) * 16);
    }
    UserSession* session = malloc(sizeof(UserSession));
    session->userId = userId;
    session->startTime = startTime;
    strcpy(session->ip, ip);
    session->status = strdup("connected");
    (*sessions)[(*size)++] = session;
}

void userSessions_updateStatus(UserSession** sessions, int size, const char* status) {
    for (int i = 0; i < size; i++) {
        if ((*sessions)[i]->status != NULL) {
            free((*sessions)[i]->status);
        }
        (*sessions)[i]->status = strdup(status);
    }
}

void userSessions_free(UserSession** sessions, int size) {
    for (int i = 0; i < size; i++) {
        if ((*sessions)[i]->status != NULL) {
            free((*sessions)[i]->status);
        }
        free((*sessions)[i]);
    }
    free(*sessions);
}

int userSessions_countActive(UserSession** sessions, int size, const char* ipStart, const char* ipEnd) {
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (strcmp((*sessions)[i]->ip >= ipStart && strcmp((*sessions)[i]->ip <= ipEnd)) {
            if (difftime(time(NULL), (*sessions)[i]->startTime) < 300) { // 5 minutes
                count++;
            }
        }
    }
    return count;
}
