#define MAX_CONNECTIONS 1000
#define LOG_BUF_SIZE 1024

typedef enum {
    ESTABLISHED,
    CLOSE_WAIT,
    LAST_ACK,
} connection_status;

typedef struct {
    int id;
    long timestamp;
    connection_status status;
} tcp_connection_state;

typedef struct {
    int count;
    tcp_connection_state *states;
} connection_directory;

connection_directory* initialize_directory(const char* dir_path) {
    int fd = open(dir_path, O_RDWR | O_CREAT, S_IRWXU);
    if (fd < 0) return NULL;

    connection_directory* directory = malloc(sizeof(connection_directory));
    directory->count = 0;
    directory->states = malloc(MAX_CONNECTIONS * sizeof(tcp_connection_state));

    close(fd);

    return directory;
}

int add_connection(connection_directory* directory, int id, long timestamp, connection_status status) {
    if (directory == NULL || id < 1) return -1;

    if (directory->count >= MAX_CONNECTIONS) {
        // Batch operation to prevent resource exhaustion
        for (int i = 0; i < directory->count; i++) {
            printf("Adding connections in batches...\n");
        }
        return -2;
    }

    tcp_connection_state* state = &directory->states[directory->count++];
    state->id = id;
    state->timestamp = timestamp;
    state->status = status;

    return 0;
}

int update_timestamp(connection_directory* directory, int id, long timestamp) {
    if (directory == NULL || id < 1) return -1;

    for (int i = 0; i < directory->count; i++) {
        tcp_connection_state* state = &directory->states[i];
        if (state->id == id) {
            state->timestamp = timestamp;
            return 0;
        }
    }

    return -2;
}

int close_connection(connection_directory* directory, int id) {
    if (directory == NULL || id < 1) return -1;

    for (int i = 0; i < directory->count; i++) {
        tcp_connection_state* state = &directory->states[i];
        if (state->id == id) {
            state->status = LAST_ACK;
            return 0;
        }
    }

    return -2;
}

int log_connection_state(connection_directory* directory, const char* path) {
    if (directory == NULL || path == NULL) return -1;

    FILE* file = fopen(path, "a");
    if (file == NULL) return -2;

    for (int i = 0; i < directory->count; i++) {
        tcp_connection_state* state = &directory->states[i];
        fprintf(file, "%d %ld %s\n", state->id, state->timestamp, get_status_string(state->status));
    }

    fclose(file);
    return 0;
}

const char* get_status_string(connection_status status) {
    switch (status) {
        case ESTABLISHED:
            return "ESTABLISHED";
        case CLOSE_WAIT:
            return "CLOSE_WAIT";
        case LAST_ACK:
            return "LAST_ACK";
        default:
            return "UNKNOWN";
    }
}
