**Python: processLargeFile**

```python
import os
import hashlib
import gzip
import heapq

def processLargeFile(path):
    chunk_size = 1024 * 1024  # default to 1MB
    file_size = os.path.getsize(path)

    with open(path, 'rb') as f:
        while True:
            data = f.read(min(chunk_size, file_size))
            if not data:
                break

            normalized_data = normalize(data)
            deduplicated_data = deduplicate(normalized_data)
            compressed_data = gzip.compress(deduplicated_data)

            hash_object = hashlib.md5()
            hash_object.update(compressed_data)
            md5_hash = hash_object.hexdigest()

            file_size -= len(data)
            print(f"Processed {file_size / (1024 * 1024)} MB...")

    return md5_hash, len(compressed_data)
}
