typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Doubly-Linked List Node Structure
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Linked List Structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex; // Synchronization Mechanism for Thread Safety
} LinkedList;

// Function to Initialize the Doubly-Linked List
LinkedList* initLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list) {
        list->head = NULL;
        list->tail = NULL;
        list->size = 0;
        pthread_mutex_init(&list->mutex, NULL);
    }
    return list;
}

// Function to Insert a New Log Entry into the List
void insertLogEntry(LinkedList* list, LogEntry entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode) {
        newNode->entry = entry;
        newNode->prev = NULL;
        newNode->next = list->head;

        // Update Head and Tail References
        if (list->head == NULL) {
            list->head = newNode;
            list->tail = newNode;
        } else {
            list->head->prev = newNode;
            list->head = newNode;
        }

        list->size++;
    }
}

// Function to Iterate Over the Linked List and Print Entries
void iterateAndPrint(LinkedList* list, int fd) {
    Node* current = list->head;

    while (current != NULL) {
        LogEntry entry = current->entry;
        printf("%ld %d %s\n", entry.timestamp, entry.logLevel, entry.message);

        // Write to File Descriptor
        write(fd, &entry, sizeof(LogEntry));

        current = current->next;
    }
}

// Function to Free Memory and Destroy the Linked List
void destroyLinkedList(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}
