typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Doubly-Linked List Node Structure
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Doubly-Linked List Structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    int size;
    int messageCount;
    size_t totalMessageSize;
    double averageMessageLength;
    pthread_mutex_t lock;
} LinkedList;

// Function to create a new LogEntry structure
LogEntry* logEntryCreate(time_t timestamp, int logLevel, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = strdup(message);
    return entry;
}

// Function to create a new LinkedList structure
LinkedList* listCreate() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->messageCount = 0;
    list->totalMessageSize = 0;
    list->averageMessageLength = 0.0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to free memory allocated for a LogEntry structure
void logEntryFree(LogEntry* entry) {
    free(entry->message);
    free(entry);
}

// Function to add an entry to the linked list
int listAdd(LinkedList* list, time_t timestamp, int logLevel, const char* message) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = logEntryCreate(timestamp, logLevel, message);
    node->prev = NULL;
    node->next = list->head;

    if (list->head != NULL)
        list->head->prev = &node->prev;

    list->tail = &node;
    list->size++;
    list->messageCount++;
    list->totalMessageSize += strlen(message) + 1; // include null terminator
    pthread_mutex_unlock(&list->lock);
    return 0;
}

// Function to print all log entries in the linked list
void listPrint(LinkedList* list, FILE* fileDescriptor) {
    Node* current = list->head;

    while (current != NULL) {
        LogEntry* entry = current->entry;
        fprintf(fileDescriptor, "Timestamp: %ld, LogLevel: %d, Message: %s\n", entry->timestamp, entry->logLevel, entry->message);
        current = current->next;
    }
}

// Function to free memory allocated for the linked list
void listFree(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        logEntryFree(current->entry);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to load a linked list from a binary file
LinkedList* listLoad(const char* filename) {
    // implementation details omitted for brevity
}

// Function to save a linked list to a binary file
int listSave(LinkedList* list, const char* filename) {
    // implementation details omitted for brevity
}

// Function to filter log entries by timestamp range and log level
void listFilter(LinkedList* list, time_t start, time_t end, int minLogLevel, int maxLogLevel, FILE* output) {
    Node* current = list->head;

    while (current != NULL) {
        LogEntry* entry = current->entry;
        if ((start <= entry->timestamp && entry->timestamp <= end) && (minLogLevel <= entry->logLevel && entry->logLevel <= maxLogLevel)) {
            fprintf(output, "Timestamp: %ld, LogLevel: %d, Message: %s\n", entry->timestamp, entry->logLevel, entry->message);
        }
        current = current->next;
    }
}

// Function to get statistics about the linked list
void listStatistics(LinkedList* list) {
    printf("Log entries: %d, Total message size: %zu bytes, Average message length: %.2f\n", list->size, list->totalMessageSize, list->averageMessageLength);
}
