    public static EVP_CIPHER ValidateAndChooseCipher(XmlDocument xmlDoc)
    {
        XmlElement root = xmlDoc.DocumentElement;
        XmlElement tokenResponse = root["OAuthTokenResponse"];

        if (tokenResponse == null)
            throw new Exception("No 'OAuthTokenResponse' element found in the XML document.");

        string jsonTokenResponse = tokenResponse.InnerText;

        dynamic tokenData = JsonConvert.DeserializeObject(jsonTokenResponse);

        if (!tokenData.ContainsKey("access_token") ||
            !tokenData.ContainsKey("expires_in") ||
            !tokenData.ContainsKey("token_type"))
            throw new Exception("OAuth2 access token response is invalid");

        if (tokenData["token_type"].ToString() != "Bearer" ||
            Convert.ToInt32(tokenData["expires_in"]) <= 0)
            throw new Exception("OAuth2 access token is invalid");

        EVP_CIPHER chosenCipher;

        // DES ECB mode
        chosenCipher = EVP_CipherInit(EVP_get_cipherbyname("des-ecb"), null, null);

        // DES EDE mode
        chosenCipher = EVP_CipherInit(EVP_get_cipherbyname("des-ede"), null, null);

        // DES EDE3 mode
        chosenCipher = EVP_CipherInit(EVP_get_cipherbyname("des-ede3"), null, null);

        // CFB mode
        chosenCipher = EVP_CipherInit(EVP_get_cipherbyname("des-cfb8"), null, null);

        // Null encryption for testing purposes
        chosenCipher = EVP_CipherInit(EVP_get_cipherbyname(""), null, null);

        return chosenCipher;
    }
}
