void insertIntoSortedVector(std::vector<int>& vec, int target, int toInsert) {
    if (vec.empty()) {
        vec.push_back(toInsert);
        return;
    }

    auto it = std::lower_bound(vec.begin(), vec.end(), target);

    vec.insert(it, toInsert);
}

void initializeAndTestVector(int n, int minVal, int maxVal) {
    std::vector<int> vec;

    for (int i = 0; i < n; ++i) {
        vec.push_back(minVal + rand() % (maxVal - minVal + 1));
    }

    // Test case: Empty vector
    insertIntoSortedVector(vec, 5, 3);
    std::cout << "Before insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;
    insertIntoSortedVector(vec, 8, 4);
    std::cout << "After insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;

    // Test case: Vector already sorted
    vec.clear();
    for (int i = 0; i < n; ++i) {
        vec.push_back(minVal + rand() % (maxVal - minVal + 1));
    }
    std::sort(vec.begin(), vec.end());
    insertIntoSortedVector(vec, 7, 5);
    std::cout << "Before insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;
    insertIntoSortedVector(vec, 10, 6);
    std::cout << "After insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;

    // Test case: Vector has duplicates
    vec.clear();
    for (int i = 0; i < n; ++i) {
        vec.push_back(minVal + rand() % (maxVal - minVal + 1));
    }
    vec.push_back(5);
    vec.push_back(3);
    insertIntoSortedVector(vec, 5, 2);
    std::cout << "Before insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;
    insertIntoSortedVector(vec, 8, 6);
    std::cout << "After insertion: ";
    for (int x : vec) { std::cout << x << " "; } std::cout << std::endl;
}

