} MetricSample;

typedef struct {
    MetricSample* buffer;
    size_t capacity;
    size_t size;
} CircularBuffer;

CircularBuffer* circular_buffer_init(size_t initial_capacity) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->buffer = (MetricSample*)calloc(initial_capacity, sizeof(MetricSample));
    buffer->capacity = initial_capacity;
    buffer->size = 0;
