class TokenBucket {
public:
    TokenBucket(int capacity, int refillRate) : tokens(capacity), refillRate(refillRate) {}

    bool try_acquire() {
        if (tokens <= 0) {
            this_thread::sleep_for(chrono::milliseconds(1));
            return false;
        }
        tokens -= refillRate;
        return true;
    }

private:
