public class FileProcessor
{
    public async Task<(List<string>, List<string>)> ProcessFilesAsync(List<string> filePaths, CloudStorageService cloudStorage, params Func<byte[], byte[], Task(byte[])>[] transformations)
    {
        var successfulFiles = new List<string>();
        var errorFiles = new List<string>();

        foreach (var filePath in filePaths)
        {
            try
            {
                using (var fileStream = File.OpenRead(filePath))
                {
                    var fileContent = new MemoryStream();
                    await fileContent.WriteToAsync(fileStream);

                    var processedFileContent = fileContent.ToArray();
                    foreach (var transformation in transformations)
                    {
                        processedFileContent = await transformation(fileContent.ToArray(), processedFileContent);
                    }

                    if (cloudStorage != null)
                    {
                        await cloudStorage.UploadFileAsync(filePath, processedFileContent);
                    }

                    successfulFiles.Add(filePath);
                }
            }
            catch (Exception ex)
            {
                errorFiles.Add(filePath);
                Console.WriteLine($"Error processing file {filePath}: {ex.Message}");
            }
        }

        return (successfulFiles, errorFiles);
    }
}
