from datetime import datetime

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

PREFERENCES = {}

def get_preference(identifier):
    return PREFERENCES.get(identifier)

def update_preference(identifier, data):
    if not identifier or not isinstance(data, dict):
        return jsonify({'error': 'Invalid request'}), 400
    if any(key in data for key in PREFERENCES.keys()):
        return jsonify({'error': 'Duplicate keys'}), 400
    PREFERENCES[identifier] = data
    cache.delete(identifier)
    return jsonify(PREFERENCES[identifier]), 200

def delete_preference(identifier):
    if not identifier:
        return jsonify({'error': 'Invalid request'}), 400
    preference = get_preference(identifier)
    if not preference:
        return jsonify({'error': 'Preference not found'}), 404
    del PREFERENCES[identifier]
    cache.delete(identifier)
    return jsonify({'preferences': list(PREFERENCES.keys())}), 200

@app.route('/preferences', methods=['GET'])
@cache.cached(timeout=60)  # Cache for 1 minute
def get_preferences():
    return jsonify(list(PREFERENCES.keys()))

@app.route('/preferences/<string:identifier>', methods=['PUT'])
def put_preference(identifier):
    return update_preference(identifier, request.get_json())

@app.route('/preferences/<string:identifier>', methods=['DELETE'])
