using System;
using System.Xml;
using System.Xml.XPath;

public class XPathParser
{
    private readonly XPathDocument _xpathDoc;
    private readonly XmlNamespaceManager _namespaceManager;
    private readonly bool _debugEnabled;

    public XPathParser(string xmlContent, bool debugEnabled)
    {
        _xpathDoc = new XPathDocument(new XmlDocument());
        _xpathDoc.LoadXml(xmlContent);
        _namespaceManager = new XmlNamespaceManager(_xpathDoc.NameTable);
        _debugEnabled = debugEnabled;
    }

    public List<XElement> ParseXPath(string xpathExpression, string elementName, params KeyValuePair<string, string>[] attributeFilters)
    {
        XPathNavigator navigator = _xpathDoc.CreateNavigator();
        XPathExpression expression = navigator.Compile(xpathExpression);

        XPathNodeIterator iterator = navigator.Select(expression);
        List<XElement> results = new List<XElement>();

        while (iterator.MoveNext())
        {
            XElement element = iterator.Current.ToXElement();

            if (element.Name.LocalName == elementName)
            {
                bool matchesAttributes = true;

                foreach (var filter in attributeFilters)
                {
                    XPathNodeIterator attrIterator = navigator.Select(expression.XPathEvaluate($"//{elementName}[@{filter.Key}='{filter.Value}' or @*[local-name()='*)' + filter.Key + "'][1]"));

                    if (!attrIterator.MoveNext())
                    {
                        matchesAttributes = false;
                        break;
                    }
                }

                if (matchesAttributes)
                {
                    results.Add(element);

                    // Log debugging information
                    if (_debugEnabled)
                    {
                        Console.WriteLine($"Found element '{elementName}' with attributes: {string.Join(", ", attributeFilters.Select(x => $"{x.Key}={x.Value}"))}");
                    }
                }
            }
        }

        return results;
    }
}
