public class UpdatePageElementController : ControllerBase
{
    private readonly ILogger _logger;
    private readonly IUpdateService _updateService;
    private readonly HashSet<string> _allowedTags = new HashSet<string> { "b", "i", "u", "strong", "em" };
    private readonly HashSet<string> _allowedAttributes = new HashSet<string> { "href", "title" };

    public UpdatePageElementController(ILogger logger, IUpdateService updateService)
    {
        _logger = logger;
        _updateService = updateService;
    }

    [HttpPost]
    public IActionResult UpdatePageElement([FromBody]UpdatePageElementRequest request)
    {
        string ip = Request.HttpContext.Connection.RemoteIpAddress.MapToIPv4().ToString();
        if (request.RateLimitTime > DateTime.Now.AddMinutes(-10))
            return BadRequest("Rate limit exceeded");

        try
        {
            if (!IsValidHtml(request.HtmlContent))
                return BadRequest("Invalid HTML content");

            _updateService.UpdateElement(request.PageSectionId, request.ElementId, request.HtmlContent);
            return Ok(new { Refresh = true });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating page element");
            return StatusCode(500, "Internal Server Error");
        }
    }

    private bool IsValidHtml(string htmlContent)
    {
        var htmlPattern = new Regex(@"<([^>]+)>.*?<\/\1>");
        foreach (Match match in htmlPattern.Matches(htmlContent))
        {
            string tag = match.Groups[1].Value;
            if (!_allowedTags.Contains(tag.ToLower()))
                return false;

            foreach (Match attributeMatch in new Regex(@"([a-zA-Z0-9_]+)=""([^""]*)""").Matches(match.Value))
            {
                string attributeName = attributeMatch.Groups[1].Value;
                if (!_allowedAttributes.Contains(attributeName.ToLower()))
                    return false;
            }
        }

        return true;
    }
}

public class UpdatePageElementRequest
{
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
    public string HtmlContent { get; set; }
    public DateTime RateLimitTime { get; set; }
}
