import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoader {
    private static final Lock lock = new ReentrantLock();
    private Map<String, Long> lastModifiedMap = new HashMap<>();
    private ObjectInputStream objectInputStream;

    public MoSTState loadState(String filePath) throws Exception {
        try (FileInputStream fileInputStream = new FileInputStream(filePath)) {
            File file = fileInputStream.getFD().getChannel().tryLock();

            if (!file.exists() || !file.canRead()) {
                return null;
            }

            if (!validateTimestamp(filePath, lastModifiedMap)) {
                // Outdated object. Do not load.
                return null;
            }

            try (ObjectInputStream in = new ObjectInputStream(new FileInputStream(file))) {
                MoSTState state = (MoSTState) in.readObject();
                return state;
            }
        } catch (IOException e) {
            logger.error("Error loading state from file: " + filePath, e);
            return null;
        } finally {
            if (objectInputStream != null) {
                objectInputStream.close();
            }
        }
    }

    private boolean validateTimestamp(String filePath, Map<String, Long> lastModifiedMap) {
        // Check the timestamp of the loaded file against the expected one
        long expectedLastModified = lastModifiedMap.get(filePath);
        File file = new File(filePath);
        long actualLastModified = file.lastModified();

        if (actualLastModified != expectedLastModified) {
            return false;
        }
        return true;
    }

    private void logger(String message, Exception e) {
        // Implement your logging mechanism here
    }
}
