["```
const fs = require('fs');
const path = require('path');
const { log } = require('./logging');

const DEFAULT_DIRS = process.env.DEFAULT_DIRS || [];
const ACCEPTABLE_TYPES = process.env.ACCEPTABLE_TYPES.split(',');
const MAX_SIZE = parseInt(process.env.MAX_FILE_SIZE, 10);

function readFileSync(file) {
  if (!fs.existsSync(file)) {
    throw new Error(`File ${file} does not exist`);
  }

  const stat = fs.statSync(file);
  if (stat.isDirectory()) {
    throw new Error(`File ${file} is a directory`);
  }

  if (!ACCEPTABLE_TYPES.includes(path.extname(file).substring(1))) {
    throw new Error(`Invalid file type for ${file}`);
  }

  if (stat.size > MAX_SIZE) {
    throw new Error(`File ${file} exceeds maximum size limit`);
  }

  return fs.readFileSync(file);
}

function readFileAsync(file) {
  return new Promise((resolve, reject) => {
    readFileSync(file).then(() => {
      try {
        resolve(readFileSync(file));
      } catch (err) {
        reject(err);
      }
    }).catch(reject);
  });
}

class FileCache {
  constructor() {
    this.cache = {};
  }

  get(key) {
    return this.cache[key];
  }

  set(key, value) {
    this.cache[key] = value;
  }

  remove(key) {
    delete this.cache[key];
  }
}

const cache = new FileCache();

function readCachedFile(file) {
  if (cache.get(file)) {
    return Promise.resolve(cache.get(file));
  } else {
    const cachedResult = readFileAsync(file);
    cache.set(file, cachedResult);
    return cachedResult;
  }
}

function rateLimit(maxRequestsPerSecond) {
  let requestCount = 0;
  let lastRequestTime = new Date().getTime();

  function checkRateLimit() {
    if (requestCount >= maxRequestsPerSecond) {
      const delayMs = 1000 / maxRequestsPerSecond - (new Date().getTime() - lastRequestTime);
      setTimeout(() => {
        requestCount--;
        checkRateLimit();
      }, delayMs);
    } else {
      requestCount++;
      lastRequestTime = new Date().getTime();
    }
  }

  return function wrapAsyncFunction(func) {
    return async () => {
      await checkRateLimit();
      return func();
    };
  };
}

const rateLimitedReadFile = rateLimit(5);

function readExternalFile(file) {
  log.info(`Reading file ${file} from external source`);

  try {
    const response = await fetch(file);
    if (!response.ok) {
      throw new Error(`Failed to retrieve file ${file}: ${response.statusText}`);
    }

    const fileBuffer = await response.arrayBuffer();
    const fileStats = fs.statSync(file);
    log.info(`File ${file} transferred successfully`);

    return { buffer: fileBuffer, stats: fileStats };
  } catch (err) {
    log.error(`Error reading file ${file}: ${err}`);
    throw err;
  }
}

function validateFile(file, buffer) {
  if (!buffer || buffer.length === 0) {
    throw new Error(`File ${file} is empty`);
  }

  const fileStats = fs.statSync(file);
  if (fileStats.size !== buffer.length) {
    throw new Error(`File ${file} size mismatch`);
  }
}

async function readExternalFileAsync(file) {
  try {
    const response = await rateLimitedReadFile(readExternalFile)(file);
    validateFile(file, response.buffer);
    return response;
  } catch (err) {
    log.error(`Error reading file ${file}: ${err}`);
    throw err;
  }
}

module.exports = { readFileSync, readFileAsync, readCachedFile, readExternalFileAsync };
