async function executeFeatureTests(featureName, testCases, resetInterval, maxRetries) {
  try {
    const { default: featureModule } = await import(`features/${featureName}`);

    const workerPool = new WorkerPool({
      limit: Math.min(testCases.length, 10), // adjust the parallelism limit as needed
      onTaskComplete: async (task) => {
        console.log(`Test "${task.name}" completed with outcome ${task.outcome}.`);

        if (!task.outcome) { // failed test
          let retries = 0;
          const backoffInterval = 1000; // start with a 1-second delay

          while (!task.outcome && retries < maxRetries) {
            await new Promise((resolve) => setTimeout(resolve, backoffInterval));
            try {
              task.function();
              task.outcome = true;
            } catch (error) {
              console.error(`Test "${task.name}" failed with error: ${error.stack}`);
            }
            backoffInterval *= 2; // increase delay for consecutive failures
          }
        }
      },
    });

    await Promise.all(testCases.map(async (testCase, index) => {
      const testResult = { name: testCase.name };

      try {
        configStore.reset(resetInterval);

        const startTime = performance.now();
        await featureModule[testCase.name]();
        const endTime = performance.now();
        testResult.outcome = true;
        testResult.duration = endTime - startTime;
        testResult.memoryUsage = process.memoryUsage().rss;

        console.log(`Test "${testCase.name}" passed in ${endTime - startTime} ms and used ${process.memoryUsage().rss} bytes of memory.`);
      } catch (error) {
        if (!configStore.isReset()) { // only log errors for the first test
          console.error(`Test "${testCase.name}" failed with error: ${error.stack}`);
        }

        testResult.outcome = false;
        testResult.duration = performance.now() - startTime;
        testResult.memoryUsage = process.memoryUsage().rss;
      } finally {
        await workerPool.addTask(testCase);
      }
    }));
  } catch (error) {
    console.error(`Error executing feature tests: ${error.stack}`);
  }
}

class WorkerPool {
  constructor({ limit, onTaskComplete }) {
    this.workers = [];
    this.limit = limit;
    this.onTaskComplete = onTaskComplete;
  }

  addTask(task) {
    if (this.workers.length >= this.limit) {
      return new Promise((resolve) => setTimeout(resolve, 0));
    }

    const worker = new Worker(`worker.js`);
    worker.postMessage({ task });

    this.workers.push(worker);

    return new Promise((resolve) => {
      worker.onmessage = () => {
        if (this.workers.length === 1) {
          resolve();
        }
      };
    }).then(() => {
      this.onTaskComplete(task);
      this.workers.pop();
    });
  }
}
