function processReligiousTextReferences(documents) {
  const regexPatterns = [
    /the\s*([a-z]+)\s*gospel/i,
    /\b([A-Za-z]+)\s*(of|according to)\s*[a-z]+/i,
    /\b([A-Za-z]+)\s*\w+(,\s*or\s*)?\s+[a-z]+/i,
  ];

  const canonicalDatabase = await fetch('https://api.religioustable.com/texts')
    .then(response => response.json())
    .catch(error => console.error('Error fetching canonical database:', error));

  function matchRegex(text) {
    return regexPatterns.reduce((matches, pattern) => {
      const matchesForPattern = text.match(pattern);
      if (matchesForPattern) {
        matches.push(...matchesForPattern.map(match => ({
          text: match,
          type: pattern[0],
        })));
      }
      return matches;
    }, []);
  }

  function processMatches(matches, document) {
    const result = {};
    for (const match of matches) {
      if (!result[match.type]) {
        result[match.type] = [];
      }
      result[match.type].push({
        text: match.text,
        context: document.substring(match.index - 50, match.index + 50),
      });
    }
    return result;
  }

  function generateReport(matches) {
    const report = {};
    for (const [type, texts] of Object.entries(matches)) {
      report[type] = texts.map((text, index) => ({
        text,
        context: text.context,
        frequency: index + 1,
      }));
    }
    return report;
  }

  function verifyAndStandardizeReferences(references) {
    const verifiedReferences = [];
    for (const reference of references) {
      let canonicalReference;
      for (const [canonicalText, apiData] of Object.entries(canonicalDatabase)) {
        if (apiData.references.includes(reference.text)) {
          canonicalReference = canonicalText;
          break;
        }
      }
      if (!canonicalReference) {
        // Handle unknown or missing references
      } else {
        verifiedReferences.push({ ...reference, canonical: canonicalReference });
      }
    }
    return verifiedReferences;
  }

  async function main() {
    const matches = await Promise.all(documents.map(matchRegex));
    const processedMatches = matches.reduce((processed, current) => processMatches(current, document), {});
    const report = generateReport(processedMatches);
    const verifiedReferences = verifyAndStandardizeReferences(report);
    console.log(verifiedReferences);
  }

  main();
}
