function generateDashboardLayout(widgets) {
  let html = '<div class="dashboard">';
  for (let i = 0; i < widgets.length; i++) {
    const widget = widgets[i];
    switch (widget.type) {
      case 'graph':
        html += `<div class="panel ${widget.title}">
          <h2>${widget.title}</h2>
          <canvas id="${widget.title}-canvas"></canvas>
          <script>fetch('${widget.dataSource}').then(response => response.json()).then(data => {
            const ctx = document.getElementById('${widget.title}-canvas').getContext('2d');
            const chart = new Chart(ctx, {
              type: 'line',
              data: { labels: [...], datasets: [{ label: '${widget.title}', data: [...]}] }
            });
          });</script>
        </div>`;
        break;
      case 'table':
        html += `<div class="panel ${widget.title}">
          <h2>${widget.title}</h2>
          <table id="${widget.title}-table">
            <thead><tr><th>...</th></tr></thead>
            <tbody id="${widget.title}-body"></tbody>
          </table>
          <script>fetch('${widget.dataSource}').then(response => response.json()).then(data => {
            const tableBody = document.getElementById(`${widget.title}-body`);
            data.forEach(row => {
              let rowHTML = '';
              row.forEach(cell => {
                rowHTML += `<td>${cell}</td>`;
              });
              tableBody.innerHTML += `<tr>${rowHTML}</tr>`;
            });
          });</script>
        </div>`;
        break;
      case 'gauge':
        html += `<div class="panel ${widget.title}">
          <h2>${widget.title}</h2>
          <div id="${widget.title}-gauge"></div>
          <script>fetch('${widget.dataSource}').then(response => response.json()).then(data => {
            const gauge = new Gauge(document.getElementById(`${widget.title}-gauge`), data);
          });</script>
        </div>`;
        break;
    }
  }
  html += '</div>';
  return html;
