function hashLargeFile(filePath, chunkSize) {
  const fs = require('fs');
  const crypto = require('crypto');
  const { parallel } = require('async');
  const logger = require('./logger');

  return new Promise((resolve, reject) => {
    if (!filePath || !fs.existsSync(filePath)) {
      reject(`Error: File not found at ${filePath}`);
    }

    let totalChunks = 0;
    let bytesRead = 0;

    fs.open(filePath, 'r', (err, fd) => {
      if (err) {
        reject(`Error: Unable to open file ${filePath}`);
      } else {
        const buffer = Buffer.allocUnsafe(chunkSize);
        const chunks = [];

        parallel(
          () => {
            let chunkHash;
            let bytesReadChunk;

            fs.read(fd, buffer, 0, chunkSize, null, (err, bytesRead) => {
              if (err) {
                reject(`Error: Unable to read file ${filePath}`);
              } else {
                bytesReadChunk = bytesRead;
                const hash = crypto.createHash('sha256');
                hash.update(buffer);
                chunkHash = hash.digest('hex');

                chunks.push({ hash: chunkHash, bytesRead: bytesReadChunk });

                if (bytesRead >= 1024 * 10) { // log every 10%
                  logger.info(`Hashing progress: ${((totalChunks + chunks.length) / totalChunks) * 100}%`);
                }

                totalChunks += chunks.length;
              }
            });
          },
          {
            concurrency: 5, // adjust the number of concurrent requests
            step: (err, results) => {
              if (err) {
                reject(err);
              } else {
                const summary = {
                  elapsed: Date.now() - process.hrtime()[0],
                  totalChunks,
                  bytesRead,
                };

                resolve({ hash: crypto.createHash('sha256').update(chunks.map(chunk => Buffer.from(chunk.hash, 'hex')).reduce((a, b) => Buffer.concat([a, b]))).digest('hex'), summary });
              }
            },
          }
        );
      }
    });
  });
