import java.io.IOException;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.logging.Level;
import java.util.logging.Logger;

public class NIOClient {

    private static final Logger LOG = Logger.getLogger(NIOClient.class.getName());
    private static final int PORT = 8080; // adjust as needed
    private Selector selector;
    private boolean isRunning = true;

    public void establishConnection(String host, int port) throws IOException {
        selector = Selector.open();
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.bind(null);
        channel.connect(new InetSocketAddress(host, port));
        channel.register(selector, SelectionKey.OP_CONNECT);

        while (isRunning) {
            selector.select();
            for (SelectionKey key : selector.selectedKeys()) {
                if (key.isReadable() || key.isWritable()) {
                    try {
                        handleConnection(key);
                    } catch (IOException e) {
                        LOG.log(Level.SEVERE, "Error handling connection", e);
                    }
                }
            }
            selector.selectedKeys().clear();
        }

        selector.close();
    }

    private void handleConnection(SelectionKey key) throws IOException {
        SocketChannel channel = (SocketChannel) key.channel();

        if (key.isConnectNow()) {
            channel.finishConnect();
        } else {
            // Handle read/write operations
            while (channel.isOpen() && isRunning) {
                int bytesRead = channel.read(new byte[1024]);
                if (bytesRead > 0) {
                    processReceivedData(channel, new String(channel.socket().getInputStream().readByteArray(bytesRead)));
                }
                if (!isRunning) {
                    break;
                }
            }
        }

        if (channel.isClosed()) {
            channel.close();
        }
    }

    private void processReceivedData(SocketChannel channel, String data) {
        // Implement your business logic here
        LOG.log(Level.INFO, "Received: {0}", data);
    }

    public void shutdown() {
        isRunning = false;
    }
}
