use tokio::prelude::*;
use tokio_tungstenite::{connect_async, WebSocketStream};
use tungstenite::{Message, Result};

async fn establish_connection(
    server_endpoint: &str,
    reconnection_timeout: u64,
) -> Result<WebSocketStream> {
    loop {
        match connect_async(server_endpoint).await {
            Ok((stream,)) => return Ok(stream),
            Err(err) => {
                log::error!("Connection to {} failed: {}", server_endpoint, err);
                tokio::time::sleep(reconnection_timeout).await;
            }
        }
    }
}

async fn send_message<T>(stream: &mut WebSocketStream, message: T)
where
    T: Serialize + 'static,
{
    let msg = Message::Text(serde_json::to_string(&message)?);
    stream.send(msg).await?;
}

async fn receive_message(stream: &mut WebSocketStream) -> Result<String> {
    let msg = stream.recv().await?;
    match msg {
        Message::Text(text) => Ok(text),
        _ => Err("Invalid message type".to_string()),
    }
}

async fn manage_backpressure(
    stream: &mut WebSocketStream,
    max_pending_messages: usize,
) -> Result<()> {
    let mut pending_messages = Vec::new();
    loop {
        if pending_messages.len() >= max_pending_messages {
            // Backpressure is applied when the number of pending messages exceeds the limit
            log::warn!("Backpressure applied due to excessive message pending");
            while !stream.is_closed() && pending_messages.pop().is_some() {}
        }
        let msg = receive_message(stream).await?;
        if let Err(err) = stream.send(Message::Text(msg.clone())) {
            // Message sending failed, so we send the message again
            log::error!("Failed to send message: {}", err);
            stream.send(Message::Text(msg)).await?;
        } else {
            pending_messages.push(msg);
        }
    }
}

async fn compress_message<T>(stream: &mut WebSocketStream, message: T) -> Result<String>
where
    T: Serialize + 'static,
{
