use std::process::{Command, Output};
use std::time::{Instant, Duration};
use std::mem;
use std::sync::{Arc, Mutex};
use std::fs::File;
use std::io::Write;

async fn compile_rust() -> Result<i32> {
    let start = Instant::now();
    let output = Command::new("rustc")
        .arg("--crate-type=lib")
        .output()
        .expect("Failed to execute process");
    let end = Instant::now();

    let duration = end.duration_since(start).unwrap_or_default();

    // measure RSS before and after compilation
    let rss_before = get_rss().unwrap();
    Command::new("rustc").arg("--crate-type=lib").output()
        .expect("Failed to execute process");
    let rss_after = get_rss().unwrap();

    // calculate RSS usage
    let rss_usage = rss_after - rss_before;

    println!("Compilation took: {:?}", duration);
    println!("RSS usage: {}", rss_usage);

    Ok(output.status().code().unwrap_or(0))
}

fn main() {
    let result = compile_rust();
    match result {
        Ok(exit_code) => println!("Exit code: {}", exit_code),
        Err(err) => early_error(err).expect("Early error failed"),
    }
}
