import os

class CacheSystem:
    def __init__(self):
        self.cache = {}
        self.lock = threading.Lock()

    def update_cache(self, user_id, last_accessed, session_info):
        with self.lock:
            if user_id in self.cache:
                # Invalidate previously cached data for this user
                del self.cache[user_id]
            self.cache[user_id] = {'last_accessed': last_accessed, 'session_info': session_info}
        return {'status': 'updated'}

class Cacher:
    def __init__(self):
        self.cache_hashes = {}

    def get_hash(self, file_path):
        if file_path in self.cache_hashes:
            return self.cache_hashes[file_path]
        hash_val = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
        self.cache_hashes[file_path] = hash_val
        return hash_val

def timer(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        start_time = time.time()
        result = func(*args, **kwargs)
        end_time = time.time()
        execution_time = end_time - start_time
        print(f"Execution Time: {execution_time} seconds")
        return result
    return wrapper

def cache_update(user_id, last_accessed, session_info):
    cacher = Cacher()
    cache_system = CacheSystem()

    @timer
    def process_file(file_path):
        file_hash = cacher.get_hash(file_path)
        # Perform operations based on the file hash and metadata
        print(f"Processed file: {file_path} with hash {file_hash}")

