        try:
            user_id = int(input("Enter the user ID: "))
            last_accessed = input("Enter the last accessed timestamp: ")
            session_info = input("Enter the session information: ")

            # Create a thread pool with a configurable maximum number of concurrent threads
            max_threads = 5
            with ThreadPoolExecutor(max_workers=max_threads) as executor:
                # Concurrently process multiple files using the thread pool
                files_to_process = ["file1.txt", "file2.txt", "file3.txt"]
                for file_path in files_to_process:
                    executor.submit(process_file, file_path)

            print("Cache updated successfully!")
        except Exception as e:
            logging.error(f"Error: {str(e)}")
        finally:
            # Log the cache update and its outcome
            logging.info(f"Cache update completed with status {'success' if cache_system.update_cache(user_id, last_accessed, session_info) else 'failure'}")

    main()
