import os
import hashlib
from functools import lru_cache
from concurrent.futures.thread import ThreadPoolExecutor
from threading import Lock
from logging import getLogger, handlers
from time import perf_counter
from requests.exceptions import ConnectionError

class Cache:
    def __init__(self):
        self.cache = {}
        self.lock = Lock()

    @lru_cache(maxsize=1000)
    def compute_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

def update_cache(user_id: str, metadata: dict) -> tuple:
    cache = Cache()

    start_time = perf_counter()

    try:
        user_data = {
            "last_accessed": int(perf_counter()),
            "session_info": metadata.get("session_info", {}),
            "device_type": metadata.get("device_type", "")
        }

        if not os.path.exists(user_id):
            raise FileNotFoundError

        with cache.lock:
            for file_path in metadata.get("files", []):
                try:
                    hash_value = cache.compute_hash(file_path)
                    cache.cache[file_path] = {"hash": hash_value, "user_data": user_data}
                except (ConnectionError, Exception) as e:
                    getLogger().error(f"Failed to update cache: {str(e)}")

        end_time = perf_counter()

        return True, {
            "operation_time": end_time - start_time,
            "cache_size": len(cache.cache),
            "concurrent_threads": ThreadPoolExecutor(max_workers=5).max_workers
        }, None

    except Exception as e:
        getLogger().error(f"Failed to update cache: {str(e)}")
        return False, {}, None

def main():
    metadata = {
        "session_info": {"some_data": True},
        "device_type": "desktop",
        "files": ["file1.txt", "file2.txt"]
    }

    status, metrics, exception = update_cache("user1", metadata)

    if not status:
        print(f"Error updating cache: {str(exception)}")
    else:
        print(f"Cache updated successfully. Metrics: {metrics}")

if __name__ == "__main__":
    main()
