def processLargeFile(file_path, chunk_size=1024*1024):
    with open(file_path, 'rb') as file:
        file_hash = hashlib.md5()
        chunk = 0
        while True:
            chunk_data = file.read(chunk_size)
            if not chunk_data:
                break
            file_hash.update(chunk_data)
            print(f"Processed {int((chunk + 1) * 10 / file_size * 100)}%")
