    char metric_name[32];
    double value;
    char unit[16];
} MetricSample;

// Circular Buffer
struct {
    size_t capacity;
    size_t size;
    MetricSample* samples;
} CircularBuffer;

void circular_buffer_init(CircularBuffer* buffer, size_t capacity) {
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->samples = (MetricSample*)calloc(capacity, sizeof(MetricSample));
}

// Serialization and Deserialization
uint8_t* serialize_metric_sample(const MetricSample* sample) {
    uint8_t* serialized_data = (uint8_t*)malloc(40);
    memcpy(serialized_data, &sample->timestamp, 8);
    memcpy(serialized_data + 8, sample->metric_name, 32);
    *(uint16_t*)(serialized_data + 40) = htons((uint16_t)(sample->value * 10000)); // Scale value to avoid float precision issues
    strcpy((char*)serialized_data + 42, sample->unit);
    return serialized_data;
}

void deserialize_metric_sample(MetricSample* sample, const uint8_t* data) {
    memcpy(&sample->timestamp, data, 8);
    strncpy(sample->metric_name, (const char*)data + 8, 32);
    sample->value = ntohs(*(uint16_t*)((const uint8_t*)data + 40)) / 10000.0; // Scale value back to original range
    strcpy(sample->unit, (const char*)data + 42);
}

// AES-256-CBC Cipher

struct {
    EVP_CIPHER_CTX* cipher_ctx;
    unsigned char iv[16];
    unsigned char key[32];
} AesCipher;

void aes_cipher_init(AesCipher* cipher, const char* password) {
    SHA256_CTX sha_ctx;
    SHA256_Init(&sha_ctx);
    SHA256_Update(&sha_ctx, password, strlen(password));
    SHA256_Final(cipher->key, &sha_ctx);

    // Derive the encryption key using PBKDF2
    int iter_count = 1000; // Default iteration count for key derivation
    unsigned char derived_key[32];
    PBKDF2_HMAC_SHA1(password, strlen(password), cipher->key, sizeof(cipher->key), &derived_key, sizeof(derived_key), iter_count);

    // Initialize the AES-256-CBC cipher context
    EVP_CIPHER_CTX_init(&cipher->cipher_ctx);
    EVP_CipherInit_ex(&cipher->cipher_ctx, EVP_aes_256_cbc(), NULL, derived_key, sizeof(derived_key));

    // Generate a random initialization vector (IV)
    RAND_bytes(cipher->iv, 16);

    // Set the IV and key for the cipher context
    EVP_CIPHER_CTX_set_IV_len(&cipher->cipher_ctx, 16);
    EVP_CIPHER_CTX_set_key_length(&cipher->cipher_ctx, 32);
}

void aes_cipher_disable(AesCipher* cipher) {
    EVP_CIPHER_CTX_free(&cipher->cipher_ctx);
}
