typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

typedef struct LinkedListNode {
    LogEntry* entry;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct LinkedList {
    LinkedListNode* head;
    int maxSize;
    int size;
} LinkedList;

LinkedList* linkedListCreate(int maxSize) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->maxSize = maxSize;
    list->size = 0;
    return list;
}

void linkedListDestroy(LinkedList* list) {
    LinkedListNode* current = list->head;
    LinkedListNode* next = NULL;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int linkedListAdd(LinkedList* list, LogEntry* entry) {
    if (list->size >= list->maxSize) {
        // purge older entries
        LinkedListNode* node = list->head;
        LinkedListNode* prev = NULL;
        while (node != NULL && list->size > list->maxSize / 2) {
            prev = node;
            node = node->next;
            free(prev);
            list->size--;
        }
    }

    // add new entry
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    newNode->entry = entry;
    newNode->next = list->head;
    list->head = newNode;
    list->size++;
    return 0;
}

int linkedListFilterWrite(LinkedList* list, FILE* file) {
    LinkedListNode* current = list->head;
    while (current != NULL) {
        LogEntry* entry = current->entry;
        // filter log entries based on configurable criteria
        if (/* apply filters */) {
            // write filtered entry to file or external service
            fwrite(entry->message, strlen(entry->message), 1, file);
        }
        current = current->next;
    }
    return 0;
}

int main() {
    LinkedList* list = linkedListCreate(100); // initialize with a maximum size of 100

    LogEntry entry;
    entry.timestamp = time(NULL);
    entry.logLevel = LOG_INFO;
    char* message = (char*)malloc(strlen("Hello, world!") + 1);
    strcpy(message, "Hello, world!");
    linkedListAdd(list, &entry);

    FILE* file = fopen("log.txt", "w");
    linkedListFilterWrite(list, file);
    fclose(file);

    linkedListDestroy(list); // destroy the linked list

    return 0;
}
