void conditionalLog(log_level_t level, const char *fmt, ...) {
    static struct LogBuffer log_buffer = {0};
    static int current_log_entry_count = 0;

    if (current_log_entry_count >= MAX_LOG_ENTRIES) {
        // Rotate logs
        rotateLogs();
    }

    va_list args;
    va_start(args, fmt);

    char buffer[LOG_MAX_SIZE];
    vsnprintf(buffer, sizeof(buffer), fmt, args);

    struct LogEntry new_entry = {level, buffer};
    log_buffer.entries[log_buffer.head] = new_entry;

    if (++log_buffer.count >= MAX_LOG_ENTRIES) {
        log_buffer.full = true;
    }

    log_buffer.tail = (log_buffer.tail + 1) % LOG_BUFFER_SIZE;
    current_log_entry_count++;

    va_end(args);
}

