```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    char* message;
    int source_ip;
    int source_port;
    int priority;
} Event;

typedef struct {
    Event* events;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} EventQueue;

EventQueue* event_queue_init(size_t initial_size) {
    EventQueue* queue = (EventQueue*)malloc(sizeof(EventQueue));
    queue->size = 0;
    queue->events = (Event*)calloc(initial_size, sizeof(Event));
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

void event_queue_free(EventQueue* queue) {
    for (int i = 0; i < queue->size; i++) {
        free(queue->events[i].message);
    }
    free(queue->events);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

void event_queue_insert(EventQueue* queue, Event event) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == queue->events->size) {
        // Reallocate memory for the events array
        queue->events = (Event*)realloc(queue->events, 2 * queue->size * sizeof(Event));
    }
    queue->events[queue->size] = event;
    queue->size++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

Event event_queue_remove(EventQueue* queue) {
    Event event;
    pthread_mutex_lock(&queue->mutex);
    if (queue->size > 0) {
        event = queue->events[0];
        memmove(queue->events, &queue->events[1], (queue->size - 1) * sizeof(Event));
        queue->size--;
        if (queue->size < (int)(queue->events->size / 2)) {
            // Reallocate memory for the events array
            queue->events = (Event*)realloc(queue->events, (int)(queue->size + 1) * sizeof(Event));
        }
    }
    pthread_mutex_unlock(&queue->mutex);
    return event;
}

void event_queue_iterate(EventQueue* queue, void (*callback)(Event)) {
    pthread_mutex_lock(&queue->mutex);
    for (int i = 0; i < queue->size; i++) {
        callback(queue->events[i]);
    }
    pthread_mutex_unlock(&queue->mutex);
}
