#include <fcntl.h>
#include <pthread.h>

// Define the structure of a log entry
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

// Define the linked list node structure
typedef struct Node {
    LogEntry log_entry;
    struct Node* next;
} Node;

// Initialize the linked list
Node* init_linked_list(int N) {
    // Allocate memory for the head of the linked list
    Node* head = (Node*)malloc(sizeof(Node));

    if (head == NULL) {
        return NULL;
    }

    // Initialize the linked list with N entries
    for (int i = 0; i < N; i++) {
        LogEntry log_entry;
        log_entry.timestamp = time(NULL);
        log_entry.log_level = rand() % 3; // Random log level

        // Dynamically allocate memory for the message string
        char* message = (char*)malloc(100 * sizeof(char));

        if (message == NULL) {
            return NULL;
        }

        sprintf(message, "Log entry %d", i);

        log_entry.message = message;

        head->log_entry = log_entry;
        head->next = (Node*)malloc(sizeof(Node));

        if (head->next == NULL) {
            free(head->message);
            return NULL;
        }

        head = head->next;
    }

    // Return the head of the linked list
    return head;
}

// Iterate over the linked list and print log entries to a file descriptor
void iterate_linked_list(Node* head, int fd) {
    while (head != NULL) {
        LogEntry log_entry = head->log_entry;

        // Print log entry details
        printf("Timestamp: %ld\n", log_entry.timestamp);
        printf("Log level: %d\n", log_entry.log_level);
        printf("Message: %s\n\n", log_entry.message);

        // Write log entry to file descriptor
        write(fd, &log_entry, sizeof(log_entry));

        head = head->next;
    }
}

// Persist the linked list to disk after every N operations
void persist_linked_list(Node* head, int fd) {
    while (head != NULL) {
        LogEntry log_entry = head->log_entry;

        // Write log entry to file descriptor
        write(fd, &log_entry, sizeof(log_entry));

        head = head->next;
    }
}

// Filter log entries based on a specified log level
void filter_log_entries(Node* head, int fd, int log_level) {
    while (head != NULL) {
        LogEntry log_entry = head->log_entry;

        if (log_entry.log_level <= log_level) {
            // Print filtered log entry details
            printf("Timestamp: %ld\n", log_entry.timestamp);
            printf("Log level: %d\n", log_entry.log_level);
            printf("Message: %s\n\n", log_entry.message);

            // Write filtered log entry to file descriptor
            write(fd, &log_entry, sizeof(log_entry));
        }

        head = head->next;
    }
}

// Compact the linked list periodically
void compact_linked_list(Node** head) {
    Node* prev = NULL;
    Node* curr = *head;

    while (curr != NULL) {
        Node* next = curr->next;

        if (next == NULL) {
            break;
        }

        free(curr);
        curr = next;
    }

    *head = curr;
}

int main() {
    int N = 10; // Number of log entries
    int fd = open("log.txt", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR); // Open file descriptor

    Node* head = init_linked_list(N);

    iterate_linked_list(head, fd);

    persist_linked_list(head, fd);

    filter_log_entries(head, fd, 1);

    compact_linked_list(&head);

    return 0;
}
