using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

public class LogEntry
{
    public DateTime Timestamp { get; set; }
    public LogLevel Level { get; set; }
    public string Message { get; set; }
}

public enum LogLevel
{
    Debug,
    Info,
    Warning,
    Error
}

public class LogManager
{
    private readonly object _syncRoot = new object();
    private readonly SortedSet<LogEntry> _logEntries;
    private readonly int _maxEntries;
    private readonly long _maxDiskUsage;
    private readonly int _rollingLogThreshold;
    private readonly TimeSpan _rollingLogDuration;

    public LogManager(int maxEntries, long maxDiskUsage, int rollingLogThreshold, TimeSpan rollingLogDuration)
    {
        _logEntries = new SortedSet<LogEntry>();
        _maxEntries = maxEntries;
        _maxDiskUsage = maxDiskUsage;
        _rollingLogThreshold = rollingLogThreshold;
        _rollingLogDuration = rollingLogDuration;
    }

    public void AddLogEntry(LogEntry entry)
    {
        lock (_syncRoot)
        {
            if (_logEntries.Count >= _maxEntries)
                RollOverLog();

            _logEntries.Add(entry);
        }
    }

    public void DeleteLogEntry(DateTime timestamp, LogLevel level)
    {
        lock (_syncRoot)
        {
            var entriesToRemove = _logEntries.Where(e => e.Timestamp == timestamp && e.Level == level).ToList();
            foreach (var entry in entriesToRemove)
                _logEntries.Remove(entry);
        }
    }

    public IEnumerable<LogEntry> GetLogEntries()
    {
        lock (_syncRoot)
        {
            return _logEntries.ToList();
        }
    }

    private void RollOverLog()
    {
        var oldestEntries = _logEntries.Take(_rollingLogThreshold).ToList();
        foreach (var entry in oldestEntries)
            _logEntries.Remove(entry);

        // Serialize and persist the log entries
        using var stream = File.Create("logs.log");
        using var writer = new BinaryWriter(stream);
        foreach (var entry in oldestEntries)
        {
            writer.Write(entry.Timestamp.Ticks);
            writer.Write((int)entry.Level);
            writer.Write(entry.Message);
        }

        _logEntries.Clear();
    }
}

