void startFileTransfer(FileTransferTask& task) {
    // Initialize variables
    ifstream file(task.filePath, ios::binary);
    if (!file.is_open()) {
        throw runtime_error("Failed to open the file");
    }

    // Calculate MD5 and SHA-256 hashes of the file
    map<string, string> fileHashes;
    md5(fileHashes["MD5"], file);
    sha256(fileHashes["SHA-256"], file);

    // Transfer the file to the destination server with customizable compression level
    transferFile(task.filePath, task.destinationServer, task.compressionLevel);

    // Update the transfer status and log any errors
    updateTransferStatus(task.filePath, "complete");
}

// Function to calculate MD5 hash of a file in chunks
void md5(string& hash, ifstream& file) {
    const int buffer_size = 1024 * 1024; // Calculate hashes in chunks
    char buffer[buffer_size];
    string chunk_hash;
    while (file.read(buffer, buffer_size)) {
        MD5_CTX ctx;
        MD5Update(&ctx, buffer, buffer_size);
        MD5Final(&ctx, buffer);
        for (int i = 0; i < buffer_size; i++) {
            chunk_hash += hexDigit((ctx.words[0] >> (24 - i * 8)) & 0xFF);
            chunk_hash += hexDigit((ctx.words[1] >> (24 - i * 8)) & 0xFF);
        }
    }
    hash = "MD5-" + chunk_hash;
}

// Function to calculate SHA-256 hash of a file in chunks
void sha256(string& hash, ifstream& file) {
    const int buffer_size = 1024 * 1024; // Calculate hashes in chunks
    char buffer[buffer_size];
    string chunk_hash;
    while (file.read(buffer, buffer_size)) {
        SHA256_CTX ctx;
        SHA256Update(&ctx, buffer, buffer_size);
        SHA256Final(&ctx, buffer);
        for (int i = 0; i < buffer_size; i++) {
            chunk_hash += hexDigit((ctx.words[0] >> (24 - i * 8)) & 0xFF);
            chunk_hash += hexDigit((ctx.words[1] >> (24 - i * 8)) & 0xFF);
        }
    }
    hash = "SHA-256-" + chunk_hash;
}

