LogEntry* initializeLogLinkedList(const char* filePath, size_t chunkSize) {
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filePath);
        return NULL;
    }

    LogEntry* head = NULL;
    LogEntry** tail = &head;

    while (1) {
        char buffer[chunkSize];
        size_t bytesRead = fread(buffer, 1, chunkSize, file);
        if (bytesRead == 0) break; // end of file

        LogEntry* entry = malloc(sizeof(LogEntry));
        if (!entry) {
            printf("Error allocating memory for log entry\n");
            fclose(file);
            return NULL;
        }

        entry->timestamp = time(NULL);
        entry->logLevel = 1; // default log level
        entry->message = strdup(buffer);
        if (!entry->message) {
            printf("Error allocating memory for message\n");
            free(entry);
            fclose(file);
            return NULL;
        }

        *tail = entry;
        tail = &((*tail)->next);

        double progress = (double)bytesRead / ftell(file) * 100.0;
        printf("Hashing progress: %.2f%%\n", progress);
    }

    fclose(file);

    LogEntry* current = head;
    while (current) {
        // print log entries to file descriptor
