    LogList* list = (LogList*)malloc(sizeof(LogList));
    if (!list) return NULL;

    list->head = NULL;
    list->size = 0;

    // Initialize the cipher
    EVP_CIPHER_CTX* cipherCtx = AES_encrypt("your_password_here", "your_initialization_vector_here");
    if (!cipherCtx) {
        free(list);
        return NULL;
    }

    // Initialize the linked list with a fixed size
    for (int i = 0; i < maxEntries; i++) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        if (!entry) break;

        entry->timestamp = 0;
        entry->logLevel = 0;
        entry->message = NULL;

        // Append the entry to the linked list
        entry->next = list->head;
        list->head = entry;
    }

    return list;
}

void appendLogEntry(LogList* list, int timestamp, int logLevel, char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return;

    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = NULL; // Dynamically allocate the message string

    // Encrypt the message using AES-256-CBC
    char encryptedMessage[MAX_LOG_ENTRY_SIZE];
    int encryptedSize = 0;
    int encryptedLength = strlen(message);
    if (AES_encrypt(cipherCtx, message, &encryptedSize, encryptedMessage) != 1) {
        free(entry->message);
        free(entry);
        return;
    }

    // Allocate memory for the encrypted message
    entry->message = malloc(encryptedSize + 1);
    memcpy(entry->message, encryptedMessage, encryptedSize);
    entry->message[encryptedSize] = '\0';

    // Append the entry to the linked list
    entry->next = list->head;
    list->head = entry;

    // Increment the log list size
    list->size++;
}

void destroyLogList(LogList* list) {
    LogEntry* current = list->head;
    LogEntry* next = NULL;

    while (current != NULL) {
        next = current->next;
        free(current->message);
        free(current);
        current = next;
    }

    free(list);
}

EVP_CIPHER_CTX* AES_encrypt(char* password, char* initializationVector) {
    // Initialize the AES-256-CBC cipher with the given password
    EVP_CIPHER_CTX* ctx = EVP_Cipher_CTX_new();
    if (!ctx) return NULL;

    int passwordLength = strlen(password);
    int ivLength = strlen(initializationVector);

    if (EVP_Cipher_CTX_set_key(ctx, SHA1_hash((unsigned char*)password, passwordLength), &passwordLength) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    if (EVP_Cipher_CTX_set_iv(ctx, initializationVector, ivLength) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Enable the cipher
    if (EVP_Cipher_CTX_enable(ctx) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanupCipher(EVP_CIPHER_CTX* ctx) {
    EVP_Cipher_CTX_disable(ctx);
    EVP_Cipher_CTX_free(ctx);
}
