#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define struct LogEntry
typedef struct {
    int timestamp;
    char log_level[16];
    char* message;
} LogEntry;

// Define struct LogManager
typedef struct {
    pthread_mutex_t lock;
    LogEntry** entries;
    int entry_count;
    int capacity;
    pthread_cond_t cond;
    int last_modified_index;
} LogManager;

// Function to initialize the log manager
LogManager* init_log_manager(int initial_capacity) {
    LogManager* log_manager = (LogManager*)malloc(sizeof(LogManager));
    log_manager->entries = (LogEntry**)malloc(initial_capacity * sizeof(LogEntry*));
    for (int i = 0; i < initial_capacity; i++) {
        log_manager->entries[i] = NULL;
    }
    log_manager->entry_count = 0;
    log_manager->capacity = initial_capacity;
    pthread_mutex_init(&log_manager->lock, NULL);
    pthread_cond_init(&log_manager->cond, NULL);
    log_manager->last_modified_index = -1;
    return log_manager;
}

// Function to add a new log entry
void add_log_entry(LogManager* log_manager, LogEntry* entry) {
    pthread_mutex_lock(&log_manager->lock);
    if (log_manager->entry_count >= log_manager->capacity) {
        // Reallocate memory for entries and increment capacity
        int new_capacity = log_manager->capacity * 2;
        LogEntry** new_entries = (LogEntry**)realloc(log_manager->entries, new_capacity * sizeof(LogEntry*));
        for (int i = log_manager->capacity; i < new_capacity; i++) {
            new_entries[i] = NULL;
        }
        log_manager->entries = new_entries;
        log_manager->capacity = new_capacity;
    }
    log_manager->entries[log_manager->entry_count++] = entry;
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to remove a log entry
void remove_log_entry(LogManager* log_manager, int index) {
    pthread_mutex_lock(&log_manager->lock);
    if (index >= 0 && index < log_manager->entry_count) {
        free(log_manager->entries[index]->message);
        free(log_manager->entries[index]);
        for (int i = index; i < log_manager->entry_count - 1; i++) {
            log_manager->entries[i] = log_manager->entries[i + 1];
        }
        log_manager->entry_count--;
    }
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to iterate over log entries
void iterate_log_entries(LogManager* log_manager, void (*callback)(LogEntry*)) {
    pthread_mutex_lock(&log_manager->lock);
    for (int i = 0; i < log_manager->entry_count; i++) {
        callback(log_manager->entries[i]);
    }
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to serialize log entries
void serialize_log_entries(LogManager* log_manager, char** serialized_entries) {
    pthread_mutex_lock(&log_manager->lock);
    for (int i = 0; i < log_manager->entry_count; i++) {
        serialized_entries[i] = (char*)malloc(strlen(log_manager->entries[i]->message) + 1);
        sprintf(serialized_entries[i], "%d %s %s", log_manager->entries[i]->timestamp, log_manager->entries[i]->log_level, log_manager->entries[i]->message);
    }
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to deserialize log entries
void deserialize_log_entries(LogManager* log_manager, char** serialized_entries) {
    pthread_mutex_lock(&log_manager->lock);
    for (int i = 0; i < log_manager->entry_count; i++) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        sscanf(serialized_entries[i], "%d %s %s", &entry->timestamp, entry->log_level, &entry->message);
        add_log_entry(log_manager, entry);
    }
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to perform garbage collection
void gc_log_manager(LogManager* log_manager) {
    pthread_mutex_lock(&log_manager->lock);
    for (int i = 0; i < log_manager->capacity; i++) {
        if (log_manager->entries[i] == NULL) continue;
        free(log_manager->entries[i]->message);
        free(log_manager->entries[i]);
    }
    pthread_mutex_unlock(&log_manager->lock);
}

// Function to perform rolling log
void roll_log(LogManager* log_manager, int max_age_seconds) {
    pthread_mutex_lock(&log_manager->lock);
    for (int i = 0; i < log_manager->entry_count; i++) {
        if ((time(NULL) - log_manager->entries[i]->timestamp) > max_age_seconds) {
            remove_log_entry(log_manager, i);
            i--;
        }
    }
    pthread_mutex_unlock(&log_manager->lock);
}

int main() {
    LogManager* log_manager = init_log_manager(10);
    LogEntry* entry1 = (LogEntry*)malloc(sizeof(LogEntry));
    entry1->timestamp = 1643723400;
    entry1->log_level = "INFO";
    char* message = (char*)malloc(strlen("This is a test log") + 1);
    strcpy(message, "This is a test log");
    entry1->message = message;
    add_log_entry(log_manager, entry1);

    LogEntry* entry2 = (LogEntry*)malloc(sizeof(LogEntry));
    entry2->timestamp = 1643723410;
    entry2->log_level = "WARNING";
    char* message2 = (char*)malloc(strlen("Another log") + 1);
    strcpy(message2, "Another log");
    entry2->message = message2;
    add_log_entry(log_manager, entry2);

    iterate_log_entries(log_manager, (void (*)(LogEntry*))printf);

    serialize_log_entries(log_manager, NULL);

    deserialize_log_entries(log_manager, NULL);

    gc_log_manager(log_manager);

    roll_log(log_manager, 3600); // Roll log every hour

    return 0;
}
