```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for LogEntry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define the structure for DoublyLinkedList
typedef struct Node {
    LogEntry* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create a new node with a given log entry
Node* newNode(LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to initialize the doubly-linked list
Node* initList() {
    Node* head = NULL;
    return head;
}

// Function to print log entries from the linked list to a file descriptor
void printLog(Node* head, int fd) {
    // Iterate over the list and print each entry
    while (head != NULL) {
        LogEntry* entry = head->data;
        write(fd, &entry->timestamp, sizeof(time_t));
        write(fd, &entry->level, sizeof(int));
        size_t message_len = strlen(entry->message);
        write(fd, &message_len, sizeof(size_t));
        write(fd, entry->message, message_len);
        head = head->next;
    }
}

// Function to add a new log entry to the linked list
void addEntry(Node** head, LogEntry* entry) {
    Node* node = newNode(entry);
    if (*head == NULL) {
        *head = node;
    } else {
        node->prev = *head;
        (*head)->next = node;
        *head = node;
    }
}

// Function to remove a log entry from the linked list
void removeEntry(Node** head, LogEntry* entry) {
    Node* current = *head;
    while (current != NULL) {
        if (current->data == entry) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                *head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }
            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to serialize the linked list to a binary file
void serialize(Node* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }
    while (head != NULL) {
        LogEntry* entry = head->data;
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        fwrite(&entry->level, sizeof(int), 1, file);
        size_t message_len = strlen(entry->message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(entry->message, message_len, 1, file);
        head = head->next;
    }
    fclose(file);
}

// Function to deserialize the linked list from a binary file
Node* deserialize(const char* filename) {
    Node* head = NULL;
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL;
    }
    while (1) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        fread(&entry->timestamp, sizeof(time_t), 1, file);
        fread(&entry->level, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char* message = (char*)malloc((message_len + 1) * sizeof(char));
        fread(message, message_len, 1, file);
        message[message_len] = '\0';
        addEntry(&head, entry);
    }
    fclose(file);
}

// Function to print statistics about the log entries
void printStats(Node* head) {
    size_t total_size = 0;
    int total_entries = 0;
    for (Node* current = head; current != NULL; current = current->next) {
        LogEntry* entry = current->data;
        total_size += strlen(entry->message) + sizeof(time_t) + sizeof(int);
        total_entries++;
    }
    printf("Total entries: %d\n", total_entries);
    printf("Total size: %zu bytes\n", total_size);
}

// Function to truncate the log list after a configurable period
void truncate(Node** head, time_t max_timestamp) {
    Node* current = *head;
    while (current != NULL && current->data->timestamp < max_timestamp) {
        removeEntry(head, current->data);
        current = current->next;
    }
}

int main() {
    // Initialize the linked list
    Node* head = initList();

    // Add log entries to the list
    addEntry(&head, (LogEntry*)malloc(sizeof(LogEntry)));
    // ...

    // Serialize the list to a file
    serialize(head, "log.bin");

    // Deserialize the list from the file
    Node* deserialized_head = deserialize("log.bin");

    // Print log entries from the deserialized list
    printLog(deserialized_head, stdout);

    // Print statistics about the log entries
    printStats(deserialized_head);

    // Truncate the log list after a configurable period
    truncate(&deserialized_head, time(NULL) - 3600); // 1 hour ago

    return 0;
}
