DoublyLinkedList* dll_init() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new LogEntry to the end of the list
void dll_append(DoublyLinkedList* list, LogEntry* entry) {
    pthread_mutex_lock(&list->mutex);

    if (list->tail == NULL) {
        list->head = entry;
        list->tail = entry;
    } else {
        entry->next = NULL;
        entry->prev = list->tail;
        list->tail->next = entry;
        list->tail = entry;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to print all LogEntries in the list to a file descriptor
void dll_print(DoublyLinkedList* list, int fd) {
    pthread_mutex_lock(&list->mutex);

    LogEntry* current = list->head;
    while (current != NULL) {
        fprintf(fd, "%ld %d %s\n", current->timestamp, current->log_level, current->message);
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Function to free memory for the entire DoublyLinkedList
void dll_free(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->mutex);

    LogEntry* current = list->head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current->message);
        free(current);
        current = next;
