void manageDatabaseConnectionAndQueries(Query* queries, int queryCount) {
    // Establish a secure database connection
    dbConn = establishSecureDBConn();
    if (dbConn == NULL) {
        // Handle error in establishing the connection
        va_start(errBuff, 3);
        vfprintf(stderr, "Error: %s\n", "Failed to establish DB connection");
        va_end(errBuff);
        return;
    }

    for (int i = 0; i < queryCount; i++) {
        Query* currentQuery = &queries[i];

        // Execute the query
        dbResult result = executeQuery(dbConn, currentQuery->query);
        if (result == NULL) {
            // Handle error in executing the query
            va_start(errBuff, 3);
            vfprintf(stderr, "Error: %s\n", "Failed to execute DB query");
            va_end(errBuff);
            continue;
        }

        // Log execution time and any errors encountered
        char logBuff[1024];
        time_t now = time(NULL);
        strftime(logBuff, sizeof(logBuff), "%Y-%m-%d %H:%M:%S", localtime(&now));
        snprintf(logBuff + strlen(logBuff), sizeof(logBuff) - strlen(logBuff) - 1, "Query executed at %s with result: %d\n", logBuff, result);
        fprintf(stdout, logBuff);

        // Clean up the query
        free(currentQuery->query);
        currentQuery->result = NULL;
    }

    // Close the database connection and cleanup any dynamically allocated memory
    closeDBConn(dbConn);
    for (int i = 0; i < queryCount; i++) {
        Query* currentQuery = &queries[i];
        if (currentQuery->query != NULL) {
            free(currentQuery->query);
        }
    }
}
