        return;
    }
    head->message = NULL;
}

void add_log_entry(int logLevel, const char* message) {
    LogEntry* newEntry = malloc(sizeof(LogEntry));
    if (!newEntry) {
        printf("Failed to allocate new log entry.\n");
        return;
    }
    newEntry->timestamp = time(NULL);
    newEntry->logLevel = logLevel;
    newEntry->message = strdup(message);
    if (!head) {
        head = newEntry;
    } else {
        LogEntry* current = head;
        while (current->message) {
            current = current->message->next;
        }
        current->message = newEntry;
    }
}

void print_log_entries(int fd) {
    LogEntry* current = head;
    while (current) {
        fwrite(&current->timestamp, sizeof(time_t), 1, fd);
        fwrite(&current->logLevel, sizeof(int), 1, fd);
        size_t messageLen = strlen(current->message);
        fwrite(&messageLen, sizeof(size_t), 1, fd);
        fwrite(current->message, sizeof(char), messageLen + 1, fd);
        current = current->message;
    }
}

void destroy_log_system() {
    LogEntry* current = head;
    LogEntry* next;
    while (current) {
        next = current->message;
        free(current->message);
        free(current);
        current = next;
    }
