// Custom allocator struct to manage memory efficiently
typedef struct {
    void* start;
    size_t size;
} custom_allocator;

// LogEntry structure with timestamp, log level, and message string
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
    custom_allocator allocator;
} LogEntry;

// Linked list node structure to store LogEntry instances
typedef struct {
    LogEntry* entry;
    struct Node* next;
} Node;

// Initialize the log system with a linked list and custom allocator
void initialize_log_system(int threshold) {
    // Initialize custom allocator with initial memory block
    custom_allocator alloc = {malloc(1024), 1024};

    // Create head of the linked list
    Node* head = malloc(sizeof(Node));
    head->entry = NULL;
    head->next = NULL;

    // Initialize log level and message size limits
    int log_level_limit = 2; // TODO: adjust according to requirements
    int message_size_limit = 1024; // TODO: adjust according to requirements

    // Create a thread-safe mutex for synchronization
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Function to add new log entry at the end of the list
    void add_log_entry(time_t timestamp, int log_level, char* message) {
        Node* node = malloc(sizeof(Node));
        node->entry = (LogEntry*)malloc(sizeof(LogEntry));
        node->entry->timestamp = timestamp;
        node->entry->log_level = log_level;
        node->entry->message = (char*)malloc(strlen(message) + 1);
        strcpy(node->entry->message, message);
        node->entry->allocator = alloc;

        // Insert new entry at the end of the list
        Node* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }

    // Function to iterate over the log entries and print them to a file descriptor
    void print_log_entries(int fd) {
        Node* current = head;
        while (current != NULL) {
            LogEntry* entry = current->entry;
            write(fd, &entry->timestamp, sizeof(time_t));
            write(fd, &entry->log_level, sizeof(int));
            size_t message_len = strlen(entry->message);
            write(fd, entry->message, message_len);
            free(entry->message);
            current = current->next;
        }
    }

    // Function to destroy the log system and free allocated memory
    void destroy_log_system() {
        Node* current = head;
        while (current != NULL) {
            Node* next = current->next;
            free(current->entry->message);
            free(current->entry);
            free(current);
            current = next;
        }
        free(head);
    }

    // Function to check and enforce the memory size limit
    int check_memory_size_limit(size_t total_size) {
        if (total_size > threshold) {
            // Trigger notification or error handling
            printf("Memory usage exceeds threshold\n");
            return -1;
        }
        return 0;
    }

    // Function to add a new log entry while ensuring memory size limit is not exceeded
    void add_log_entry_safe(time_t timestamp, int log_level, char* message) {
        size_t total_size = 0;
        Node* current = head;
        while (current != NULL) {
            total_size += sizeof(LogEntry) + strlen(current->entry->message);
            current = current->next;
        }
        if (check_memory_size_limit(total_size)) {
            // Error handling or notification
            return;
        }
        add_log_entry(timestamp, log_level, message);
    }

    // Function to log to multiple file descriptors simultaneously
    void log_to_multiple_fds(int fd1, int fd2) {
        Node* current = head;
        while (current != NULL) {
            LogEntry* entry = current->entry;
            write(fd1, &entry->timestamp, sizeof(time_t));
            write(fd1, &entry->log_level, sizeof(int));
            size_t message_len = strlen(entry->message);
            write(fd1, entry->message, message_len);
            write(fd2, &entry->timestamp, sizeof(time_t));
            write(fd2, &entry->log_level, sizeof(int));
            write(fd2, entry->message, message_len);
            current = current->next;
        }
    }
}
