// Define LogEntry structure
typedef struct {
    int timestamp;
    char level;
    char *message;
} LogEntry;

// Define Doubly-Linked List Node
typedef struct Node {
    LogEntry entry;
    struct Node *prev;
    struct Node *next;
} Node;

// Define Doubly-Linked List
typedef struct {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DoublyLinkedList;

// Function to create a new node with the given entry
Node* create_node(LogEntry entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to initialize the doubly-linked list
DoublyLinkedList* init_list() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->head = NULL;
    list->tail = NULL;
    return list;
}

// Function to add a new node to the end of the list
void add_node(DoublyLinkedList* list, LogEntry entry) {
    Node* node = create_node(entry);
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to free the memory allocated for the linked list
void free_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

// Function to print the log entries in the linked list
void print_log(DoublyLinkedList* list, int fd) {
    Node* current = list->head;
    while (current != NULL) {
        LogEntry entry = current->entry;
        // Print the log entry here
        fwrite(&entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
}

// Function to serialize the linked list to a file
void serialize_list(DoublyLinkedList* list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        // Handle error
    } else {
        Node* current = list->head;
        while (current != NULL) {
            LogEntry entry = current->entry;
            fwrite(&entry, sizeof(LogEntry), 1, file);
            current = current->next;
        }
        fclose(file);
    }
}

// Function to deserialize the linked list from a file
DoublyLinkedList* deserialize_list(const char *filename) {
    DoublyLinkedList* list = init_list();
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        // Handle error
    } else {
        Node* current = list->head;
        while (fread(&current->entry, sizeof(LogEntry), 1, file) == 1) {
            if (list->head == NULL) {
                list->head = current;
                list->tail = current;
            } else {
                list->tail->next = current;
                current->prev = list->tail;
                list->tail = current;
            }
        }
        fclose(file);
    }
    return list;
}

// Function to integrate with the third-party monitoring service
void send_log_to_service(DoublyLinkedList* list) {
    // Send log entries to the service here
}

int main() {
    DoublyLinkedList* list = init_list();
    add_node(list, (LogEntry){1, 'I', "Initial message"});
    add_node(list, (LogEntry){2, 'D', "Debug message"});
    // Print the log entries
