// Define the structure for LogEntry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define the structure for the doubly-linked list
typedef struct _Node {
    LogEntry entry;
    struct _Node* prev;
    struct _Node* next;
} Node;

// Define the doubly-linked list
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock; // Lock for concurrent access
    int size; // Number of entries in the list
    int capacity; // Maximum number of entries in the list
} LogList;

// Function to initialize a new LogEntry
LogEntry* log_entry_new(time_t timestamp, int level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = NULL; // Dynamically allocated message string
    return entry;
}

// Function to add a new log entry to the list
void log_list_append(LogList* list, LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = *entry;
    node->prev = list->tail;
    if (list->head == NULL) {
        list->head = node;
    } else {
        list->tail->next = node;
    }
    list->tail = node;
    list->size++;
}

// Function to print log entries to a file descriptor
void log_list_print(LogList* list, int fd) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
}

// Function to free the memory used by the log entries
void log_list_free(LogList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

// Function to serialize the log list to a binary file
int log_list_serialize(LogList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // Error opening file
    }
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, file);
        current = current->next;
    }
    fclose(file);
    return 0; // Success
}

// Function to deserialize the log list from a binary file
int log_list_deserialize(LogList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Error opening file
    }
    LogEntry entry;
    while (fread(&entry, sizeof(LogEntry), 1, file) == 1) {
        log_list_append(list, &entry);
    }
    fclose(file);
    return 0; // Success
}

// Function to get statistics about the log list
void log_list_stats(LogList* list) {
    printf("Number of entries: %d\n", list->size);
    printf("Total size of log data: %zu bytes\n", sizeof(LogEntry) * list->size);
    printf("Average message length: %f characters\n",
           (double)(list->size > 0 ? strlen(list->tail->entry.message) : 0) / list->size);
}

// Function to implement the garbage collector
void log_list_garbage_collect(LogList* list, int interval) {
