import hashlib
import os

def calculate_md5_large_file(file_path, chunk_size=1048576):
    md5_hash = hashlib.md5()

    try:
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                md5_hash.update(chunk)
                if os.get_terminal_size().columns > 0 and int((file.tell() / os.path.getsize(file_path)) * 100) % 10 == 0:
                    print(f"Processing... {(file.tell() / os.path.getsize(file_path)) * 100}%")
    except (IOError, FileNotFoundError):
        raise

    return md5_hash.hexdigest()
