public class MD5Calculator {
    public static String computeMD5Hash(String filePath) {
        try (FileInputStream file = new FileInputStream(new File(filePath))) {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] chunk = new byte[1024]; // Default chunk size

            int read;
            while ((read = file.read(chunk)) != -1) {
                md.update(chunk, 0, read);
                if (System.getProperty("java.io.tmpdir") + "/hash_progress.txt".exists()) {
                    try (PrintWriter writer = new PrintWriter(new FileWriter(System.getProperty("java.io.tmpdir") + "/hash_progress.txt"))) {
                        writer.println(String.format("%.1f%%", ((double) (read / file.available()) * 100)));
                    }
                }
            }

            byte[] digest = md.digest();
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                String hex = Integer.toHexString(0xff & b);
                sb.append(hex.length() == 1 ? "0" + hex : hex);
            }

            return sb.toString();
        } catch (Exception e) {
            // Handle exceptions
        }
    }
}
