    LogManager* manager = (LogManager*)malloc(sizeof(LogManager));
    manager->capacity = capacity;
    manager->size = 0;
    manager->entries = (LogEntry**)calloc(capacity, sizeof(LogEntry*));
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Function to add a log entry to the system
void insertLogEntry(LogManager* manager, time_t timestamp, int logLevel, char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = message;
    pthread_mutex_lock(&manager->mutex);
    if (manager->size < manager->capacity) {
        size_t index = manager->size++;
        manager->entries[index] = entry;
    } else {
