// Define the doubly-linked list node structure
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the doubly-linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

// Function to initialize a doubly-linked list
DoublyLinkedList* initDLL() {
    DoublyLinkedList* dll = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    return dll;
}

// Function to add a LogEntry to the end of the list
void addLogEntry(DoublyLinkedList* dll, LogEntry entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->prev = dll->tail;
    newNode->next = NULL;

    if (dll->tail != NULL) {
        dll->tail->next = newNode;
        dll->tail = newNode;
    } else {
        dll->head = newNode;
        dll->tail = newNode;
    }

    dll->size++;
}

// Function to free the doubly-linked list
void freeDLL(DoublyLinkedList* dll) {
    Node* current = dll->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(dll);
}
