**Python Function: Calculate MD5 Hash of a File**

```python
import hashlib
import os

def calculate_md5_hash(file_path):
    md5 = hashlib.md5()
    chunk_size = 65536

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            md5.update(chunk)

    start_time = os.time()
    print(f"Calculating MD5 hash: {file_path}")
    for i in range(100):
        progress = (i / 100) * len(file_path)
        print(f"\rProgress: {progress:.2f} bytes")
    end_time = os.time()

    print(f"MD5 Hash: {md5.hexdigest()}")
    print(f"Total Time: {(end_time - start_time):.2f} seconds")

    return md5.hexdigest()
```

