class VersionControlSystem {
public:
    static const int MAX_ENTRIES = 10000000; // 10 million entries
    static const size_t PAYLOAD_MAX_SIZE = 8 * 1024 * 1024; // 8 MB

private:
    std::mutex mutex;
    std::condition_variable cv;
    bool running;

public:
    VersionControlSystem() : running(true) {}

    void addEntry(VersionControlEntry& entry) {
        std::unique_lock<std::mutex> lock(mutex);
        while (entries.size() >= MAX_ENTRIES) {
            cv.wait(lock, [this] { return !running; });
        }
        entries.push_back(entry);
        cv.notify_all();
    }

    void removeEntry(const std::string& commitID) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = entries.begin();
        while (it != entries.end()) {
            if (it->commitID == commitID) {
                entries.erase(it);
                break;
            }
            ++it;
        }
    }

    void getEntries(std::vector<VersionControlEntry>& result) {
        std::unique_lock<std::mutex> lock(mutex);
        result = entries;
    }

private:
