class DataRecord {
public:
    int id;
    long timestamp;
    std::string sourceIP;
    std::string userAgent;
    std::unique_ptr<char[]> payload;

    DataRecord(int _id, long _timestamp, const std::string& _sourceIP, const std::string& _userAgent, const char* _payload, size_t _payloadSize) 
        : id(_id), timestamp(_timestamp), sourceIP(_sourceIP), userAgent(_userAgent), payload(std::make_unique<char[]>(_payloadSize)) {
        for (size_t i = 0; i < _payloadSize; ++i) {
            payload[i] = _payload[i];
        }
    }
};

class DataProcessor {
public:
    std::vector<DataRecord*> records;
    std::mutex mutex;
    std::condition_variable condition;

    void insertDataRecord(DataRecord* record) {
        {
            std::unique_lock<std::mutex> lock(mutex);
            records.push_back(record);
        }
        condition.notify_one();
    }

    DataRecord* getDataRecord(int id) {
        for (auto& record : records) {
            if (record->id == id) {
                return record;
            }
        }
        return nullptr;
    }

    void removeDataRecord(int id) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = std::remove_if(records.begin(), records.end(), [&](auto& record) { return record->id == id; });
        records.erase(it, records.end());
    }
};

class HashCalculator {
public:
    std::unordered_map<int, std::pair<std::string, std::string>> hashes;

    void calculateHash(DataRecord* record) {
        try {
            auto md5 = MD5(record->payload.get(), record->payload.size());
            auto sha256 = SHA256(record->payload.get(), record->payload.size());
            hashes[record->id] = {std::move(md5), std::move(sha256)};
        } catch (const std::exception& e) {
            // handle errors
            std::cout << "Error: " << e.what() << std::endl;
        }
    }

    std::string getMD5Hash(int id) {
        auto it = hashes.find(id);
        if (it != hashes.end()) {
            return it->second.first;
        }
        return "";
    }

    std::string getSHA256Hash(int id) {
        auto it = hashes.find(id);
        if (it != hashes.end()) {
            return it->second.second;
        }
        return "";
    }
};

