#include <string>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <fstream>

using namespace std;

struct FileTransfer {
    string sourcePath;
    string destinationServer;
    int compressionLevel;
};

class DistributedFileTransferSystem {
public:
    void startTransfer(const vector<FileTransfer>& transfers) {
        threadPool_.start(transfers);
    }

private:
    mutex mtx_;
    condition_variable cv_;
    vector<thread> threadPool_;
    unordered_map<string, pair<int, int>> fileStats_;

    void transferFiles(const FileTransfer& fileTransfer) {
        string sourcePath = fileTransfer.sourcePath;
        string destinationServer = fileTransfer.destinationServer;

        ifstream ifs(sourcePath, ios::binary);
        if (!ifs.is_open()) {
            // Handle error
            return;
        }

        ofstream ofs(destinationServer + "/" + sourcePath, ios::binary);

        if (ofs.is_open()) {
            size_t chunkSize = 4096; // Adjust as needed
            char buffer[chunkSize];

            while (!ifs.eof()) {
                ifs.read(buffer, chunkSize);
                size_t bytesRead = ifs.gcount();
                ofs.write(buffer, bytesRead);
            }
        }

        ifs.close();
        ofs.close();

        pair<int, int> stats = fileStats_[sourcePath];
        stats.first++; // Increment transfer count
        fileStats_[sourcePath] = stats;

        cout << "Transfer completed: " << sourcePath << endl;
    }
};

unordered_map<string, string> calculateHashes(const DistributedFileTransferSystem& system) {
    unordered_map<string, pair<int, int>> fileStats = system.fileStats_;
    unordered_map<string, string> hashes;

    for (const auto& entry : fileStats_) {
        string filePath = entry.first;
        size_t fileSize = 0; // Calculate or read from file metadata
        ifstream ifs(filePath, ios::binary);
        if (!ifs.is_open()) {
            // Handle error
            continue;
        }

        MD5_CTX ctx;
        MD5_Init(&ctx);
        SHA256_CTX shaCtx;
        SHA256_Init(&shaCtx);

        size_t chunkSize = 4096; // Adjust as needed
        char buffer[chunkSize];

        while (!ifs.eof()) {
            ifs.read(buffer, chunkSize);
            size_t bytesRead = ifs.gcount();
            MD5_Update(&ctx, buffer, bytesRead);
            SHA256_Update(&shaCtx, buffer, bytesRead);
        }

        MD5_Final(&ctx);
        SHA256_Final(&shaCtx);

        string md5HexDigest = bytesToHex(MD5_Finalize(&ctx));
        string sha256HexDigest = bytesToHex(SHA256_Finalize(&shaCtx));

        hashes[filePath] = {"MD5: " + md5HexDigest, "SHA-256: " + sha256HexDigest};
    }

    return hashes;
}

string bytesToHex(const uint8_t* data, size_t size) {
    string hexDigits;
    for (size_t i = 0; i < size; ++i) {
        char buffer[3];
        sprintf(buffer, "%02x", data[i]);
        hexDigits += string(buffer);
    }
    return hexDigits;
}

int main() {
    DistributedFileTransferSystem system;

    // Initialize transfer list
    vector<FileTransfer> transfers = {
        {"file1.txt", "server1.com", 6},
        {"file2.txt", "server2.com", 5},
        {"largeFile.bin", "server3.com", 7}
    };

    system.startTransfer(transfers);

    // Retrieve and display transfer statistics
    unordered_map<string, pair<int, int>> fileStats = system.fileStats_;
    cout << "Transfer Statistics:" << endl;
    for (const auto& entry : fileStats_) {
        string filePath = entry.first;
        size_t transfersCount = entry.second.first;
        size_t bytesTransferred = entry.second.second;

        cout << "File: " << filePath << ", Transfers: " << transfersCount
             << ", Bytes: " << bytesTransferred << endl;
    }

    // Calculate and display hash values
    unordered_map<string, string> hashes = system.calculateHashes(system);
    for (const auto& entry : hashes_) {
        cout << "File: " << entry.first << ", Hash Values: " << entry.second << endl;
    }

    return 0;
}
