    char src_ip[16];
    char dst_ip[16];
    size_t payload_size;
    char* data;
} NetworkPacket;

typedef struct {
    NetworkPacket packets[BUFFER_SIZE];
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int head, tail, count;
} CircularBuffer;

void init_circular_buffer(CircularBuffer* buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);
}

void put_packet(CircularBuffer* buffer, NetworkPacket packet) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == BUFFER_SIZE) {
        pthread_cond_wait(&buffer->cond, &buffer->mutex);
    }
    buffer->packets[buffer->tail] = packet;
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count++;
    pthread_mutex_unlock(&buffer->mutex);
    pthread_cond_signal(&buffer->cond);
}

NetworkPacket get_packet(CircularBuffer* buffer) {
    NetworkPacket packet;
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_cond_wait(&buffer->cond, &buffer->mutex);
    }
    packet = buffer->packets[buffer->head];
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return packet;
}

