    *mutex = PTHREAD_MUTEX_INITIALIZER;
}

void gc_packets(NetworkPacket** buffer, uint32_t capacity, pthread_mutex_t* mutex) {
    for (uint32_t i = 0; i < capacity; i++) {
        pthread_mutex_lock(mutex);
        if ((*buffer)[i].id == 0) {
            free((*buffer)[i].data);
            memset(&(*buffer)[i], 0, sizeof(NetworkPacket));
        }
        pthread_mutex_unlock(mutex);
    }
}

