    int max_lives;
    int difficulty_level;
    char* config_details;
} GameConfig;

// Function to initialize a doubly-linked list of GameConfig structures
GameConfig** initialize_game_config_list(int num_entries) {
    GameConfig** game_configs = (GameConfig**)malloc((num_entries + 1)*sizeof(GameConfig*));

    // Initialize each entry with default values
    for(int i = 0; i < num_entries; i++) {
        game_configs[i] = (GameConfig*)malloc(sizeof(GameConfig));
        game_configs[i]->player_health = 100;
        game_configs[i]->max_lives = 3;
        game_configs[i]->difficulty_level = 1;

        // Dynamically allocate memory for config_details
        game_configs[i]->config_details = (char*)malloc(1024);  // Change the size as needed
        sprintf(game_configs[i]->config_details, "Default Config %d", i);
    }

    return game_configs;
}

// Function to free allocated memory when destroying the linked list
void free_game_config_list(GameConfig** game_configs, int num_entries) {
    for(int i = 0; i < num_entries; i++) {
        free(game_configs[i]->config_details);
        free(game_configs[i]);
    }

    free(game_configs);
}

// Function to update UI elements based on configuration settings
void update_ui_elements(GameConfig** game_configs, int num_entries) {
    // Iterate over the list and update UI elements as needed
    for(int i = 0; i < num_entries; i++) {
        printf("Player Health: %d\n", game_configs[i]->player_health);
        printf("Max Lives: %d\n", game_configs[i]->max_lives);
        printf("Difficulty Level: %d\n", game_configs[i]->difficulty_level);
    }
}

// Function to serialize the entire configuration history to a binary format
void serialize_game_config_list(GameConfig** game_configs, int num_entries) {
    // Serialize the list to a binary file
    FILE* file = fopen("game_config.bin", "wb");

    fwrite(&num_entries, sizeof(int), 1, file);

    for(int i = 0; i < num_entries; i++) {
        fwrite(game_configs[i], sizeof(GameConfig), 1, file);
    }

    fclose(file);
}

// Function to deserialize the entire configuration history from a binary format
GameConfig** deserialize_game_config_list() {
    // Deserialize the list from a binary file
    FILE* file = fopen("game_config.bin", "rb");

    int num_entries;
    fread(&num_entries, sizeof(int), 1, file);

    GameConfig** game_configs = (GameConfig**)malloc((num_entries + 1)*sizeof(GameConfig*));

    for(int i = 0; i < num_entries; i++) {
        GameConfig* config = (GameConfig*)malloc(sizeof(GameConfig));
        fread(config, sizeof(GameConfig), 1, file);

        game_configs[i] = config;
    }

    fclose(file);

    return game_configs;
}

int main() {
    int num_entries = 5;
    GameConfig** game_configs = initialize_game_config_list(num_entries);

    update_ui_elements(game_configs, num_entries);

    serialize_game_config_list(game_configs, num_entries);

    free_game_config_list(game_configs, num_entries);

    return 0;
}
