#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

typedef struct LinkedListNode {
    LogEntry* entry;
    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* initList() {
    return NULL;
}

void addEntry(LinkedListNode** list, LogEntry* entry) {
    LinkedListNode* newNode = (LinkedListNode*) malloc(sizeof(LinkedListNode));
    newNode->entry = entry;
    newNode->next = *list;
    *list = newNode;
}

LogEntry* getEntry(LinkedListNode* list, int index) {
    for (int i = 0; i < index; i++) {
        if (!list || !list->next)
            return NULL;
        list = list->next;
    }
    return list ? list->entry : NULL;
}

void removeEntry(LinkedListNode** list, int index) {
    LinkedListNode* prev = *list;
    LinkedListNode* current = (*list)->next;

    for (int i = 0; i < index - 1; i++) {
        if (!prev || !current)
            return;
        prev = current;
        current = current->next;
    }

    if (current) {
        *list = current;
        free(prev);
    }
}

void freeList(LinkedListNode** list) {
    LinkedListNode* temp = *list;
    while (*list) {
        LinkedListNode* next = (*list)->next;
        free(*list);
        *list = next;
    }
}

int filterEntries(LinkedListNode* list, int startTimestamp, int endTimestamp, int minLogLevel) {
    int count = 0;
    for (LinkedListNode* node = list; node; node = node->next) {
        if ((node->entry->timestamp >= startTimestamp && node->entry->timestamp <= endTimestamp) &&
            (node->entry->logLevel >= minLogLevel)) {
            count++;
        }
    }
    return count;
}

void filterEntriesToFile(LinkedListNode* list, int startTimestamp, int endTimestamp, int minLogLevel, char* filePath) {
    FILE* file = fopen(filePath, "w");
    if (!file)
        return;

    for (LinkedListNode* node = list; node; node = node->next) {
        if ((node->entry->timestamp >= startTimestamp && node->entry->timestamp <= endTimestamp) &&
            (node->entry->logLevel >= minLogLevel)) {
            fprintf(file, "%ld %d %s\n", node->entry->timestamp, node->entry->logLevel, node->entry->message);
        }
    }

    fclose(file);
}
