    int user_id;
    char* action_type;
    char* description;
    time_t timestamp;
} AuditEvent;

struct Node {
    AuditEvent event;
    struct Node* next;
};

AuditEventList* init_audit_event_list() {
    return NULL;  // initial state
}

void add_audit_event(AuditEventList* list, AuditEvent* event) {
    struct Node* new_node = (struct Node*) malloc(sizeof(struct Node));
    new_node->event = *event;
    new_node->next = (*list);
    (*list) = new_node;
}

AuditEvent* get_audit_event_by_id(AuditEventList* list, int id) {
    struct Node* current = (*list);
    while (current != NULL) {
        if (current->event.transaction_id == id) {
            return &current->event;
        }
        current = current->next;
    }
    return NULL;  // not found
}

void remove_audit_event(AuditEventList* list, int id) {
    struct Node* previous = NULL;
    struct Node* current = (*list);
    while (current != NULL) {
        if (current->event.transaction_id == id) {
            if (previous == NULL) {
                (*list) = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void filter_audit_events_by_action_type(AuditEventList* list, char* action_type) {
    struct Node* current = (*list);
    while (current != NULL) {
        if (strcmp(current->event.action_type, action_type) == 0) {
            // process event
        } else {
            remove_audit_event(list, current->event.transaction_id);
        }
        current = current->next;
    }
}

void filter_audit_events_by_timestamp_range(AuditEventList* list, time_t start_time, time_t end_time) {
    struct Node* current = (*list);
    while (current != NULL) {
        if (current->event.timestamp >= start_time && current->event.timestamp <= end_time) {
            // process event
        } else {
            remove_audit_event(list, current->event.transaction_id);
        }
        current = current->next;
    }
}
