typedef struct {
    int timestamp;
    int logLevel;
    char* message;
} LogEntry;

LogEntry* initLogEntry(int timestamp, int logLevel) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = NULL;
    return entry;
}

int processAudioFiles(char* sourceDir, char* targetFileExt, char* outputDir, int maxConcurrency) {
    // Initialize linked list for logging
    LogEntry* head = NULL;
    LogEntry* tail = NULL;

    // Set up batching mechanism
    int batchSize = 5; // adaptive value based on system load and available resources
    pthread_mutex_t batchMutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t batchCond = PTHREAD_COND_INITIALIZER;
    pthread_t* threads = (pthread_t*)malloc(maxConcurrency * sizeof(pthread_t));

    // Initialize cache for recently processed files
    int cacheSize = 10; // adaptive value based on system load and available resources
    char** cachedFiles = (char**)malloc(cacheSize * sizeof(char*));
    int cachedCount = 0;

    // Main loop for processing audio files
    DIR* dir = opendir(sourceDir);
    if (!dir) {
        logError("Failed to open source directory");
        return -1;
    }

    while (...) {
        struct dirent* entry = readdir(dir);
        if (entry == NULL || strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // Check file extension and skip non-audio files
        char* filePath = malloc(strlen(sourceDir) + strlen(entry->d_name) + 2);
        sprintf(filePath, "%s/%s", sourceDir, entry->d_name);
        if (strcmp(strrchr(filePath, '.') + 1, targetFileExt)) {
            free(filePath);
            continue;
        }

        // Spawn new thread for processing the file
        pthread_create(&threads[cachedCount++ % maxConcurrency], NULL, processFileThread, (void*)filePath);

