    pthread_mutex_t lock; // Mutex for thread safety
    int size; // Number of log entries in the list
} LinkedList;

// Function to initialize a doubly-linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to free a linked list
void free_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->entry.message);
        free(current);
        current = next;
    }
    free(list);
}

// Function to print log entries to a file descriptor
void print_log_entries(LinkedList* list, int fd) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
}

// Function to iterate over the linked list and free unused memory
void garbage_collect(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->entry.message == NULL || strlen(current->entry.message) == 0) {
            Node* next = current->next;
            free(current->entry.message);
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
}

// Function to serialize the linked list to a binary file
void serialize_log_entries(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        return;
    }

    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, file);
        current = current->next;
    }
    fclose(file);
}

// Function to deserialize the linked list from a binary file
void deserialize_log_entries(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return;
    }

