void* allocate_token(int size) {
    return malloc(size);
}

int free_token(void* token) {
    free(token);
    return 0;
}

// Insert session into the hash table
int insert_session(Session** sessions, int size, Session new_session) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; i++) {
        if (sessions[i]->session_id == new_session.session_id) {
            // Handle duplicate session ID error
            printf("Error: Duplicate session ID!\n");
            pthread_mutex_unlock(&lock);
            return -1;
        }
    }

    // Insert the new session into the table
    for (int i = 0; i < size; i++) {
        if (!sessions[i]) {
            sessions[i] = &new_session;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

// Delete a session from the hash table
int delete_session(Session** sessions, int size, int session_id) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; i++) {
        if (sessions[i]->session_id == session_id) {
            // Free the memory associated with the token and user metadata
            free_token(sessions[i]->authentication_token);
            free(sessions[i]);

            // Shift all subsequent sessions to fill the gap
            for (int j = i + 1; j < size; j++) {
                sessions[j - 1] = sessions[j];
            }

            sessions[size - 1] = NULL;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
    return 0;
}

// Validate a session
int validate_session(Session* session) {
    // Check the token against the configured expiration time and whitelist of allowed IP addresses

    if (!is_valid(session->authentication_token)) {
        return -1; // Invalid token
    }

    if (time_elapsed_since_creation(session) > EXPIRATION_TIME) {
        return -2; // Token has expired
    }

    // Validate the IP address against the allowed list

    if (!is_allowed_ip_address(session->user_metadata)) {
        return -3; // Unauthorized IP address
    }

    return 0; // Valid session
}

// Iterate over the hash table and serialize all entries to a JSON format for persistence
int serialize_sessions(Session** sessions, int size) {
    pthread_mutex_lock(&lock);

    FILE* json_file = fopen("sessions.json", "w");

    if (!json_file) {
        printf("Error: Could not create JSON file!\n");
        pthread_mutex_unlock(&lock);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        Session* session = sessions[i];

        if (session) {
            // Serialize the session data
            fprintf(json_file, "{\"session_id\": %d, \"user_metadata\": \"%s\", \"token\": \"%p\"}\n",
                    session->session_id, session->user_metadata, session->authentication_token);
        }
    }

    fclose(json_file);

    pthread_mutex_unlock(&lock);
    return 0;
}

int main() {
    // Initialize the hash table
    hash_table = malloc(sizeof(Session*) * INITIAL_TABLE_SIZE);
    for (int i = 0; i < INITIAL_TABLE_SIZE; i++) {
        hash_table[i] = NULL;
