```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct ConfigItem {
    char* key;
    int type;
    char* value;
} ConfigItem;

typedef struct HashTable {
    pthread_mutex_t mutex;
    unsigned long size;
    ConfigItem** items;
    unsigned long numItems;
} HashTable;

void hashTableInit(HashTable* table, int capacity) {
    table->size = capacity;
    table->items = (ConfigItem**)malloc(sizeof(ConfigItem*) * capacity);
    table->numItems = 0;
}

void hashTableInsert(HashTable* table, char* key, int type, char* value) {
    pthread_mutex_lock(&table->mutex);
    unsigned long index = key % table->size;
    ConfigItem* item = (ConfigItem*)malloc(sizeof(ConfigItem));
    item->key = key;
    item->type = type;
    item->value = value;
    table->items[index] = item;
    table->numItems++;
    pthread_mutex_unlock(&table->mutex);
}

void hashTableDestroy(HashTable* table) {
    for (unsigned long i = 0; i < table->size; i++) {
        if (table->items[i]) {
            free(table->items[i]);
        }
    }
    free(table->items);
}

void transformationFunction(ConfigItem* item, void (*func)(char*)) {
    func(item->value);
}

void hashTableTransform(HashTable* table, void (*func)(char*)) {
    pthread_mutex_lock(&table->mutex);
    for (unsigned long i = 0; i < table->size; i++) {
        if (table->items[i]) {
            transformationFunction(table->items[i], func);
        }
    }
    pthread_mutex_unlock(&table->mutex);
}

int main() {
    // Initialize the hash table
    HashTable* table = malloc(sizeof(HashTable));
    hashTableInit(table, 10);

    // Insert configuration items into the hash table
    hashTableInsert(table, "key1", 0, "value1");
    hashTableInsert(table, "key2", 1, "value2");

    // Apply transformation function to each item's value
    void (*transformFunc)(char*) = &myTransformationFunction;
    hashTableTransform(table, transformFunc);

    // Destroy the hash table
    hashTableDestroy(table);
    free(table);

    return 0;
}

void myTransformationFunction(char* str) {
    printf("%s\n", str);
}
