            $weather_data = array_merge($weather_response, $geolocation_response, $air_quality_response);
            $caching_strategy->set_weather_data($weather_data);
            return json_encode($weather_data);
        } catch (Exception $e) {
            // Log errors and retry
            error_log("Error: " . $e->getMessage());
            sleep(1);
        }
    }

    // Return error message on failure
    return json_encode(array('error' => 'Failed to retrieve weather report'));
}

