public class OAuthTokenValidator
{
    public static void ValidateOAuthToken(string xmlContent)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlContent);

        XmlElement tokenResponseElement = xmlDoc.SelectSingleNode("//OAuthTokenResponse") as XmlElement;
        if (tokenResponseElement == null)
            throw new Exception("No OAuthTokenResponse element found in the XML document");

        string jsonTokenResponse = tokenResponseElement.InnerText;

        JObject jsonObject = JObject.Parse(jsonTokenResponse);
        string accessToken = (string)jsonObject["access_token"];
        int expiresIn = (int)jsonObject["expires_in"];
        string tokenType = (string)jsonObject["token_type"];

        if (!new[] { "Bearer" }.Contains(tokenType))
            throw new Exception("Invalid token type");

        if (expiresIn <= 0)
            throw new Exception("Expires in must be a positive integer");

        // Choose the encryption mode based on predefined conditions and user input
        int cipherMode = GetCipherMode();

        using (Aes aes = Aes.Create())
        {
            aes.KeySize = 256;
            aes.BlockSize = 128;

            // Generate a secure key for encryption
            byte[] keyBytes = new byte[32];
            using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
                rng.GetBytes(keyBytes);

            aes.Key = keyBytes.Take(aes.KeySize / 8).ToArray();
            aes.IV = keyBytes.Skip(aes.KeySize / 8).Take(aes.BlockSize / 8).ToArray();

            // Encrypt the access token
            byte[] encryptedToken;
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Write))
                {
                    byte[] tokenBytes = Encoding.UTF8.GetBytes(accessToken);
                    cs.Write(tokenBytes, 0, tokenBytes.Length);
                }
                encryptedToken = ms.ToArray();
            }

            // Decrypt the access token
            byte[] decryptedToken;
            using (MemoryStream ms = new MemoryStream())
            {
                using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
                {
                    cs.Write(encryptedToken, 0, encryptedToken.Length);
                }
                decryptedToken = ms.ToArray();
            }

            // Check the decrypted access token
            string decryptedAccessToken = Encoding.UTF8.GetString(decryptedToken);
            if (decryptedAccessToken != accessToken)
                throw new Exception("Access token decryption failed");
        }
    }

    private static int GetCipherMode()
    {
