            std::string md5Hash = getMD5Hash((const char*)fileBuffer, file.gcount());
            std::string sha256Hash = getSHA256Hash((const char*)fileBuffer, file.gcount());

            hashValues[filePath] = { md5Hash, sha256Hash };

            // Monitor the hash computation progress and log errors if a file fails to open or compute its hash
            if (bytesRead > 1024 * 1024 * 8) {
                std::cout << "Hash calculation exceeded the maximum allowed size." << std::endl;
                return nullptr;
            }
        }

        // Handle interruptions gracefully, allowing the function to resume from the last successful hash computation
        signal(SIGINT, [](int) {
            std::cout << "Interrupted. Resuming from the last successful hash computation." << std::endl;
        });

        return &hashValues;
    }
}
