} MetricSample;

MetricSample** circular_buffer_init(int capacity) {
    // Dynamically allocate memory for the buffer and its elements
    MetricSample** buffer = (MetricSample**)malloc((capacity + 1) * sizeof(MetricSample*));
    if (!buffer) return NULL;  // Handle allocation error

    // Initialize each element with dynamically allocated memory
    for (int i = 0; i <= capacity; i++) {
        buffer[i] = (MetricSample*)malloc(sizeof(MetricSample));
        if (!buffer[i]) {
            free(buffer);  // Free the partial buffer on failure
            return NULL;
        }
    }

    return buffer;
}

void circular_buffer_free(MetricSample** buffer, int capacity) {
    for (int i = 0; i <= capacity; i++) {
        free(buffer[i]);
    }
    free(buffer);
}
