#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    int timestamp;
    char level[10];
    char* message;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

Node* create_node(LogEntry entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if(node != NULL) {
        free(node->entry.message);
        free(node);
    }
}

void init_list(Node** head, Node** tail) {
    *head = NULL;
    *tail = NULL;
}

Node* insert_entry(Node* head, Node* tail, LogEntry entry) {
    Node* new_node = create_node(entry);

    if(*head == NULL && *tail == NULL) {
        *head = new_node;
        *tail = new_node;
    } else {
        new_node->prev = *tail;
        (*tail)->next = new_node;
        *tail = new_node;
    }

    return *tail;
}

void remove_entries(Node* head, Node* tail, int start, int end) {
    if(start > end || !head || !tail) {
        return;
    }

    Node* current = head;

    while(current != NULL && current->entry.timestamp <= start) {
        current = current->next;
    }

    while(current != tail && current->entry.timestamp <= end) {
        if(current->next != NULL) {
            current->prev->next = current->next;
            current->next->prev = current->prev;
            free_node(current);
            current = current->next;
        } else {
            *tail = current;
            break;
        }
    }

    return;
}

void print_list(Node* head, int fd) {
    Node* current = head;

    while(current != NULL) {
        dprintf(fd, "%d - %s: %s\n", current->entry.timestamp, current->entry.level, current->entry.message);
        current = current->next;
    }

    return;
}

void free_list(Node** head, Node** tail) {
    Node* current = *head;

    while(current != NULL) {
        Node* next = current->next;
        free_node(current);
        current = next;
    }

    *head = NULL;
    *tail = NULL;
}
