#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    char* metric_name;
    double* value;
} MetricData;

typedef struct {
    size_t capacity;
    size_t size;
    MetricData* data;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    volatile size_t head;
    volatile size_t tail;
} CircularBuffer;

CircularBuffer* circular_buffer_init(size_t capacity) {
    CircularBuffer* buffer = malloc(sizeof(CircularBuffer));
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->data = calloc(capacity, sizeof(MetricData));
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    buffer->head = 0;
    buffer->tail = 0;
    return buffer;
}

void circular_buffer_destroy(CircularBuffer* buffer) {
    for (size_t i = 0; i < buffer->size; i++) {
        free(buffer->data[i].value);
        free(buffer->data[i].metric_name);
    }
    free(buffer->data);
    pthread_mutex_destroy(&buffer->mutex);
    pthread_cond_destroy(&buffer->cond);
    free(buffer);
}

void circular_buffer_insert(CircularBuffer* buffer, MetricData data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    (buffer->head)++;
    if (buffer->head >= buffer->capacity) {
        buffer->head = 0;
    }
    while ((buffer->tail + 1) % buffer->capacity != buffer->head) {
        pthread_cond_wait(&buffer->cond, &buffer->mutex);
    }
    (buffer->tail)++;
    if (buffer->tail >= buffer->capacity) {
        buffer->tail = 0;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

MetricData circular_buffer_remove(CircularBuffer* buffer) {
    MetricData data;
    pthread_mutex_lock(&buffer->mutex);
    while (buffer->head == buffer->tail) {
        pthread_cond_wait(&buffer->cond, &buffer->mutex);
    }
    data = buffer->data[buffer->tail];
    (buffer->tail)++;
    if (buffer->tail >= buffer->capacity) {
        buffer->tail = 0;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

double circular_buffer_average(CircularBuffer* buffer) {
    double sum = 0.0;
    for (size_t i = 0; i < buffer->size; i++) {
        sum += *buffer->data[i].value;
    }
    return sum / buffer->size;
}

// Serialize and deserialize functions
int serialize(CircularBuffer* buffer, FILE* file) {
    fwrite(&buffer->capacity, sizeof(size_t), 1, file);
    fwrite(&buffer->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < buffer->size; i++) {
        MetricData data;
        memcpy(&data, &buffer->data[i], sizeof(MetricData));
        fwrite(&data.timestamp, sizeof(int), 1, file);
        fwrite(data.metric_name, strlen(data.metric_name) + 1, 1, file);
        fwrite(&data.value, sizeof(double), 1, file);
    }
}

int deserialize(CircularBuffer* buffer, FILE* file) {
    fread(&buffer->capacity, sizeof(size_t), 1, file);
    fread(&buffer->size, sizeof(size_t), 1, file);
    buffer->data = realloc(buffer->data, buffer->capacity * sizeof(MetricData));
    for (size_t i = 0; i < buffer->size; i++) {
        MetricData data;
        fread(&data.timestamp, sizeof(int), 1, file);
        char* metric_name = malloc(strlen(data.metric_name) + 1);
        fread(metric_name, strlen(data.metric_name) + 1, 1, file);
        double* value = malloc(sizeof(double));
        fread(value, sizeof(double), 1, file);
        data.metric_name = metric_name;
        data.value = value;
        buffer->data[i] = data;
    }
}

// Aggregation functions
double average(MetricData data) {
    return *data.value;
}
