// Add a new log entry to the linked list
void addLogEntry(LogEntry* entry) {
    LinkedListNode* newNode = malloc(sizeof(LinkedListNode));
    if (!newNode) {
        // Handle allocation failure
    }
    newNode->entry = *entry;
    newNode->next = NULL;

    pthread_mutex_lock(&mutex);
    LinkedListNode* current = linkedList;
    if (current == NULL || currentEntries < maxEntries) {
        linkedList = newNode;
    } else {
        while (current->next != NULL && currentEntries > maxEntries - 1) {
            current = current->next;
        }
        // Purge old entries and add the new one
    }
    pthread_mutex_unlock(&mutex);

    currentEntries++;
}

// Print log entries to a file descriptor
void printLogEntries(int fd, int numEntries) {
    LinkedListNode* current = linkedList;
    for (int i = 0; i < numEntries && current != NULL; i++) {
        fwrite(&current->entry.timestamp, sizeof(time_t), 1, fd);
        fwrite(&current->entry.logLevel, sizeof(int), 1, fd);
        size_t messageLength = strlen(current->entry.message);
        fwrite(&messageLength, sizeof(size_t), 1, fd);
        fwrite(current->entry.message, 1, messageLength, fd);
        current = current->next;
    }
}

// Purge old log entries based on configurable parameters
void purgeLogEntries() {
    pthread_mutex_lock(&mutex);
    LinkedListNode* current = linkedList;
    LinkedListNode* previous = NULL;
    while (current != NULL && currentEntries > maxEntries) {
        previous = current;
        current = current->next;
        free(previous);
    }
    linkedList = current;
    pthread_mutex_unlock(&mutex);

    currentEntries--;
}

