typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_pdu(int size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
    }
    return ptr;
}

void free_pdu(void* pdu) {
    free(pdu);
}

int add_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->pdu = pdu;
    new_node->next = head;
    pthread_mutex_lock(&lock);
    if (head == NULL) {
        head = new_node;
    } else {
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
    return 0;
}

int remove_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *current = head;
    while (current != NULL && current->pdu != pdu) {
        current = current->next;
    }
    if (current == NULL) {
        printf("PDU not found\n");
        return -1;
    }
    Node *temp = current->next;
    pthread_mutex_lock(&lock);
    head = temp;
    free(current);
    pthread_mutex_unlock(&lock);
    return 0;
}

// Periodic cleanup function
void* periodic_cleanup(void*) {
    while (1) {
        sleep(60); // Every minute
        Node *current = head;
        while (current != NULL) {
            if (current->pdu->crcflag == 0) { // Assume CRC flag is used to track usage
                remove_pdu(current->pdu);
                free(current);
            }
            current = current->next;
        }
    }
}

int main() {
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, periodic_cleanup, NULL);
    return 0;
}
