logging.basicConfig(level=logging.INFO)

def get_pokemon_weaknesses(pokemon_type):
    api_url = "https://pokeapi.co/api/v2/type/"
    response = requests.get(api_url + pokemon_type)
    if response.status_code == 200:
        return json.loads(response.content)["damage_relations"]
    else:
        logging.error(f"Failed to retrieve Pokémon weaknesses for type {pokemon_type}")
        return {}

def replace_placeholders(config_file, placeholders):
    sed_command = f"s/{'/'.join(map(re.escape, placeholders.keys()))}/{' '.join(map(str, placeholders.values()))}/g"
    try:
        with open(config_file, 'w') as file:
            subprocess.run(['sed', '-i', sed_command, config_file], check=True)
    except subprocess.CalledProcessError:
        logging.error(f"Failed to replace placeholders in {config_file}")
        raise

def append_password(config_file):
    password = "your_encrypted_password"
    with open(config_file, 'a') as file:
        file.write(password)

def integrate_pokemon_weaknesses(config_file, pokemon_type):
    weaknesses = get_pokemon_weaknesses(pokemon_type)
    sed_command = f"s/Pokémon_Weaknesses:.*/Pokémon_Weaknesses: {json.dumps(weaknesses)}/g"
    try:
        with open(config_file, 'w') as file:
            subprocess.run(['sed', '-i', sed_command, config_file], check=True)
    except subprocess.CalledProcessError:
        logging.error(f"Failed to integrate Pokémon weaknesses in {config_file}")
        raise

def process_config_files(configs):
    with ThreadPoolExecutor(max_workers=10) as executor:
        for config in configs:
            file_name = f"{config['file_name']}.conf"
            placeholders = {key: value for key, value in config.items() if key.startswith("PLACEHOLDER_")}
            replace_placeholders(file_name, placeholders)
            append_password(file_name)
            integrate_pokemon_weaknesses(file_name, "normal")  # default to normal type

if __name__ == "__main__":
    configs = [
        {"file_name": "config1", "PLACEHOLDER_USERNAME": "user1", "PLACEHOLDER_PASSWORD": "pass1"},
        {"file_name": "config2", "PLACEHOLDER_USERNAME": "user2", "PLACEHOLDER_PASSWORD": "pass2"},
