#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    int source;
    int destination;
    char data[256];
} MAC_Header;

typedef struct {
    MAC_Header header;
    char data[1024];
    int trailer;
} MAC_PDU_DATA;

typedef struct {
    MAC_PDU_DATA *data;
    int size;
    int capacity;
} MAC_PDU;

void process_pdu(MAC_PDU_DATA* pdu, void (*callback)(MAC_PDU_DATA*)) {
    callback(*pdu);
}

void cleanup(PMAC_PDU p) {
    if (p.data != NULL) {
        free(p.data);
    }
}

int init_mac_pdu_array(int max_size, void (*callback)(MAC_PDU_DATA*), char** hashes) {
    MAC_PDU p;
    int i;

    p.size = 0;
    p.capacity = 2; // Initialize with a capacity of 2

    for (i = 0; i < max_size && p.size < p.capacity; i++) {
        MAC_PDU_DATA* pdu = (MAC_PDU_DATA*)malloc(sizeof(MAC_PDU_DATA));
        if (pdu == NULL) {
            printf("Error: Memory allocation failed.\n");
            return -1;
        }

        // Generate random MAC_Header
        srand(time(NULL));
        pdu->header.source = rand();
        pdu->header.destination = rand();

        // Initialize MAC_Trailer
        pdu->trailer = 0;

        p.data = realloc(p.data, (p.size + 1) * sizeof(MAC_PDU_DATA));
        if (p.data == NULL) {
            printf("Error: Memory allocation failed.\n");
            return -1;
        }

        p.data[p.size] = *pdu;

        process_pdu(&p.data[p.size], callback);

        // Compute MD5 hash
        unsigned char md5[16];
        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);
        MD5_Update(&md5_ctx, pdu->data, 256);
        MD5_Final(md5, &md5_ctx);

        char hash[33];
        for (int j = 0; j < 16; j++) {
            sprintf(hash + j * 2, "%02x", md5[j]);
        }
        hashes[i] = malloc(strlen(hash) + 1);
        strcpy(hashes[i], hash);
    }

    return i;
}

int main() {
    int max_size = 10;
    void (*callback)(MAC_PDU_DATA*) = NULL;

    char** hashes = (char**)malloc(max_size * sizeof(char*));
    for (int i = 0; i < max_size; i++) {
        hashes[i] = NULL;
    }

    init_mac_pdu_array(max_size, callback, hashes);

    // Cleanup memory
    for (int i = 0; i < max_size; i++) {
        if (hashes[i] != NULL) {
            free(hashes[i]);
