    MAC_PDU* array;
    int size;
    pthread_mutex_t lock;
} BibleMACArray;

void initializeBibleMACArray(BibleMACArray** bible_array) {
    *bible_array = (BibleMACArray*)malloc(sizeof(BibleMACArray));
    (*bible_array)->array = NULL;
    (*bible_array)->size = 0;
    pthread_mutex_init(&((*bible_array)->lock), NULL);
}

void* initializeAndResizeArray(int new_size, BibleMACArray* bible_array) {
    void* ptr = realloc(bible_array->array, new_size * sizeof(MAC_PDU));
    if (!ptr) {
        LOG_ERROR("Failed to allocate memory for array");
        return NULL;
    }
    bible_array->array = ptr;
    bible_array->size = new_size;
    return bible_array->array;
}

int processText(BibleMACArray* bible_array, char* text) {
    regex_t regex[20];
    regcomp(regex, "[A-Z]{3,4}", REG_EXTENDED | REG_NEWLINE);
    int i, j, count;

    for (i = 0; i < bible_array->size; i++) {
        pthread_mutex_lock(&bible_array->lock);
        MAC_PDU* pdu = &bible_array->array[i];
        pthread_mutex_unlock(&bible_array->lock);

        if (!pdu->pdu_data.data) {
            continue;
        }

        for (j = 0; j < i; j++) {
            if (regexec(regex, pdu->pdu_data.data, (size_t)256, NULL, 0)) {
                regfree(regex);
                return -1;
            }
        }
    }

    // Map for storing book frequencies
    int freq[20] = {0};

    for (i = 0; i < strlen(text); i++) {
        if (text[i] >= 'A' && text[i] <= 'Z') {
            char c = tolower(text[i]);
            for (j = 0; j < 20; j++) {
                if (strnstr(bible_array->array[j].pdu_data.data, &c, strlen(bible_array->array[j].pdu_data.data))) {
                    freq[j]++;
                }
            }
        }
    }

    return 0;
}

