    ResourceAllocation* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Doubly linked list
typedef struct {
    Node* head;
    Node* tail;
    int size;
    int capacity;
    pthread_mutex_t lock;
} LinkedList;

// Initialize the doubly linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = 10; // Initial capacity
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Free the doubly linked list and its nodes
void free_list(LinkedList* list) {
    Node* curr = list->head;
    while (curr) {
        Node* next = curr->next;
        free(curr->data->description);
        free(curr);
        curr = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Add a new resource allocation to the linked list
void add_resource(LinkedList* list, ResourceAllocation* alloc) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return; // Error handling
    node->data = alloc;
    node->prev = NULL;
    node->next = list->head;
    if (list->head) list->head->prev = &node->next;
    else list->tail = &node->next;
    list->head = &node->next;
    list->size++;
}

