        if (!prev || strcmp(curr->data->type, prev->data->type) != 0) {
            prev = curr;
        } else {
            // Merge consecutive entries with the same resource type
            free(curr->data->description);
            free(curr);
            prev->next = next;
            if (next) next->prev = prev;
            list->size--;
            if (!list->tail || strcmp(list->tail->data->type, prev->data->type) != 0)
                list->tail = &prev->next;
        }
    }
}

// Filter resource allocations based on a specified minimum ID and resource type
void filter_list(LinkedList* list, int min_id, char* type) {
    Node* curr = list->head;
    while (curr) {
        ResourceAllocation* alloc = curr->data;
        if (alloc->id < min_id || strcmp(alloc->type, type) != 0) {
            // Remove filtered resources
            Node* next = curr->next;
            if (!prev) list->head = &next;
            else prev->next = next;
            if (!list->tail || &curr == list->tail)
                list->tail = &next;
            free(curr->data->description);
            free(curr);
            list->size--;
        } else {
            prev = curr;
            curr = next;
        }
