#define MAX_PDU 1024
#define HASH_SIZE 33 // Size of MD5 hash string

typedef struct {
    int srcMac[6];
    int dstMac[6];
} MAC_Header;

typedef struct {
    MAC_Header header;
    char data[256]; // Maximum size for data field (adjust as needed)
} MAC_PDU_DATA;

typedef struct {
    int pduCount;
    MAC_PDU_DATA* pdus;
} PDU_Array;

// Function to generate a random MAC header
void genRandomMAC(MAC_Header* mac) {
    srand(time(NULL));
    int i;
    for(i = 0; i < 6; i++) {
        mac->srcMac[i] = rand() % 256;
        mac->dstMac[i] = rand() % 256;
    }
}

// Callback function to process each MAC PDU
void processPDU(MAC_PDU_DATA* pdu, void* userData) {
    // Replace with your custom processing logic
    printf("Processing PDU: %x%x:%x%x - %s\n", pdu->header.srcMac[0], pdu->header.srcMac[1], pdu->header.dstMac[0], pdu->header.dstMac[1], pdu->data);
}

// Function to compute the MD5 hash of a MAC PDU
char* computeMD5Hash(MAC_PDU_DATA* pdu) {
    // Implement your own cryptographic hash function or use a standard library one
    // For simplicity, assume a MD5 hash size of 16 bytes (32 characters in hexadecimal)
    static char md5Hash[HASH_SIZE];
    // Compute the MD5 hash and store it in the array
    sprintf(md5Hash, "%02x%02x%02x%02x%02x%02x", pdu->data[0], pdu->data[1], pdu->data[2], pdu->data[3], pdu->data[4], pdu->data[5]);
    return md5Hash;
}

// Function to initialize and process MAC PDUs
void initAndProcessMAC_PDUs(int maxPDUCount, void* userData) {
    PDU_Array pdus = {0};
    pdus.pduCount = 0;
    pdus.pdus = NULL;

    // Allocate memory for the dynamic array of PDUs
    while (pdus.pduCount < maxPDUCount && (pdus.pdus = realloc(pdus.pdus, (pdus.pduCount + 1) * sizeof(MAC_PDU_DATA))) == NULL) {
        pdus.pduCount = 0;
        break; // Handle allocation failure
    }

    for(int i = 0; i < maxPDUCount; i++) {
        MAC_PDU_DATA* pdu = &pdus.pdus[i];
        genRandomMAC(&pdu->header);
        // Initialize and process each PDU using the callback function
        processPDU(pdu, userData);

        // Compute and store the MD5 hash for this PDU
        char* md5Hash = computeMD5Hash(pdu);
        printf("MD5 Hash: %s\n", md5Hash);
    }

    // Clean up memory when processing is complete
    if (pdus.pdus != NULL) {
        free(pdus.pdus);
    }
}

int main() {
    int maxPDUCount = MAX_PDU;
    initAndProcessMAC_PDUs(maxPDUCount, NULL); // Pass a callback function or NULL for default processing
    return 0;
}
