typedef struct {
    int src_addr;
    int dst_addr;
} MAC_Header;

typedef struct {
    MAC_Header header;
    char data[256];
} MAC_PDU_DATA;

typedef struct {
    MAC_PDU_DATA pdu_data;
    uint8_t trailer[4];
} MAC_PDU;

// Function to compute MD5 hash of serialized PDU data
char* computeMD5Hash(const void* pdu_data) {
    MD5_CTX md5_ctx;
    unsigned char md5_hash[16];

    MD5_Init(&md5_ctx);
    MD5_Update(&md5_ctx, pdu_data, sizeof(MAC_PDU_DATA));
    MD5_Final(md5_hash, &md5_ctx);

    // Convert MD5 hash to hexadecimal string
    char* md5_str = malloc(33);
    sprintf(md5_str, "%02x%02x%02x%02x%02x%02x%02x%02x",
            md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3],
            md5_hash[4], md5_hash[5], md5_hash[6], md5_hash[7]);
    return md5_str;
}

// Function to initialize the dynamic array of MAC_PDUs
void* initMAC_PDUs(int max_pdu_count, void (*callback)(const MAC_PDU_DATA*)) {
    // Initialize an empty array and its size
    MAC_PDU** pdus = NULL;
    int pdu_count = 0;

    // Allocate memory for the dynamic array
    while (pdu_count < max_pdu_count) {
        pdus = realloc(pdus, sizeof(MAC_PDU*) * (pdu_count + 1));
        if (!pdus) break; // Handle failed allocation

        MAC_PDU* pdu = malloc(sizeof(MAC_PDU));
        if (!pdu) break; // Handle failed allocation

        // Initialize MAC Header and Trailer
        srand(time(NULL)); // Re-seed random number generator
        pdu->pdu_data.header.src_addr = rand() % 256;
        pdu->pdu_data.header.dst_addr = rand() % 256;
        memcpy(pdu->pdu_data.data, "Random PDU Data", 17);

        // Add the newly created PDU to the array
        pdus[pdu_count] = pdu;
        pdu_count++;
    }

    // Process each PDU and compute its MD5 hash
    for (int i = 0; i < pdu_count; i++) {
        callback(pdus[i]->pdu_data);
        printf("PDU %d: %s\n", i, computeMD5Hash(&pdus[i]->pdu_data));
    }

    // Clean up memory allocation and re-allocation
    for (int i = 0; i < pdu_count; i++) {
        free(pdus[i]);
    }
    free(pdus);

    return NULL;
}

// Example callback function to process PDU data
void processPDU(const MAC_PDU_DATA* pdu_data) {
    printf("Processing PDU with source address %d and destination address %d...\n",
           pdu_data->header.src_addr, pdu_data->header.dst_addr);
}

int main() {
    int max_pdu_count = 10; // Set the initial maximum number of PDUs
    initMAC_PDUs(max_pdu_count, processPDU);

    return 0;
}
