        return cacheMap.getOrDefault(key, null);

        // Dynamic eviction policy (LRU)
        if (!cacheMap.containsKey(key)) {
            // Handle cache miss
            missCount.incrementAndGet();
            totalRequests.incrementAndGet();
            return null;
        }
    }

    public void evict(String key) {
        // Consistent hashing algorithm for distributed caching
        String nodeHash = getNodeId(key);
        Map<String, Object> localCache = getLocalCache(nodeHash);
        localCache.remove(key);
