    int log_level;
    char* message;
} LogEntry;

// Define the doubly-linked list node
typedef struct Node {
    LogEntry entry;
    struct Node* next;
    struct Node* prev;
} Node;

// Define the doubly-linked list
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    int size;
} LinkedList;

// Function to initialize a new node
Node* newNode(LogEntry entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to create a new linked list
LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    return list;
}

// Function to add a new entry to the linked list
void insertEntry(LinkedList* list, LogEntry entry) {
    Node* node = newNode(entry);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to free the linked list
void freeList(LinkedList* list) {
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

// Function to iterate over the linked list and print entries
void printEntries(LinkedList* list, int fd) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(current->entry.message, 1, strlen(current->entry.message), fd);
        current = current->next;
    }
}

// Function to garbage collect unused memory
void gc(LinkedList* list) {
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        if (strlen(current->entry.message) == 0) {
            free(current->entry.message);
            free(current);
            if (list->head == current)
                list->head = next;
            else if (list->tail == current)
                list->tail = next;
            if (next != NULL)
                next->prev = current->prev;
            if (current->prev != NULL)
                current->prev->next = next;
        } else
            current = next;
    }
}

// Function to serialize the linked list to a file
void serialize(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");
    Node* current = list->head;
    while (current != NULL) {
        fwrite(&current->entry.timestamp, sizeof(time_t), 1, file);
        fwrite(&current->entry.log_level, sizeof(int), 1, file);
        size_t len = strlen(current->entry.message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->entry.message, 1, len, file);
        current = current->next;
    }
    fclose(file);
}

// Function to deserialize the linked list from a file
LinkedList* deserialize(char* filename) {
    LinkedList* list = createList();
    FILE* file = fopen(filename, "rb");
    Node* current = NULL;
    while (1) {
        time_t timestamp;
        int log_level;
        size_t len;
        fread(&timestamp, sizeof(time_t), 1, file);
        fread(&log_level, sizeof(int), 1, file);
        fread(&len, sizeof(size_t), 1, file);
        char* message = (char*)malloc(len + 1);
        fread(message, 1, len, file);
        message[len] = '\0';
        LogEntry entry;
        entry.timestamp = timestamp;
        entry.log_level = log_level;
        entry.message = message;
        if (list->head == NULL)
            list->head = newNode(entry);
        else
            current->next = newNode(entry);
        current = current->next;
    }
    fclose(file);
    return list;
}

