LogEntry** initLogList(int capacity) {
    // Allocate memory for the head and tail nodes
    LogEntry** head = (LogEntry**)malloc(sizeof(LogEntry*) * 2);
    head[0] = NULL;
    head[1] = NULL;

    return head;
}

// Function to garbage collect unused memory within the list
void gc(LogEntry** head, int threshold) {
    // Calculate memory pressure metrics
    size_t totalMemUsage = 0;
    LogEntry* current = head[0]->next;
    while (current != NULL) {
        totalMemUsage += current->messageSize + sizeof(LogEntry);
        current = current->next;
    }

    if (totalMemUsage > threshold) {
        // Reclaim unused memory by truncating old entries
        LogEntry* temp = head[0]->next;
        while (temp != NULL) {
            if (temp->timestamp < 3600 * 24 * 7) { // Truncate entries older than a week
                free(temp->message);
                LogEntry* prev = head[0];
                while (prev->next != temp) prev = prev->next;
                prev->next = temp->next;
                free(temp);
            } else {
                temp = temp->next;
            }
        }
    }
}

// Function to serialize and deserialize the log history
void serializeLog(const LogEntry** head, FILE* file) {
    // Write the number of entries and total size to the file
    fwrite(&head[0]->size, sizeof(int), 1, file);

    // Serialize each entry in the list
    LogEntry* current = head[0]->next;
    while (current != NULL) {
        fwrite(&current->timestamp, sizeof(time_t), 1, file);
        fwrite(&current->logLevel, sizeof(int), 1, file);
        size_t messageSize = strlen(current->message);
        fwrite(&messageSize, sizeof(size_t), 1, file);
        fwrite(current->message, messageSize + 1, 1, file);

        current = current->next;
    }
}

int main() {
    // Initialize the log list with a capacity of 1000 entries
    LogEntry** head = initLogList(1000);

    // Simulate concurrent write operations
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, logWriteThread, (void*)head);
    }

    // Serialize the log history to a file
    FILE* file = fopen("log_history.bin", "wb");
    serializeLog(head, file);

    return 0;
}

// Function to calculate the MD5 hash of a large file given its path
#include <hashlib.h>
#include <sys/stat.h>

size_t calcMD5(const char* filePath) {
    // Open the file in binary mode
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) return 0;

    // Create an MD5 hash object
    hashlib.md5() md5Hash;

    // Read the file in chunks of 1MB and update the hash
    struct stat fileStats;
    fstat(file->fileno(), &fileStats);
    size_t fileSize = fileStats.st_size;
    size_t bytesRead = 0;
    char* buffer = malloc(1024 * 1024); // 1MB chunk
    while (read(file, buffer, 1024 * 1024) == 1024 * 1024) {
        md5Hash.update(buffer, 1024 * 1024);
        bytesRead += 1024 * 1024;
    }
    if (fseeko(file, 0, SEEK_END) != 0) return 0;

    // Calculate the remaining bytes to read
    size_t remainingBytes = fileSize - bytesRead;
    if (remainingBytes > 0) {
        md5Hash.update(buffer, remainingBytes);
    }

    // Get the MD5 hash as a hexadecimal string
    char* md5Hex = md5Hash.hexdigest();

    free(buffer);
    fclose(file);

    return strlen(md5Hex);
}
