#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    long timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Function to initialize the doubly linked list
void initList(LogEntry** head, LogEntry** tail) {
    *head = NULL;
    *tail = NULL;
}

// Function to add a new entry to the list
void append(LogEntry** head, LogEntry** tail, LogEntry* entry) {
    if (*tail != NULL) {
        // Update the next pointer of the last node
        (*tail)->next = entry;
        entry->prev = *tail;
    } else {
        entry->prev = NULL;
    }

    // Update the head and tail pointers
    if (*head == NULL) {
        *head = entry;
    }
    *tail = entry;
}

// Function to remove an existing entry from the list
void removeEntry(LogEntry** head, LogEntry** tail, LogEntry* entry) {
    if (entry->prev != NULL) {
        // Update the previous pointer of the next node
        entry->prev->next = entry->next;
    } else {
        *head = entry->next;
    }

    if (entry->next != NULL) {
        // Update the next pointer of the previous node
        entry->next->prev = entry->prev;
    } else {
        *tail = entry->prev;
    }
}

// Function to iterate over the list and print entries based on log level and timestamp range
void printEntries(LogEntry* head, int minLogLevel, long minTimestamp, long maxTimestamp) {
    LogEntry* current = head;

    while (current != NULL) {
        if ((current->logLevel >= minLogLevel) && 
            (current->timestamp >= minTimestamp) && 
            (current->timestamp <= maxTimestamp)) {
            printf("%ld %d %s\n", current->timestamp, current->logLevel, current->message);
        }

        current = current->next;
    }
}

// Function to write entries to a specified file descriptor
void writeEntries(LogEntry* head, int fd) {
    LogEntry* current = head;

    while (current != NULL) {
        fwrite(current->message, 1, strlen(current->message), fd);
        fwrite("\n", 1, 1, fd);

        current = current->next;
    }
}

// Function to destroy the linked list and free associated resources
void destroyList(LogEntry** head, LogEntry** tail) {
    while (*head != NULL) {
        LogEntry* temp = *head;
        *head = (*head)->next;
        if (temp->message != NULL) {
            free(temp->message);
        }
        free(temp);
    }

    *tail = NULL;
}

// Function to allocate and initialize a new LogEntry structure
LogEntry* createLogEntry(long timestamp, int logLevel, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (entry == NULL) {
        return NULL;  // Memory allocation failed
    }

    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = (char*)malloc(strlen(message) + 1);
    strcpy(entry->message, message);

    return entry;
}
