```python
import hashlib
import os

def file_and_string_hasher(file_path, checksum_str=None):
    md5 = hashlib.md5()

    if os.path.exists(file_path):
        with open(file_path, 'rb') as f:
            chunk_size = 1024 * 1024 * 10  # 10MB chunks
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
    else:
        raise ValueError(f"File {file_path} not found")

    if checksum_str is not None:
        expected_checksum = checksum_str.encode('utf-8')
        if md5.hexdigest() != hashlib.md5(expected_checksum).hexdigest():
            return None, False, 0

    progress = int(os.path.getsize(file_path) / (1024 * 1024 * 10) * 100)
    return md5.hexdigest(), True, progress
