int main() {
    // Compute file hashes
    map<string, pair<string, string>> fileHashes = computeFileHashes({"file1.txt", "file2.txt"});

    // Print the results
    for (const auto& entry : fileHashes) {
        cout << "File: " << entry.first << ", MD5 Hash: " << entry.second.first << ", SHA-256 Hash: " << entry.second.second << endl;
    }

