map<string, pair<string, string>> computeFileHashes(const vector<string>& filePaths) {
    map<string, pair<string, string>> fileHashes;

    for (const auto& filePath : filePaths) {
        ifstream file(filePath);

        if (!file.is_open()) {
            // Handle file open error
        }

        // Compute the MD5 and SHA-256 hashes of the file in chunks
        MD5_CTX md5Context;
        SHA256_CTX sha256Context;

        unsigned char chunk[1024];
        while (file.read((char*)chunk, 1024)) {
            MD5Update(&md5Context, chunk, 1024);
            SHA256Update(&sha256Context, chunk, 1024);
        }

        fileHashes[filePath] = {computeMD5Hash(md5Context), computeSHA256Hash(sha256Context)};
    }

    return fileHashes;
}

string computeMD5Hash(const MD5_CTX& ctx) {
    unsigned char result[16];
    MD5Final(&ctx, result);

    // Convert the hash to a hexadecimal string
    stringstream ss;
    for (const auto& byte : result) {
        ss << hex << setfill('0') << setw(2) << (int)byte;
    }

    return ss.str();
}

string computeSHA256Hash(const SHA256_CTX& ctx) {
    unsigned char result[32];
    SHA256Final(&ctx, result);

    // Convert the hash to a hexadecimal string
    stringstream ss;
    for (const auto& byte : result) {
        ss << hex << setfill('0') << setw(2) << (int)byte;
    }

    return ss.str();
}
