    // Example usage
    FILE* data_source = fopen("data.txt", "r");
    if (!data_source) {
        printf("Error opening data source file.\n");
        return 1;
    }

    int num_structures = 5000; // Adjust this value to generate more or fewer structures
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = generate_crc_indication_pdu(num_structures, data_source);

    if (crc_indication_pdu) {
        for (int i = 0; i < num_structures; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
                   crc_indication_pdu[i].RX_UE_INFORMATION_TAG,
                   crc_indication_pdu[i].RNTI,
                   crc_indication_pdu[i].CRC_INDICATION_REL8_TAG,
                   crc_indication_pdu[i].CRCFLAG);
        }
    }

    fclose(data_source);
    free(crc_indication_pdu);

    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(int n, FILE* data_source) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_indication_pdu) {
        printf("Error allocating memory for CRC indication pdu structures.\n");
        return NULL;
    }

    int i;
    int data_source_size;

    data_source_size = (int)fseeko(data_source, 0, SEEK_END);
    rewind(data_source);

    char* buffer = (char*)malloc((data_source_size + 1) * sizeof(char));
    fread(buffer, 1, data_source_size, data_source);
    buffer[data_source_size] = '\0';

    int num_entries;
    sscanf(buffer, "%d", &num_entries);

    if (n > num_entries) {
        n = num_entries;
    }

    srand(time(NULL));

    for (i = 0; i < n; i++) {
        crc_indication_pdu[i].RX_UE_INFORMATION_TAG = rand() % (int)data_source_size + 1;
        crc_indication_pdu[i].RNTI = rand() % 2 ? data_source_size : -data_source_size;
        crc_indication_pdu[i].CRC_INDICATION_REL8_TAG = rand() % 2 ? data_source_size : -data_source_size;
        crc_indication_pdu[i].CRCFLAG = (rand() % 2) ? 1 : 0;
    }

    free(buffer);
    return crc_indication_pdu;
}
