void init_pdu_array(int max_elements) {
    if (pdu_array != NULL) {
        for (int i = 0; i < pdu_count; i++) {
            free(pdu_array[i].data.data);
        }
        free(pdu_array);
    }
    pdu_array = malloc(max_elements * sizeof(MAC_PDU));
    pdu_count = 0;
}

void process_pdu(int index, void (*callback)(MAC_PDU *)) {
    if (index >= 0 && index < pdu_count) {
        callback(&pdu_array[index]);
    } else {
        printf("Invalid PDU index\n");
    }
