    // Calculate the checksum using a suitable algorithm (e.g., XOR of bytes)
    int checksum = 0;
    for (int i = 0; i < 16; i++) {
        checksum ^= ((unsigned char*)RX_UE_INFORMATION_TAG)[i];
    }
    checksum ^= RNTI;

    return checksum;
