        }
    }

    // Memory cleanup routine
    free(pdus);

    return 0;
}

void serialize_MAC_PDUs(MAC_PDU* pdus, int count) {
    FILE* file = fopen("pdus.bin", "wb");
    if (!file) {
        return;  // File creation failed
    }

    for (int i = 0; i < count; i++) {
        fwrite(&pdus[i].pdu, sizeof(MAC_PDU_DATA), 1, file);
    }

    fclose(file);
}

MAC_PDU* deserialize_MAC_PDUs(int count) {
    FILE* file = fopen("pdus.bin", "rb");
    if (!file) {
        return NULL;  // File not found
    }

    MAC_PDU* pdus = (MAC_PDU*)malloc(count * sizeof(MAC_PDU));
    if (!pdus) {
        fclose(file);
        return NULL;  // Memory allocation failed
    }

    for (int i = 0; i < count; i++) {
        fread(&pdus[i].pdu, sizeof(MAC_PDU_DATA), 1, file);
    }

    fclose(file);

    return pdus;
}
