#define LOG_FORMAT "%s: %d\n"

typedef struct {
    uint16_t source_port;
    uint16_t destination_port;
    uint32_t sequence_number;
} TCP_Header;

typedef struct {
    TCP_Header header;
    char payload[];
} TCP_Segment;

void* tcp_segment_alloc(size_t size) {
    return malloc(size);
}

void tcp_segment_free(void* segment, size_t size) {
    free(segment);
}

int tcp_init_segments(int max_segments, int min_padding_size, void (*callback)(TCP_Segment*)) {
    int i;
    TCP_Segment** segments = NULL;
    FILE* log_file = NULL;

    if (max_segments <= 0 || min_padding_size < MIN_PADDING) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    srand(time(NULL));

    for (i = 0; i < max_segments; i++) {
        TCP_Segment* segment = tcp_segment_alloc(sizeof(TCP_Segment) + min_padding_size);
        if (!segment) {
            break;
        }
        segment->header.source_port = rand() % 65535;
        segment->header.destination_port = rand() % 65535;
        segment->header.sequence_number = rand() % 4294967295;
        callback(segment);
    }

    if (LOG_ENABLED) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
        } else {
            fprintf(log_file, LOG_FORMAT, "Initial segment count", i);
            fclose(log_file);
        }
    }

    return i;
}

void tcp_free_segments(int segment_count, TCP_Segment** segments) {
    int i;
    for (i = 0; i < segment_count; i++) {
        tcp_segment_free(segments[i], sizeof(TCP_Segment) + MIN_PADDING);
    }
    free(segments);
}
