from cryptography.fernet import Fernet
from retrying import retry

logging.basicConfig(filename='config_file_processor.log', level=logging.INFO)

def encrypt_password(password):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    encrypted_password = cipher_suite.encrypt(password.encode())
    return encrypted_password.decode()

@retry(wait_exponential_max=3, stop_max_attempt_number=3)
def replace_placeholders_and_append_password(file_path, placeholders, password):
    with open(file_path, 'r') as file:
        content = file.read()

    for key, value in placeholders.items():
        content = content.replace(f'{{ {key} }}', str(value))

    encrypted_password = encrypt_password(password)
    while True:
        try:
            cipher_suite = Fernet(Fernet.generate_key())
            decrypted_password = cipher_suite.decrypt(encrypted_password.encode()).decode()
            if password == decrypted_password:
                break
            else:
                encrypted_password = encrypt_password(password)
        except Exception as e:
            logging.error(f"Failed to encrypt password for {file_path}: {e}")

    content += f'\n{{ encryption_key }}: {encrypted_password}'
    with open(file_path, 'w') as file:
        file.write(content)

def process_config_files(directory, placeholders, dry_run=False):
    if not os.path.exists(directory):
        logging.error(f"Directory '{directory}' does not exist")
        return

    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if file.endswith('.conf'):
                try:
                    replace_placeholders_and_append_password(file_path, placeholders, 'password')
                    logging.info(f"Processed {file_path} successfully")
                except Exception as e:
                    logging.error(f"Failed to process {file_path}: {e}")

    if not dry_run:
        print("Processing complete. All changes are committed.")

if __name__ == "__main__":
    directory = 'path/to/config/directory'
    placeholders = {'env_var1': 'value1', 'env_var2': 'value2'}
    process_config_files(directory, placeholders, dry_run=False)
