#include <string.h>
#include <pthread.h>

// Define the LogEntry struct
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

// Define the doubly-linked list node structure
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the linked list structure
typedef struct {
    Node* head;
    Node* tail;
    int count;
    size_t total_size;
    size_t average_message_length;
    pthread_mutex_t lock;
} LinkedList;

// Function to initialize a new LogEntry and allocate memory for its message
LogEntry* log_entry_init(const char* msg) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->timestamp = time(NULL);
    entry->log_level = 0; // Default log level
    entry->message = strdup(msg);
    if (!entry->message) {
        free(entry);
        return NULL;
    }

    return entry;
}

// Function to initialize a new LinkedList and set up synchronization mechanisms
LinkedList* linked_list_init() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;

    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->total_size = 0;
    list->average_message_length = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

// Function to add a new LogEntry to the linked list
int linked_list_add(LinkedList* list, LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return -1; // Allocation failed

    node->entry = *entry;
    node->prev = NULL;
    node->next = list->head;

    if (list->head) {
        list->head->prev = &node->entry;
    } else {
        list->tail = &node->entry;
    }

    list->head = node;
    list->count++;
    list->total_size += sizeof(LogEntry) + strlen(entry->message) + 1; // Account for message size
    list->average_message_length = (list->total_size / list->count);

    return 0;
}

// Function to remove a LogEntry from the linked list
int linked_list_remove(LinkedList* list, Node* node) {
    if (!node) return -1; // Invalid node

    if (node == list->head) {
        list->head = node->next;
    } else if (node == list->tail) {
        list->tail = node->prev;
    }

    node->prev->next = node->next;
    node->next->prev = node->prev;

    free(node->entry.message);
    free(node);

    list->count--;
    list->total_size -= sizeof(LogEntry) + strlen(&node->entry.message) + 1; // Account for message size
    list->average_message_length = (list->total_size / list->count);

    return 0;
}

// Function to serialize the linked list to a binary format
int linked_list_serialize(LinkedList* list, FILE* file) {
    Node* node = list->head;
    while (node) {
        fwrite(&node->entry.timestamp, sizeof(time_t), 1, file);
        fwrite(&node->entry.log_level, sizeof(int), 1, file);
        size_t message_len = strlen(node->entry.message) + 1;
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(node->entry.message, 1, message_len, file);
        node = node->next;
    }

    return 0;
}

// Function to deserialize the linked list from a binary format
int linked_list_deserialize(LinkedList* list, FILE* file) {
    Node* node = NULL;
    while (fread(&entry.timestamp, sizeof(time_t), 1, file)) {
        LogEntry* entry = log_entry_init(NULL);
        fread(&entry.log_level, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char* msg = (char*)malloc(message_len);
        fread(msg, 1, message_len, file);

        node = (Node*)malloc(sizeof(Node));
        if (!node) return -1; // Allocation failed

        node->entry = *entry;
        node->prev = NULL;
        node->next = list->head;

        if (list->head) {
            list->head->prev = &node->entry;
        } else {
            list->tail = &node->entry;
        }

        list->head = node;
        list->count++;
        list->total_size += sizeof(LogEntry) + message_len + 1; // Account for message size
        list->average_message_length = (list->total_size / list->count);
    }

    return 0;
}

// Function to filter logs by timestamp range and log level
int linked_list_filter(LinkedList* list, time_t start, time_t end, int min_log_level) {
    Node* node = list->head;
    while (node) {
        if (node->entry.timestamp < start || node->entry.timestamp > end || node->entry.log_level < min_log_level) {
            linked_list_remove(list, node);
        } else {
            node = node->next;
        }
    }

    return 0;
}

// Function to print log entries in a human-readable format
void linked_list_print(LinkedList* list) {
    Node* node = list->head;
    while (node) {
        printf("%ld %d '%s'\n", node->entry.timestamp, node->entry.log_level, node->entry.message);
        node = node->next;
    }
}

// Function to perform garbage collection and reclaim unused memory
void linked_list_gc(LinkedList* list) {
    Node* node = list->head;
    while (node) {
        if (node->entry.timestamp < time(NULL) - 3600) { // Remove entries older than an hour
            linked_list_remove(list, node);
        } else {
            node = node->next;
        }
    }
}

int main() {
    LinkedList* list = linked_list_init();

    LogEntry* entry1 = log_entry_init("This is a test message 1");
