#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for a log entry
typedef struct LogEntry {
    long timestamp;
    int level;
    char* message;
} LogEntry;

// Define the doubly-linked list structure
typedef struct DoublyLinkedListNode {
    LogEntry* data;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

// Function to initialize a doubly-linked list of LogEntry structures
DoublyLinkedListNode* initLogList() {
    // Allocate memory for the head node
    DoublyLinkedListNode* head = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    head->prev = NULL;
    head->next = NULL;

    return head;
}

// Function to add a new log entry to the list
void addLogEntry(DoublyLinkedListNode* head, LogEntry* entry) {
    // Allocate memory for a new node
    DoublyLinkedListNode* newNode = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    newNode->data = entry;
    newNode->prev = NULL;
    newNode->next = NULL;

    // Add the new node to the list
    newNode->next = head->next;
    if (head->next != NULL) {
        head->next->prev = newNode;
    }
    head->next = newNode;
}

// Function to remove a log entry from the list
void removeLogEntry(DoublyLinkedListNode* head, LogEntry* entry) {
    // Find the node with the matching data
    DoublyLinkedListNode* current = head;
    while (current != NULL && current->data != entry) {
        current = current->next;
    }
    if (current == NULL) {
        return;  // Entry not found in the list
    }

    // Remove the node from the list
    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        head = current->next;
    }
    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    // Free the memory allocated for the node
    free(current);
}

// Function to print the log entries in the list
void printLogList(DoublyLinkedListNode* head) {
    DoublyLinkedListNode* current = head;
    while (current != NULL) {
        LogEntry* entry = current->data;
        printf("Timestamp: %ld, Level: %d, Message: %s\n", entry->timestamp, entry->level, entry->message);
        current = current->next;
    }
}

// Function to serialize the log list to a binary file
void serializeLogList(DoublyLinkedListNode* head, FILE* file) {
    // Serialize the list nodes
    DoublyLinkedListNode* current = head;
    while (current != NULL) {
        LogEntry* entry = current->data;
        fwrite(&entry->timestamp, sizeof(long), 1, file);
        fwrite(&entry->level, sizeof(int), 1, file);
        size_t messageLen = strlen(entry->message);
        fwrite(&messageLen, sizeof(size_t), 1, file);
        fwrite(entry->message, 1, messageLen, file);
        current = current->next;
    }
}

// Function to deserialize the log list from a binary file
DoublyLinkedListNode* deserializeLogList(FILE* file) {
    // Deserialize the list nodes
    DoublyLinkedListNode* head = NULL;
    LogEntry* entry;
    while (fread(&entry->timestamp, sizeof(long), 1, file) == 1) {
        entry->level = fread(&entry->level, sizeof(int), 1, file);
        size_t messageLen;
        fread(&messageLen, sizeof(size_t), 1, file);
        entry->message = (char*)malloc(messageLen + 1);
        fread(entry->message, 1, messageLen, file);
        entry->message[messageLen] = '\0';
        addLogEntry(head, entry);
    }
    return head;
}

// Function to garbage collect unused memory
void gc() {
    // Find and free any nodes with empty messages
    DoublyLinkedListNode* current = head;
    while (current != NULL) {
        LogEntry* entry = current->data;
        if (strlen(entry->message) == 0) {
            removeLogEntry(head, entry);
        }
        current = current->next;
    }
}

int main() {
    // Initialize the log list
    DoublyLinkedListNode* head = initLogList();

    // Add some log entries to the list
    LogEntry* entry1 = (LogEntry*)malloc(sizeof(LogEntry));
    entry1->timestamp = 1643723400;
    entry1->level = LOG_INFO;
    entry1->message = (char*)malloc(50);
    strcpy(entry1->message, "This is a log message");
    addLogEntry(head, entry1);

    LogEntry* entry2 = (LogEntry*)malloc(sizeof(LogEntry));
    entry2->timestamp = 1643723410;
    entry2->level = LOG_WARNING;
    entry2->message = (char*)malloc(20);
    strcpy(entry2->message, "Warning: something went wrong");
    addLogEntry(head, entry2);

    // Print the log entries in the list
    printLogList(head);

    // Serialize the log list to a binary file
    FILE* file = fopen("log.bin", "wb");
    serializeLogList(head, file);
    fclose(file);

    // Deserialize the log list from the binary file
    head = deserializeLogList(fopen("log.bin", "rb"));
    fclose(file);

    // Garbage collect unused memory
    gc();

    return 0;
}

