#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    char metric_name[64];
    double* value;
} MetricData;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t size;
    MetricData** data;
} CircularBuffer;

void circular_buffer_init(CircularBuffer* buffer, size_t capacity) {
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->data = (MetricData**)malloc(capacity * sizeof(MetricData*));
    pthread_mutex_init(&buffer->mutex, NULL);
}

void circular_buffer_insert(CircularBuffer* buffer, MetricData* data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size == buffer->capacity) {
        // handle buffer overflow
    }
    buffer->data[buffer->size] = data;
    buffer->size = (buffer->size + 1) % buffer->capacity;
    pthread_mutex_unlock(&buffer->mutex);
}

void circular_buffer_aggregate(CircularBuffer* buffer, char* metric_name, double (*aggregation_func)(double*)) {
    pthread_mutex_lock(&buffer->mutex);
    for (int i = 0; i < buffer->size; i++) {
        if (!strcmp(buffer->data[i]->metric_name, metric_name)) {
            aggregation_func(buffer->data[i]->value);
        }
    }
    pthread_mutex_unlock(&buffer->mutex);
}

double* circular_buffer_get_value(CircularBuffer* buffer, char* metric_name) {
    pthread_mutex_lock(&buffer->mutex);
    for (int i = 0; i < buffer->size; i++) {
        if (!strcmp(buffer->data[i]->metric_name, metric_name)) {
            return buffer->data[i]->value;
        }
    }
    pthread_mutex_unlock(&buffer->mutex);
    return NULL;
}

void circular_buffer_free(CircularBuffer* buffer) {
    for (int i = 0; i < buffer->size; i++) {
        free(buffer->data[i]->value);
        free(buffer->data[i]);
    }
    free(buffer->data);
    pthread_mutex_destroy(&buffer->mutex);
}
