import subprocess
import concurrent.futures
import time
import hashlib
import logging

logging.basicConfig(level=logging.INFO)

def update_config(deployment):
    config_file = f"config_{deployment['env']}.yaml"
    env_vars = deployment["env_vars"]
    service_endpoints = deployment["service_endpoints"]
    resource_allocation = deployment["resource_allocation"]

    command = f"sed -i 's/old_env_var/{env_vars}/g' {config_file}"
    subprocess.run(command.split(" "), check=True)

    for endpoint in service_endpoints:
        command = f"echo '{endpoint}' >> {config_file}"
        subprocess.run(command.split(" "), check=True)

    command = f"resource_allocation={json.dumps(resource_allocation)} > {config_file}.bak"
    subprocess.run(command.split(" "), check=True)

def get_service_metrics(deployment):
    endpoint_url = deployment["service_endpoints"][0]
    api_key = "your_api_key"

    def api_request(endpoint):
        try:
            response = requests.get(endpoint, headers={"Authorization": f"Bearer {api_key}"})
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            logging.error(f"Error fetching metrics for {endpoint}: {str(e)}")
            return None

    with concurrent.futures.ThreadPoolExecutor() as executor:
        futures = [executor.submit(api_request, endpoint) for endpoint in service_endpoints]
        results = [future.result() for future in futures]

    return {endpoint: result for endpoint, result in zip(service_endpoints, results)}

def calculate_md5(file_path):
    md5_hash = hashlib.md5()
    with open(file_path, "rb") as file:
        while True:
            chunk = file.read(4096)
            if not chunk:
                break
            md5_hash.update(chunk)
    return md5_hash.hexdigest()

def deploy_services(deployments):
    threads = []
    for deployment in deployments:
        thread = threading.Thread(target=update_config, args=(deployment,))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    metrics = {}
    for deployment in deployments:
        service_metrics = get_service_metrics(deployment)
        if service_metrics:
            metrics.update(service_metrics)

    logging.info(f"Deployment complete. Metrics: {metrics}")

if __name__ == "__main__":
    deployments = [
        {"env": "dev", "env_vars": ["old_env_var"], "service_endpoints": ["https://dev.service.com"], "resource_allocation": {"cpu": 1, "memory": 2}},
        {"env": "stg", "env_vars": ["new_env_var"], "service_endpoints": ["https://stg.service.com"], "resource_allocation": {"cpu": 3, "memory": 4}},
    ]

    deploy_services(deployments)
