    char getRandomCRCFlag() {
        return (rand() % 2 == 0) ? '1' : '0';
    }

    // Function to create a new NFAPI_CRC_INDICATION_PDU_T structure with valid fields and a randomly set CRCFLAG
    void* createNewEntry(int RNTI) {
