    // Function to handle edge cases where the array is full
    void handleArrayFull(int** array, int* size) {
        if (*size == 100) { // Array is full, handle this edge case as per requirement
            printf("Array is full. Cannot add more entries.\n");
            return;
        }
    }

    int main() {
        int** array = NULL;
        int size = 0;

        manage_crc_indication_array(&array, &size);

        // Example usage: Add and print entries
        for (int i = 0; i < 5; i++) {
