typedef struct DataPacket {
    int id;
    long timestamp;
    char* payload;
} DataPacket;

DataPacket* initializeDynamicDataProcessor(int maxPayloadSize, int maxBufferSize) {
    SHA256_CTX* shaContext = SHA256_CTX_new();
    if (shaContext == NULL) {
        return NULL;
    }

    int bufferSize = 2; // initial buffer size
    DataPacket** buffer = (DataPacket**)malloc(bufferSize * sizeof(DataPacket*));
    if (buffer == NULL) {
        SHA256_CTX_free(shaContext);
        return NULL;
    }

    for (int i = 0; i < bufferSize; i++) {
        buffer[i] = NULL;
    }

    int currentBufferSize = 0;

    // hash parameters
    unsigned char hashParam[32];
    memset(hashParam, 0, 32);

    SHA256_SetHashsize(shaContext, maxPayloadSize);
    SHA256_SetHashparam(shaContext, hashParam);

    return (DataPacket*)shaContext;
}

void cleanupDynamicDataProcessor(DataPacket* buffer) {
    for (int i = 0; i < currentBufferSize; i++) {
        if (buffer[i]->payload != NULL) {
            free(buffer[i]->payload);
        }
    }

    free(buffer);
}
