#include <string.h>
#include <pthread.h>

typedef struct DataPacket {
    int id;
    time_t timestamp;
    char* payload;
} DataPacket;

typedef struct CircularBuffer {
    DataPacket* packets[100]; // assume max size of 100
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int head, tail, size;
    int gc_interval; // garbage collection interval in seconds
    int gc_pressure_threshold; // memory pressure threshold to trigger GC
} CircularBuffer;

void initCircularBuffer(CircularBuffer* buffer) {
    pthread_mutex_init(&buffer->lock, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
}

DataPacket* enqueue(CircularBuffer* buffer, DataPacket packet) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->size >= sizeof(buffer->packets[0])) {
        // buffer is full
        pthread_cond_signal(&buffer->cond);
        pthread_mutex_unlock(&buffer->lock);
        return NULL;
    }

    buffer->packets[buffer->tail] = &packet;
    buffer->tail = (buffer->tail + 1) % sizeof(buffer->packets[0]);
    buffer->size++;
    pthread_mutex_unlock(&buffer->lock);

    return &packet;
}

DataPacket* dequeue(CircularBuffer* buffer) {
    pthread_mutex_lock(&buffer->lock);

    if (buffer->size <= 0) {
        // buffer is empty
        pthread_cond_wait(&buffer->cond, &buffer->lock);
    }

    DataPacket* packet = buffer->packets[buffer->head];
    buffer->head = (buffer->head + 1) % sizeof(buffer->packets[0]);
    buffer->size--;
    pthread_mutex_unlock(&buffer->lock);

    return packet;
}

void iterate(CircularBuffer* buffer, FILE* fd) {
    pthread_mutex_lock(&buffer->lock);
    for (int i = 0; i < buffer->size; i++) {
        DataPacket* packet = buffer->packets[(buffer->head + i) % sizeof(buffer->packets[0])];
        fprintf(fd, "%d %ld %s\n", packet->id, packet->timestamp, packet->payload);
    }
    pthread_mutex_unlock(&buffer->lock);
}

void garbageCollect(CircularBuffer* buffer) {
    // implement your garbage collection logic here
}

void saveCircularBufferToFile(CircularBuffer* buffer, const char* filename) {
    FILE* fd = fopen(filename, "wb");
    if (!fd) return;
    fwrite(buffer, sizeof(CircularBuffer), 1, fd);
    fclose(fd);
}

