#define CACHE_SIZE 1000000

typedef struct {
    char* key;
    int timestamp;
    size_t value_size;
    void* value;
} CacheEntry;

typedef struct {
    CacheEntry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DistributedCache;

DistributedCache cache = {NULL, 0, 0};

void init_cache() {
    cache.entries = (CacheEntry**)malloc(CACHE_SIZE * sizeof(CacheEntry*));
    cache.capacity = CACHE_SIZE;
    cache.size = 0;
    pthread_mutex_init(&cache.mutex, NULL);
    pthread_cond_init(&cache.cond, NULL);
}

int cache_put(const char* key, int timestamp, void* value) {
    size_t i;
    CacheEntry* entry;

    for (i = 0; i < cache.size; i++) {
        if (!strcmp(key, cache.entries[i]->key)) {
            // Update existing entry
            cache.entries[i]->timestamp = timestamp;
            *((void**)cache.entries[i]->value) = value;
            return 0;
        }
    }

    // Create new entry
    entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    entry->key = strdup(key);
    entry->timestamp = timestamp;
    entry->value_size = sizeof(*value);
    entry->value = malloc(entry->value_size);

    if (!entry) {
        return -1; // Out of memory
    }

    * ((void**)entry->value) = value;

    if (cache.size == cache.capacity) {
        // Resize the cache
        cache.capacity *= 2;
        cache.entries = (CacheEntry**)realloc(cache.entries, cache.capacity * sizeof(CacheEntry*));
    }

    cache.entries[cache.size++] = entry;
    return 0;
}

int main() {
    init_cache();
    // Insertions and retrievals...
    return 0;
}
