#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    int timestamp;
    char level;
    char* message;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    int size;
} DoublyLinkedList;

DoublyLinkedList* dll_init() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

void dll_insert(DoublyLinkedList* list, LogEntry entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->entry.timestamp = entry.timestamp;
    new_node->entry.level = entry.level;
    new_node->entry.message = strdup(entry.message);
    new_node->prev = NULL;
    new_node->next = list->head;

    if(list->head != NULL) {
        list->head->prev = &new_node->prev;
    } else {
        list->tail = &new_node->prev;
    }
    list->head = &new_node;
    list->size++;
}

void dll_free(DoublyLinkedList* list) {
    Node* current = list->head;
    while(current != NULL) {
        Node* next = current->next;
        free(current->entry.message);
        free(current);
        current = next;
    }
    free(list);
}

void dll_print(DoublyLinkedList* list, int fd) {
    Node* current = list->head;
    while(current != NULL) {
        fwrite(&current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
}

int dll_serialize(DoublyLinkedList* list, char* file_path) {
    FILE* file = fopen(file_path, "wb");
    if(file == NULL) return -1;

    Node* current = list->head;
    while(current != NULL) {
        fwrite(&current->entry.timestamp, sizeof(int), 1, file);
        fwrite(&current->entry.level, sizeof(char), 1, file);
        size_t message_len = strlen(current->entry.message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(current->entry.message, sizeof(char), message_len + 1, file);

        current = current->next;
    }

    fclose(file);
    return 0;
}

int dll_deserialize(DoublyLinkedList* list, char* file_path) {
    FILE* file = fopen(file_path, "rb");
    if(file == NULL) return -1;

    Node* new_node = (Node*)malloc(sizeof(Node));
    while(fread(&new_node->entry.timestamp, sizeof(int), 1, file) == 1 &&
         fread(&new_node->entry.level, sizeof(char), 1, file) == 1) {
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char* new_message = (char*)malloc((message_len + 1)*sizeof(char));
        fread(new_message, sizeof(char), message_len, file);
        new_message[message_len] = '\0';
        new_node->entry.message = new_message;
        dll_insert(list, new_node->entry);

        free(new_node);
        new_node = (Node*)malloc(sizeof(Node));
    }

    fclose(file);
    return 0;
}

int main() {
    DoublyLinkedList* list = dll_init();

    // Insert log entries
    LogEntry entry1 = {"timestamp1", 'I', "message1"};
    LogEntry entry2 = {"timestamp2", 'E', "message2"};
    dll_insert(list, entry1);
    dll_insert(list, entry2);

    // Print log entries to file descriptor
    int fd = 0;
    dll_print(list, fd);

    // Serialize log entries to a file
    char* file_path = "log.bin";
    dll_serialize(list, file_path);

    // Deserialize log entries from the file
    dll_deserialize(list, file_path);

    // Free memory and list
    dll_free(list);

    return 0;
}
