            printf("Packet %d: TCP/UDP header checksum is invalid\n", i+1);
        }
    }
}

int main() {
    int limit = 100; // Maximum number of packets
    int port_range_start = 1024, port_range_end = 49151; // User-defined port range

    Packet** packets = manage_packets(limit, &port_range_start, &port_range_end);
