['Here's a C function that implements a command-line interface (CLI) tool for managing large-scale configuration files:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>

// Configuration setting structure
typedef struct {
    char* key;
    void* value; // pointer to string, int, or float
} Setting;

// Configuration file structure
typedef struct {
    uint32_t num_sections;
    Setting** sections;
} ConfigFile;

// Thread-safe configuration management functions
ConfigFile* config_new(uint32_t num_sections) {
    ConfigFile* conf = (ConfigFile*)malloc(sizeof(ConfigFile));
    conf->num_sections = num_sections;
    conf->sections = (Setting**)calloc(num_sections, sizeof(Setting*));
    return conf;
}

void config_free(ConfigFile* conf) {
    for (uint32_t i = 0; i < conf->num_sections; i++) {
        free(conf->sections[i]->key);
        free(conf->sections[i]->value);
    }
    free(conf->sections);
    free(conf);
}

Setting* setting_new(const char* key, void* value) {
    Setting* s = (Setting*)malloc(sizeof(Setting));
    s->key = strdup(key);
    s->value = value;
    return s;
}

void setting_free(Setting* s) {
    free(s->key);
    free(s->value);
    free(s);
}

int main() {
    // Initialize configuration file
    ConfigFile* conf = config_new(10000);

    // Load configuration file from disk (omitted for brevity)
    // ...

    // Provide CLI interface for managing configuration settings
    while (1) {
        printf("Enter command (get, set, delete, quit): ");
        char cmd[32];
        fgets(cmd, 32, stdin);
        cmd[strcspn(cmd, "\n")] = 0;

        if (strcmp(cmd, "get") == 0) {
            // Get configuration setting
            printf("Enter key: ");
            char* key = malloc(32);
            fgets(key, 32, stdin);
            key[strcspn(key, "\n")] = 0;
            Setting* s = setting_new(key, NULL); // load setting from config file
            printf("%s: %p\n", key, s->value);
            free(s);
        } else if (strcmp(cmd, "set") == 0) {
            // Set configuration setting
            printf("Enter key: ");
            char* key = malloc(32);
            fgets(key, 32, stdin);
            key[strcspn(key, "\n")] = 0;
            printf("Enter value (string, int, or float): ");
            void* value = ...; // load value from user input
            setting_new(key, value); // update config file
        } else if (strcmp(cmd, "delete") == 0) {
            // Delete configuration setting
            printf("Enter key: ");
            char* key = malloc(32);
            fgets(key, 32, stdin);
            key[strcspn(key, "\n")] = 0;
            // delete setting from config file
        } else if (strcmp(cmd, "quit") == 0) {
            break;
        }
    }

    // Free configuration file and settings
    config_free(conf);

    return 0;
}
```
This code provides a basic CLI interface for managing large-scale configuration files. It includes thread-safe functions for creating, loading, and updating configuration files, as well as setting and deleting individual settings. The `config_new` function initializes the configuration file structure, while the `setting_new` function creates a new setting with a given key and value.

Note that this is just a starting point, and you will need to add additional functionality, error handling, and optimizations to make the CLI tool robust and efficient.']

