// Define structure for MetricData
typedef struct {
    time_t timestamp;
    char* metric_name;
    double* value;
} MetricData;

// Define circular buffer structure
typedef struct {
    size_t capacity;
    size_t head;
    size_t tail;
    MetricData** data;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CircularBuffer;

// Function to initialize a concurrent circular buffer of MetricData structures
CircularBuffer* circular_buffer_init(size_t capacity) {
    // Allocate memory for the circular buffer
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));

    // Initialize the buffer with given capacity
    buffer->capacity = capacity;
    buffer->head = 0;
    buffer->tail = 0;
    buffer->data = (MetricData**)malloc(capacity * sizeof(MetricData*));

    // Initialize mutex and condition variable for synchronization
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);

    return buffer;
}

// Function to free the circular buffer when it is destroyed or flushed
void circular_buffer_free(CircularBuffer* buffer) {
    // Free memory allocated for each MetricData structure
    for (size_t i = 0; i < buffer->capacity; ++i) {
        if (buffer->data[i] != NULL) {
            free(buffer->data[i]->value);
            free(buffer->data[i]->metric_name);
            free(buffer->data[i]);
        }
    }

    // Free the circular buffer itself
    free(buffer->data);
    pthread_mutex_destroy(&buffer->mutex);
    pthread_cond_destroy(&buffer->cond);
    free(buffer);
}

// Function to perform serialization of MetricData structures in the circular buffer
void serialize_circular_buffer(CircularBuffer* buffer, FILE* file) {
    // Write the number of entries in the buffer
    fwrite(&buffer->capacity, sizeof(size_t), 1, file);

    // Write each MetricData structure serially
    for (size_t i = 0; i < buffer->capacity; ++i) {
        MetricData* metric_data = buffer->data[i];

        // Serialize timestamp
