        fwrite(&metric_name_len, sizeof(size_t), 1, file);
        fwrite(metric_data->metric_name, sizeof(char), metric_name_len + 1, file);

        // Serialize value
        fwrite(&metric_data->value, sizeof(double), 1, file);
    }
}

// Function to deserialize MetricData structures from a binary format
CircularBuffer* deserialize_circular_buffer(FILE* file) {
    CircularBuffer* buffer;

    // Read the number of entries in the buffer
    size_t capacity;
    fread(&capacity, sizeof(size_t), 1, file);

    // Allocate memory for the circular buffer and its contents
    buffer = circular_buffer_init(capacity);

    // Read each MetricData structure deserially
    for (size_t i = 0; i < capacity; ++i) {
        MetricData* metric_data = buffer->data[i];

