        metric_data->metric_name = (char*)malloc(metric_name_len + 1);
        fread(metric_data->metric_name, sizeof(char), metric_name_len + 1, file);

        // Deserialize value
        fread(&metric_data->value, sizeof(double), 1, file);
    }

    return buffer;
}

