    enum { CRCFLAG_SET, CRCFLAG_RESET } CRCFLAG;
    enum { CRC_INDICATION_REL8_TAG_VAL1, CRC_INDICATION_REL8_TAG_VAL2 } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_and_populate_array(int num_elements, int seed) {
    srand(seed);

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed. Exiting...\n");
        exit(1);
    }

    for (int i = 0; i < num_elements; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 256;
        array[i].RNTI = rand() % 65536;
        if (rand() % 2) {
            array[i].CRCFLAG = CRCFLAG_SET;
        } else {
            array[i].CRCFLAG = CRCFLAG_RESET;
        }
        array[i].CRC_INDICATION_REL8_TAG = (enum { CRC_INDICATION_REL8_TAG_VAL1, CRC_INDICATION_REL8_TAG_VAL2 }) rand() % 2;

        if (!array[i].RX_UE_INFORMATION_TAG || !array[i].RNTI) {
            free(array);
            fprintf(stderr, "Failed to generate valid data structure. Exiting...\n");
            exit(1);
        }
    }

    // Validate the integrity of the generated data structures
    for (int i = 0; i < num_elements; i++) {
        if (!array[i].RX_UE_INFORMATION_TAG || !array[i].RNTI) {
            fprintf(stderr, "Invalid data structure detected at index %d. Exiting...\n", i);
            free(array);
            exit(1);
        }
    }

    // Log any failures during the memory allocation process
    if (num_elements > 10000) {
        printf("Memory allocated for %d elements successfully.\n", num_elements);
    } else {
        printf("Memory allocated for up to 10,000 elements efficiently.\n");
    }

    free(array);
}
