#include <openssl/md5.h>

typedef struct {
    uint16_t src_addr;
    uint16_t dst_addr;
} MAC_Header;

typedef struct {
    MAC_Header header;
    char data[1024];
    MAC_Trailer trailer;
} MAC_PDU_DATA;

typedef struct {
    int num_pdus;
    MAC_PDU_DATA* pdus;
} MAC_PDU_ARRAY;

MAC_PDU_ARRAY* init_mac_pdu_array(int max_num_pdus) {
    MAC_PDU_ARRAY* array = (MAC_PDU_ARRAY*)malloc(sizeof(MAC_PDU_ARRAY));
    if (!array) {
        printf("Error: Unable to allocate memory for MAC PDU array.\n");
        return NULL;
    }
    array->num_pdus = 0;
    array->pdus = (MAC_PDU_DATA*)malloc(max_num_pdus * sizeof(MAC_PDU_DATA));
    if (!array->pdus) {
        free(array);
        printf("Error: Unable to allocate memory for MAC PDUs.\n");
        return NULL;
    }
    return array;
}

void process_mac_pdu_data(const char* p, int len, void (*callback)(const char*, int)) {
    // Process the PDU data
    callback(p, len);
}

char* compute_md5_hash(const MAC_PDU_DATA* pdu) {
    uint8_t hash[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, &pdu->header, sizeof(MAC_Header));
    MD5_Update(&ctx, pdu->data, strlen(pdu->data));
    MD5_Final(hash, &ctx);
    char* hash_str = (char*)malloc(MD5_DIGEST_LENGTH * 2 + 1);
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&hash_str[i * 2], "%02x", hash[i]);
    }
    return hash_str;
}

void cleanup_mac_pdu_array(MAC_PDU_ARRAY* array) {
    if (!array) return;
    free(array->pdus);
    free(array);
}
