#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure to hold log entry information
typedef struct {
    time_t timestamp;
    int log_level;
    char *message;
} LogEntry;

// Define a structure to hold linked list nodes
typedef struct Node {
    LogEntry *entry;
    struct Node *prev;
    struct Node *next;
} Node;

// Function to initialize the doubly-linked list of LogEntry structures
void init_log_list(Node **head, int initial_capacity) {
    *head = (Node *)malloc(sizeof(Node));
    (*head)->prev = NULL;
    (*head)->next = NULL;
}

// Function to add a new log entry to the list
void add_log_entry(Node **head, LogEntry *entry) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    new_node->entry = entry;
    new_node->prev = NULL;
    new_node->next = (*head);
    if ((*head) != NULL)
        (*head)->prev = &new_node;
    else
        new_node->prev = NULL;
    (*head) = new_node;
}

// Function to print the log entries in the list
void print_log_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("Timestamp: %ld, Log Level: %d, Message: %s\n",
               current->entry->timestamp,
               current->entry->log_level,
               current->entry->message);
        current = current->next;
    }
}

// Function to free the log entries in the list
void free_log_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        free(current->entry->message);
        free(current);
        current = current->next;
    }
    free(head);
}
