    table->entries = (ConfigEntry**)malloc(initial_size * sizeof(ConfigEntry*));
    for (int i = 0; i < initial_size; i++) {
        table->entries[i] = NULL;
    }
}

void hash_table_insert(HashTable* table, ConfigEntry* entry) {
    int index = entry->key % table->size;
    if (table->entries[index] == NULL) {
        table->entries[index] = entry;
    } else {
        // resize and rehash
        int new_size = table->size * 2;
        HashTable new_table;
        hash_table_init(&new_table, new_size);
        for (int i = 0; i < table->size; i++) {
            if (table->entries[i] != NULL) {
                ConfigEntry* new_entry = malloc(sizeof(ConfigEntry));
                strcpy(new_entry->key, table->entries[i]->key);
                new_entry->value = table->entries[i]->value;
                new_entry->type = table->entries[i]->type;
                int newIndex = new_entry->key % new_size;
                new_table.entries[newIndex] = new_entry;
            }
        }
        free(table->entries);
        table->entries = new_table.entries;
        table->size = new_size;
    }
}

void hash_table_remove(HashTable* table, ConfigEntry* entry) {
    int index = entry->key % table->size;
    if (table->entries[index] == entry) {
        free(entry->value);
        free(entry);
        table->entries[index] = NULL;
    } else {
        // find and remove
        for (int i = 0; i < table->size; i++) {
            if (table->entries[i] == entry) {
                free(entry->value);
                free(entry);
                table->entries[i] = NULL;
                return;
            }
        }
    }
}

void serialize_config(HashTable* table, FILE* file) {
    json_object* config = json_object_new();
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL) {
            json_object_object_add(config, table->entries[i]->key, table->entries[i]->value);
        }
    }
    fprintf(file, "%s", json_object_to_json_string(config));
    json_object_free(config);
}

void deserialize_config(HashTable* table, FILE* file) {
    json_object* config = json_object_from_file(file);
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]->value);
            free(table->entries[i]);
        }
    }
    for (json_object_iterator it = json_object_iter_begin(config); it; it = json_object_iter_next(it)) {
        ConfigEntry* entry = malloc(sizeof(ConfigEntry));
        strcpy(entry->key, json_object_get_string(it));
        entry->value = malloc(strlen(json_object_get_string(it)) + 1);
        sprintf(entry->value, "%s", json_object_get_string(it));
        entry->type = JSON_OBJECT_GET_TYPE(it);
        int index = entry->key % table->size;
        table->entries[index] = entry;
    }
    json_object_free(config);
}

void* get_config_value(HashTable* table, char* key) {
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL && strcmp(table->entries[i]->key, key) == 0) {
            return table->entries[i]->value;
        }
    }
    return NULL;
}

void set_config_value(HashTable* table, char* key, void* value) {
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL && strcmp(table->entries[i]->key, key) == 0) {
            free(table->entries[i]->value);
            table->entries[i]->value = value;
            return;
        }
    }
}

void evict_config(HashTable* table, int threshold) {
    for (int i = 0; i < table->size; i++) {
        if (table->entries[i] != NULL && strcmp(table->entries[i]->key, "") == 0) {
            free(table->entries[i]->value);
            free(table->entries[i]);
            table->entries[i] = NULL;
            return;
        }
    }
}

