#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 1000
#define TIMESTAMP_INCREMENT 100 // arbitrary value to ensure monotonicity

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
    long timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfa_pi_crc_indication_pdu_list_create(int num_entries) {
    void* list = NULL;
    NFAPI_CRC_INDICATION_PDU_T* pdu = NULL;

    if(num_entries > MAX_ENTRIES) {
        // handle error
        return NULL;
    }

    int i;
    for(i = 0; i < num_entries; i++) {
        pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if(pdu == NULL) {
            // handle error
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRCFLAG = (rand() % 2);

        // ensure timestamp is monotonically increasing
        if(i > 0) {
            pdu->timestamp += TIMESTAMP_INCREMENT;
        } else {
            pdu->timestamp = time(NULL); // initialize with current time
        }

        // append to list
        if(list == NULL) {
            list = pdu;
        } else {
            ((NFAPI_CRC_INDICATION_PDU_T*)list)->next = pdu;
        }
    }

    return list;
}

void nfa_pi_crc_indication_pdu_list_free(void* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)list;
    NFAPI_CRC_INDICATION_PDU_T* next = NULL;

    while(current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

void nfa_pi_crc_indication_pdu_list_cleanup(void* list, int threshold_entries_stale) {
    NFAPI_CRC_INDICATION_PDU_T* current = (NFAPI_CRC_INDICATION_PDU_T*)list;
    NFAPI_CRC_INDICATION_PDU_T* next = NULL;

    while(current != NULL) {
        if(current->timestamp + TIMESTAMP_INCREMENT < time(NULL)) { // stale entry
            next = current->next;
            free(current);
            current = next;
        } else {
            current = next;
        }
    }
}
