CREATE FUNCTION GetEmployeeData (@supervisorID INT)
RETURNS TABLE
AS
RETURN (
    SELECT e.Name, c.City, a.Address 
    FROM Employees e 
    INNER JOIN Addresses a ON e.AddressID = a.ID 
    INNER JOIN Cities c ON a.CityID = c.ID 
    WHERE e.SupervisorID = @supervisorID
);

GO

CREATE PROCEDURE GetEmployeeData_SP (@supervisorID INT)
AS
BEGIN
    SET NOCOUNT ON;
    SELECT * FROM GetEmployeeData(@supervisorID);
END;

