#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <json-c/json.h>

// Configuration structure
typedef struct {
    char *name;
    char *type;
    double default_value;
    double *current_value;
} Config;

// Dynamic configuration manager
typedef struct {
    int size;
    Config **configs;
    pthread_mutex_t mutex;
} ConfigManager;

// Initialize the configuration manager
ConfigManager* config_manager_init() {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    manager->size = 0;
    manager->configs = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
    return manager;
}

// Add a new configuration to the manager
void config_manager_add(ConfigManager* manager, char *name, char *type, double default_value) {
    Config *config = (Config*)malloc(sizeof(Config));
    config->name = strdup(name);
    config->type = strdup(type);
    config->default_value = default_value;
    config->current_value = (double*)malloc(sizeof(double));
    *config->current_value = default_value;

    pthread_mutex_lock(&manager->mutex);
    manager->configs = (Config**)realloc(manager->configs, sizeof(Config*)*(manager->size + 1));
    manager->configs[manager->size] = config;
    manager->size++;
    pthread_mutex_unlock(&manager->mutex);
}

// Free the configuration manager
void config_manager_free(ConfigManager* manager) {
    for(int i = 0; i < manager->size; i++) {
        free(manager->configs[i]->name);
        free(manager->configs[i]->type);
        free((void*)manager->configs[i]->current_value);
        free((void*)manager->configs[i]);
    }
    free(manager->configs);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

// Serialize the configuration manager to JSON
char* config_manager_serialize(ConfigManager* manager) {
    json_object *root = json_object_new_object();
    for(int i = 0; i < manager->size; i++) {
        Config *config = manager->configs[i];
        json_object *conf_obj = json_object_new_object();
        json_object_object_add(conf_obj, "name", json_string(config->name));
        json_object_object_add(conf_obj, "type", json_string(config->type));
        json_object_object_add(conf_obj, "default_value", json_real(config->default_value));
        json_object_object_add(conf_obj, "current_value", json_real(*config->current_value));
        json_object_object_add(root, config->name, conf_obj);
    }
    char *json_str = json_object_to_json_string(root);
    json_decref(root);
    return json_str;
}

// Deserialize the configuration manager from JSON
ConfigManager* config_manager_deserialize(char *json_str) {
    ConfigManager *manager = (ConfigManager*)malloc(sizeof(ConfigManager));
    pthread_mutex_init(&manager->mutex, NULL);
    json_object *root = json_tokener_parse(json_str);
    for(json_object_object_iterator it = json_object_iter(root); it;(it = json_object_iter_next(it))) {
        char *name = json_string_value(it.key);
        Config *config = (Config*)malloc(sizeof(Config));
        config->name = strdup(name);
        config->type = strdup(json_string_value(json_object_object_get(root, name)));
        config->default_value = json_real_value(json_object_object_get(root, name));
        config->current_value = (double*)malloc(sizeof(double));
        *config->current_value = config->default_value;
        pthread_mutex_lock(&manager->mutex);
        manager->configs = (Config**)realloc(manager->configs, sizeof(Config*)*(manager->size + 1));
        manager->configs[manager->size] = config;
        manager->size++;
        pthread_mutex_unlock(&manager->mutex);
    }
    free((void*)root);
    return manager;
}

// Compute aggregated metrics for each type of configuration
void config_manager_aggregate(ConfigManager* manager) {
