    int timestamp;
    double value;
    void* metadata;
} MetricData;

// Circular doubly-linked list node structure
typedef struct Node {
    LogEntry log_entry;
    MetricData metric_data;
    struct Node* next;
    struct Node* prev;
} Node;

// Circular doubly-linked list structure
typedef struct LinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    size_t size;
} LinkedList;

// Function to initialize a circular doubly-linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add an entry to the circular doubly-linked list
void add_entry(LinkedList* list, LogEntry log_entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->log_entry = log_entry;
    new_node->metric_data = metric_data; // assuming metric_data exists
    new_node->next = NULL;
    new_node->prev = list->tail;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_lock(&list->mutex);
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove an entry from the circular doubly-linked list
void remove_entry(LinkedList* list, Node* node) {
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    pthread_mutex_lock(&list->mutex);
    list->size--;
    free(node);
    pthread_mutex_unlock(&list->mutex);
}

