#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <thread>

using namespace std;

class Node {
public:
    unordered_map<string, pair<dynamic_byte_array, uint64_t>> data;
    unordered_map<string, bool> bloomFilter;

    void addData(const string& key, const dynamic_byte_array& value, uint64_t expirationTime) {
        data[key] = {value, expirationTime};
        bloomFilter[key] = true;
    }

    pair<dynamic_byte_array, uint64_t>* getData(const string& key) {
        if (data.find(key) != data.end()) {
            return &data[key];
        }
        return nullptr;
    }

    void removeData(const string& key) {
        data.erase(key);
        bloomFilter.erase(key);
    }

    bool checkExistence(const string& key) {
        return bloomFilter.find(key) != bloomFilter.end();
    }
};

class DistributedKeyValStore {
public:
    vector<Node> nodes;
    unordered_map<string, Node*> nodeMap;

    void addNode(Node* node) {
        nodes.push_back(*node);
        nodeMap[node->getName()] = node;
    }

    void removeNode(const string& nodeName) {
        auto it = find_if(nodes.begin(), nodes.end(),
            [nodeName](const Node& node) { return node.getName() == nodeName; });
        if (it != nodes.end()) {
            nodes.erase(it);
            nodeMap.erase(nodeName);
        }
    }

    void putData(const string& key, const dynamic_byte_array& value, uint64_t expirationTime) {
        for (auto& node : nodes) {
            node.addData(key, value, expirationTime);
        }
    }

    pair<dynamic_byte_array, uint64_t>* getData(const string& key) {
        for (auto& node : nodes) {
            if (node.getData(key)) {
                return &node.getData(key)->second;
            }
        }
        return nullptr;
    }

    void removeData(const string& key) {
        for (auto& node : nodes) {
            node.removeData(key);
        }
    }

    bool checkExistence(const string& key) {
        for (auto& node : nodes) {
            if (node.checkExistence(key)) {
                return true;
            }
        }
        return false;
    }
};

int main() {
    // Create nodes
    Node* node1 = new Node();
    Node* node2 = new Node();
    Node* node3 = new Node();

    DistributedKeyValStore store;

    // Add nodes to the store
    store.addNode(node1);
    store.addNode(node2);
    store.addNode(node3);

    // Put data into the store
    store.putData("key1", dynamic_byte_array(), 1643723400);

    // Get and remove data from the store
    pair<dynamic_byte_array, uint64_t>* data = store.getData("key1");
    if (data) {
        cout << "Data: " << *data->first << endl;
    } else {
        cout << "Key not found." << endl;
    }

    store.removeData("key1");

    return 0;
}
