#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
    struct LogEntry* next;
} LogEntry;

LogEntry* initialize_log_entries() {
    LogEntry* head = (LogEntry*) malloc(sizeof(LogEntry));
    if (!head) return NULL;
    head->next = NULL;
    return head;
}

void add_log_entry(LogEntry** head, time_t timestamp, int logLevel, const char* message) {
    LogEntry* newNode = (LogEntry*) malloc(sizeof(LogEntry));
    if (!newNode) return; // Handle memory allocation failure
    newNode->timestamp = timestamp;
    newNode->logLevel = logLevel;
    newNode->message = (char*) malloc(strlen(message) + 1);
    strcpy(newNode->message, message);
    newNode->next = (*head);
    *head = newNode;
}

void print_log_entries(LogEntry* head, int fd, int mode) {
    while (head) {
        fprintf(fd, "%ld %d %s\n", head->timestamp, head->logLevel, head->message);
        if (mode == 1) { // Verbose mode
            fprintf(fd, "Timestamp: %ld | Log Level: %d | Message: %s\n", head->timestamp, head->logLevel, head->message);
        }
        head = head->next;
    }
}

void destroy_log_entries(LogEntry** head) {
    while (*head) {
        LogEntry* temp = *head;
        *head = (*head)->next;
        free(temp->message);
        free(temp);
    }
    free(*head);
}

int serialize_log_entries(LogEntry* head, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -1; // Handle file opening failure
    LogEntry* temp = head;
    while (temp) {
        fwrite(&temp->timestamp, sizeof(time_t), 1, file);
        fwrite(&temp->logLevel, sizeof(int), 1, file);
        size_t len = strlen(temp->message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(temp->message, 1, len + 1, file);
        temp = temp->next;
    }
    fclose(file);
}

int deserialize_log_entries(LogEntry** head, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -1; // Handle file opening failure
    LogEntry* newNode = (LogEntry*) malloc(sizeof(LogEntry));
    size_t len;
    while (fread(&newNode->timestamp, sizeof(time_t), 1, file) == 1 &&
           fread(&newNode->logLevel, sizeof(int), 1, file) == 1 &&
           fread(&len, sizeof(size_t), 1, file) == 1) {
        newNode->message = (char*) malloc(len + 1);
        fread(newNode->message, 1, len, file);
        newNode->message[len] = '\0';
        newNode->next = (*head);
        *head = newNode;
    }
    fclose(file);
}

int main() {
    LogEntry* head = initialize_log_entries();
    // Add log entries
    add_log_entry(&head, time(NULL), 1, "This is a test message.");
    add_log_entry(&head, time(NULL) + 1000, 2, "Another test message.");
    // Print log entries
    int fd = open("log.txt", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    print_log_entries(head, fd, 1);
    close(fd);
    // Destroy log entries
    destroy_log_entries(&head);
    return 0;
}
