    *head = NULL;
}

LogEntry* create_log_entry(int timestamp, char log_level, int message_len) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = (char*)malloc(message_len + 1);
    return entry;
}

void insert_entry(struct Node** head, LogEntry* entry) {
    if (*head == NULL || (*head)->entry.timestamp < entry->timestamp) {
        struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
        new_node->entry = *entry;
        new_node->prev = NULL;
        new_node->next = *head;
        if (*head != NULL)
            (*head)->prev = &new_node->entry;
        *head = &new_node->entry;
    } else {
        struct Node* current = *head;
        while (current->next != NULL && current->next->entry.timestamp <= entry->timestamp) {
            current = current->next;
        }
        entry->message = (char*)malloc(strlen(entry->message) + 1);
        strcpy(entry->message, current->entry.message);
        struct Node* new_node = (struct Node*)malloc(sizeof(struct Node));
        new_node->entry = *entry;
        new_node->prev = current;
        new_node->next = current->next;
        if (current->next != NULL)
            current->next->prev = &new_node->entry;
        else
            current->next = &new_node->entry;
        current->prev = &new_node->entry;
    }
}

