#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <chrono>
#include <sstream>

class LogEntry {
public:
    std::time_t timestamp;
    int level;
    char* message;

    LogEntry(std::time_t timestamp, int level, const char* message) : 
        timestamp(timestamp), level(level), message(new char[strlen(message) + 1]) {
            strcpy(message, message);
        }

    ~LogEntry() { delete[] message; }
};

class LogManager {
public:
    std::vector<LogEntry*> logEntries;
    std::mutex lock;

    void addLogEntry(std::time_t timestamp, int level, const char* message) {
        LogEntry* entry = new LogEntry(timestamp, level, message);
        {
            std::lock_guard<std::mutex> guard(lock);
            logEntries.push_back(entry);
        }
    }

    void removeLogEntry(int index) {
        if (index < 0 || index >= logEntries.size()) return;
        {
            std::lock_guard<std::mutex> guard(lock);
            delete logEntries[index];
            logEntries.erase(logEntries.begin() + index);
        }
    }

    void printLogs() {
        for (const auto& entry : logEntries) {
            std::cout << "Timestamp: " << entry->timestamp 
                      << ", Level: " << entry->level 
                      << ", Message: " << entry->message << std::endl;
        }
    }
};

int main() {
    LogManager logger;

    // Example usage:
    for (int i = 0; i < 10; i++) {
        logger.addLogEntry(std::time(nullptr), 1, "This is a log message");
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    logger.printLogs();

    return 0;
}
