    pthread_mutex_t lock; // Mutex for thread safety
    int num_entries; // Number of log entries
    LogEntry** entries; // Array of log entries
    size_t total_size; // Total size of log data in bytes
    double avg_message_len; // Average message length
} LoggingFramework;

// Initialize the logging framework
LoggingFramework* init_logging_framework() {
    LoggingFramework* fw = malloc(sizeof(LoggingFramework));
    fw->num_entries = 0;
    fw->entries = NULL;
    fw->total_size = 0;
    fw->avg_message_len = 0.0;
    pthread_mutex_init(&fw->lock, NULL);
    return fw;
}

// Free the logging framework
void free_logging_framework(LoggingFramework* fw) {
    if (fw == NULL) return;
    for (int i = 0; i < fw->num_entries; i++) {
        free(fw->entries[i]->message);
        free(fw->entries[i]);
    }
    free(fw->entries);
    pthread_mutex_destroy(&fw->lock);
    free(fw);
}

// Insert a new log entry into the framework
void insert_log_entry(LoggingFramework* fw, LogEntry* entry) {
    pthread_mutex_lock(&fw->lock); // Lock for thread safety
    fw->entries = realloc(fw->entries, (fw->num_entries + 1) * sizeof(LogEntry*));
    fw->entries[fw->num_entries] = entry;
    fw->num_entries++;
    if (entry->message != NULL) {
        size_t message_len = strlen(entry->message);
        fw->total_size += message_len + sizeof(time_t) + sizeof(int); // Update total size
        fw->avg_message_len = (fw->total_size / fw->num_entries); // Update average message length
    }
    pthread_mutex_unlock(&fw->lock);
}

