#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MESSAGE_SIZE 4096
#define MAX_ENTRIES 100000

typedef struct LogEntry {
    int timestamp;
    char level;
    char* message;
} LogEntry;

LogEntry* createLogEntry(int timestamp, char level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;

    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = NULL;

    return entry;
}

int addLogEntry(LogEntry** head, int timestamp, char level) {
    LogEntry* newEntry = createLogEntry(timestamp, level);
    if (!newEntry) return -1; // memory allocation failed

    if (*head == NULL || (*head)->timestamp > newEntry->timestamp) {
        newEntry->next = *head;
        *head = newEntry;
    } else {
        LogEntry* current = *head;
        while (current->next && current->next->timestamp >= newEntry->timestamp)
            current = current->next;
        newEntry->next = current->next;
        current->next = newEntry;
    }

    return 0; // successful insertion
}

void freeLogEntry(LogEntry* entry) {
    if (entry->message) free(entry->message);
    free(entry);
}

int printLogs(LogEntry* head, FILE* file, char targetLevel) {
    int count = 0;
    LogEntry* current = head;
    while (current) {
        if (current->level == targetLevel || targetLevel == 'A') { // all levels
            fwrite(current->message, sizeof(char), strlen(current->message), file);
            fputc('\n', file);
            count++;
        }
        current = current->next;
    }
    return count;
}

void destroyLogList(LogEntry** head) {
    LogEntry* current = *head;
    LogEntry* next;

    while (current) {
        next = current->next;
        freeLogEntry(current);
        current = next;
    }

    *head = NULL;
}
