void initHashTable(ResourceConfig** ht, int size) {
    *ht = (ResourceConfig**)malloc(size * sizeof(ResourceConfig*));
    for (int i = 0; i < size; i++) {
        (*ht)[i] = (ResourceConfig*)malloc(sizeof(ResourceConfig));
        (*ht)[i]->key = (char*)malloc(10);
        strcpy((*ht)[i]->key, "default");
        (*ht)[i]->type = INT;
        (*ht)[i]->value = NULL;
    }
}

// Function to iterate over the hash table and convert value
void iterateHashTable(ResourceConfig** ht, int size) {
    for (int i = 0; i < size; i++) {
        switch ((*ht)[i]->type) {
            case INT:
                printf("Key: %s, Value: %d\n", (*ht)[i]->key, *(int*)(*ht)[i]->value);
                break;
            case STRING:
                printf("Key: %s, Value: %s\n", (*ht)[i]->key, (char*)*(void*)((*ht)[i]->value));
                break;
        }
    }
}

// Function to serialize the hash table to a file descriptor
int serializeHashTable(int fd, ResourceConfig** ht, int size) {
    for (int i = 0; i < size; i++) {
        if (!write(fd, (*ht)[i]->key, strlen((*ht)[i]->key))) return -1;
        if (!write(fd, &(*ht)[i]->type, sizeof(enum {INT, STRING}))) return -1;
        if ((*ht)[i]->value) {
            switch ((*ht)[i]->type) {
                case INT:
                    if (!write(fd, (void*)&(*(int*)((*ht)[i]->value)), sizeof(int))) return -1;
                    break;
                case STRING:
                    if (!write(fd, (void*)&((char*)*(void*)((*ht)[i]->value)), strlen((char*)*(void*)((*ht)[i]->value)))) return -1;
                    break;
            }
        }
    }
    return 0;
}

// Function to destroy the hash table
void destroyHashTable(ResourceConfig** ht, int size) {
    for (int i = 0; i < size; i++) {
        free((*ht)[i]->key);
        if ((*ht)[i]->value) free((*ht)[i]->value);
        free((*ht)[i]);
    }
    free(*ht);
}
