#include <pthread.h>

#define MAX_MESSAGE_SIZE 4096
#define LOG_LEVEL_MAX 255

typedef struct LogEntry {
    time_t timestamp;
    int log_level;
    char* message;
    struct LogEntry* next;
    struct LogEntry* prev;
} LogEntry;

LogEntry* init_log_entry(time_t timestamp, int log_level);
void add_log_entry(LogEntry** list_head, time_t timestamp, int log_level, const char* message);
void print_log_entries(LogEntry* list_head, int log_level_filter, int fd);
void destroy_log_entry(LogEntry* entry);

// Function to initialize a LogEntry structure
LogEntry* init_log_entry(time_t timestamp, int log_level) {
    LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!new_entry) {
        printf("Memory allocation failed for log entry.\n");
        return NULL;
    }
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = NULL;

    return new_entry;
}

// Function to add a LogEntry structure to the list
void add_log_entry(LogEntry** list_head, time_t timestamp, int log_level, const char* message) {
    LogEntry* new_entry = init_log_entry(timestamp, log_level);

    if (!new_entry || !message) {
        printf("Error creating or adding log entry.\n");
        return;
    }

    size_t message_len = strlen(message);
    if (message_len > MAX_MESSAGE_SIZE) {
        // Split the message into multiple nodes if necessary
        char* temp_message = (char*)malloc(MAX_MESSAGE_SIZE + 1);
        strncpy(temp_message, message, MAX_MESSAGE_SIZE);
        temp_message[MAX_MESSAGE_SIZE] = '\0';
        new_entry->message = temp_message;
    } else {
        new_entry->message = strdup(message);
    }

    if (!(*list_head)) {
        *list_head = new_entry;
    } else {
        LogEntry* current = *list_head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_entry;
        new_entry->prev = current;
    }
}

// Function to print log entries
void print_log_entries(LogEntry* list_head, int log_level_filter, int fd) {
    LogEntry* current = list_head;

    while (current) {
        if (log_level_filter && current->log_level > log_level_filter) {
            current = current->next;
            continue;
        }

        // Print the log entry
        printf("%ld: %d - %s\n", current->timestamp, current->log_level, current->message);

        current = current->next;
    }
}

// Function to destroy a LogEntry structure
void destroy_log_entry(LogEntry* entry) {
    if (!entry) return;

    if (entry->message) free(entry->message);
    free(entry);
}

// Example usage:
int main() {
    time_t timestamp = time(NULL);
    int log_level = 1;
    const char* message = "This is a test message";

    LogEntry* list_head = NULL;

    add_log_entry(&list_head, timestamp, log_level, message);

    // Print the log entries
    print_log_entries(list_head, log_level, STDOUT_FILENO);

    // Destroy the log entries
    while (list_head) {
        LogEntry* current = list_head;
        list_head = current->next;
        destroy_log_entry(current);
    }

    return 0;
}
