void logToFile(LogEntry** logList, int fileSize) {
    // Iterate over the linked list and write each entry to the file
    for (int i = 0; i < fileSize; i++) {
        LogEntry* currentLogEntry = logList[i];
        // Append the timestamp, log level, and message string to the file
        fwrite(&currentLogEntry->timestamp, sizeof(time_t), 1, stdout);
