        fwrite(currentLogEntry->message, strlen(currentLogEntry->message) + 1, 1, stdout);
    }
}

// Function to manage memory efficiently when the linked list is destroyed
void freeLogList(LogEntry** logList, int fileSize) {
    for (int i = 0; i < fileSize; i++) {
        LogEntry* currentLogEntry = logList[i];
        free(currentLogEntry->message);
        free(logList[i]);
    }
    free(logList);
}

