    (*headRef)->timestamp = time(NULL);
    (*headRef)->logLevel = 1; // Assume log level is 1 for simplicity
    char* message = (char*)malloc(100); // Allocate memory for the message
    sprintf(message, "Initial Log Entry");
    (*headRef)->message = message;

    int maxWeightedSum = 0;
    int transactionId = 0;

    // Iterate over the linked list and print each entry to the file descriptor
    LogEntry* current = *headRef;
    while (current) {
        printf("%s\n", current->message);
        // Filter transactions based on age, number of transactions in the past 3 seconds, and weighted sum
        if (current->timestamp > time(NULL) - 3 && current->weightedSum > maxWeightedSum) {
            maxWeightedSum = current->weightedSum;
            transactionId = current->id;
        }
        current = current->next;
    }

    // Free allocated memory when the linked list is destroyed
    while (*headRef) {
        LogEntry* temp = *headRef;
        *headRef = (*headRef)->next;
        free(temp->message);
        free(temp);
    }

    return transactionId;
}
