// Function to initialize the ring buffer
RingBuffer* ring_buffer_init(int size) {
    RingBuffer* rb = (RingBuffer*)malloc(sizeof(RingBuffer));
    rb->size = size;
    rb->start = 0;
    rb->end = 0;
    rb->data = (void**)calloc(size, sizeof(void*));
    return rb;
}

// Function to free the ring buffer
void ring_buffer_free(RingBuffer* rb) {
