#include <openssl/aes.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    uint8_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generateNFAPCRandomCRCIndications(int numIndications, NFAPI_CRC_INDICATION_PDU_T **indications) {
    *indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < numIndications; i++) {
        (*indications)[i].RX_UE_INFORMATION_TAG = rand() % 100;
        (*indications)[i].RNTI = (uint8_t)rand();
        (*indications)[i].CRC_INDICATION_REL8_TAG = rand() % 65536;
        (*indications)[i].CRCFLAG = rand() % 2;
    }

    for (int i = 0; i < numIndications; i++) {
        if (!encryptNFAPI_CRC_INDICATION_PDU_T((*indications) + i, "your_encryption_key", "your_initialization_vector")) {
            free(*indications);
            *indications = NULL;
            return;
        }
    }
}

int encryptNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T *pdu, const char *key, const char *iv) {
    int blockSize = AES_BLOCK_SIZE;
    int keySize = strlen(key);
    int ivSize = strlen(iv);

    // Pad data
    int paddedDataLen = blockSize - (sizeof(int) + sizeof(uint16_t));
    uint8_t *paddedData = (uint8_t *)malloc(paddedDataLen);
    memcpy(paddedData, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < paddedDataLen; i++) {
        paddedData[i] = (uint8_t)(i % 256);
    }

    // Encrypt
    AES_KEY keyStruct;
    EVP_BytesToKey(&keyStruct, EVP_aes_256_cbc(), NULL, (const unsigned char *)key, strlen(key), (unsigned char *)"SaltValue", &keySize);

    unsigned char *encryptedData = malloc(blockSize + paddedDataLen);
    memcpy(encryptedData, iv, ivSize);
    memcpy(encryptedData + ivSize, paddedData, paddedDataLen);

    EVP_EncryptInit_ex(&keyStruct, EVP_aes_256_cbc(), NULL, encryptedData + ivSize, (unsigned char *)iv);
    EVP_EncryptUpdate(&keyStruct, encryptedData + ivSize, &paddedDataLen, paddedData, paddedDataLen);
    EVP_EncryptFinal_ex(&keyStruct, encryptedData + ivSize + paddedDataLen, &paddedDataLen);

    // Clean up
    free(paddedData);
    free(encryptedData);

    return 1;
}
