// Define a struct to hold file metadata and hashes
struct FileMetadata {
    std::string path;
    std::string dstAddress;
    int compressionLevel;
    std::string md5Hash;
    std::string sha256Hash;
};

// Define a function to transfer files
std::unordered_map<std::string, std::string> transferFiles(
    const std::vector<FileMetadata>& files,
    const std::string& dstAddress,
    int compressionLevel
) {
    // Initialize an unordered map to store file metadata and hashes
    std::unordered_map<std::string, FileMetadata> results;

    // Create a thread pool with concurrent reads and writes
    std::thread pool[10]; // Assume 10 threads for concurrent operations

    // Initialize a queue for transfer requests
    std::queue<FileMetadata*> transferQueue;

    // Add files to the transfer queue
    for (const auto& file : files) {
        transferQueue.push(&file);
    }

    // Start transferring files concurrently
    while (!transferQueue.empty()) {
        FileMetadata* file = transferQueue.front();
        transferQueue.pop();

        // Transfer the file using concurrent read and write operations
        pool[0].join(); // Assume the thread is available for reuse

        // Store the transferred file metadata and hashes in the results map
        results[file->path] = *file;
    }

    return results;
}

int main() {
    // Define a list of files to transfer
    std::vector<FileMetadata> files = {
        {"source/file1.txt", "destination-server-1", 6},
        {"source/file2.txt", "destination-server-2", 4},
        {"source/file3.txt", "destination-server-3", 5}
    };

    // Transfer the files with compression level 5
    std::unordered_map<std::string, std::string> results = transferFiles(files, "destination-server-all", 5);

    // Print the transferred file metadata and hashes
    for (const auto& pair : results) {
        std::cout << "File: " << pair.first << ", MD5 Hash: " << pair.second.md5Hash << ", SHA-256 Hash: " << pair.second.sha256Hash << std::endl;
    }

    return 0;
}

