#define MAX_LOG_ENTRIES 10000000
#define GARbage_COLLECTION_INTERVAL 60 // seconds

typedef struct LogEntry {
    int timestamp;
    char log_level;
    char* message;
} LogEntry;

typedef struct DoublyLinkedListNode {
    LogEntry* entry;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

DoublyLinkedListNode* doubly_linked_list = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int log_entry_count = 0;
size_t total_log_data_size = 0;
size_t average_message_length = 0;

void init_doubly_linked_list() {
    doubly_linked_list = malloc(sizeof(DoublyLinkedListNode));
    doubly_linked_list->prev = NULL;
    doubly_linked_list->next = NULL;
}

void free_doubly_linked_list() {
    DoublyLinkedListNode* temp = doubly_linked_list;
    while (temp) {
        DoublyLinkedListNode* next = temp->next;
        free(temp);
        temp = next;
    }
    doubly_linked_list = NULL;
}

LogEntry* insert_log_entry(int timestamp, char log_level) {
    LogEntry* entry = malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = strdup("Initial message");
    pthread_mutex_lock(&lock);
    DoublyLinkedListNode* new_node = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    new_node->entry = entry;
    if (!doubly_linked_list) {
        doubly_linked_list = new_node;
    } else {
        new_node->next = doubly_linked_list;
        doubly_linked_list->prev = new_node;
        doubly_linked_list = new_node;
    }
    log_entry_count++;
    total_log_data_size += strlen(entry->message) + 1;
    average_message_length = (total_log_data_size - (log_entry_count-1)*sizeof(LogEntry)) / log_entry_count;
    pthread_mutex_unlock(&lock);
    return entry;
}

void delete_log_entry(LogEntry* entry) {
    pthread_mutex_lock(&lock);
    DoublyLinkedListNode* current = doubly_linked_list;
    while (current && current->entry != entry)
        current = current->next;
    if (!current) {
        // Entry not found
        return;
    }
    if (current->prev) {
        current->prev->next = current->next;
    } else {
        doubly_linked_list = current->next;
    }
    if (current->next) {
        current->next->prev = current->prev;
    } else {
        doubly_linked_list = current->prev;
    }
    free(entry->message);
    free(entry);
    log_entry_count--;
    total_log_data_size -= strlen(entry->message) + 1;
    average_message_length = (total_log_data_size - (log_entry_count-1)*sizeof(LogEntry)) / log_entry_count;
    pthread_mutex_unlock(&lock);
}

void print_log_entries(int fd) {
    pthread_mutex_lock(&lock);
    DoublyLinkedListNode* current = doubly_linked_list;
    while (current) {
        fwrite(current->entry, sizeof(LogEntry), 1, fd);
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void garbage_collection() {
    // Implement logic to periodically reclaim unused memory within the list
}

void serialize_log_entries(char* file_path) {
    // Implement logic to serialize log entries to a binary format for persistence
}

void deserialize_log_entries(char* file_path) {
    // Implement logic to deserialize log entries from a binary format
