['Here is the C function to initialize a doubly-linked list of `LogEntry` structures:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the LogEntry structure
typedef struct {
    int timestamp;
    char level;
    char* message;
} LogEntry;

// Function to initialize a doubly-linked list of LogEntries
void init_log_list(LogEntry** head, size_t capacity) {
    *head = (LogEntry**)malloc(sizeof(LogEntry*) * capacity);
    for(size_t i = 0; i < capacity; i++) {
        (*head)[i] = NULL;
    }
}

// Function to add a new LogEntry to the list
void add_log_entry(LogEntry** head, size_t* size, LogEntry* entry) {
    // Allocate memory for the new entry if necessary
    if(*size >= *size + 1) {
        size_t new_capacity = (*size + 1) * 2;
        LogEntry** new_head = (LogEntry**)realloc(*head, sizeof(LogEntry*) * new_capacity);
        for(size_t i = *size; i < new_capacity; i++) {
            new_head[i] = NULL;
        }
        *head = new_head;
    }

    // Add the new entry to the end of the list
    (*head)[*size] = entry;
    (*size)++;
}

// Function to free the LogEntry and its message
void free_log_entry(LogEntry* entry) {
    if(entry->message != NULL) {
        free((char*)entry->message);
        entry->message = NULL;
    }
}

// Function to free the entire log list
void free_log_list(LogEntry** head, size_t size) {
    for(size_t i = 0; i < size; i++) {
        if((*head)[i] != NULL) {
            free_log_entry((*head)[i]);
            free((LogEntry*)*head[i]);
        }
    }
    free(*head);
}
