import threading
from collections import defaultdict

class VersionControlSystem:
    def __init__(self):
        self.entries = []
        self.lock = threading.Lock()
        self.stats = {"count": 0, "size": 0, "avg_size": 0}

    def add_entry(self, entry):
        with self.lock:
            self.entries.append(entry)
            self.stats["count"] += 1
            if entry.payload_size > 0:
                self.stats["size"] += entry.payload_size
                self.stats["avg_size"] = self.stats["size"] / len(self.entries)

    def get_entries(self):
        with self.lock:
            return self.entries[:]

    def remove_entry(self, commit_id):
        with self.lock:
            for entry in self.entries:
                if entry.commit_id == commit_id:
                    self.entries.remove(entry)
                    break

    def compute_hashes(self):
        hash_dict = defaultdict(dict)

        for entry in self.entries:
            try:
                md5_hash = self.compute_md5_hash(entry.payload)
                sha256_hash = self.compute_sha256_hash(entry.payload)
                hash_dict[entry.commit_id] = {"md5": md5_hash, "sha256": sha256_hash}
            except Exception as e:
                print(f"Error computing hashes for {entry.commit_id}: {str(e)}")

        return hash_dict

    def compute_md5_hash(self, payload):
        with open(payload, "rb") as f:
            chunk_size = 4096
