#include <iostream>
#include <queue>
#include <map>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>

using namespace std;

class Message {
public:
    int id;
    long long timestamp;
    int senderId;
    int recipientId;
    int priority;
    shared_ptr<char[]> payload;

    // constructor
    Message(int id, long long timestamp, int senderId, int recipientId, int priority, shared_ptr<char[]> payload)
        : id(id), timestamp(timestamp), senderId(senderId), recipientId(recipientId), priority(priority), payload(payload) {}
};

class MessageBroker {
public:
    queue<Message> messages;
    map<int, condition_variable> subscriberCVs;

    void publishMessage(Message message) {
        // Publish the message
        messages.push(message);

        // Notify all subscribers that a new message is available
        notifySubscribers();
    }

    void subscribe(int recipientId) {
        auto it = subscriberCVs.find(recipientId);
        if (it == subscriberCVs.end()) {
            condition_variable cv;
            subscriberCVs[recipientId] = cv;
            cv.wait_for(chrono::milliseconds(0));
        }
    }

    void unsubscribe(int recipientId) {
        // Remove the subscription
        subscriberCVs.erase(recipientId);
    }

    void receiveMessages() {
        while (true) {
            Message message = messages.front();
            messages.pop();

            // Notify all subscribers that a new message is available
            notifySubscribers(message);

            this_thread::sleep_for(chrono::milliseconds(100));
        }
    }

    void notifySubscribers(Message message = Message{}) {
        for (auto& subscriber : subscriberCVs) {
            subscriber.second.notify_all();
        }
    }
};

int main() {
    MessageBroker broker;

    // Start receiving messages
    thread receiverThread(&MessageBroker::receiveMessages, &broker);

    // Publish some sample messages
    vector<Message> messages = {};
    for (int i = 0; i < 10000; i++) {
        Message message(i, chrono::system_clock::now().time_since_epoch().count(), i + 1, i + 2, i % 10, make_shared<char[]>(i));
        broker.publishMessage(message);
    }

    // Wait for the receiver thread to finish
    receiverThread.join();

    return 0;
}
