#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LogEntry
typedef struct {
    int timestamp;
    int log_level;
    char* message;
} LogEntry;

// Define the doubly-linked list node
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the linked list
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} LinkedList;

// Function to initialize the linked list
LinkedList* init_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to insert a new node into the linked list
void insert_node(LinkedList* list, LogEntry entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->entry = entry;
    new_node->prev = NULL;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }

    pthread_mutex_unlock(&list->lock);
}

// Function to print all entries in the linked list
void print_entries(LinkedList* list, int fd) {
    Node* current = list->head;

    while (current != NULL) {
        char message[256];
        sprintf(message, "%d: %s\n", current->entry.timestamp, current->entry.message);
        write(fd, message, strlen(message));
        current = current->next;
    }
}

// Function to free the linked list
void free_linked_list(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(list);
}

// Function to garbage collect unused memory
void gc_unused_memory(LinkedList* list) {
    // implement garbage collection logic here
}

// Function to serialize the linked list to a file
int serialize_linked_list(LinkedList* list, FILE* file) {
    Node* current = list->head;

    while (current != NULL) {
        fwrite(&current->entry.timestamp, sizeof(int), 1, file);
        fwrite(&current->entry.log_level, sizeof(int), 1, file);
        size_t message_len = strlen(current->entry.message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(current->entry.message, sizeof(char), message_len + 1, file);
        current = current->next;
    }

    return 0;
}

// Function to deserialize the linked list from a file
int deserialize_linked_list(LinkedList* list, FILE* file) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    int timestamp;
    int log_level;

    while (fread(&timestamp, sizeof(int), 1, file) == 1 && fread(&log_level, sizeof(int), 1, file) == 1) {
        size_t message_len;
        char* message = malloc(message_len + 1);
        fread(&message_len, sizeof(size_t), 1, file);
        fread(message, sizeof(char), message_len + 1, file);

        new_node->entry.timestamp = timestamp;
        new_node->entry.log_level = log_level;
        new_node->entry.message = message;

        if (list->head == NULL) {
            list->head = new_node;
            list->tail = new_node;
        } else {
            list->tail->next = new_node;
            new_node->prev = list->tail;
            list->tail = new_node;
        }
    }

    free(new_node);

    return 0;
}

// Function to load the log history from a file
int load_log_history(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "rb");

    if (file == NULL)
        return -1;

    deserialize_linked_list(list, file);

    fclose(file);

    return 0;
}

// Function to save the log history to a file
int save_log_history(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file == NULL)
        return -1;

    serialize_linked_list(list, file);

    fclose(file);

    return 0;
}

// Function to print statistics about the linked list
void print_stats(LinkedList* list) {
    Node* current = list->head;

    int entry_count = 0;
    size_t total_size = 0;
    double average_message_length = 0.0;

    while (current != NULL) {
        entry_count++;
        total_size += strlen(current->entry.message);
        current = current->next;
    }

    printf("Entry count: %d\n", entry_count);
    printf("Total size: %zu bytes\n", total_size);
    printf("Average message length: %.2f characters\n", (double)total_size / entry_count);
}

// Function to monitor the linked list's performance
void monitor_performance(LinkedList* list) {
    // implement monitoring logic here
}
