#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a LogEntry
typedef struct {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Define the structure for a doubly-linked list node
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the structure for a doubly-linked list
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
    int totalSize;
} LinkedList;

// Function to initialize the linked list
LinkedList* initLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->totalSize = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new LogEntry to the linked list
void addLogEntry(LinkedList* list, time_t timestamp, int logLevel, char* message) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->entry = (LogEntry*)malloc(sizeof(LogEntry));
    newNode->entry->timestamp = timestamp;
    newNode->entry->logLevel = logLevel;
    newNode->entry->message = (char*)malloc(strlen(message)+1);
    strcpy(newNode->entry->message, message);

    pthread_mutex_lock(&list->lock);
    if(list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        newNode->prev = list->tail;
        newNode->next = NULL;
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;
    list->totalSize += strlen(message) + 1;
    pthread_mutex_unlock(&list->lock);
}

// Function to free the linked list
void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    while(current != NULL) {
        Node* next = current->next;
        free(current->entry->message);
        free(current->entry);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to iterate over the linked list and print log entries
void printLogEntries(LinkedList* list, int fileDescriptor) {
    Node* current = list->head;
    while(current != NULL) {
        printf("%ld %d %s\n", current->entry->timestamp, current->entry->logLevel, current->entry->message);
        fflush(stdout);
        write(fileDescriptor, current->entry->message, strlen(current->entry->message)+1);
        current = current->next;
    }
}

// Function to serialize the linked list to a file
void serializeLinkedList(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");
    Node* current = list->head;
    while(current != NULL) {
        LogEntry* entry = current->entry;
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        fwrite(&entry->logLevel, sizeof(int), 1, file);
        int messageLength = strlen(entry->message) + 1;
        fwrite(&messageLength, sizeof(int), 1, file);
        fwrite(entry->message, messageLength, 1, file);
        current = current->next;
    }
    fclose(file);
}

// Function to deserialize the linked list from a file
void deserializeLinkedList(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "rb");
    Node* current = NULL;
    while(fread(&entry->timestamp, sizeof(time_t), 1, file) == 1) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->entry = (LogEntry*)malloc(sizeof(LogEntry));
        newNode->entry->logLevel = fread(&newNode->entry->logLevel, sizeof(int), 1, file);
        int messageLength = fread(&messageLength, sizeof(int), 1, file);
        newNode->entry->message = (char*)malloc(messageLength+1);
        fread(newNode->entry->message, messageLength, 1, file);
        if(current == NULL) {
            list->head = newNode;
            list->tail = newNode;
        } else {
            current->next = newNode;
            newNode->prev = current;
            list->tail = newNode;
        }
        current = newNode;
    }
    fclose(file);
}

// Function to calculate statistics about the linked list
void calculateStatistics(LinkedList* list) {
    list->totalSize += strlen(message)+1;
    int totalEntries = 0;
    for(Node* current = list->head; current != NULL; current = current->next) {
        totalEntries++;
    }
}

// Function to integrate with an external event processing service
void processEvents(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");
    Node* current = list->head;
    while(current != NULL) {
        LogEntry* entry = current->entry;
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        fwrite(&entry->logLevel, sizeof(int), 1, file);
        int messageLength = strlen(entry->message) + 1;
        fwrite(&messageLength, sizeof(int), 1, file);
        fwrite(entry->message, messageLength, 1, file);
        current = current->next;
    }
    fclose(file);

    // Process events asynchronously
    pthread_t thread;
    pthread_create(&thread, NULL, processEventsAsync, (void*)list);
    pthread_join(thread, NULL);
}

// Function to process events asynchronously
void* processEventsAsync(void* arg) {
