void* nfaPool = NULL;
size_t nfaPoolSize = 0;
size_t nfaPoolUsed = 0;

NFAPI_CRC_INDICATION_PDU_T* createNFAPI_CRC_INDICATION_PDU(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* nfa = (NFAPI_CRC_INDICATION_PDU_T*)malloc(1);
    if (!nfa) return NULL;

    // ... initialize other fields ...
    nfa->RNTI = RNTI;

    return nfa;
}

void destroyNFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* nfa) {
    free(nfa);
}

int verifyNFAPI_CRC_INDICATION_PDU(NFAPI_CRC_INDICATION_PDU_T* nfa) {
    // ... check the integrity of the structure ...
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T** createAndPopulateNFAPList(int N, int* pSize) {
    *pSize = 0;

    if (nfaPool == NULL || nfaPoolUsed + N > nfaPoolSize) {
        size_t newSize = (nfaPool ? nfaPoolSize : 1);
        while ((newSize & (newSize - 1)) != 0) newSize <<= 1; // next power of 2
        void* newPool = realloc(nfaPool, newSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newPool) return NULL;

        nfaPool = newPool;
        nfaPoolSize = newSize;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)&nfaPool[nfaPoolUsed];
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* nfa = createNFAPI_CRC_INDICATION_PDU(rand());

        // Ensure RNTI values are unique
        while (findRNTI(list, *pSize, nfa->RNTI)) {
            destroyNFAPI_CRC_INDICATION_PDU(nfa);
            nfa = createNFAPI_CRC_INDICATION_PDU(rand());
        }

        list[*pSize] = nfa;
        (*pSize)++;
    }

    return list;
}

int findRNTI(NFAPI_CRC_INDICATION_PDU_T** list, int size, int RNTI) {
    for (int i = 0; i < size; ++i) {
        if (list[i]->RNTI == RNTI) return 1;
    }
    return 0;
}

// Helper function to verify the integrity of the generated structures
void verifyNFAPList(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    for (int i = 0; i < size; ++i) {
        if (verifyNFAPI_CRC_INDICATION_PDU(list[i])) return;
    }
}

// Example usage:
