    int N = 1000;
    int* pSize = &pSize;

    NFAPI_CRC_INDICATION_PDU_T** NFAPList = createAndPopulateNFAPList(N, pSize);

    if (NFAPList) {
        verifyNFAPList(NFAPList, *pSize);

        // Use the generated list...
        for (int i = 0; i < *pSize; ++i) {
            printf("%d ", NFAPList[i]->RNTI);
        }
        printf("\n");
    } else {
