void append(Node** head, LogEntry entry) {
    if (*head == NULL) {
        *head = malloc(sizeof(Node));
        (*head)->prev = NULL;
        (*head)->next = NULL;
        (*head)->entry.timestamp = entry.timestamp;
        (*head)->entry.logLevel = entry.logLevel;
        (*head)->entry.message = malloc(strlen(entry.message) + 1);
        strcpy((*head)->entry.message, entry.message);
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        Node* newNode = malloc(sizeof(Node));
        newNode->prev = current;
        newNode->next = NULL;
        newNode->entry.timestamp = entry.timestamp;
        newNode->entry.logLevel = entry.logLevel;
        newNode->entry.message = malloc(strlen(entry.message) + 1);
        strcpy(newNode->entry.message, entry.message);
        current->next = newNode;
    }
}

void prepend(Node** head, LogEntry entry) {
    if (*head == NULL) {
        *head = malloc(sizeof(Node));
        (*head)->prev = NULL;
        (*head)->next = NULL;
        (*head)->entry.timestamp = entry.timestamp;
        (*head)->entry.logLevel = entry.logLevel;
        (*head)->entry.message = malloc(strlen(entry.message) + 1);
        strcpy((*head)->entry.message, entry.message);
    } else {
        Node* newNode = malloc(sizeof(Node));
        newNode->prev = NULL;
        newNode->next = *head;
        newNode->entry.timestamp = entry.timestamp;
        newNode->entry.logLevel = entry.logLevel;
        newNode->entry.message = malloc(strlen(entry.message) + 1);
        strcpy(newNode->entry.message, entry.message);
        (*head)->prev = newNode;
        *head = newNode;
    }
}

void insertAfter(Node* prev, LogEntry entry) {
    Node* newNode = malloc(sizeof(Node));
    newNode->prev = prev;
    newNode->next = prev->next;
    newNode->entry.timestamp = entry.timestamp;
    newNode->entry.logLevel = entry.logLevel;
    newNode->entry.message = malloc(strlen(entry.message) + 1);
    strcpy(newNode->entry.message, entry.message);
    if (newNode->next != NULL)
        newNode->next->prev = newNode;
    else
        prev->next = newNode;
    prev->next = newNode;
}

LogEntry* searchByTimestamp(Node* head, time_t timestamp) {
    Node* current = head;
    while (current != NULL) {
        if (current->entry.timestamp == timestamp)
            return &current->entry;
        current = current->next;
    }
    return NULL;
}

LogEntry* searchByLogLevel(Node* head, int logLevel) {
    Node* current = head;
    while (current != NULL) {
        if (current->entry.logLevel == logLevel)
            return &current->entry;
        current = current->next;
    }
    return NULL;
}

void removeOlderThan(time_t timestamp) {
    // Remove entries older than the given timestamp
}

void writeEntriesToFile(int fd, Node* head) {
    // Write all entries to a file descriptor
}

Node* reverseList(Node* head) {
    Node* current = head;
    Node* previous = NULL;
    while (current != NULL) {
        Node* nextTemp = current->next;
        current->next = previous;
        previous = current;
        current = nextTemp;
    }
    return previous;
