#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Define a structure to represent a log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define a structure to represent a doubly-linked list node
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Initialize the doubly-linked list
void initList(Node** head) {
    *head = NULL;
}

// Insert a new log entry at the beginning of the list
void insertEntry(Node** head, LogEntry* entry) {
    Node* newNode = malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->prev = NULL;
    newNode->next = *head;
    if (*head != NULL)
        (*head)->prev = &newNode->next;
    else
        newNode->next = NULL;
    *head = newNode;
}

// Remove all entries older than 7 days and compact the list
void compactList(Node** head) {
    time_t now = time(NULL);
    Node* current = *head, *prev = NULL;
    while (current != NULL) {
        if ((now - current->entry->timestamp) > 7*24*60*60) {
            prev = current;
            current = current->next;
            free(current->entry->message);
            free(current->entry);
            free(current);
        } else {
            prev = current;
            current = current->next;
        }
    }
    if (prev == NULL)
        *head = NULL;
    else
        prev->next = NULL;
}

// Search for log entries based on timestamp or log level
LogEntry* searchList(Node* head, int targetLevel, time_t targetTimestamp) {
    Node* current = head;
    while (current != NULL) {
        if ((current->entry->level == targetLevel && current->entry->timestamp == targetTimestamp) ||
            (targetLevel == -1 && targetTimestamp == -1)) {
            return current->entry;
        }
        current = current->next;
    }
    return NULL;
}

// Print the log entries in the list
void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%ld: %d - %s\n", current->entry->timestamp, current->entry->level, current->entry->message);
        current = current->next;
    }
}

// Main function to demonstrate the doubly-linked list
int main() {
    Node* head = NULL;

    // Initialize and populate the list with log entries
    initList(&head);
    for (int i = 0; i < 10000; i++) {
        LogEntry* entry = malloc(sizeof(LogEntry));
        entry->timestamp = time(NULL);
        entry->level = rand() % 3;
        asprintf(&entry->message, "Log message %d", i);
        insertEntry(&head, entry);
    }

    // Compact the list to remove entries older than 7 days
    compactList(&head);

    // Search for log entries based on timestamp or log level
    LogEntry* target = searchList(head, 1, time(NULL) - 24*60*60);
    if (target != NULL)
        printf("Found entry: %ld, Level: %d\n", target->timestamp, target->level);

    // Print the updated list of log entries
    printList(head);

    return 0;
}
