['Here is the C code for the doubly-linked list of LogEntry structures:
```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    int log_level;
    char *message;
} LogEntry;

typedef struct Node {
    LogEntry *entry;
    struct Node *prev;
    struct Node *next;
} Node;

typedef struct DoublyLinkedList {
    Node *head;
    Node *tail;
    pthread_mutex_t mutex;
} DoublyLinkedList;

DoublyLinkedList *create_list();
void insert_entry(DoublyLinkedList *, LogEntry *);
LogEntry *remove_entry(DoublyLinkedList *, time_t);
void print_entries(DoublyLinkedList *, int (*)(const char *));
void destroy_list(DoublyLinkedList *);

DoublyLinkedList *create_list() {
    DoublyLinkedList *list = (DoublyLinkedList *)malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void insert_entry(DoublyLinkedList *list, LogEntry *entry) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->next = list->head;
        list->head->prev = node;
        list->head = node;
    }

    pthread_mutex_unlock(&list->mutex);
}

LogEntry *remove_entry(DoublyLinkedList *list, time_t timestamp) {
    Node *node = list->head;

    while (node != NULL) {
        if (node->entry->timestamp == timestamp) {
            LogEntry *entry = node->entry;
            if (node->prev != NULL) {
                node->prev->next = node->next;
            } else {
                list->head = node->next;
            }
            if (node->next != NULL) {
                node->next->prev = node->prev;
            } else {
                list->tail = node->prev;
            }
            free(node);
            return entry;
        }
        node = node->next;
    }

    return NULL;
}

void print_entries(DoublyLinkedList *list, int (*callback)(const char *)) {
    Node *node = list->head;

    while (node != NULL) {
        callback(node->entry->message);
        node = node->next;
    }
}

void destroy_list(DoublyLinkedList *list) {
    Node *node = list->head;

    while (node != NULL) {
        LogEntry *entry = node->entry;
        free(entry->message);
        free(node);
        node = node->next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}
