['Here's an example code block in C that implements a robust logging framework:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the log entry structure
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define the doubly-linked list node structure
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the logging framework structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    int num_nodes;
    char** nodes;
} LoggingFramework;

// Function to create a new log entry
LogEntry* create_log_entry(time_t timestamp, int level, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);
    return entry;
}

// Function to add a log entry to the list
void add_log_entry(LoggingFramework* framework, LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;

    if (framework->head == NULL) {
        framework->head = node;
        framework->tail = node;
    } else {
        node->prev = framework->tail;
        node->next = NULL;
        framework->tail->next = node;
        framework->tail = node;
    }

    pthread_mutex_unlock(&framework->mutex);
}

// Function to remove a log entry from the list
void remove_log_entry(LoggingFramework* framework, LogEntry* entry) {
    Node* node = framework->head;
    while (node != NULL && node->entry != entry) {
        node = node->next;
    }

    if (node == NULL) {
        // Entry not found in the list
        return;
    }

    if (node->prev == NULL) {
        // Entry is at the head of the list
        framework->head = node->next;
    } else {
        node->prev->next = node->next;
    }

    if (node->next == NULL) {
        // Entry is at the tail of the list
        framework->tail = node->prev;
    } else {
        node->next->prev = node->prev;
    }

    free(node);
}

// Function to print the log entries in the list
void print_log_entries(LoggingFramework* framework) {
    Node* node = framework->head;
    while (node != NULL) {
        LogEntry* entry = node->entry;
        printf("Timestamp: %ld, Level: %d, Message: %s\n", entry->timestamp, entry->level, entry->message);
        node = node->next;
    }
}

// Function to create a new logging framework
LoggingFramework* create_logging_framework(int num_nodes) {
    LoggingFramework* framework = (LoggingFramework*)malloc(sizeof(LoggingFramework));
    framework->head = NULL;
    framework->tail = NULL;
    pthread_mutex_init(&framework->mutex, NULL);
    framework->num_nodes = num_nodes;
    framework->nodes = (char**)malloc(sizeof(char*) * num_nodes);
    for (int i = 0; i < num_nodes; i++) {
        framework->nodes[i] = (char*)malloc(1024);
    }
    return framework;
}

// Function to free the logging framework
void free_logging_framework(LoggingFramework* framework) {
    Node* node = framework->head;
    while (node != NULL) {
        LogEntry* entry = node->entry;
        free(entry->message);
        free(node);
        node = node->next;
    }
    for (int i = 0; i < framework->num_nodes; i++) {
        free(framework->nodes[i]);
    }
    free(framework->nodes);
    pthread_mutex_destroy(&framework->mutex);
    free(framework);
}
