['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <pthread.h>

typedef struct {
    char* key;
    void* value;
    time_t expiration;
    int referenceCount;
} Entry;

typedef struct {
    Entry** entries;
    int size;
    pthread_mutex_t mutex;
} Cache;

Cache* cache_create(int capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->entries = (Entry**)calloc(capacity, sizeof(Entry*));
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

void cache_free(Cache* cache) {
    for (int i = 0; i < cache->size; i++) {
        free(cache->entries[i]->key);
        free(cache->entries[i]->value);
        free(cache->entries[i]);
    }
    free(cache->entries);
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

void* cache_insert(Cache* cache, const char* key, void* value, time_t expiration) {
    // Find an available slot
    int index = -1;
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i]->expiration == 0 || cache->entries[i]->expiration > time(NULL)) {
            index = i;
            break;
        }
    }

    // Evict an entry if necessary
    if (index == -1 && cache->size >= cache->size * 3 / 4) {
        pthread_mutex_lock(&cache->mutex);
        for (int i = 0; i < cache->size; i++) {
            if (cache->entries[i]->expiration <= time(NULL)) {
                free(cache->entries[i]->key);
                free(cache->entries[i]->value);
                free(cache->entries[i]);
                memmove(&cache->entries[i], &cache->entries[i + 1], sizeof(Entry*) * (cache->size - i - 1));
                cache->size--;
            }
        }
        pthread_mutex_unlock(&cache->mutex);
    }

    // Insert the new entry
    if (index == -1) {
        index = cache->size++;
        cache->entries[index] = (Entry*)malloc(sizeof(Entry));
        cache->entries[index]->key = strdup(key);
        cache->entries[index]->value = value;
        cache->entries[index]->expiration = expiration;
        cache->entries[index]->referenceCount = 1;
    } else {
        Entry* entry = cache->entries[index];
        entry->value = value;
        entry->expiration = expiration;
        entry->referenceCount++;
    }

    return value;
}

void cache_remove(Cache* cache, const char* key) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->entries[i]->key, key) == 0) {
            free(cache->entries[i]->key);
            free(cache->entries[i]->value);
            free(cache->entries[i]);
            memmove(&cache->entries[i], &cache->entries[i + 1], sizeof(Entry*) * (cache->size - i - 1));
            cache->size--;
            return;
        }
    }
}

void* cache_get(Cache* cache, const char* key) {
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->entries[i]->key, key) == 0 && cache->entries[i]->expiration > time(NULL)) {
            Entry* entry = cache->entries[i];
            entry->referenceCount++;
            return entry->value;
        }
    }
    return NULL;
}

void cache_flush(Cache* cache) {
    for (int i = 0; i < cache->size; i++) {
        free(cache->entries[i]->key);
        free(cache->entries[i]->value);
        free(cache->entries[i]);
    }
    cache->size = 0;
}
