#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int ue_id;
    int *flow_ids;
    int flow_id_count;
    time_t last_modified;
} SessionContext;

SessionContext **session_list = NULL;
int session_count = 0;

// Function to add a new session
void add_session(int ue_id, int *flow_ids, int flow_id_count) {
    SessionContext *new_session = (SessionContext *)malloc(sizeof(SessionContext));
    new_session->ue_id = ue_id;
    new_session->flow_id_count = flow_id_count;
    new_session->flow_ids = (int *)malloc(flow_id_count * sizeof(int));
    memcpy(new_session->flow_ids, flow_ids, flow_id_count * sizeof(int));
    new_session->last_modified = time(NULL);

    session_list = (SessionContext **)realloc(session_list, (session_count + 1) * sizeof(SessionContext *));
    session_list[session_count] = new_session;
    session_count++;
}

// Function to update an existing session
void update_session(int ue_id, int *flow_ids, int flow_id_count) {
    for (int i = 0; i < session_count; i++) {
        if (session_list[i]->ue_id == ue_id) {
            free(session_list[i]->flow_ids);
            session_list[i]->flow_id_count = flow_id_count;
            session_list[i]->flow_ids = (int *)malloc(flow_id_count * sizeof(int));
            memcpy(session_list[i]->flow_ids, flow_ids, flow_id_count * sizeof(int));
            session_list[i]->last_modified = time(NULL);
            return;
        }
    }
}

// Function to retrieve a session
SessionContext *get_session(int ue_id) {
    for (int i = 0; i < session_count; i++) {
        if (session_list[i]->ue_id == ue_id) {
            return session_list[i];
        }
    }
    return NULL;
}

// Function to prune old sessions
void prune_sessions() {
    time_t current_time = time(NULL);
    for (int i = 0; i < session_count; i++) {
        if ((current_time - session_list[i]->last_modified) > 3600) { // Prune sessions older than 1 hour
            free(session_list[i]->flow_ids);
            free(session_list[i]);
            session_list[i] = NULL;
            for (int j = i; j < session_count - 1; j++) {
                session_list[j] = session_list[j + 1];
            }
            session_count--;
        }
    }
}

// Function to handle concurrent access
void *access_session(void *arg) {
    int ue_id = *(int *)arg;
    SessionContext *session = get_session(ue_id);
    if (session == NULL) {
        printf("Session not found: %d\n", ue_id);
    } else {
        // Handle the session here
        printf("Session found: %d, last modified at: %s\n", ue_id, ctime(&session->last_modified));
    }
    free(arg);
    return NULL;
}

int main() {
    int thread_ids[5] = {1, 2, 3, 4, 5};
    for (int i = 0; i < 5; i++) {
        pthread_create(NULL, NULL, access_session, &thread_ids[i]);
    }
    sleep(1);
    prune_sessions();
    return 0;
}
