#include <string.h>

typedef struct {
    int timestamp;
    char log_level;
    char* message;
} LogEntry;

void init_linked_list(LogEntry** head, FILE* file) {
    *head = NULL;
    char line[1024];
    while(fgets(line, 1024, file)) {
        LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
        if(new_entry == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }
        // Parse the line to extract necessary fields
        char* token = strtok(line, " ");
        new_entry->timestamp = atoi(token);
        token = strtok(NULL, " ");
        new_entry->log_level = *token;
        token = strtok(NULL, "\n");
        size_t message_len = strlen(token) + 1; // add null terminator
        new_entry->message = (char*)malloc(message_len);
        strcpy(new_entry->message, token);
        if(*head == NULL) {
            *head = new_entry;
        } else {
            LogEntry* current = *head;
            while(current->next != NULL) {
                current = current->next;
            }
            current->next = new_entry;
        }
    }
}

void process_linked_list(LogEntry* head, int fd) {
    if(head == NULL) return;
    double total_sum = 0.0;
    LogEntry* current = head;
    while(current != NULL) {
        // Find the last two numeric fields in each message string
        char* token = strtok(current->message, " ");
        double num1 = atof(token);
        token = strtok(NULL, " ");
        double num2 = atof(token);
        total_sum += (num1 + num2);
        free(current->message); // Free memory for the current message
        current = current->next;
    }
    double average = total_sum / (head != NULL ? head->timestamp : 0.0);
    fprintf(fd, "Average: %.2f\n", average);
}

int main() {
    FILE* file = fopen("input.txt", "r");
    if(file == NULL) {
        printf("Error opening input file.\n");
        return 1;
    }
    LogEntry* head = NULL;
    init_linked_list(&head, file);
    fclose(file);
    file = fopen("output.txt", "w+");
    if(file == NULL) {
        printf("Error opening output file.\n");
        return 1;
    }
    process_linked_list(head, fileno(file));
    fclose(file);
    while(head != NULL) {
        LogEntry* temp = head;
        head = head->next;
        free(temp->message); // Free memory for the current message
        free(temp); // Free the current log entry
    }
    return 0;
}
