#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

void* log_entry_init() {
    return malloc(sizeof(LogEntry));
}

void log_entry_free(void* entry) {
    free(entry);
}

void log_linked_list_init(LogEntry** head, pthread_mutex_t* mutex) {
    *head = NULL;
    *mutex = PTHREAD_MUTEX_INITIALIZER;
}

void log_linked_list_free(LogEntry** head) {
    LogEntry* current = *head;
    LogEntry* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *head = NULL;
}

void log_entry_append(LogEntry** head, pthread_mutex_t* mutex, void* entry) {
    pthread_mutex_lock(mutex);

    LogEntry* new_entry = (LogEntry*)entry;

    if (*head == NULL) {
        *head = new_entry;
    } else {
        LogEntry* last = *head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = new_entry;
    }

    pthread_mutex_unlock(mutex);
}

void log_linked_list_serialize(FILE* file, LogEntry** head) {
    LogEntry* current = *head;

    while (current != NULL) {
        fprintf(file, "%ld %d %s\n", current->timestamp, current->log_level, current->message);

        free(current->message);
        free(current);

        current = current->next;
    }
}

void log_linked_list_deserialize(FILE* file, LogEntry** head, pthread_mutex_t* mutex) {
    LogEntry* new_head = NULL;

    char buffer[1024];
    LogEntry* entry;

    while (fscanf(file, "%ld %d %s", &entry->timestamp, &entry->log_level, buffer) == 3) {
        entry->message = strdup(buffer);
        pthread_mutex_lock(mutex);

        if (*head == NULL) {
            *head = entry;
        } else {
            LogEntry* last = *head;
            while (last->next != NULL) {
                last = last->next;
            }
            last->next = entry;
        }

        pthread_mutex_unlock(mutex);
    }
}

void log_linked_list_truncate(LogEntry** head, time_t threshold) {
    LogEntry* current = *head;
    LogEntry* previous = NULL;

    while (current != NULL) {
        if (current->timestamp < threshold) {
            if (previous == NULL) {
                *head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current);
            current = previous->next;
            previous = current;
        } else {
            previous = current;
            current = current->next;
        }
    }
}

int main() {
    // Example usage
    LogEntry** head = NULL;
    pthread_mutex_t mutex;

    log_linked_list_init(&head, &mutex);

    void* entry1 = log_entry_init();
    ((LogEntry*)entry1)->timestamp = time(NULL);
    ((LogEntry*)entry1)->log_level = 0;
    ((LogEntry*)entry1)->message = strdup("This is an example log message.");

    void* entry2 = log_entry_init();
    ((LogEntry*)entry2)->timestamp = time(NULL) + 60;
    ((LogEntry*)entry2)->log_level = 1;
    ((LogEntry*)entry2)->message = strdup("This is another log message, this time with a different level.");

    pthread_mutex_lock(&mutex);
    log_entry_append(&head, &mutex, entry1);
    log_entry_append(&head, &mutex, entry2);
    pthread_mutex_unlock(&mutex);

    // Example serialization
    FILE* file = fopen("log.txt", "w");
    if (file != NULL) {
        log_linked_list_serialize(file, &head);
        fclose(file);
    }

    // Example deserialization
    file = fopen("log.txt", "r");
    if (file != NULL) {
        log_linked_list_deserialize(file, &head, &mutex);
        fclose(file);
    }

    // Example truncation
    time_t threshold = time(NULL) - 3600;
    log_linked_list_truncate(&head, threshold);

    // Free allocated memory
    log_linked_list_free(&head);

    return 0;
}
