#include <string.h>

// Define Task structure
typedef struct {
    int priority;
    time_t due_date;
    char* description;
} Task;

// Define Node for doubly linked list
typedef struct Node {
    Task task;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize a new Task with dynamically allocated memory
Task* createTask(int priority, time_t due_date) {
    Task* task = (Task*)malloc(sizeof(Task));
    task->priority = priority;
    task->due_date = due_date;
    task->description = (char*)malloc(256 * sizeof(char)); // allocate 256 chars for description
    return task;
}

// Function to print a Task structure to a file descriptor
void printTask(FILE* fd, Task* task) {
    fprintf(fd, "Priority: %d\n", task->priority);
    fprintf(fd, "Due Date: %ld\n", task->due_date);
    fprintf(fd, "Description: %s\n", task->description);
}

// Function to insert a new Task at the correct position in the sorted list
void insertTask(Node** head, Node** tail, Task* new_task) {
    if (*head == NULL || new_task->priority <= (*head)->task.priority) {
        // Insert at the beginning of the list
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->task = *new_task;
        new_node->prev = NULL;
        new_node->next = (*head);
        if (*head != NULL)
            (*head)->prev = &new_node->task;
        *head = &new_node->task;
        if (*tail == &((*head)->task))
            *tail = &new_node->task;
    } else {
        // Insert at the end of the list
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->task = *new_task;
        new_node->prev = *tail;
        (*tail)->next = &new_node->task;
        *tail = &new_node->task;
    }
}

// Function to sort and print the doubly linked list
void printList(FILE* fd, Node* head) {
    Node* current = head;
    while (current != NULL) {
        printTask(fd, &current->task);
        current = current->next;
    }
}

int main() {
    // Example usage:
    Node* head = NULL;
    Node* tail = NULL;

    Task* task1 = createTask(3, time(NULL));
    strcpy(task1->description, "Task 1");
    insertTask(&head, &tail, task1);

    Task* task2 = createTask(1, time(NULL));
    strcpy(task2->description, "Task 2");
    insertTask(&head, &tail, task2);

    Task* task3 = createTask(2, time(NULL));
    strcpy(task3->description, "Task 3");
    insertTask(&head, &tail, task3);

    FILE* fd = fopen("task_list.txt", "w");
    printList(fd, head);
    fclose(fd);

    // Free allocated memory
    Node* current = head;
    while (current != NULL) {
        Task* task = &current->task;
        free(task->description);
        free(current);
        current = current->next;
    }

    return 0;
}
