// Allocate memory from the pool
void* allocate_memory_pool(MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->size) {
        // Resize the pool if necessary
        pool->blocks = (void**)realloc(pool->blocks, (pool->size * 2) * sizeof(void*));
        pool->size *= 2;
    }
    return pool->blocks[pool->used++];
}

// Free memory from the pool
void free_memory_pool(MemoryPool* pool) {
    for (size_t i = 0; i < pool->used; i++) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
