    .memory = NULL,
    .capacity = 0,
    .used = 0
};

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initMemoryPool(size_t initialCapacity) {
    memoryPool.memory = malloc(initialCapacity);
    memoryPool.capacity = initialCapacity;
}

void* allocateFromMemoryPool(size_t size) {
    pthread_mutex_lock(&lock);
    if (memoryPool.used + size > memoryPool.capacity) {
        // Dynamically resize the memory pool
        memoryPool.memory = realloc(memoryPool.memory, (memoryPool.used + size) * 2);
        memoryPool.capacity *= 2;
    }
    void* ptr = memoryPool.memory + memoryPool.used;
    memoryPool.used += size;
    pthread_mutex_unlock(&lock);
    return ptr;
}

void freeFromMemoryPool(void* ptr, size_t size) {
    pthread_mutex_lock(&lock);
    if (ptr >= memoryPool.memory && ptr < memoryPool.memory + memoryPool.capacity) {
        memoryPool.used -= size;
    }
    pthread_mutex_unlock(&lock);
}

