['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_LIST_SIZE 1000
#define THRESHOLD 500
#define RNTI_COUNT 10
#define CRCFLAG_MAX 16
#define LATENCY_MS 5

typedef struct {
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* list[MAX_LIST_SIZE];
int list_count = 0;
int log_count[RNTI_COUNT];

void init_log() {
    for(int i=0; i<RNTI_COUNT; i++) {
        log_count[i] = 0;
    }
}

int generate_rnti() {
    return rand() % RNTI_COUNT;
}

NFAPI_CRC_INDICATION_PDU_T* generate_list_entry() {
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    entry->rnti = generate_rnti();
    entry->crcflag = rand() % CRCFLAG_MAX;
    return entry;
}

void add_entry_to_list(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&lock);
    list[list_count++] = entry;
    pthread_mutex_unlock(&lock);
}

int get_log_count(int rnti) {
    return log_count[rnti];
}

void update_log(int rnti) {
    log_count[rnti]++;
}

int check_duplicate_rnti(NFAPI_CRC_INDICATION_PDU_T* entry) {
    for(int i=0; i<list_count; i++) {
        if(list[i]->rnti == entry->rnti) return 1;
    }
    return 0;
}

void resize_list() {
    if(list_count >= THRESHOLD * 2 && list_count / (double)THRESHOLD > 1.5) {
        NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDICATION_PDU_T**)realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T*)*THRESHOLD*2);
        for(int i=0; i<list_count; i++) {
            new_list[i] = list[i];
        }
        free(list);
        list = new_list;
    }
}

void rate_limit() {
    static int last_access_time = 0;
    if(time(NULL) - last_access_time < 1) {
        // Rate limit exceeded, sleep for 1 second
        usleep(1000000);
        return;
    }
    last_access_time = time(NULL);
}

int main() {
    srand(time(NULL));
    init_log();
    while(list_count < MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* entry = generate_list_entry();
        if(check_duplicate_rnti(entry)) continue;
        add_entry_to_list(entry);
        update_log(entry->rnti);
        rate_limit();
        usleep(LATENCY_MS * 1000); // Simulate network latency
    }
    return 0;
}
