    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

LogEntry** log_entries;
int num_log_entries = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_log_system() {
    log_entries = (LogEntry**)malloc(MAX_LOG_ENTRIES * sizeof(LogEntry*));
    pthread_mutex_init(&lock, NULL);
}

void add_log_entry(int log_level, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->log_level = log_level;
    entry->message = strdup(message);

    pthread_mutex_lock(&lock);
    log_entries[num_log_entries++] = entry;
    pthread_mutex_unlock(&lock);
}

void remove_log_entry(int index) {
    if (index < 0 || index >= num_log_entries) return;

    LogEntry* entry = log_entries[index];
    free(entry->message);
    free(entry);

    for (int i = index; i < num_log_entries - 1; i++) {
        log_entries[i] = log_entries[i + 1];
    }
    num_log_entries--;
}

void dump_log_entries() {
    for (int i = 0; i < num_log_entries; i++) {
        LogEntry* entry = log_entries[i];
        printf("Timestamp: %ld, Log Level: %d, Message: %s\n", 
               entry->timestamp, entry->log_level, entry->message);
    }
}

void destroy_log_system() {
    for (int i = 0; i < num_log_entries; i++) {
        free(log_entries[i]->message);
        free(log_entries[i]);
    }
    free(log_entries);
}
