LogEntry* create_log_entry(int timestamp, int level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = NULL;
    return entry;
}

