void free_log_entry(LogEntry* entry) {
    if (entry->message != NULL)
        free(entry->message);
    free(entry);
}

// Function to create a new LinkedListNode with the given entry
LinkedListNode* create_linked_node(LogEntry* entry) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    node->entry = *entry;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

// Function to add a new LogEntry to the end of the list
void add_log_entry(DoublyLinkedList* list, LogEntry* entry) {
    LinkedListNode* new_node = create_linked_node(entry);
    if (list->head == NULL)
        list->head = new_node;
    else
        list->tail->next = new_node;
    new_node->prev = list->tail;
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
