    // Compute the final hash value
    MD5_Final(md5_hash, &ctx);

    char *hash_str = (char *)malloc(33 * sizeof(char));  // 32 characters + null terminator
    sprintf(hash_str, "%02x%02x%02x%02x%02x%02x", md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3],
            md5_hash[4], md5_hash[5]);
    return hash_str;
}

// Function to verify the integrity of a file by comparing its calculated hash with a provided checksum
int verify_file_integrity(const char *path, const char *checksum) {
    // Calculate the MD5 hash of the file using the file_md5_hash() function
    char *file_hash = file_md5_hash(path);

    if (strcmp(file_hash, checksum) != 0) {
        // Log error and raise a custom exception
        return -1;
    }

    free(file_hash);
    return 0;
}

// Example usage:
int main() {
    int max_size = 100;  // Maximum number of PDUs to initialize
    pdu_callback cb = my_pdu_callback;

    char **pdus = init_pdu_array(max_size, cb);

    // Process each PDU using the callback function

    char **md5_hashes = compute_md5_hashes(max_size, pdus);

    for (int i = 0; i < max_size; i++) {
        printf("%s\n", md5_hashes[i]);
    }

    free(pdus);
    free(md5_hashes);

    return 0;
}
