// Resource node structure
typedef struct {
    int id;
    char type;
    char *description;
} ResourceNode;

// Binary tree node structure
typedef struct {
    ResourceNode resource;
    struct binary_tree_node *left;
    struct binary_tree_node *right;
} BinaryTree;

// Function to create a new resource node
ResourceNode* create_resource_node(int id, char type) {
    ResourceNode* node = (ResourceNode*)malloc(sizeof(ResourceNode));
    node->id = id;
    node->type = type;
    node->description = NULL;
    return node;
}

// Function to insert a resource into the binary tree
void insert_resource(binary_tree_node **root, ResourceNode *resource) {
    if (*root == NULL) {
        *root = (binary_tree_node*)malloc(sizeof(binary_tree_node));
        (*root)->resource = *resource;
        (*root)->left = NULL;
        (*root)->right = NULL;
    } else if (resource->id < (*root)->resource.id) {
        insert_resource(&((*root)->left), resource);
    } else if (resource->id > (*root)->resource.id) {
        insert_resource(&((*root)->right), resource);
    }
}

// Function to traverse the binary tree and apply transformation function
void traverse_tree(binary_tree_node *node, void (*transform)(ResourceNode *)) {
    if (node != NULL) {
        transform(&node->resource);
        traverse_tree(node->left, transform);
        traverse_tree(node->right, transform);
    }
}

// Function to free the memory allocated for a resource node
void free_resource_node(ResourceNode *node) {
    free(node->description);
    free(node);
}

// Function to serialize the binary tree into a binary format
int serialize_tree(binary_tree_node *root, FILE *file) {
    if (root != NULL) {
        fwrite(&root->resource.id, sizeof(int), 1, file);
        fwrite(&root->resource.type, sizeof(char), 1, file);
        size_t description_length = strlen(root->resource.description);
        fwrite(&description_length, sizeof(size_t), 1, file);
        fwrite(root->resource.description, sizeof(char), description_length + 1, file);
        serialize_tree(root->left, file);
        serialize_tree(root->right, file);
    }
}

// Function to deserialize the binary tree from a binary format
binary_tree_node* deserialize_tree(FILE *file) {
    int id;
    char type;
    size_t description_length;
    ResourceNode *resource;

    if (fread(&id, sizeof(int), 1, file) != 1 || fread(&type, sizeof(char), 1, file) != 1 || fread(&description_length, sizeof(size_t), 1, file) != 1 || fread(resource->description, sizeof(char), description_length + 1, file) != description_length + 1) {
        return NULL;
    }

    resource = create_resource_node(id, type);
    resource->description = (char*)malloc(description_length + 1);

    binary_tree_node *node = (binary_tree_node*)malloc(sizeof(binary_tree_node));
    node->resource = *resource;
    node->left = deserialize_tree(file);
    node->right = deserialize_tree(file);

    return node;
}

// Function to merge two resource catalogs into a single binary tree
binary_tree_node* merge_catalogs(binary_tree_node *catalog1, binary_tree_node *catalog2) {
