void* nfa_pi_allocate_message(int size) {
    static int pool_index = 0;
    static int allocated_count = 0;
    static int compacted = 0;
    static int rate_limited = 0;
    static int total_memory_usage = 0;

    if (rate_limited++ >= RATE_LIMIT || allocated_count >= MAX_POOL_SIZE) {
        // Handle exceeded pool size or rate limit
        printf("Error: Pool size exceeded or rate limited.\n");
        return NULL;
    }

    if (!compacted && allocated_count >= MIN_COMPACT_INTERVAL) {
        // Compact the memory pool periodically
        printf("Compacting memory pool...\n");
        compacted = 1;
    }

    if (pool_index >= MAX_POOL_SIZE - size) {
        // Resize the pool to accommodate additional elements
        NFAPI_MESSAGE_T* new_pool = realloc(pool, sizeof(NFAPI_MESSAGE_T) * (MAX_POOL_SIZE + 1024));
        if (!new_pool) {
            printf("Error: Memory allocation failed.\n");
            return NULL;
        }
        pool = new_pool;
        MAX_POOL_SIZE *= 2;
    }

    NFAPI_MESSAGE_T* message = &pool[pool_index];
    pool_index += sizeof(NFAPI_MESSAGE_T) / sizeof(NFAPI_MESSAGE_T);
    allocated_count++;

    // Update performance monitoring metrics
    total_memory_usage += size;

    return (void*)message;
}

