#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure type
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node type
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct Node *next;
} Node;

// Function to create a new node
Node* create_node(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->pdu = pdu;
    node->next = NULL;
    return node;
}

// Function to add a new node to the linked list
void add_node(Node **head, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    Node *new_node = create_node(pdu);
    if (!*head) {
        *head = new_node;
    } else {
        Node *curr = *head;
        while (curr->next) curr = curr->next;
        curr->next = new_node;
    }
}

// Function to remove a node from the linked list
void remove_node(Node **head, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!*head) return;
    Node *curr = *head;
    Node *prev = NULL;
    while (curr && curr->pdu != pdu) {
        prev = curr;
        curr = curr->next;
    }
    if (curr) {
        if (prev) prev->next = curr->next;
        else *head = curr->next;
        free(curr);
    }
}

// Function to calculate the MD5 hash of a file
char* calculate_md5(const char* filepath) {
    FILE *file = fopen(filepath, "rb");
    if (!file) return NULL;

    MD5_CTX ctx;
    uint8_t buffer[1024];
    size_t read_bytes;
    unsigned char md5_hash[16];

    MD5_Init(&ctx);
    while ((read_bytes = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&ctx, buffer, read_bytes);
    }
    fclose(file);

    MD5_Final(md5_hash, &ctx);

    char* md5_str = (char*)malloc(33); // space for "xxxxxxxxxxxxxxxxxxxxxxxx"
    if (!md5_str) return NULL;
    sprintf(md5_str, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
             md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3],
             md5_hash[4], md5_hash[5], md5_hash[6], md5_hash[7],
             md5_hash[8], md5_hash[9], md5_hash[10], md5_hash[11],
             md5_hash[12], md5_hash[13], md5_hash[14], md5_hash[15]);
    return md5_str;
}

// Function to create a web service endpoint for uploading files and triggering the MD5 hash calculation
void upload_file(const char* filepath) {
    // Create a JSON response
    cJSON *response = cJSON_CreateObject();
    if (!response) return;

    char* md5_hash = calculate_md5(filepath);
    if (md5_hash) {
        cJSON_AddItemToObject(response, "md5", cJSON_CreateString(md5_hash));
        free(md5_hash);
    }

    // Handle potential errors
    if (!response) {
        printf("Error generating JSON response\n");
        return;
    }

    // Send the JSON response to the client
    char* json_str = cJSON_Print(response);
    printf("%s\n", json_str);
    cJSON_Delete(response);
}

int main() {
    Node *head = NULL;

    NFAPI_CRC_INDICATION_PDU_T pdu1, pdu2, pdu3;
    // Initialize structures and add nodes to the linked list
    add_node(&head, &pdu1);
    add_node(&head, &pdu2);
    add_node(&head, &pdu3);

    // Remove a node from the linked list
    remove_node(&head, &pdu2);

    return 0;
}
