#include <iostream>
#include <fstream>
#include <map>
#include <string>

std::map<std::string, std::pair<std::string, std::string>> computeHashes(const char* path) {
    // Initialize OpenSSL
    SSL_library_init();

    EVP_CIPHER_CTX *ctx = NULL;
    EVP_MD_CTX *md_ctx = NULL;

    FILE *file = fopen(path, "rb");
    if (!file) {
        return {};  // File failed to open
    }

    std::map<std::string, std::pair<std::string, std::string>> result;

    while (1) {
        char buffer[1024];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);

        if (!bytes_read)
            break;  // End of file

        int total_bytes_read = 0;
        do {
            AES_cbc_encrypt(buffer, buffer, bytes_read, ctx);
            bytes_read = AES_cbc_encrypt(buffer, buffer, bytes_read, ctx);
            total_bytes_read += bytes_read;
        } while (bytes_read > 0);

        char hash[32];
        EVP_Digest(buffer, total_bytes_read, hash, sizeof(hash), EVP_md_sha256(), NULL);

        result[path] = {"MD5", hexdigest(hash, total_bytes_read)};
    }

    fclose(file);
    return result;
}

std::string hexdigest(const char* buffer, size_t length) {
    // Convert bytes to hexadecimal string
    std::string result(length * 2, '0');
    for (size_t i = 0; i < length; ++i)
        sprintf(&result[i * 2], "%02x", (unsigned char)buffer[i]);
    return result;
}

int main() {
    // Example usage:
    auto hashes = computeHashes("path/to/file");
    if (hashes.empty())
        std::cerr << "Error processing file." << std::endl;
    else
        for (const auto& p : hashes)
            std::cout << p.first << ": " << p.second.first << " - " << p.second.second << std::endl;

    return 0;
}
