#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

typedef struct LinkedListNode {
    LogEntry entry;
    struct LinkedListNode* next;
} LinkedListNode;

typedef struct LinkedList {
    LinkedListNode* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* linkedListInit() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void linkedListInsert(LinkedList* list, LogEntry entry) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    node->entry = entry;
    node->next = list->head;
    list->head = node;
    pthread_mutex_unlock(&list->lock);
}

void linkedListDelete(LinkedList* list, LogEntry entry) {
    LinkedListNode* current = list->head;
    LinkedListNode* previous = NULL;

    while (current != NULL) {
        if (current->entry == entry) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void linkedListPrint(LinkedList* list, int fd) {
    LinkedListNode* node = list->head;

    while (node != NULL) {
        fprintf(fd, "Timestamp: %ld, LogLevel: %d, Message: %s\n", node->entry.timestamp, node->entry.logLevel, node->entry.message);
        node = node->next;
    }
}

void linkedListFree(LinkedList* list) {
    LinkedListNode* current = list->head;

    while (current != NULL) {
        LinkedListNode* next = current->next;
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}
