typedef struct DoublyLinkedListNode {
    LogEntry* entry;
    struct DoublyLinkedListNode* prev;
    struct DoublyLinkedListNode* next;
} DoublyLinkedListNode;

typedef struct DoublyLinkedList {
    DoublyLinkedListNode* head;
    DoublyLinkedListNode* tail;
    int size;
    pthread_mutex_t mutex;
} DoublyLinkedList;

void doubly_linked_list_init(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void doubly_linked_list_insert(DoublyLinkedList* list, LogEntry* entry) {
    DoublyLinkedListNode* node = (DoublyLinkedListNode*) malloc(sizeof(DoublyLinkedListNode));
    node->entry = entry;
    node->prev = NULL;
    node->next = list->head;

    if(list->head != NULL)
        list->head->prev = &node->next;
    else
        list->tail = &node;

    list->head = &node;

    pthread_mutex_lock(&list->mutex);
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void doubly_linked_list_free(DoublyLinkedList* list) {
    DoublyLinkedListNode* current = list->head;
    while(current != NULL) {
        DoublyLinkedListNode* next = current->next;
        free(current->entry->message);
        free(current);
        current = next;
    }

    pthread_mutex_destroy(&list->mutex);
}

void log_entry_free(LogEntry* entry) {
    free(entry->message);
    free(entry);
}

