# Function to calculate the MD5 hash of a file in chunks using hashlib.md5()
def md5_file(file_path):
    chunk_size = 1024 * 1024
    m = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data: break
            m.update(data)
    return m.hexdigest()

