def process_data(data_configs):
    results = []
    for config in data_configs:
        df = pd.DataFrame()
        filters = config['filters']
        aggregate_methods = config['aggregates']
        output_format = config['output_format']

        # Filter data based on user-defined criteria
        filtered_df = filter_data(df, filters)

        # Aggregate results based on user-defined methods
        aggregated_results = aggregate_results(filtered_df, aggregate_methods)

        # Generate reports in the specified format
        report = generate_report(aggregated_results, output_format)

        results.append(report)

    return results

def filter_data(df, filters):
    for key, value in filters.items():
        df = df[df[key] == value]
    return df

def aggregate_results(df, aggregates):
    aggregated_results = {}
    for key, method in aggregates.items():
        aggregated_results[key] = df.groupby(key)[method].sum().reset_index()
    return aggregated_results

def generate_report(results, output_format):
    report = ''
    if output_format == 'csv':
        report += results.to_csv(index=False)
    elif output_format == 'json':
        report += results.to_json(orient='records')
    else:
        report += str(results)
    return report

def get_data_from_api(config):
    api_url = config['api_url']
    response = requests.get(api_url)
    data = response.json()
    return data

def process_api_data(data_configs):
    with Pool() as pool:
        partial_get_data = partial(get_data_from_api)
        results = list(pool.map(partial_get_data, data_configs))

    # Handle concurrent API requests
