#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for LogEntry
typedef struct {
    int timestamp;
    char level;
    char* message;
} LogEntry;

// Define the structure for Doubly-Linked List Node
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the doubly-linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int count;
} DList;

// Function to create a new log entry
LogEntry* createLogEntry(int timestamp, char level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = NULL;
    return entry;
}

// Function to initialize the doubly-linked list
DList* initDList() {
    DList* list = (DList*)malloc(sizeof(DList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Function to add a new log entry to the linked list
void addEntry(DList* list, LogEntry* entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->entry = *entry;
    newNode->prev = NULL;
    newNode->next = list->head;

    if (list->head != NULL) {
        list->head->prev = &newNode->entry;
    } else {
        list->tail = &newNode->entry;
    }
    list->head = newNode;
    list->count++;

    pthread_mutex_unlock(&list->lock);
}

// Function to print all log entries in the linked list
void printEntries(DList* list, int fd) {
    Node* current = list->head;
    while (current != NULL) {
        // Print the log entry details here
        fprintf(fd, "%d %c %s\n", current->entry.timestamp, current->entry.level, current->entry.message);
        current = current->next;
    }
}

// Function to free memory for each node in the linked list
void freeList(DList* list) {
    Node* temp = list->head;
    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    free(list);
}
