void process_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    callback(*pdu);
}

int create_crc_indication_pdu_array(int max_num_pdus, int (*callback)(NFAPI_CRC_INDICATION_PDU_T*, void (*)(NFAPI_CRC_INDICATION_PDU_T*)), char** error_message) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = NULL;
    size_t allocated_size = 0;
    size_t current_index = 0;

    // Allocate initial memory
    while (allocated_size < max_num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        pdus = realloc(pdus, allocated_size + max_num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            *error_message = "Memory allocation failed.";
            return -1;
        }
        allocated_size += max_num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    // Initialize PDUs
    for (int i = 0; i < max_num_pdus; i++) {
        pdus[i].rx_ue_info = ...; // Initialize RX_UE_INFORMATION_TAG
        pdus[i].rnti = ...; // Initialize RNTI
        pdus[i].crc_ind_rel8_tag = ...; // Initialize CRC_INDICATION_REL8_TAG
        pdus[i].crcflag = rand() % 2; // Randomly set CRCFLAG

        if (callback) {
            callback(&pdus[i], process_pdu);
        }
    }

    // Compute and return MD5 hash of each PDU
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    for (int i = 0; i < max_num_pdus; i++) {
        unsigned char* serialized_pdu = ...; // Serialize the PDU
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, serialized_pdu, strlen((char*)serialized_pdu));
        MD5_Final(md5_hash, &ctx);

        // Convert hash to string
        char hash_str[3 * sizeof(unsigned int) + 1];
        for (int j = 0; j < MD5_DIGEST_LENGTH; j++) {
            sprintf(&hash_str[j * 2], "%02x", md5_hash[j]);
        }
        printf("PDU %d MD5 Hash: %s\n", i, hash_str);
    }

    // Clean up memory
    free(pdus);

    return 0;
}
