#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Doubly-linked list node structure
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Concurrent doubly-linked list structure
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} List;

// Function to create a new log entry
LogEntry* log_entry_create(time_t timestamp, int level, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return NULL;
    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);
    return entry;
}

// Function to create a new list
List* list_create() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->head = NULL;
    list->tail = NULL;
    return list;
}

// Function to insert a log entry into the list
void list_insert(List* list, LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return;
    node->entry = entry;
    node->prev = list->tail;
    node->next = NULL;
    if (list->head == NULL) list->head = node;
    else list->tail->next = node;
    list->tail = node;
}

// Function to delete a log entry from the list
void list_delete(List* list, LogEntry* entry) {
    Node* node = list->head;
    while (node != NULL && node->entry != entry) node = node->next;
    if (node == NULL) return;
    if (node == list->tail) list->tail = node->prev;
    else node->prev->next = node->next;
    if (node == list->head) list->head = node->next;
    free(node);
}

// Function to iterate over the log entries in the list
void list_iterate(List* list, void (*callback)(LogEntry*)) {
    Node* node = list->head;
    while (node != NULL) {
        callback(node->entry);
        node = node->next;
    }
}

