    size_t size;
    pthread_mutex_t mutex;
} NetworkStateList;

NetworkStateList* init_network_state_list() {
    NetworkStateList* list = (NetworkStateList*)malloc(sizeof(NetworkStateList));
    if (!list) return NULL;
    list->capacity = 1;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_connection(NetworkStateList* list, int id, time_t timestamp, enum { ACTIVE, IDLE, ERROR } status) {
    Connection* new_connections = (Connection*)realloc(list->connections, (list->size + 1) * sizeof(Connection));
    if (!new_connections) {
        printf("Memory allocation failed!\n");
        return;
    }
    list->connections = new_connections;
    list->connections[list->size].id = id;
    list->connections[list->size].timestamp = timestamp;
    list->connections[list->size].status = status;
    list->size++;
}

void process_connection(NetworkStateList* list, int id) {
    for (int i = 0; i < list->size; i++) {
        if (list->connections[i].id == id) {
            // Process the connection here
            printf("Processed connection %d.\n", id);
            return;
        }
    }
}

void free_network_state_list(NetworkStateList* list) {
    pthread_mutex_unlock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->connections[i].id);
    }
    free(list->connections);
    free(list);
}

int main() {
    NetworkStateList* list = init_network_state_list();

    add_connection(list, 1, time(NULL), ACTIVE);
    add_connection(list, 2, time(NULL), IDLE);
    add_connection(list, 3, time(NULL), ERROR);

    process_connection(list, 1);
    process_connection(list, 2);
    process_connection(list, 3);

    free_network_state_list(list);

    return 0;
}
