```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for LogEntry
typedef struct {
    int timestamp;
    char logLevel;
    char* message;
} LogEntry;

// Define the structure for Node in Doubly-Linked List
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create a new node with given LogEntry
Node* createNode(LogEntry entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Function to initialize the doubly-linked list
void initDoublyLinkedList(Node** headRef, pthread_mutex_t* mutex) {
    *headRef = NULL;
    *mutex = PTHREAD_MUTEX_INITIALIZER;
}

// Function to add a new LogEntry to the end of the linked list
void addLogEntry(Node** headRef, LogEntry entry) {
    Node* newNode = createNode(entry);
    if (*headRef == NULL) {
        *headRef = newNode;
    } else {
        Node* lastNode = *headRef;
        while (lastNode->next != NULL) {
            lastNode = lastNode->next;
        }
        lastNode->next = newNode;
        newNode->prev = lastNode;
    }
}

// Function to print the linked list
void printDoublyLinkedList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d - %c - %s\n", current->entry.timestamp, current->entry.logLevel, current->entry.message);
        current = current->next;
    }
}

// Function to free the memory used by the linked list
void freeDoublyLinkedList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* nextNode = current->next;
        free(current);
        current = nextNode;
    }
}
