    char* message;
} LogEntry;

typedef struct DoublyLinkedListNode {
    LogEntry entry;
    struct DoublyLinkedListNode* next;
    struct DoublyLinkedListNode* prev;
} DoublyLinkedListNode;

DoublyLinkedListNode* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_entry_init(LogEntry* entry, char* message) {
    entry->timestamp = time(NULL);
    // Initialize level
    strcpy(entry->message, message);
}

LogEntry* log_entry_create(char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry)
        return NULL;

    log_entry_init(entry, message);

    return entry;
}

void doubly_linked_list_init(DoublyLinkedListNode** head_ref) {
    *head_ref = NULL;
}

DoublyLinkedListNode* create_node(LogEntry* entry) {
    DoublyLinkedListNode* new_node = (DoublyLinkedListNode*)malloc(sizeof(DoublyLinkedListNode));
    if (!new_node)
        return NULL;

    new_node->entry = *entry;
    new_node->next = NULL;
    new_node->prev = NULL;

    return new_node;
}

void doubly_linked_list_insert(DoublyLinkedListNode** head_ref, LogEntry* entry) {
    DoublyLinkedListNode* new_node = create_node(entry);
    pthread_mutex_lock(&lock);

    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else {
        new_node->next = *head_ref;
        (*head_ref)->prev = new_node;
        *head_ref = new_node;
    }

    pthread_mutex_unlock(&lock);
}

void log_entry_free(LogEntry* entry) {
    free(entry->message);
    free(entry);
}

void doubly_linked_list_free(DoublyLinkedListNode* head) {
    while (head != NULL) {
        DoublyLinkedListNode* temp = head;
        head = head->next;

        log_entry_free(&temp->entry);

        free(temp);
    }
}

