#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct LogEntry {
    int timestamp;
    char level;
    char *message;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node *prev, *next;
} Node;

Node *create_node(LogEntry e) {
    Node *node = (Node *)malloc(sizeof(Node));
    node->entry = e;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

void destroy_list(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current->next;
        free(current->message);
        free(current);
        current = temp;
    }
    *head = NULL;
}

int print_entries(Node *head, int fd) {
    int count = 0;
    Node *current = head;
    while (current != NULL) {
        char buffer[1024];
        sprintf(buffer, "%d %c: %s\n", current->entry.timestamp, current->entry.level, current->entry.message);
        write(fd, buffer, strlen(buffer));
        count++;
        current = current->next;
    }
    return count;
}

void serialize_list(Node *head, FILE *file) {
    Node *current = head;
    while (current != NULL) {
        fwrite(&current->entry.timestamp, sizeof(int), 1, file);
        fputc(current->entry.level, file);
        size_t len = strlen(current->entry.message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(current->entry.message, sizeof(char), len + 1, file);
        current = current->next;
    }
}

Node *deserialize_list(FILE *file) {
    Node *head = NULL;
    int timestamp;
    char level;
    size_t len;
    while (fread(&timestamp, sizeof(int), 1, file) == 1 &&
           fread(&level, sizeof(char), 1, file) == 1 &&
           fread(&len, sizeof(size_t), 1, file) == 1) {
        LogEntry e = {timestamp, level, NULL};
        char *message = (char *)malloc(len + 1);
        fread(message, sizeof(char), len + 1, file);
        message[len] = '\0';
        Node *node = create_node(e);
        node->entry.message = message;
        if (head == NULL)
            head = node;
        else {
            Node *current = head;
            while (current->next != NULL)
                current = current->next;
            current->next = node;
            node->prev = current;
        }
    }
    return head;
}

void garbage_collect(Node **head, int interval) {
    // Implement your custom garbage collection logic here
}

int main() {
    // Test the code
    LogEntry entry1 = {1643723400, 'I', "This is an info message."};
    LogEntry entry2 = {1643723410, 'W', "Warning: Something went wrong."};
    LogEntry entry3 = {1643723420, 'E', "Error: The program terminated."};

    Node *head = create_node(entry1);
    head->next = create_node(entry2);
    head->next->next = create_node(entry3);

    int fd = open("log.txt", O_WRONLY | O_TRUNC | O_CREAT);
    if (fd >= 0) {
        printf("%d entries\n", print_entries(head, fd));
        close(fd);
    }

    FILE *file = fopen("log.bin", "wb");
    serialize_list(head, file);
    fclose(file);

    Node *deserialized_head = deserialize_list(fopen("log.bin", "rb"));
    destroy_list(&head);
    garbage_collect(&deserialized_head, 1000); // Test the garbage collector

    return 0;
}

