**Python Function for MD5 Hashing Large File**
```python
import hashlib
import os

def calculate_md5_large_file(file_path, chunk_size=1024*1024):
    md5_hash = hashlib.md5()
    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            md5_hash.update(chunk)

            # Log progress every 10% completion
            if (file.tell() / os.path.getsize(file_path)) * 100 >= 10:
                print(f"Hashing {int((file.tell() / os.path.getsize(file_path)) * 100)}% complete.")

    return md5_hash.hexdigest()

def main():
    file_path = "path_to_large_file.txt"
    try:
        hash_value = calculate_md5_large_file(file_path)
        print(f"MD5 Hash: {hash_value}")
    except (FileNotFoundError, IsADirectoryError) as e:
        print(f"Error: {e}")
