#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for session data
typedef struct {
    int id;
    time_t expiration;
    char *profile;
} Session;

// Define DHT node structure
typedef struct {
    pthread_mutex_t lock; // Synchronization mutex
    int num_sessions;
    int total_size;
    double average_profile_len;
    Session **sessions; // Array of sessions
    int gc_interval; // Garbage collection interval (in seconds)
} DHTNode;

// Function to initialize a DHT node
DHTNode *dht_init(int num_nodes, int max_sessions) {
    DHTNode *node = (DHTNode *)malloc(sizeof(DHTNode));
    node->num_sessions = 0;
    node->total_size = 0;
    node->average_profile_len = 0.0;
    node->sessions = (Session **)calloc(max_sessions, sizeof(Session *));
    node->gc_interval = 10; // Default garbage collection interval
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

// Function to add a new session to the DHT
int dht_add_session(DHTNode *node, int id, time_t expiration, char *profile) {
    Session *session = (Session *)malloc(sizeof(Session));
    session->id = id;
    session->expiration = expiration;
    session->profile = profile;

    // Check if memory allocation failed
    if (!session->profile) return -1; // Error handling

    node->num_sessions++;
    node->total_size += strlen(profile) + sizeof(Session);
    node->average_profile_len = (node->total_size / node->num_sessions);

    // Update statistics
    pthread_mutex_lock(&node->lock);
    node->sessions[node->num_sessions - 1] = session;
    pthread_mutex_unlock(&node->lock);

    return 0; // Success
}

// Function to free a DHT node and its sessions
void dht_free_node(DHTNode *node) {
    for (int i = 0; i < node->num_sessions; i++) {
        Session *session = node->sessions[i];
        free(session->profile);
        free(session);
    }
    free(node->sessions);
    pthread_mutex_destroy(&node->lock);
    free(node);
}

// Function to garbage collect and reclaim unused memory
void dht_gc(DHTNode *node, int delay) {
    // Check if it's time for garbage collection based on the interval
    sleep(delay);

    pthread_mutex_lock(&node->lock);
    for (int i = 0; i < node->num_sessions; i++) {
        Session *session = node->sessions[i];
        // Check session expiration and reclaim memory as needed
        if (time(NULL) > session->expiration) {
            free(session->profile);
            free(session);
            node->num_sessions--;
            node->total_size -= strlen(session->profile) + sizeof(Session);
            i--; // Decrement the loop counter since we removed an element
        }
    }
    pthread_mutex_unlock(&node->lock);
}

// Function to serialize and deserialize sessions to/from a file
int dht_serialize(DHTNode *node, FILE *file) {
    for (int i = 0; i < node->num_sessions; i++) {
        Session *session = node->sessions[i];
        fwrite(&session, sizeof(Session), 1, file);
        // Serialize the profile string
        size_t len = strlen(session->profile);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(session->profile, sizeof(char), len, file);
    }
    return 0; // Success
}

int dht_deserialize(DHTNode *node, FILE *file) {
    Session **new_sessions = (Session **)calloc(node->num_sessions, sizeof(Session *));
    int i;
    for (i = 0; i < node->num_sessions; i++) {
        Session *session = (Session *)malloc(sizeof(Session));
        fread(&session, sizeof(Session), 1, file);
        // Deserialize the profile string
        size_t len;
        fread(&len, sizeof(size_t), 1, file);
        char *profile = (char *)malloc(len + 1);
        fread(profile, sizeof(char), len, file);
        profile[len] = '\0'; // Null-terminate the string
        session->id = session->id; // No need to copy id
        session->expiration = session->expiration;
        session->profile = profile;

        new_sessions[i] = session;
    }

    free(node->sessions);
    node->num_sessions = i;
    node->sessions = new_sessions;

    return 0; // Success
}

// Function to iterate over sessions and stream information to a file descriptor for logging purposes
int dht_stream(DHTNode *node, int fd) {
    for (int i = 0; i < node->num_sessions; i++) {
        Session *session = node->sessions[i];
        // Stream session information to the file descriptor
        write(fd, &session, sizeof(Session));
        // Stream the profile string
        size_t len = strlen(session->profile);
        write(fd, &len, sizeof(size_t));
        write(fd, session->profile, len);
    }
    return 0; // Success
}

// Function to filter sessions by expiration range and status
int dht_filter_sessions(DHTNode *node, time_t min_expiration, time_t max_expiration, int *num_results) {
    int count = 0;
    for (int i = 0; i < node->num_sessions; i++) {
        Session *session = node->sessions[i];
        if (session->expiration >= min_expiration && session->expiration <= max_expiration) {
            // Apply custom filtering logic based on the session status
            if (/* Filtering condition */) {
                count++;
            }
        }
    }

    *num_results = count;
    return 0; // Success
}

