// Define structure for Doubly-Linked List
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
    int size;
} LinkedList;

// Function to initialize a new doubly-linked list
LinkedList* init_list() {
    LinkedList* list = (LinkedList*) malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

// Function to add a new log entry to the doubly-linked list
void add_entry(LinkedList* list, LogEntry* entry) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;

    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }

    list->size++;
    pthread_mutex_unlock(&list->lock);
}

// Function to print all entries in the doubly-linked list
void print_list(LinkedList* list, int fd) {
    Node* current = list->head;

    while (current != NULL) {
        fprintf(fd, "Timestamp: %ld, Log Level: %d, Message: %s\n",
                current->entry->timestamp, current->entry->log_level,
                current->entry->message);

        current = current->next;
    }
}

// Function to free the resources of the doubly-linked list
void free_list(LinkedList* list) {
    Node* current = list->head;

    while (current != NULL) {
        Node* next = current->next;

        free(current->entry->message);
        free(current);

        current = next;
    }

    pthread_mutex_destroy(&list->lock);
    free(list);
}

// Function to serialize the doubly-linked list to a binary file
void serialize_list(LinkedList* list, char* filename) {
    FILE* file = fopen(filename, "wb");

    if (file != NULL) {
        Node* current = list->head;

        while (current != NULL) {
            LogEntry* entry = current->entry;
            fwrite(&entry->timestamp, sizeof(time_t), 1, file);
            fwrite(&entry->log_level, sizeof(int), 1, file);
            int message_len = strlen(entry->message);
            fwrite(&message_len, sizeof(int), 1, file);
            fwrite(entry->message, sizeof(char), message_len + 1, file);

            current = current->next;
        }

        fclose(file);
    }
}

// Function to deserialize the doubly-linked list from a binary file
LinkedList* deserialize_list(char* filename) {
    LinkedList* list = init_list();
    FILE* file = fopen(filename, "rb");

    if (file != NULL) {
        Node* current = list->head;

        while (1) {
            time_t timestamp;
            int log_level;
            int message_len;

            fread(&timestamp, sizeof(time_t), 1, file);
            fread(&log_level, sizeof(int), 1, file);
            fread(&message_len, sizeof(int), 1, file);

            LogEntry* entry = (LogEntry*) malloc(sizeof(LogEntry));
            entry->timestamp = timestamp;
            entry->log_level = log_level;

            char* message = (char*) malloc((message_len + 1) * sizeof(char));
            fread(message, sizeof(char), message_len + 1, file);

            entry->message = message;

            if (current == NULL) {
                list->head = current;
                list->tail = current;
            } else {
                Node* next = current->next;

                current->next = (Node*) malloc(sizeof(Node));
                current->next->prev = current;
                current->next->entry = entry;
                current->next->next = next;

                if (current == list->tail) {
                    list->tail = current->next;
                }

                current = current->next;
            }
        }

        fclose(file);
    }

    return list;
}

