// Function to initialize the linked list
LogEntryList* log_entry_list_init() {
    LogEntryList* list = (LogEntryList*)malloc(sizeof(LogEntryList));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Function to add a new entry to the linked list
int log_entry_list_add(LogEntryList* list, LogEntry* entry) {
    // ... code for adding the entry to the list ...
    if (!list || !entry) return -1;

    pthread_mutex_lock(&list->mutex);

    // Add the entry at the end of the list
    if (list->tail) {
        list->tail->next = entry;
        entry->prev = list->tail;
        list->tail = entry;
    } else {
        list->head = list->tail = entry;
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

// Function to remove an entry from the linked list
void log_entry_list_remove(LogEntryList* list, LogEntry* entry) {
    // ... code for removing the entry from the list ...
    if (!list || !entry) return;

    pthread_mutex_lock(&list->mutex);

    if (entry == list->head) {
        list->head = entry->next;
    }
    if (entry == list->tail) {
        list->tail = entry->prev;
    }

    // Update the next and prev pointers
    entry->next->prev = entry->prev;
    entry->prev->next = entry->next;

    pthread_mutex_unlock(&list->mutex);
}

// Function to serialize the linked list to a file
int log_entry_list_serialize(LogEntryList* list, FILE* file) {
    // ... code for serializing the list to the file ...
    if (!list || !file) return -1;

    pthread_mutex_lock(&list->mutex);

    // Write the number of entries in the list
    fwrite(&list->head, sizeof(LogEntry*), 1, file);

    // Write each entry in the list
    LogEntry* current = list->head;
    while (current) {
        fwrite(&current->timestamp, sizeof(long), 1, file);
        fwrite(&current->logLevel, sizeof(int), 1, file);
        // ... code for writing the message and refCount ...
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);

    return 0;
}

