    int downlink_power;
} LTE_Ue_Context;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void lte_ue_context_init(LTE_Ue_Context** contexts, int capacity) {
    *contexts = (LTE_Ue_Context*)calloc(capacity, sizeof(LTE_Ue_Context));
}

int lte_ue_context_add(LTE_Ue_Context** contexts, int capacity, LTE_Ue_Context* new_ctx) {
    pthread_mutex_lock(&lock);
    for(int i = 0; i < capacity; i++) {
        if(!(*contexts)[i].ue_id) {
            (*contexts)[i] = *new_ctx;
            return i;
        }
    }
    printf("Error: Context array is full.\n");
    pthread_mutex_unlock(&lock);
    return -1;
}

void lte_ue_context_update(LTE_Ue_Context** contexts, int index, LTE_Ue_Context* updated_ctx) {
    pthread_mutex_lock(&lock);
    (*contexts)[index] = *updated_ctx;
    pthread_mutex_unlock(&lock);
}

int lte_ue_context_remove(LTE_Ue_Context** contexts, int capacity, int index) {
    pthread_mutex_lock(&lock);
    if(index >= 0 && index < capacity) {
        memset((*contexts)[index].bwp_ids, 0, sizeof(int));
        (*contexts)[index].ue_id = 0;
        return 1;
    }
    printf("Error: Invalid context index.\n");
    pthread_mutex_unlock(&lock);
    return -1;
}

void lte_ue_context_log(LTE_Ue_Context* ctx) {
    printf("UE ID: %d\n", ctx->ue_id);
    for(int i = 0; i < ctx->bwp_count; i++) {
        printf("BWP ID: %d\n", ctx->bwp_ids[i]);
    }
    printf("Uplink Power: %d dBm\n", ctx->uplink_power);
    printf("Downlink Power: %d dBm\n", ctx->downlink_power);
}
