#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

// Define the structure for a LogEntry
typedef struct {
    long timestamp;
    int log_level;
    char* message;
    int ref_count;
} LogEntry;

// Define the structure for a doubly-linked list node
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize and manage the linked list
void init_log_list(Node** head, int size) {
    *head = NULL;
}

// Function to create a new log entry with dynamically allocated message
LogEntry* create_log_entry(long timestamp, int log_level, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = (char*)malloc(strlen(message) + 1);
    strcpy(entry->message, message);
    entry->ref_count = 0;
    return entry;
}

// Function to increment the reference count of a log entry
void increment_ref_count(LogEntry* entry) {
    entry->ref_count++;
}

// Function to decrement the reference count of a log entry and free it if necessary
void decrement_ref_count(LogEntry* entry) {
    if (entry->ref_count == 0) {
        free(entry->message);
        free(entry);
    } else {
        entry->ref_count--;
    }
}

// Function to add an entry to the linked list at the end
void log_list_add(Node** head, LogEntry* new_entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->entry = new_entry;
    new_node->prev = NULL;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* tail = *head;
        while (tail->next != NULL)
            tail = tail->next;
        tail->next = new_node;
        new_node->prev = tail;
    }
}

// Function to remove an entry from the linked list
void log_list_remove(Node** head, LogEntry* old_entry) {
    Node* current = *head;

    while (current != NULL && current->entry != old_entry)
        current = current->next;

    if (current == NULL || current->entry != old_entry)
        return; // Entry not found in the list

    if (current->prev != NULL)
        current->prev->next = current->next;
    else
        *head = current->next;

    if (current->next != NULL)
        current->next->prev = current->prev;
    free(current);
}

// Function to print the linked list
void log_list_print(Node* head) {
    while (head != NULL) {
        printf("%ld %d %s\n", head->entry->timestamp, head->entry->log_level, head->entry->message);
        head = head->next;
    }
}

// Function to destroy the linked list and free all dynamically allocated resources
void log_list_destroy(Node** head) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = temp->next;
        free(temp->entry->message);
        free(temp->entry);
        free(temp);
    }
}
