typedef struct LogEntry {
    int timestamp;
    char level;
    char* message;
} LogEntry;

// Define a struct for our doubly-linked list
typedef struct Node {
    LogEntry* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Define a struct for our doubly-linked list
typedef struct DLL {
    Node* head;
    Node* tail;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DLL;

// Initialize the DLL with default values
void init_DLL(DLL* dll) {
    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    pthread_mutex_init(&dll->mutex, NULL);
    pthread_cond_init(&dll->cond, NULL);
}

// Free all allocated memory for the DLL and its nodes
void free_DLL(DLL* dll) {
    Node* current = dll->head;
    while (current != NULL) {
        Node* next = current->next;
        if (current->data->message != NULL)
            free(current->data->message);
        free(current);
        current = next;
    }
    dll->size = 0;
}

// Insert a new LogEntry at the end of the DLL
void insert_DLL(DLL* dll, LogEntry* entry) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->data = (LogEntry*)malloc(sizeof(LogEntry));
    strcpy(newNode->data->message, entry->message);
    newNode->data->timestamp = entry->timestamp;
    newNode->data->level = entry->level;
    newNode->prev = dll->tail;
    newNode->next = NULL;

    if (dll->head == NULL)
        dll->head = newNode;
    else
        dll->tail->next = newNode;

    dll->tail = newNode;
    dll->size++;
}

// Delete a LogEntry from the DLL based on timestamp
void delete_DLL(DLL* dll, int timestamp) {
    Node* current = dll->head;
    while (current != NULL) {
        if (current->data->timestamp == timestamp) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                dll->head = current->next;

            if (current->next != NULL)
                current->next->prev = current->prev;
            else
                dll->tail = current->prev;

            free(current->data->message);
            free(current);
            dll->size--;
            return;
        }
        current = current->next;
    }
}

// Print all LogEntries in the DLL to a file descriptor
void print_DLL(DLL* dll, int fd) {
    Node* current = dll->head;
    while (current != NULL) {
        fwrite(current->data->message, sizeof(char), strlen(current->data->message), fd);
        current = current->next;
    }
}

