#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SESSIONS 10000000
#define MAX_USER_PROFILE_SIZE 1024

typedef struct {
    char* id;
    time_t expiration_time;
    char* profile;
} UserSession;

UserSession** hash_table;
int num_sessions = 0;

void init_hash_table(int size) {
    hash_table = (UserSession**)malloc(size * sizeof(UserSession*));
    for (int i = 0; i < size; i++) {
        hash_table[i] = NULL;
    }
}

void destroy_hash_table() {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (hash_table[i]) {
            free(hash_table[i]->id);
            free(hash_table[i]->profile);
            free(hash_table[i]);
        }
    }
    free(hash_table);
}

// Hash function to map user ID to hash table index
int hash_function(char* id) {
    int result = 0;
    for (int i = 0; i < strlen(id); i++) {
        result += (id[i] * 31 + 1) % MAX_SESSIONS;
    }
    return result;
}

// Insert session into the hash table
void insert_session(UserSession* session) {
    int index = hash_function(session->id);
    if (!hash_table[index]) {
        hash_table[index] = malloc(sizeof(UserSession));
        *hash_table[index] = *session;
        num_sessions++;
    } else {
        // Handle collision by chaining or open addressing
        // For simplicity, we'll just resize the table when a collision occurs
        if (num_sessions >= MAX_SESSIONS / 2) {
            int new_size = MAX_SESSIONS * 2;
            UserSession** new_table = realloc(hash_table, new_size * sizeof(UserSession*));
            for (int i = 0; i < MAX_SESSIONS; i++) {
                new_table[i] = NULL;
            }
            hash_table = new_table;
        }
    }
}

// Export sessions to a file
void export_sessions(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    // Serialize sessions and write to file
    for (int i = 0; i < MAX_SESSIONS; i++) {
        UserSession* session = hash_table[i];
        if (session) {
            fwrite(session->id, sizeof(char), strlen(session->id), file);
            fwrite(&session->expiration_time, sizeof(time_t), 1, file);
            fwrite(session->profile, sizeof(char), strlen(session->profile), file);
        }
    }

    fclose(file);
}

// Load sessions from a file
void load_sessions(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    // Read session data from file and deserialize
    for (int i = 0; i < MAX_SESSIONS; i++) {
        UserSession* session;
        fread(&session->id, sizeof(char), strlen(session->id), file);
        fread(&session->expiration_time, sizeof(time_t), 1, file);
        fread(&session->profile, sizeof(char), strlen(session->profile), file);
        // Insert session into the hash table
    }

    fclose(file);
}

int main() {
    init_hash_table(MAX_SESSIONS);

    // Example usage: insert sessions and export to a file
    UserSession* session1 = malloc(sizeof(UserSession));
    session1->id = "session1";
    session1->expiration_time = time(NULL) + 3600;
    session1->profile = strdup("profile1");

    UserSession* session2 = malloc(sizeof(UserSession));
    session2->id = "session2";
    session2->expiration_time = time(NULL) + 7200;
    session2->profile = strdup("profile2");

    insert_session(session1);
    insert_session(session2);

    export_sessions("sessions.bin");

    destroy_hash_table();

    return 0;
}
