```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

// Define a structure representing a cache entry
typedef struct {
    int key;
    void* value;
    time_t expiration_time;
    int reference_count;
} CacheEntry;

// Define the cache structure
typedef struct {
    int size;
    CacheEntry** entries;
    pthread_mutex_t mutex;
} Cache;

// Function to initialize the cache
Cache* cache_init(int initial_size) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    cache->size = initial_size;
    cache->entries = (CacheEntry**)malloc(initial_size * sizeof(CacheEntry*));
    for (int i = 0; i < initial_size; i++) {
        cache->entries[i] = NULL;
    }
    pthread_mutex_init(&cache->mutex, NULL);
    return cache;
}

// Function to free the cache
void cache_free(Cache* cache) {
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i]) {
            free(cache->entries[i]->value);
            free(cache->entries[i]);
        }
    }
    pthread_mutex_destroy(&cache->mutex);
    free(cache);
}

// Function to get the total number of entries
int cache_get_entry_count(Cache* cache) {
    int count = 0;
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i]) {
            count++;
        }
    }
    return count;
}

// Function to get the average value size
double cache_get_average_value_size(Cache* cache) {
    int total_size = 0;
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i]) {
            total_size += sizeof(void*);
        }
    }
    return (double)total_size / cache_get_entry_count(cache);
}

// Function to get the hit rate over time
double cache_get_hit_rate(Cache* cache, time_t current_time) {
    int hits = 0;
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i] && cache->entries[i]->expiration_time > current_time) {
            hits++;
        }
    }
    return (double)hits / cache_get_entry_count(cache);
}

// Function to insert a new entry
void cache_insert(Cache* cache, int key, void* value) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (!cache->entries[i]) {
            cache->entries[i] = malloc(sizeof(CacheEntry));
            cache->entries[i]->key = key;
            cache->entries[i]->value = value;
            cache->entries[i]->expiration_time = time(NULL) + 60 * 60; // Set expiration time to 1 hour
            cache->entries[i]->reference_count = 1;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Function to delete an entry
void cache_delete(Cache* cache, int key) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i] && cache->entries[i]->key == key) {
            free(cache->entries[i]->value);
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Function to evict an entry
void cache_evict(Cache* cache, int key) {
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i] && cache->entries[i]->key == key) {
            free(cache->entries[i]->value);
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
}

// Function to integrate with the external logging system
void cache_log(Cache* cache, char* message) {
    // Implement logging functionality here
}
