#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    char userId[20];
    char actionDescription[100];
} LogEntry;

void* parseAndAnalyzeLogFiles(char* directoryPath) {
    // Initialize memory pool
    size_t memoryPoolSize = 1024;
    void* memoryPool = malloc(memoryPoolSize);
    if (!memoryPool) {
        return NULL; 
    }

    // Custom resizing strategy for array
    int logEntryCount = 0;
    LogEntry** logEntries = (LogEntry**)malloc(memoryPoolSize);

    DIR *dir;
    struct dirent *ent;

    dir = opendir(directoryPath);
    if (!dir) {
        free(logEntries);
        free(memoryPool);
        return NULL; 
    }

    while ((ent = readdir(dir)) != NULL) {
        char filePath[200];
        sprintf(filePath, "%s/%s", directoryPath, ent->d_name);

        FILE *file = fopen(filePath, "r");
        if (!file) {
            closedir(dir);
            free(logEntries);
            free(memoryPool);
            return NULL; 
        }

        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        rewind(file);

        char buffer[fileSize];
        fread(buffer, 1, fileSize, file);
        fclose(file);

        // Parse log entries
        LogEntry* logEntry;
        char* token;

        token = strtok(buffer, "\n");
        while (token) {
            logEntry = (LogEntry*)malloc(sizeof(LogEntry));
            strcpy(logEntry->userId, token);

            token = strtok(NULL, " ");
            if (token) {
                strcpy(logEntry->actionDescription, token);
            }

            // Add to memory pool
            logEntries[logEntryCount++] = logEntry;

            if (logEntryCount >= memoryPoolSize / sizeof(LogEntry*)) {
                memoryPoolSize *= 2;
                void* tempMemoryPool = realloc(memoryPool, memoryPoolSize);
                if (!tempMemoryPool) {
                    for (int i = 0; i < logEntryCount; i++) {
                        free(logEntries[i]);
                    }
                    free(logEntries);
                    free(memoryPool);
                    return NULL; 
                }

                logEntries = tempMemoryPool;
            }

            token = strtok(NULL, "\n");
        }

        closedir(dir);
    }

    // Free memory pool
    for (int i = 0; i < logEntryCount; i++) {
        free(logEntries[i]);
    }
    free(logEntries);
    free(memoryPool);

    return NULL; 
}

int main() {
    parseAndAnalyzeLogFiles("path/to/log/files");
    return 0;
}
