import pandas as pd
import requests
from threading import Thread
from queue import Queue
from logging import getLogger
import time
import random
import math
import os

# Initialize logger
logger = getLogger(__name__)

class DataProcessor:
    def __init__(self):
        self.configs = []
        self.threads = []

    def process_data(self, config_list):
        self.configs = config_list
        for config in self.configs:
            self.process_config(config)

    def process_config(self, config):
        filter_params = config['filter']
        agg_method = config['agg']
        output_format = config['output']

        data = []
        for param in filter_params:
            if param['type'] == 'date':
                data.append([{'column': 'Date', 'value': random.date()}])
            else:
                data.append([{'column': param['name'], 'value': random.randint(0, 100)}])

        df = pd.DataFrame(data)
        filtered_df = self.apply_filter(df, filter_params)

        aggregated_df = self.apply_agg(filtered_df, agg_method)

        report = self.generate_report(aggregated_df, output_format)
        print(report)

    def apply_filter(self, df, filter_params):
        for param in filter_params:
            if param['type'] == 'date':
                df = df[df[param['column']] >= param['value']]
            else:
                df = df[(df[param['name']] >= param['min']) & (df[param['name']] <= param['max'])]
        return df

    def apply_agg(self, df, agg_method):
        if agg_method == 'sum':
            return df.sum()
        elif agg_method == 'avg':
            return df.mean()
        else:
            raise ValueError(f"Unsupported aggregation method: {agg_method}")

    def generate_report(self, df, output_format):
        if output_format == 'csv':
            return df.to_csv(index=False)
        elif output_format == 'json':
            return df.to_json(orient='records')
        else:
            raise ValueError(f"Unsupported output format: {output_format}")

    def run_api_requests_concurrently(self, api_configs, queue):
        threads = []
        for config in api_configs:
            thread = Thread(target=self.make_api_request, args=(config, queue))
            thread.start()
            threads.append(thread)
        for thread in threads:
            thread.join()

    def make_api_request(self, config, queue):
        try:
            response = requests.get(config['url'])
            if response.status_code == 200:
                data = response.json()
                queue.put(data)
            else:
                logger.error(f"Failed to retrieve data from {config['url']} with status code {response.status_code}")
        except Exception as e:
            logger.error(f"Error making API request: {str(e)}")

    def store_data_in_database(self, data):
        try:
            # Connect to database
            db = sqlite3.connect('data.db')
            cursor = db.cursor()

            # Store data in database
            for row in data:
                cursor.execute("INSERT INTO data VALUES (:column1, :column2)", {'column1': row['column1'], 'column2': row['column2']})
            db.commit()
        except Exception as e:
            logger.error(f"Error storing data in database: {str(e)}")
        finally:
            # Close database connection
            db.close()

    def monitor_system_resource_utilization(self):
        while True:
            cpu_usage = psutil.cpu_percent()
            memory_usage = psutil.virtual_memory().percent
            disk_usage = psutil.disk_usage('/').percent

            print(f"CPU usage: {cpu_usage}%")
            print(f"Memory usage: {memory_usage}%")
            print(f"Disk usage: {disk_usage}%")

            time.sleep(1)

if __name__ == '__main__':
    processor = DataProcessor()

    # Example dataset configurations
    config_list = [
        {'filter': [{'type': 'date', 'column': 'Date', 'value': 2022-01-01}], 
         'agg': 'sum', 
         'output': 'csv'},
        {'filter': [{'type': 'number', 'name': 'Age', 'min': 20, 'max': 30}], 
         'agg': 'avg', 
         'output': 'json'}
    ]

    processor.process_data(config_list)
