// Function to calculate the MD5 hash of a large file
std::string calculate_md5_large_file(const std::string& filename) {
    // Initialize the MD5 hash
    unsigned char md5[16];

    // Open the file in binary read mode
    std::ifstream file(filename, std::ios::binary);

    if (!file.is_open()) {
        return "Error opening file";
    }

    // Check if the file is larger than 10GB
    off_t fileSize = file.tellg();
    if (fileSize > 10240 * 1000 * 1000) {
        // Handle large files by using memory-mapped I/O
        int chunkSize = 1024 * 1024; // 1MB chunks
        char* mapBuffer = new char[chunkSize];
        off_t bytesRead = 0;

        while (bytesRead < fileSize) {
            file.seekg(bytesRead);
            file.read(mapBuffer, chunkSize);

            // Calculate the MD5 hash of each chunk
            // ...

            bytesRead += chunkSize;
        }

        // Clean up
        delete[] mapBuffer;
    } else {
        // Handle small files using regular I/O
        char buffer[1024];

        while (file.read(buffer, 1024)) {
            // Calculate the MD5 hash of each block
            // ...
        }
    }

    // Return the calculated MD5 hash
    return std::string((char*)md5, 16);
}

// Function to compute the MD5 hash of a large file in Java
public class ComputeMD5Hash {
    public static String computeMD5Hash(String filename) throws IOException {
        try (FileInputStream file = new FileInputStream(filename)) {
            // Initialize the MD5 hash
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Check if the file is larger than 10GB
            long fileSize = file.getChannel().size();
            if (fileSize > 10240 * 1000 * 1000) {
                // Handle large files by using memory-mapped I/O
                int chunkSize = 1024 * 1024; // 1MB chunks
                ByteBuffer buffer = ByteBuffer.allocate(chunkSize);

                while (file.getChannel().position() < fileSize) {
                    file.getChannel().read(buffer);
                    md.update(buffer.array());

                    buffer.rewind();
                }

                return bytesToHex(md.digest());
            } else {
                // Handle small files using regular I/O
                int bytesRead;
                byte[] buffer = new byte[1024];

                while ((bytesRead = file.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
            }

            return bytesToHex(md.digest());
        }
    }

    public static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();

        for (int i = 0; i < bytes.length; i++) {
            String f = Integer.toHexString(bytes[i] & 0xFF);
            if (f.length() == 1) {
                f = "0" + f;
            }

            hexString.append(f);
        }

        return hexString.toString();
    }
}
