typedef struct {
    AuditRecord* records;
    int capacity;
    int size;
} AuditArray;

AuditArray* audit_array_create(int initialCapacity) {
    AuditArray* arr = (AuditArray*)malloc(sizeof(AuditArray));
    arr->capacity = initialCapacity;
    arr->size = 0;
    arr->records = (AuditRecord*)calloc(initialCapacity, sizeof(AuditRecord));
    return arr;
}

void audit_array_free(AuditArray* arr) {
    free(arr->records);
    free(arr);
}

int audit_array_add_record(AuditArray* arr, int userId, time_t timestamp, const char* action, const char* ipAddress) {
    if (arr->size >= arr->capacity) {
        // Double capacity when full
        arr->capacity *= 2;
        arr->records = (AuditRecord*)realloc(arr->records, sizeof(AuditRecord) * arr->capacity);
    }
    AuditRecord* record = &arr->records[arr->size++];
    record->userId = userId;
    record->timestamp = timestamp;
    strcpy(record->action, action);
    if (ipAddress) {
        strcpy(record->ipAddress, ipAddress);
    } else {
        memset(record->ipAddress, 0, sizeof(record->ipAddress));
    }
    return arr->size - 1;
}

int audit_array_remove_record(AuditArray* arr, int index) {
    if (index >= arr->size || index < 0) {
        return -1; // Invalid index
    }
    memmove(&arr->records[index], &arr->records[index + 1], (arr->size - index - 1) * sizeof(AuditRecord));
    arr->size--;
    if (arr->size <= arr->capacity / 4) {
        // Reclaim memory when array is less than 25% full
        arr->capacity /= 2;
        arr->records = (AuditRecord*)realloc(arr->records, sizeof(AuditRecord) * arr->capacity);
    }
    return index;
}

void audit_array_serialize(const AuditArray* arr, char** jsonStr) {
    json_object* obj = json_object_new_object();
    for (int i = 0; i < arr->size; i++) {
        json_object* recordObj = json_object_new_object();
        json_object_object_add(recordObj, "userId", json_object_new_int(arr->records[i].userId));
        json_object_object_add(recordObj, "timestamp", json_object_new_int((int)arr->records[i].timestamp));
        json_object_object_add(recordObj, "action", json_object_new_string(arr->records[i].action));
        if (strlen(arr->records[i].ipAddress)) {
            json_object_object_add(recordObj, "ipAddress", json_object_new_string(arr->records[i].ipAddress));
        }
        json_object_object_add(obj, json_object_get_string(json_object_int_get_int(i)), recordObj);
    }
    *jsonStr = json_object_to_json_string_ext(obj, JSON_COMPRESSED, true);
}

int audit_array_deserialize(AuditArray* arr, char* jsonStr) {
    json_object* obj = json_parse_string(jsonStr);
    if (!obj) {
        // Handle malformed JSON
        printf("Malformed JSON\n");
        return -1;
    }
    for (json_object_object_iter iter = json_object_object_iter_first(obj); iter; json_object_object_iter_next(iter)) {
        json_object* recordObj = json_object_get_value(obj, iter.key);
        AuditRecord* record = &arr->records[arr->size++];
        record->userId = json_object_get_int(recordObj, "userId");
        record->timestamp = (time_t)json_object_get_int(recordObj, "timestamp");
        strcpy(record->action, json_object_get_string(recordObj, "action"));
        if (strlen(json_object_get_string(recordObj, "ipAddress"))) {
            strcpy(record->ipAddress, json_object_get_string(recordObj, "ipAddress"));
        } else {
            memset(record->ipAddress, 0, sizeof(record->ipAddress));
        }
    }
    return arr->size;
}
