#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <algorithm>
#include <thread>
#include <mutex>
#include <condition_variable>

class LogEntry {
public:
    uint64_t timestamp;
    int logLevel;
    std::string message;

    LogEntry(uint64_t timestamp, int logLevel, const std::string& message)
        : timestamp(timestamp), logLevel(logLevel), message(message) {}
};

class LogManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    uint64_t entryCount = 0;
    std::map<uint64_t, LogEntry*> entries;

public:
    void addLogEntry(LogEntry* entry) {
        std::unique_lock<std::mutex> lock(mtx);
        entries[entryCount++] = entry;
        cv.notify_one();
    }

    void removeLogEntry(uint64_t index) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index < entryCount) {
            delete entries[index];
            for (uint64_t i = index; i < entryCount - 1; ++i) {
                entries[i] = entries[i + 1];
            }
            --entryCount;
        }
    }

    void iterateLogEntries(const std::function<void(LogEntry*)>& callback) {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            callback(it->second);
        }
    }

    uint64_t getEntryCount() const {
        return entryCount;
    }

    double getAverageMessageLength() const {
        double totalLength = 0;
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            totalLength += it->second->message.size();
        }
        return totalLength / entryCount;
    }

    int64_t getTotalSizeInBytes() const {
        int64_t totalSize = 0;
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            totalSize += it->second->message.size();
        }
        return totalSize;
    }

    void serializeLogEntries(std::ofstream& file) const {
        std::unique_lock<std::mutex> lock(mtx);
        for (auto it = entries.begin(); it != entries.end(); ++it) {
            file.write(reinterpret_cast<const char*>(it->second), sizeof(LogEntry));
        }
    }

    void deserializeLogEntries(std::ifstream& file) {
        LogEntry* entry;
        while (file.read(reinterpret_cast<char*>(&entry), sizeof(LogEntry))) {
            addLogEntry(entry);
            delete entry;
        }
    }
};

class RollingLogManager : public LogManager {
private:
    uint64_t logSizeLimit = 1000000; // 10 million entries
    uint64_t oldEntriesLimit = 50000; // 50,000 entries

public:
    void addLogEntry(LogEntry* entry) override {
        if (entryCount > logSizeLimit) {
            removeOldEntries();
        }
        LogManager::addLogEntry(entry);
    }

    void removeOldEntries() {
        std::unique_lock<std::mutex> lock(mtx);
        while (entryCount > oldEntriesLimit) {
            removeLogEntry(0);
        }
    }
};

class FileHasher {
public:
    map<string, pair<string, string>> calculateFileHashes(const vector<string>& files) {
        map<string, pair<string, string>> fileHashes;
        for (const auto& file : files) {
            try {
                ifstream fin(file, ios::binary | ios::ate);
                if (!fin) {
                    fileHashes[file] = make_pair("Failed to open file", "Failed to open file");
                } else {
                    MD5 md5;
                    SHA256 sha256;
                    uint64_t fileSize = fin.tellg();
                    fin.seekg(0, ios::beg);

                    uint64_t bytesRead = 0;
                    while (bytesRead < fileSize) {
                        char buffer[65536];
                        fin.read(buffer, sizeof(buffer));
                        bytesRead += fin.gcount();

                        md5.update(buffer, min(fileSize - bytesRead, sizeof(buffer)));
                        sha256.update(buffer, min(fileSize - bytesRead, sizeof(buffer)));
                    }

                    string md5Hex = md5.finalize();
                    string sha256Hex = sha256.finalize();
                    fileHashes[file] = make_pair(md5Hex, sha256Hex);
                }
            } catch (const exception& e) {
                fileHashes[file] = make_pair("Error calculating hash", e.what());
            }
        }
        return fileHashes;
    }

    pair<string, string> getHash(const string& file) {
        map<string, pair<string, string>> fileHashes = calculateFileHashes({file});
        if (fileHashes.find(file) != fileHashes.end()) {
            return fileHashes[file];
        } else {
            return make_pair("Unknown", "Unknown");
        }
    }
};

int main() {
    RollingLogManager logManager;
    LogEntry entry1(1643723400, 1, "This is a test message.");
    LogEntry entry2(1643723410, 2, "Another log entry.");
    logManager.addLogEntry(&entry1);
    logManager.addLogEntry(&entry2);

    FileHasher fileHasher;
    vector<string> files = {"file1.txt", "file2.txt"};
    map<string, pair<string, string>> fileHashes = fileHasher.calculateFileHashes(files);

    return 0;
}

