#include <iostream>
#include <fstream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <functional>
#include <memory>
#include <unordered_map>
#include <bitset>

class LogEntry {
public:
    time_t timestamp;
    LogLevel logLevel;
    std::shared_ptr<char> message;

    // constructor
    LogEntry(time_t timestamp, LogLevel logLevel, const char* message) : 
        timestamp(timestamp), logLevel(logLevel), message(std::make_shared<char[]>(strlen(message) + 1)) {
            strcpy(message.get(), message);
        }
};

class LogManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::vector<std::shared_ptr<LogEntry>> logs;
    int capacity = 10000000; // 10 million entries
    time_t rollOverTime = time(NULL) + (60 * 60 * 24); // 1 day

public:
    LogManager() {
        for(int i = 0; i < capacity; i++) {
            logs.push_back(std::make_shared<LogEntry>(time(0), LogLevel::INFO, "Initial Entry"));
        }
    }

    void insert(const LogEntry& entry) {
        std::unique_lock<std::mutex> lock(mtx);
        if(logs.size() >= capacity) {
            // rolling log mechanism
            for(auto it = logs.begin(); it != logs.end();) {
                if(it->get()->timestamp < rollOverTime) {
                    it = logs.erase(it);
                } else {
                    ++it;
                }
            }
        }
        logs.push_back(std::make_shared<LogEntry>(entry.timestamp, entry.logLevel, entry.message));
    }

    void remove(time_t timestamp) {
        std::unique_lock<std::mutex> lock(mtx);
        for(auto it = logs.begin(); it != logs.end();) {
            if(it->get()->timestamp == timestamp) {
                it = logs.erase(it);
                return;
            }
            ++it;
        }
    }

    void iterate(std::function<void(const LogEntry&)> func) {
        std::unique_lock<std::mutex> lock(mtx);
        for(auto it = logs.begin(); it != logs.end();) {
            func(*it);
            ++it;
        }
    }

    // real-time statistics
    int getLogCount() {
        std::lock_guard<std::mutex> lock(mtx);
        return logs.size();
    }

    size_t getTotalSize() {
        std::lock_guard<std::mutex> lock(mtx);
        size_t total = 0;
        for(auto it = logs.begin(); it != logs.end(); ++it) {
            total += strlen(it->get()->message.get());
        }
        return total;
    }

    double getAverageMessageLength() {
        std::lock_guard<std::mutex> lock(mtx);
        size_t total = 0;
        int count = 0;
        for(auto it = logs.begin(); it != logs.end(); ++it) {
            total += strlen(it->get()->message.get());
            count++;
        }
        return static_cast<double>(total) / count;
    }

    // hash computation
    std::unordered_map<std::string, std::pair<std::string, std::string>> computeHashes(const std::vector<std::string>& files) {
        std::unordered_map<std::string, std::pair<std::string, std::string>> hashes;

        for(auto file : files) {
            std::ifstream ifs(file);
            if(!ifs.is_open()) {
                continue;
            }

            std::bitset<64> md5(0), sha256(0);

            while(true) {
                char buffer[1024];
                size_t bytesRead = ifs.read(buffer, 1024).gcount();
                if(bytesRead == 0) break;

                for(size_t i = 0; i < bytesRead; ++i) {
                    md5[i] = static_cast<std::bitset<64>::size_type>(buffer[i]);
                    sha256[i] = static_cast<std::bitset<64>::size_type>(buffer[i]);
                }

                ifs.seekg(-bytesRead, std::ios_base::cur);
            }

            hashes[file] = {{md5.to_string()}, {sha256.to_string()}};
        }

        return hashes;
    }
};

