// Structure for linked list of u_char arrays (IP addresses)
typedef struct {
    u_char* ip;
    struct node* next;
} node;

node* head = NULL;

void add_ip(char* ip) {
    node* new_node = (node*)malloc(sizeof(node));
    new_node->ip = (u_char*)malloc(16);
    strcpy((char*)new_node->ip, ip);
    new_node->next = head;
    head = new_node;
}

int dns_resolve(char* hostname) {
    // Perform DNS resolution using standard library
    struct hostent* host = gethostbyname(hostname);
    if (!host) {
        return -1;  // Error resolving hostname
    }

    char* ip = inet_ntoa(*((struct in_addr*)host->h_addr));
    add_ip(ip);

    return 0;  // Success
}

int main() {
    dns_resolve("example.com");
    return 0;
}
