typedef struct {
    int timestamp;
    char metric_name[64];
    double* value;
} MetricData;

typedef struct {
    pthread_mutex_t lock;
    size_t capacity;
    size_t size;
    MetricData** data;
} CircularBuffer;

CircularBuffer* circular_buffer_init(size_t capacity) {
    CircularBuffer* buffer = malloc(sizeof(CircularBuffer));
    buffer->capacity = capacity;
    buffer->size = 0;
    buffer->data = malloc(capacity * sizeof(MetricData*));
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void circular_buffer_free(CircularBuffer* buffer) {
    for (size_t i = 0; i < buffer->capacity; ++i) {
        if (buffer->data[i] != NULL) {
            free(buffer->data[i]->value);
            free(buffer->data[i]);
        }
    }
    pthread_mutex_destroy(&buffer->lock);
    free(buffer->data);
    free(buffer);
}

MetricData* circular_buffer_append(CircularBuffer* buffer, int timestamp, const char* metric_name, double value) {
    MetricData* data = malloc(sizeof(MetricData));
    data->timestamp = timestamp;
    strcpy(data->metric_name, metric_name);
    data->value = malloc(sizeof(double));
    *data->value = value;
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size >= buffer->capacity) {
        // Implement garbage collection mechanism here
    }
    buffer->data[buffer->size++] = data;
    pthread_mutex_unlock(&buffer->lock);
    return data;
}

void circular_buffer_flush(CircularBuffer* buffer) {
    for (size_t i = 0; i < buffer->size; ++i) {
        free(buffer->data[i]->value);
        free(buffer->data[i]);
    }
    buffer->size = 0;
}

double circular_buffer_aggregate_min(CircularBuffer* buffer, const char* metric_name) {
    pthread_mutex_lock(&buffer->lock);
    double min_value = INFINITY;
    for (size_t i = 0; i < buffer->size; ++i) {
        MetricData* data = buffer->data[i];
        if (strcmp(data->metric_name, metric_name) == 0) {
            min_value = fmin(min_value, *data->value);
        }
    }
    pthread_mutex_unlock(&buffer->lock);
    return min_value;
}

double circular_buffer_aggregate_max(CircularBuffer* buffer, const char* metric_name) {
    pthread_mutex_lock(&buffer->lock);
    double max_value = -INFINITY;
    for (size_t i = 0; i < buffer->size; ++i) {
        MetricData* data = buffer->data[i];
        if (strcmp(data->metric_name, metric_name) == 0) {
            max_value = fmax(max_value, *data->value);
        }
    }
    pthread_mutex_unlock(&buffer->lock);
    return max_value;
}

double circular_buffer_aggregate_average(CircularBuffer* buffer, const char* metric_name) {
    pthread_mutex_lock(&buffer->lock);
    double sum = 0.0;
    size_t count = 0;
    for (size_t i = 0; i < buffer->size; ++i) {
        MetricData* data = buffer->data[i];
        if (strcmp(data->metric_name, metric_name) == 0) {
            sum += *data->value;
            ++count;
        }
    }
    pthread_mutex_unlock(&buffer->lock);
    return sum / count;
}

