int parseAndAnalyzeLogFiles(const char *directoryPath, void** logEntriesPool, size_t** logEntriesCapacity) {
    DIR *dir = opendir(directoryPath);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", directoryPath);
        return -1;
    }

    struct dirent *ent;
    LogEntry* logEntries = NULL;
    size_t logEntriesSize = 0;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        FILE *file = fopen(directoryPath, "r");
        if (!file) {
            fprintf(stderr, "Failed to open log file: %s\n", ent->d_name);
            fclose(file);
            return -1;
        }

        char line[1024];
        LogEntry* currentLogEntry = NULL;

        while (fgets(line, sizeof(line), file)) {
            // Parse the log entry
            // ...

            // Allocate memory for the log entry if necessary
            if (!logEntries || logEntriesSize >= *logEntriesCapacity) {
                size_t newCapacity = *logEntriesCapacity * 2;
                void* newData = my_malloc(newCapacity * sizeof(LogEntry));
                if (!newData) {
                    fprintf(stderr, "Out of memory\n");
                    fclose(file);
                    return -1;
                }
                memcpy(newData, logEntries, logEntriesSize * sizeof(LogEntry));
                my_free(logEntries);
                logEntries = newData;
                *logEntriesCapacity = newCapacity;
            }

            if (!currentLogEntry) {
                currentLogEntry = (LogEntry*) ((char*) logEntries + logEntriesSize * sizeof(LogEntry));
            }
        }

        fclose(file);

        // Handle any exceptions and continue processing
    }

    closedir(dir);
    return 0;
}
