// Function to dynamically allocate memory for a variable number of NFAPI_CRC_INDICATION_PDU_T structures
int allocate_memory(int num_structures) {
    int allocated = 0;
    void** structures = (void**)malloc(num_structures * sizeof(void*));

    if (!structures) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return allocated;
    }

    for (int i = 0; i < num_structures; i++) {
        LogEntry* structure = (LogEntry*)malloc(sizeof(LogEntry));
        if (!structure) {
            printf("Memory allocation failed: %s\n", strerror(errno));
            break;
        }
        structure->timestamp = rand();
        structure->log_level = 'D';
        char* message = malloc(1024);
        sprintf(message, "Message %d", i);
        structure->message = message;
        structures[i] = structure;
        allocated++;
    }

    if (allocated > 0) {
        printf("Allocated %d structures successfully.\n", allocated);
    } else {
        printf("No structures allocated due to memory allocation failures.\n");
    }

    for (int i = 0; i < allocated; i++) {
        LogEntry* structure = structures[i];
        printf("Structure %d: Timestamp - %d, Log Level - %c, Message - %s\n", i, structure->timestamp, structure->log_level, structure->message);
        free(structure->message);
        free(structure);
    }

    for (int i = 0; i < allocated; i++) {
        free(structures[i]);
    }
    free(structures);

    return allocated;
}

// Function to initialize a doubly-linked list of LogEntry structures
LogEntry* create_log_entry(int timestamp, char log_level) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = malloc(1024);
    sprintf(entry->message, "Message");
    return entry;
}

// Function to iterate over the linked list and print all entries
void print_log_entries(LogEntry* head) {
    LogEntry* current = head;
    while (current) {
        printf("Timestamp: %d, Log Level: %c, Message: %s\n", current->timestamp, current->log_level, current->message);
        free(current->message);
        current = current->next;
    }
}

// Function to implement a garbage collection mechanism
void gc(LogEntry* head) {
    LogEntry* current = head;
    while (current) {
        if (current->next == NULL) {
            // Reclaim memory for the entry and its message
            free(current->message);
            free(current);
            head = current->prev;
            break;
        }
        current = current->next;
    }
}

// Function to implement thread-safe mechanisms for concurrent access
void* thread_safe_allocation(int size) {
    void* allocation = malloc(size);
    if (!allocation) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }
    return allocation;
}
