import yaml
import requests
import logging

def update_manifest(manifest_file, env_vars, resource_limits):
    with open(manifest_file, 'r') as f:
        manifest = yaml.safe_load(f)

    for container in manifest['spec']['containers']:
        if container.get('env'):
            for env_var in container['env']:
                if env_var['name'] in env_vars:
                    try:
                        value = requests.get(env_vars[env_var['name']]).json()
                        env_var['value'] = str(value)
                    except (requests.exceptions.RequestException, ValueError):
                        raise Exception(f"Failed to retrieve value for {env_var['name']}")

        if container.get('resources'):
            for resource in container['resources'].get('limits', {}).keys():
                if resource in resource_limits:
                    try:
                        value = requests.get(resource_limits[resource]).json()
                        container['resources']['limits'][resource] = str(value)
                    except (requests.exceptions.RequestException, ValueError):
                        raise Exception(f"Failed to retrieve value for {resource}")

    with open(manifest_file, 'w') as f:
        yaml.dump(manifest, f)

def main():
    logging.basicConfig(level=logging.INFO)
    manifest_file = "deployment.yaml"
    env_vars = {"MY_VAR": "https://api.example.com/myvar"}
    resource_limits = {"CPU": "https://api.example.com/cpu", "MEMORY": "https://api.example.com/memory"}

    try:
        update_manifest(manifest_file, env_vars, resource_limits)
        logging.info("Manifest updated successfully")
    except Exception as e:
        logging.error(f"Error updating manifest: {e}")

if __name__ == "__main__":
    main()
