#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <mutex>

class KVStore {
public:
    KVStore(size_t num_nodes) : nodes_(num_nodes), lock_() {}

    void put(const std::string& key, const std::string& value) {
        size_t node_id = hash(key) % nodes_;
        Node* node = &nodes_[node_id];
        std::lock_guard<stdlock> lock(lock_);
        node->put(key, value);
    }

    std::string get(const std::string& key) {
        size_t node_id = hash(key) % nodes_;
        Node* node = &nodes_[node_id];
        std::lock_guard<stdlock> lock(lock_);
        return node->get(key);
    }

private:
    struct Node {
        std::unordered_map<std::string, std::string> data;
        std::mutex lock;

        void put(const std::string& key, const std::string& value) {
            data[key] = value;
        }

        std::string get(const std::string& key) {
            return data.find(key)->second;
        }
    };

    size_t nodes_;
    std::vector<Node> nodes_;
    std::mutex lock;
};

int main() {
    KVStore store(10);
    store.put("key1", "value1");
    store.put("key2", "value2");
    std::cout << store.get("key1") << std::endl;
    return 0;
}
