void insert_log_entry(LogEntry* entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->entry = *entry;
    new_node->next = ll_head;
    if (ll_head == NULL) {
        pthread_mutex_init(&new_node->mutex, NULL);
    }
    ll_head = new_node;
}

void remove_log_entry(LogEntry* entry) {
    Node* current = ll_head;
    Node* previous = NULL;
    while (current != NULL && current->entry.message != entry->message) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) return; // not found
    pthread_mutex_lock(&current->mutex);
    if (--current->entry.refCount > 0) {
        pthread_mutex_unlock(&current->mutex);
        return; // message still in use
    }
    free(current->entry.message);
    if (previous != NULL) {
        previous->next = current->next;
    } else {
        ll_head = current->next;
    }
    free(current);
}

