    if (fd == -1) {
        perror("open");
        return 1;
    }

    while (true) {
        // iterate and print log entries
        Node* head = ll_head;
        while (head != NULL) {
            pthread_mutex_lock(&head->mutex);
            fprintf(fd, "%ld %d: %s\n", head->entry.timestamp, head->entry.logLevel, head->entry.message);
            pthread_mutex_unlock(&head->mutex);
            head = head->next;
        }

        // rotate logs every 1000 entries or 1MB size
        if (rotation_threshold <= 0 || ll_head == NULL) {
            rotation_threshold = 1000; // reset threshold
            rotation_size = 1024 * 1024; // reset size
        } else {
            rotation_threshold -= 1;
            rotation_size -= 4096; // assume 4KB per entry
