typedef struct {
    time_t timestamp;
    enum { DEBUG, INFO, WARNING, ERROR } level;
    char* message;
    int refcount;
} LogEntry;

typedef struct {
    LogEntry* head;
    pthread_mutex_t lock;
    size_t pool_size;
    void** memory_pool;
    int log_level;
    FILE* output_file;
} LogList;

void init_log_entry(LogEntry* entry) {
    entry->timestamp = time(NULL);
    entry->level = DEBUG;
    entry->refcount = 1;
}

LogList* create_log_list(size_t pool_size, int log_level, FILE* output_file) {
    LogList* list = malloc(sizeof(LogList));
    pthread_mutex_init(&list->lock, NULL);
    list->pool_size = pool_size;
    list->memory_pool = calloc(pool_size, sizeof(void*));
    list->head = NULL;
    list->log_level = log_level;
    list->output_file = output_file;
    return list;
}

void destroy_log_list(LogList* list) {
    LogEntry* current = list->head;
    LogEntry* next;
    while (current != NULL) {
        next = current->next;
        free(current->message);
        if (--current->refcount == 0) {
            free(current);
        }
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list->memory_pool);
    free(list);
}

void log_entry(LogList* list, LogEntry* entry) {
    pthread_mutex_lock(&list->lock);
    if (entry != NULL && list->log_level <= entry->level) {
        fwrite(entry->message, 1, strlen(entry->message), list->output_file);
    }
    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Example usage:
    LogList* log_list = create_log_list(1024, DEBUG, stdout);
    LogEntry* entry = malloc(sizeof(LogEntry));
    init_log_entry(entry);
    strcpy(entry->message, "This is a debug message");
    log_entry(log_list, entry);
    free(entry);
    destroy_log_list(log_list);
    return 0;
}
