DoublyLinkedList* dll_init(size_t initial_capacity) {
    DoublyLinkedList* list = malloc(sizeof(DoublyLinkedList));
    list->head = NULL;
    list->tail = NULL;
    list->capacity = initial_capacity;
    list->current_size = 0;
    pthread_mutex_init(&list->lock, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void dll_insert(DoublyLinkedList* list, LogEntry* entry) {
    if (list->head == NULL) {
        list->head = entry;
        list->tail = entry;
    } else {
        entry->next = list->head;
        list->head->prev = entry;
        list->head = entry;
    }
}

void dll_remove(DoublyLinkedList* list, LogEntry* entry) {
    if (entry == list->head) {
        list->head = entry->next;
    } else {
        entry->prev->next = entry->next;
    }
    free(entry);
}

void dll_free(DoublyLinkedList* list) {
    LogEntry* current = list->head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    free(list);
}
