typedef struct {
    int64_t timestamp;
    char* metric_name;
    double* value;
} MetricData;

// Define the circular buffer structure
typedef struct {
    MetricData* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CircularBuffer;

// Initialize the circular buffer with a given initial capacity
CircularBuffer* init_buffer(size_t capacity) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->data = (MetricData*)malloc(capacity * sizeof(MetricData));
    buffer->capacity = capacity;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    return buffer;
}

// Insert a MetricData structure into the circular buffer
void insert_metric(CircularBuffer* buffer, MetricData* metric) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size == buffer->capacity) {
        // Resize the buffer when it's full
        CircularBuffer* new_buffer = init_buffer(buffer->capacity * 2);
        for (size_t i = 0; i < buffer->size; i++) {
            new_buffer->data[i] = buffer->data[i];
        }
        free(buffer->data);
        buffer = new_buffer;
    }
    buffer->data[buffer->size++] = *metric;
    pthread_mutex_unlock(&buffer->mutex);
}

// Main function to initialize the circular buffer
int main() {
    CircularBuffer* buffer = init_buffer(10);

    // Insert some MetricData structures into the buffer
    insert_metric(buffer, (MetricData){.timestamp=0, .metric_name="metric1", .value=&(double){1.2}});
    insert_metric(buffer, (MetricData){.timestamp=1, .metric_name="metric2", .value=&(double){3.4}});
