#define MAX_TASKS 50000
#define MAX_DESC_SIZE 1024
#define ROLLING_PERIOD 3600 // one hour in seconds

typedef struct {
    int priority;
    time_t expiration_time;
    char* desc;
} Task;

Task* pq[MAX_TASKS];
int pq_size = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void enqueue(Task* task) {
    pthread_mutex_lock(&lock);
    pq[pq_size++] = task;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);
}

Task* dequeue() {
    Task* task = NULL;
    pthread_mutex_lock(&lock);
    while (pq_size == 0) {
        pthread_cond_wait(&cond, &lock);
    }
    task = pq[0];
    memmove(pq, pq+1, sizeof(Task*) * (pq_size-1));
    pq_size--;
    pthread_mutex_unlock(&lock);
    return task;
}

void clear() {
    for (int i = 0; i < pq_size; i++) {
        free(pq[i]->desc);
        free(pq[i]);
    }
    pq_size = 0;
}

