// Define the structure for LogEntry
typedef struct LogEntry {
    int timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Define the structure for doubly-linked list node
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create a new log entry
LogEntry* createLogEntry(int timestamp, int logLevel, char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = timestamp;
    entry->logLevel = logLevel;
    entry->message = message;
    return entry;
}

// Function to create a new node in the linked list
Node* createNode(LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to add a new log entry to the linked list
void addLogEntry(Node** head, LogEntry* entry) {
    Node* newNode = createNode(entry);
    if (*head == NULL) {
        *head = newNode;
    } else {
        newNode->next = *head;
        (*head)->prev = newNode;
        *head = newNode;
    }
}

// Function to print the log entries
void printLogEntries(Node* head) {
    Node* current = head;
    while (current != NULL) {
        LogEntry* entry = current->entry;
        printf("Timestamp: %d, LogLevel: %d, Message: %s\n", entry->timestamp, entry->logLevel, entry->message);
        current = current->next;
    }
}

// Function to free the memory allocated for log entries and nodes
void freeLogEntries(Node* head) {
    Node* current = head;
    while (current != NULL) {
        LogEntry* entry = current->entry;
        free(entry->message);
        free(current);
        current = current->next;
    }
}

int main() {
    // Create a new log entry
    int timestamp = 1643723400;
    int logLevel = 1;
    char* message = "Hello, world!";
    LogEntry* entry = createLogEntry(timestamp, logLevel, message);

    // Add the log entry to the linked list
    Node* head = NULL;
    addLogEntry(&head, entry);

    // Print the log entries
    printLogEntries(head);

    // Free the memory allocated for log entries and nodes
    freeLogEntries(head);

    return 0;
}
