app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'Redis', 'CACHE_REDIS_URL': 'redis://localhost:6379/0'})
es = Elasticsearch(['elasticsearch://localhost:9200'])

@app.route('/cache/<string:path>', methods=['GET', 'PUT', 'DELETE'])
def cache_handler(path):
