// Structure for MetricData
typedef struct {
    time_t timestamp;
    char* metric_name;
    double* value;
} MetricData;

// Circular Buffer Structure
typedef struct {
    int size;
    int capacity;
    MetricData** data;
    int head;
    int tail;
    int count;
} CircularBuffer;

// Function to initialize the circular buffer
CircularBuffer* init_circular_buffer(int capacity) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->size = 0;
    buffer->capacity = capacity;
    buffer->data = (MetricData**)malloc(capacity * sizeof(MetricData*));
    buffer->head = 0;
    buffer->tail = 0;
    return buffer;
}

// Function to add a new metric data entry
void add_metric_data(CircularBuffer* buffer, time_t timestamp, char* metric_name, double value) {
    MetricData* data = (MetricData*)malloc(sizeof(MetricData));
    data->timestamp = timestamp;
    data->metric_name = (char*)malloc(strlen(metric_name) + 1);
    strcpy(data->metric_name, metric_name);
    data->value = &value;

    if(buffer->size == buffer->capacity) {
        // Reallocate memory when the buffer is full
        buffer->data = (MetricData**)realloc(buffer->data, buffer->capacity * 2 * sizeof(MetricData*));
        buffer->capacity *= 2;
    }

    // Add new data to the end of the buffer
    int idx = buffer->tail % buffer->capacity;
    buffer->data[idx] = data;
    buffer->tail = (buffer->tail + 1) % buffer->capacity;

    if(buffer->size == 0) {
        buffer->head = buffer->tail;
    }

    buffer->size++;
}

// Function to get the metric data at a specific index
MetricData* get_metric_data(CircularBuffer* buffer, int idx) {
    if(idx < 0 || idx >= buffer->size) {
        return NULL;
    }
    int real_idx = (idx + buffer->head) % buffer->capacity;
    return buffer->data[real_idx];
}

// Function to print the metric data in the circular buffer
void print_metric_data(CircularBuffer* buffer) {
    for(int i = 0; i < buffer->size; i++) {
        MetricData* data = get_metric_data(buffer, i);
        printf("Timestamp: %ld, Metric Name: %s, Value: %.2f\n", (long)data->timestamp, data->metric_name, *(data->value));
    }
}

// Function to free the memory used by the circular buffer
void free_circular_buffer(CircularBuffer* buffer) {
    for(int i = 0; i < buffer->size; i++) {
        MetricData* data = get_metric_data(buffer, i);
        free(data->metric_name);
        free(data->value);
        free(data);
    }
    free(buffer->data);
    free(buffer);
}

int main() {
    CircularBuffer* buffer = init_circular_buffer(10);

    add_metric_data(buffer, 1643723400, "Metric1", 12.5);
    add_metric_data(buffer, 1643723410, "Metric2", 15.8);
    add_metric_data(buffer, 1643723420, "Metric3", 9.4);

    print_metric_data(buffer);

    free_circular_buffer(buffer);

    return 0;
}

