import requests
import logging

logging.basicConfig(level=logging.INFO)

def replace_placeholders(config_file, placeholders):
    new_content = ""
    with open(config_file, "r") as file:
        for line in file:
            for placeholder, value in placeholders.items():
                line = line.replace(placeholder, str(value))
            new_content += line
    return new_content

def encrypt_password(password, salt):
    hash_object = hashlib.sha256((str(salt) + password).encode())
    return hash_object.hexdigest()

def get_pokemon_weaknesses(pokemon_name):
    pokemon_type = get_pokemon_type(pokemon_name)
    weaknesses = ""
    if pokemon_type == "fire":
        weaknesses += "water"
    elif pokemon_type == "water":
        weaknesses += "fire"
    # ... (add more types and weaknesses as needed)
    return weaknesses

def process_config_files(configs):
    for config in configs:
        placeholders = {key: value["value"] for key, value in config.items()}
        new_file_content = replace_placeholders("config.txt", placeholders)
        salt = int(datetime.now().timestamp())
        password = encrypt_password(str(salt), salt)
        new_file_name = f"config_{salt}.txt"
        with open(new_file_name, "w") as file:
            file.write(new_file_content + "\n" + password)

def get_pokemon_type(pokemon_name):
    response = requests.get(f"https://pokeapi.co/api/v2/pokemon/{pokemon_name}/")
    if response.status_code == 200:
        data = response.json()
        return data["types"][0]["type"]["name"]
    else:
        return None

if __name__ == "__main__":
    try:
