            {"fire_place_holder": {"value": "1234"}, "water_place_holder": {"value": "5678"}},
            {"another_fire_place_holder": {"value": "9012"}, "yet_another_water_place_holder": {"value": "3456"}}
        ])
    except Exception as e:
        logging.error(f"Error occurred: {str(e)}")
