```c
#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

#define MAX_CAPACITY 1000
#define GROWTH_FACTOR 2.0
#define BUFFER_SIZE sizeof(MetricData)

typedef struct {
    time_t timestamp;
    char metric_name[32];
    double value;
} MetricData;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
MetricData *buffer;
int read_index, write_index;
int capacity, size;

void *myalloc(size_t size) {
    return malloc(size);
}

void myfree(void *ptr) {
    free(ptr);
}

void *malloc_wrapper(size_t size) {
    void *ptr = myalloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int buffer_grow() {
    int new_capacity = (int) (capacity * GROWTH_FACTOR);
    MetricData *new_buffer = (MetricData *) malloc_wrapper(new_capacity * BUFFER_SIZE);

    if (!new_buffer) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    memcpy(new_buffer, buffer, capacity * BUFFER_SIZE);
    myfree(buffer);
    buffer = new_buffer;
    capacity = new_capacity;
    size = 0;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int insert_metric(MetricData data) {
    pthread_mutex_lock(&mutex);
    if (size == capacity) {
        if (buffer_grow() < 0)
            return -1;
    }

    buffer[write_index] = data;
    write_index = (write_index + 1) % capacity;
    size++;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int get_metric(int index, MetricData *data) {
    if (index >= size)
        return -1;

    pthread_mutex_lock(&mutex);
    *data = buffer[read_index];
    read_index = (read_index + 1) % capacity;
    size--;
    pthread_mutex_unlock(&mutex);

    return 0;
}

int main() {
    // Initialize the buffer
    capacity = MAX_CAPACITY;
    buffer = (MetricData *) malloc_wrapper(capacity * BUFFER_SIZE);
    if (!buffer) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    read_index = write_index = 0;
    size = 0;

    // Perform operations on the buffer
    insert_metric(data1);
    get_metric(index, data);

    return 0;
}
