```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int timestamp;
    char log_level;
    char* message;
    int ref_count;
} LogEntry;

// Custom memory pool structure
typedef struct {
    void** blocks;
    size_t block_size;
    size_t used;
    size_t capacity;
} MemoryPool;

MemoryPool* init_memory_pool(size_t initial_capacity) {
    MemoryPool* mp = malloc(sizeof(MemoryPool));
    mp->blocks = (void**)malloc(initial_capacity * sizeof(void*));
    mp->block_size = 0;
    mp->used = 0;
    mp->capacity = initial_capacity;
    return mp;
}

void free_memory_pool(MemoryPool* mp) {
    for (size_t i = 0; i < mp->used; ++i) {
        free(mp->blocks[i]);
    }
    free(mp->blocks);
    free(mp);
}

// Doubly-linked list node structure
typedef struct Node {
    LogEntry entry;
    struct Node* next;
    struct Node* prev;
} Node;

Node* init_node(LogEntry* entry, MemoryPool* mp) {
    Node* node = (Node*)malloc/mp->block_size);
    node->entry = *entry;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

void free_node(Node* node, MemoryPool* mp) {
    if (node != NULL) {
        free(node);
    }
}

// Linked list operations
Node* init_list() {
    // Initialize the head and tail nodes
    Node* head = NULL;
    Node* tail = NULL;

    return head;
}

void append_node(Node** head, Node** tail, LogEntry* entry, MemoryPool* mp) {
    Node* node = init_node(entry, mp);
    if (*head == NULL && *tail == NULL) {
        *head = node;
        *tail = node;
    } else {
        node->prev = *tail;
        (*tail)->next = node;
        *tail = node;
    }
}

void clear_list(Node** head, Node** tail) {
    while (*head != NULL && *tail != NULL) {
        Node* next = (*head)->next;
        free_node(*head, mp);
        *head = next;
    }
    if (*head == NULL && *tail == NULL) {
        // List is empty
        return;
    }

    // Free the remaining nodes in the list
    while (*head != NULL) {
        Node* next = (*head)->next;
        free_node(*head, mp);
        *head = next;
    }
}

// LogEntry operations

void init_log_entry(LogEntry* entry, int timestamp, char log_level, const char* message, MemoryPool* mp) {
    entry->timestamp = timestamp;
    entry->log_level = log_level;
    entry->message = (char*)malloc(strlen(message) + 1);
    strcpy(entry->message, message);
    entry->ref_count = 1;
}

void free_log_entry(LogEntry* entry, MemoryPool* mp) {
    if (entry != NULL && --entry->ref_count == 0) {
        free(entry->message);
        free(entry);
    }
}

// Duplicate a LogEntry structure
LogEntry* duplicate_log_entry(LogEntry* entry, MemoryPool* mp) {
    LogEntry* new_entry = malloc(sizeof(LogEntry));
    *new_entry = *entry;
    new_entry->ref_count++;
    return new_entry;
}

void print_entries(Node* head, int fd) {
    while (head != NULL) {
        fwrite(&head->entry, sizeof(LogEntry), 1, fd);
        head = head->next;
    }
}
