typedef struct {
    int id;
    int count;
    double median;
    double variance;
    struct {
        double values[1000];
        int head, tail;
    } recent;
} device_t;

device_t* devices = NULL;
int device_count = 0;
double max_variance_ratio = -1.0;
int max_device_id = -1;

void update_device(device_t* device) {
    if (device->count < 1000) {
        device->values[device->tail] = device->recent.values[device->head];
        device->head = (device->head + 1) % 1000;
        device->count++;
    }
    device->median = median(device->values, device->count);
    device->variance = variance(device->values, device->count, device->median);
}

double median(double* values, int count) {
    double medians[2];
    if (count % 2 == 0)
        medians[0] = (values[count/2 - 1] + values[count/2]) / 2.0;
    else
        medians[0] = values[count/2];
    int i, j;
    for (i = 0; i < count; i++) {
        double minv = medians[0], maxv = medians[0];
        for (j = 0; j < count; j++) {
            if (values[j] < minv)
                minv = values[j];
            else if (values[j] > maxv)
                maxv = values[j];
        }
        medians[1] = (minv + maxv) / 2.0;
    }
    return (medians[0] + medians[1]) / 2.0;
}

double variance(double* values, int count, double median) {
    double mean, sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += (values[i] - median);
    }
    mean = sum / count;
    sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += pow((values[i] - mean), 2.0);
    }
    return sqrt(sum / count);
}

void process_data(double value, int device_id) {
    int found = 0;
    for (int i = 0; i < device_count; i++) {
        if (devices[i].id == device_id) {
            devices[i].recent.values[devices[i].tail] = value;
            devices[i].tail = (devices[i].tail + 1) % 1000;
            devices[i].count++;
            found = 1;
            break;
        }
    }
    if (!found) {
        device_t* new_device = (device_t*)malloc(sizeof(device_t));
        new_device->id = device_id;
        new_device->count = 1;
        new_device->tail = 0;
        new_device->head = 0;
        memcpy(new_device->values, &value, sizeof(double));
        devices = (device_t*)realloc(devices, sizeof(device_t) * ++device_count);
        devices[device_count - 1] = *new_device;
        free(new_device);
    }
    for (int i = 0; i < device_count; i++) {
        if (devices[i].count > 0 && devices[i].tail - devices[i].head >= 5) {
            double age = difftime(clock(), devices[i].recent.values[devices[i].head]) / CLOCKS_PER_SEC;
            int data_point_count = devices[i].count - (1000 - (devices[i].tail - devices[i].head));
            if (age < 10 && data_point_count <= 10) {
                double variance_ratio = devices[i].variance / abs(devices[i].median);
                if (variance_ratio > max_variance_ratio) {
                    max_variance_ratio = variance_ratio;
                    max_device_id = devices[i].id;
                }
            }
        }
    }
}

int main() {
    // Initialize your IoT devices and start processing data.
