```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_TRACE,
    LOG_LEVEL_NONE
} LogLevel;

typedef struct {
    time_t timestamp;
    LogLevel level;
    char* message;
    char* metadata;
} LogEntry;

// Doubly linked list node structure
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize the doubly linked list
Node* init_list() {
    return NULL;
}

// Function to append a new log entry to the list
void append_log_entry(Node** head, LogEntry* new_entry) {
    // Allocate memory for new node
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Error: Could not allocate memory for new node.\n");
        return;
    }

    // Set new entry in the new node
    new_node->entry = new_entry;

    // If list is empty, set new node as head
    if (*head == NULL) {
        *head = new_node;
    } else {
        // Find last node in the list and append new node after it
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->prev = current;
    }
}

// Function to remove a log entry from the list
void remove_log_entry(Node** head, LogEntry* entry_to_remove) {
    // Find node with the given log entry and remove it
    Node* current = *head;
    while (current != NULL) {
        if (current->entry == entry_to_remove) {
            // Update previous and next nodes
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                *head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            }

            // Free memory for removed node
            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to serialize the log entries to a file descriptor
void serialize_log_entries(int fd, Node* head) {
    if (head == NULL) {
        return;
    }

    // Write timestamp and level for each entry
    Node* current = head;
    while (current != NULL) {
        fwrite(&current->entry->timestamp, sizeof(time_t), 1, fd);
        fwrite(&current->entry->level, sizeof(LogLevel), 1, fd);

        // Write message length and then the message itself
        int message_len = strlen(current->entry->message);
        fwrite(&message_len, sizeof(int), 1, fd);
        fwrite(current->entry->message, sizeof(char), message_len, fd);

        if (current->entry->metadata != NULL) {
            // Write metadata length and then the metadata itself
            int metadata_len = strlen(current->entry->metadata);
            fwrite(&metadata_len, sizeof(int), 1, fd);
            fwrite(current->entry->metadata, sizeof(char), metadata_len, fd);
        } else {
            // If no metadata, write a null pointer instead
            fwrite(&current->entry->metadata, sizeof(char*), 1, fd);
        }

        current = current->next;
    }
}

// Function to deserialize the log entries from a file descriptor
Node* deserialize_log_entries(int fd) {
    Node* head = NULL;

    // Read timestamp and level for each entry
    time_t timestamp;
    LogLevel level;
    while (fread(&timestamp, sizeof(time_t), 1, fd) == 1 && fread(&level, sizeof(LogLevel), 1, fd) == 1) {
        LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
        if (!new_entry) {
            printf("Error: Could not allocate memory for log entry.\n");
            return NULL;
        }

        int message_len;
        fread(&message_len, sizeof(int), 1, fd);
        char* message = (char*)malloc(message_len * sizeof(char));
        if (!message) {
            printf("Error: Could not allocate memory for message.\n");
            free(new_entry);
            return NULL;
        }
        fread(message, sizeof(char), message_len, fd);

        int metadata_len;
        char* metadata = NULL;
        fread(&metadata_len, sizeof(int), 1, fd);
        if (metadata_len > 0) {
            metadata = (char*)malloc(metadata_len * sizeof(char));
            if (!metadata) {
                printf("Error: Could not allocate memory for metadata.\n");
                free(new_entry);
                return NULL;
            }
            fread(metadata, sizeof(char), metadata_len, fd);
        }

        new_entry->timestamp = timestamp;
        new_entry->level = level;
        new_entry->message = message;
        new_entry->metadata = metadata;

        // Add the log entry to the list
        append_log_entry(&head, new_entry);
    }

    return head;
}

int main() {
    // Initialize the doubly linked list
    Node* head = init_list();

    // Append some log entries to the list
    LogEntry* entry1 = (LogEntry*)malloc(sizeof(LogEntry));
    entry1->timestamp = time(NULL);
    entry1->level = LOG_LEVEL_ERROR;
    entry1->message = "Error message 1";
    entry1->metadata = "Metadata for error 1";

    LogEntry* entry2 = (LogEntry*)malloc(sizeof(LogEntry));
    entry2->timestamp = time(NULL) + 10;
    entry2->level = LOG_LEVEL_WARNING;
    entry2->message = "Warning message 2";
    entry2->metadata = "Metadata for warning 2";

    append_log_entry(&head, entry1);
    append_log_entry(&head, entry2);

    // Serialize the log entries to a file
    int fd = open("log_entries.bin", O_RDWR | O_CREAT, S_IRUSR | S_IWUSR);
    serialize_log_entries(fd, head);
    close(fd);

    return 0;
}
```
