def processLargeFile(filename):
    chunk_size = 1024 * 1024  # Default to 1MB chunks

    with open(filename, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk: break

            # Apply transformations
            chunk = chunk.decode().lower()  # Normalize
            chunk = gzip.compress(chunk.encode())  # Compress
            chunk = set(chunk)  # Deduplicate
            chunk = hashlib.md5(chunk.encode()).hexdigest()

            print(f"Transformed {filename} ({chunk_size / (1024 * 1024)} MB): {chunk}")

    return chunk

def read_file(file_path):
    try:
        with open(file_path, 'rb') as file:
            return file.read()
    except FileNotFoundError:
        print(f"{file_path} not found")
    except PermissionError:
        print(f"Permission denied for {file_path}")
    except IOError as e:
        print(f"I/O error: {e}")

