    table->data = (MetricData*)malloc(capacity * sizeof(MetricData));
    table->capacity = capacity;
    table->size = 0;
}

// Function to insert data into the hash table
void insert_metric(HashTable* table, const char* name, int timestamp, double value, char* unit) {
    // Hash function implementation
    size_t index = (name[0] % table->capacity);

    if(table->data[index].name == NULL) {
        table->data[index].name = strdup(name);
        table->data[index].timestamp = timestamp;
        table->data[index].value = value;
        table->data[index].unit = unit;
        table->size++;
    } else {
        // Handle collision
    }
}

// Function to compute aggregated metrics for each metric in the hash table
void aggregate_metrics(HashTable* table) {
    // Iterate over the hash table and compute sum, average, and maximum value for each metric
    for(size_t i = 0; i < table->capacity; i++) {
        if(table->data[i].name != NULL) {
            double sum = 0;
            int count = 0;

            for(int j = 0; j < timestamp; j++) {
                MetricData* metric = &table->data[i];
                sum += metric->value;
                count++;
            }

            if(count > 0) {
                printf("Metric: %s, Sum: %.2f, Average: %.2f, Maximum: %.2f\n", 
                       table->data[i].name, sum, (sum / count), *(table->data[i].unit));
            }
        }
    }
}

// Function to free memory allocated by the hash table
void free_hash_table(HashTable* table) {
    for(size_t i = 0; i < table->capacity; i++) {
        if(table->data[i].name != NULL) {
            free(table->data[i].name);
            free(table->data[i].unit);
        }
    }
    free(table->data);
}
