private:
    void processNetworkStream(const std::string& streamUrl) {
        Aws::S3::S3Client s3Client;
        Aws::S3::Model::GetObjectRequest request(streamUrl, "log.txt");
        Aws::S3::Model::GetObjectOutcome outcome = s3Client.GetObject(request);
        if (outcome.IsSuccess()) {
            std::string logData = outcome.GetResult().getBody();
            processLog(logData);
        } else {
            // Handle errors
            std::cerr << "Error processing network stream: " << outcome.GetError().getMessage() << std::endl;
        }
    }

    void processLocalDirectory(const std::string& directoryPath) {
        for (const auto& filePath : recursiveDirectoryTraversal(directoryPath)) {
            std::ifstream logFile(filePath);
            if (logFile.is_open()) {
                std::string logData((std::istreambuf_iterator<char>(logFile)), std::istreambuf_iterator<char>());
                processLog(logData);
                logFile.close();
            } else {
                // Handle errors
                std::cerr << "Error processing local directory: " << filePath << std::endl;
            }
        }
    }

    void processS3Bucket(const std::string& bucketName) {
        Aws::S3::S3Client s3Client;
        Aws::S3::Model::ListObjectsRequest request(bucketName, "");
        Aws::S3::Model::ListObjectsOutcome outcome = s3Client.ListObjects(request);
        if (outcome.IsSuccess()) {
