                std::string logData;
                Aws::S3::Model::GetObjectRequest getObjectRequest(bucketName, object.GetKey());
                Aws::S3::Model::GetObjectOutcome getObjectOutcome = s3Client.GetObject(getObjectRequest);
                if (getObjectOutcome.IsSuccess()) {
                    logData = getObjectOutcome.GetResult().getBody();
                    processLog(logData);
                } else {
                    // Handle errors
                    std::cerr << "Error processing S3 bucket: " << object.GetKey() << std::endl;
                }
            }
        } else {
            // Handle errors
            std::cerr << "Error processing S3 bucket: " << outcome.GetError().getMessage() << std::endl;
        }
    }

    void processLog(const std::string& logData) {
