typedef struct {
    int id;
    long timestamp;
    int priority;
    void* payload;
    size_t payload_size;
} Message;

Message* buffer[BUFFER_SIZE];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int buffer_head = 0;
int buffer_tail = 0;
int messages_count = 0;
int garbage_collection_interval = GARAGE_COLLECTION_INTERVAL;

void initialize_circular_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i] = NULL;
    }
}

Message* allocate_payload(size_t size) {
    void* payload = malloc(size);
    if (!payload) {
        // Handle memory allocation error
        return NULL;
    }
    return payload;
}

void free_payload(void* payload, size_t size) {
    free(payload);
}

int is_buffer_full() {
    return (buffer_head + 1) % BUFFER_SIZE == buffer_tail;
}

int is_buffer_empty() {
    return buffer_head == buffer_tail;
}

void insert_message(Message* message) {
    pthread_mutex_lock(&mutex);
    if (!is_buffer_full()) {
        buffer[buffer_head] = message;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        messages_count++;
    }
    pthread_mutex_unlock(&mutex);
}

Message* remove_message() {
    pthread_mutex_lock(&mutex);
    Message* message = buffer[buffer_tail];
    if (!is_buffer_empty()) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        messages_count--;
    }
    pthread_mutex_unlock(&mutex);
    return message;
}
