#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_ELEMS 10000
#define POOL_SIZE 1024

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Custom memory pool
typedef struct MemoryPool {
    void* base;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

void* malloc_safe(size_t size) {
    MemoryPool* mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!mp) return NULL;
    mp->base = malloc(size);
    if (!mp->base) {
        free(mp);
        return NULL;
    }
    mp->size = size;
    pthread_mutex_init(&mp->lock, NULL);
    return mp->base;
}

void free_safe(void* ptr) {
    MemoryPool* mp = (MemoryPool*)ptr - 1;
    free(ptr);
    free(mp);
}

// Dynamic list
typedef struct DynList {
    NFAPI_CRC_INDICATION_PDU_T* elem[MAX_ELEMS];
    int count;
} DynList;

DynList* dyn_list_new() {
    DynList* dl = malloc_safe(sizeof(DynList));
    if (!dl) return NULL;
    dl->count = 0;
    for (int i = 0; i < MAX_ELEMS; i++) dl->elem[i] = NULL;
    return dl;
}

void dyn_list_free(DynList* dl) {
    free_safe(dl);
}

// Function to manage the dynamic list
NFAPI_CRC_INDICATION_PDU_T* add_element(DynList* dl, uint8_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRCFLAG) {
    if (dl->count >= MAX_ELEMS) return NULL; // List full

    for (int i = 0; i < dl->count; i++) {
        if (dl->elem[i]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) return dl->elem[i]; // Duplicate tag
    }

    NFAPI_CRC_INDICATION_PDU_T* new_elem = malloc_safe(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_elem->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_elem->RNTI = RNTI;
    new_elem->CRCFLAG = CRCFLAG;

    for (int i = dl->count; i > 0; i--) {
        if (dl->elem[i - 1]->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) { // Find the first available slot
            break;
        }
        dl->elem[i] = dl->elem[i - 1];
    }

    dl->elem[0] = new_elem;

    dl->count++;
    return new_elem;
}

NFAPI_CRC_INDICATION_PDU_T* get_element(DynList* dl, int idx) {
    if (idx < 0 || idx >= dl->count) return NULL; // Out of bounds
    return dl->elem[idx];
}

void remove_element(DynList* dl, int idx) {
    if (idx < 0 || idx >= dl->count) return; // Out of bounds

    for (int i = idx; i < dl->count - 1; i++) {
        dl->elem[i] = dl->elem[i + 1];
    }

    free_safe(dl->elem[idx]);
    dl->count--;
}

void print_list(DynList* dl) {
    for (int i = 0; i < dl->count; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", dl->elem[i]->RX_UE_INFORMATION_TAG, dl->elem[i]->RNTI, dl->elem[i]->CRCFLAG);
    }
}

int main() {
    DynList* dl = dyn_list_new();

    NFAPI_CRC_INDICATION_PDU_T* elem1 = add_element(dl, 0x10, 1234, 0x01);
    NFAPI_CRC_INDICATION_PDU_T* elem2 = add_element(dl, 0x20, 5678, 0x02);
    NFAPI_CRC_INDICATION_PDU_T* elem3 = add_element(dl, 0x10, 9012, 0x03);

    print_list(dl);

    remove_element(dl, 1);

    print_list(dl);

    dyn_list_free(dl);

    return 0;
}
