DoublyLinkedList* dll_init() {
    DoublyLinkedList* dll = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    dll->head = NULL;
    dll->tail = NULL;
    pthread_mutex_init(&dll->lock, NULL);
    pthread_cond_init(&dll->cond, NULL);
    dll->size = 0;
    return dll;
