void dll_free(DoublyLinkedList* dll) {
    LogEntry* current = dll->head;
    while (current != NULL) {
        LogEntry* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&dll->lock);
    free(dll);
}

void dll_insert(DoublyLinkedList* dll, LogEntry* entry) {
    pthread_mutex_lock(&dll->lock);
    if (dll->head == NULL) {
        dll->head = entry;
        dll->tail = entry;
    } else {
        entry->prev = dll->tail;
        dll->tail->next = entry;
        dll->tail = entry;
    }
    dll->size++;
    pthread_cond_signal(&dll->cond);
    pthread_mutex_unlock(&dll->lock);
}

void dll_remove(DoublyLinkedList* dll, LogEntry* entry) {
    pthread_mutex_lock(&dll->lock);
    if (entry->prev != NULL) {
        entry->prev->next = entry->next;
    } else {
        dll->head = entry->next;
    }
    if (entry->next != NULL) {
        entry->next->prev = entry->prev;
    } else {
        dll->tail = entry->prev;
    }
    free(entry->message);
    free(entry);
    dll->size--;
    pthread_mutex_unlock(&dll->lock);
}

