// Function to manage the circular buffer
MetricData* init_metric_buffer(int capacity) {
    // Initialize the circular buffer with the given capacity
    MetricData* buffer = (MetricData*)malloc(sizeof(MetricData) * capacity);
    pthread_mutex_init(&buffer->mutex, NULL);  // Initialize mutex for synchronization
    return buffer;
}

void metric_insert(MetricData* buffer, int index, const char* name, double value) {
    // Insert a new metric entry into the circular buffer
    MetricData* entry = &buffer[index];
    entry->timestamp = time(NULL);
    entry->name = strdup(name);
    entry->value = (double*)malloc(sizeof(double));
    *entry->value = value;
}

void metric_aggregate(MetricData* buffer, int index) {
    // Aggregate metrics for the given index
    double sum = 0.0;
    int count = 0;
    for (int i = 0; i < capacity; i++) {
        if (buffer[i].timestamp <= buffer[index].timestamp) {
            sum += *buffer[i].value;
            count++;
        }
    }
    // Calculate min, max, and average values
    double min = INFINITY, max = -INFINITY;
    for (int i = 0; i < capacity; i++) {
        if (buffer[i].timestamp <= buffer[index].timestamp) {
            if (*buffer[i].value < min)
                min = *buffer[i].value;
            if (*buffer[i].value > max)
                max = *buffer[i].value;
        }
    }
}

// Function to manage the doubly linked list
LogEntry* init_log_list() {
    LogEntry* head = NULL, *tail = NULL;
    pthread_mutex_init(&head->mutex, NULL);  // Initialize mutex for synchronization
    return head;
}

void log_append(LogEntry* head, const char* message, int level) {
    // Append a new log entry to the doubly linked list
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);
}

void log_print(LogEntry* head, time_t start, time_t end) {
    // Print log entries within the given timestamp range
    for (LogEntry* current = head; current != NULL; current = current->next) {
        if (current->timestamp >= start && current->timestamp <= end)
            printf("%s (%d): %s\n", asctime(localtime(&current->timestamp)), current->level, current->message);
    }
}

void log_free(LogEntry* head) {
    // Free the linked list and all associated resources
    for (LogEntry* current = head; current != NULL;) {
        LogEntry* next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
}
