#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define a struct to represent log entries
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define a struct to manage the logging system
typedef struct {
    size_t capacity;
    size_t size;
    LogEntry** entries;
    pthread_mutex_t lock;
    FILE* output_file;
    int filter_level;
    float profiling_time;
} Logger;

// Function to initialize and configure the logger
Logger* init_logger(size_t capacity, int default_output) {
    Logger* logger = malloc(sizeof(Logger));
    logger->capacity = capacity;
    logger->size = 0;
    logger->entries = (LogEntry**)malloc(logger->capacity * sizeof(LogEntry*));
    pthread_mutex_init(&logger->lock, NULL);
    if(default_output == FILE_OUTPUT) {
        logger->output_file = fopen("log.txt", "a");
    } else {
        logger->output_file = stdout;
    }
    logger->filter_level = DEBUG_LEVEL;
    logger->profiling_time = 0.0;
    return logger;
}

// Function to add a new log entry
void add_log_entry(Logger* logger, int level, const char* message) {
    pthread_mutex_lock(&logger->lock);

    // Resize the log buffer if necessary
    if(logger->size == logger->capacity) {
        logger->capacity *= 2;
        logger->entries = (LogEntry**)realloc(logger->entries, logger->capacity * sizeof(LogEntry*));
    }

    LogEntry* entry = malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);
    logger->entries[logger->size++] = entry;

    // Filter log entries based on their level
    if(logger->filter_level > level) {
        free(entry->message);
        free(entry);
        --logger->size;
    }

    pthread_mutex_unlock(&logger->lock);
}

// Function to iterate over log entries and print them
void print_log_entries(Logger* logger) {
    pthread_mutex_lock(&logger->lock);

    for(size_t i = 0; i < logger->size; ++i) {
        LogEntry* entry = logger->entries[i];

        // Print the log entry based on its level
        if(entry->level >= logger->filter_level) {
            printf("%s [%d] %s\n", ctime(&entry->timestamp), entry->level, entry->message);

            // Profile the time taken to append a new log entry
            static int count = 0;
            ++count;
            float profiling_time = (float)(clock() - start_time) / CLOCKS_PER_SEC;
            if(count >= 100) {
                logger->profiling_time += profiling_time;
                printf("Average time to append log entry: %f seconds\n", logger->profiling_time / count);
                count = 0;
            }
        }

        free(entry->message);
        free(entry);
    }

    pthread_mutex_unlock(&logger->lock);
}

// Function to rotate log files
void rotate_log_files(Logger* logger, size_t threshold) {
    pthread_mutex_lock(&logger->lock);

    // Check if the current log file has reached the specified threshold
    if(fseek(logger->output_file, 0, SEEK_END) == -1 || ftell(logger->output_file) >= threshold) {
        // Create a new log file and move the old one to it
        FILE* temp = fopen("log_temp.txt", "w");
        fwrite(logger->entries[0]->message, sizeof(char), logger->size * 20, temp);
        fclose(temp);

        // Rename the temporary log file to the original name
        rename("log_temp.txt", "log.txt");
    }

    pthread_mutex_unlock(&logger->lock);
}

// Function to shut down the logging system
void shutdown_logger(Logger* logger) {
    pthread_mutex_lock(&logger->lock);

    // Free memory and close files
    for(size_t i = 0; i < logger->size; ++i) {
        free(logger->entries[i]->message);
        free(logger->entries[i]);
    }
    free(logger->entries);
    fclose(logger->output_file);

    pthread_mutex_unlock(&logger->lock);
    free(logger);
}
