            pthread_t* new_workers = (pthread_t*)realloc(workers, num_workers * sizeof(pthread_t));
            for (int i = 0; i < num_workers - current_load; i++) {
                pthread_create(&new_workers[i], NULL, &worker_thread, NULL);
