// Function to calculate the MD5 hash of a file given its path
void* calculate_MD5_hash(char* file_path) {
    // Create a dynamic array to store the chunks of the file
    char** file_chunks = (char**)malloc(1024 * sizeof(char*));

    FILE* file_pointer = fopen(file_path, "rb");
    if (file_pointer == NULL) {
        printf("Error opening file: %s\n", file_path);
        return NULL;
    }

    fseek(file_pointer, 0, SEEK_END);
    int file_size = ftell(file_pointer);
    rewind(file_pointer);

    // Calculate the MD5 hash of the file
    unsigned char* md5_hash = (unsigned char*)malloc(16 * sizeof(unsigned char));
    hashlib.md5();
    while (!feof(file_pointer)) {
        int chunk_size = fread((void*)file_chunks, 1, 1024, file_pointer);
        for (int i = 0; i < chunk_size; i++) {
            hashlib.update((void*)&file_chunks[i], 1);
        }
    }

    // Verify the integrity of the file by comparing the calculated hash with a provided checksum
    unsigned char* checksum = (unsigned char*)malloc(16 * sizeof(unsigned char));
    if (fread(checksum, 1, 16, file_pointer) != 16) {
        printf("Error reading checksum\n");
        return NULL;
    }

    for (int i = 0; i < 16; i++) {
        if (md5_hash[i] != checksum[i]) {
            printf("Hash verification failed: MD5 hash does not match the provided checksum.\n");
            return NULL;
        }
    }

    // Log successful hash calculation
    printf("MD5 hash calculated successfully.\n");

    return md5_hash;
}

// Function to simulate network latency and packet loss during hash verification
void* verify_MD5_hash(char* file_path, unsigned char* md5_hash) {
    FILE* file_pointer = fopen(file_path, "rb");
    if (file_pointer == NULL) {
        printf("Error opening file: %s\n", file_path);
        return NULL;
    }

    fseek(file_pointer, 0, SEEK_END);
    int file_size = ftell(file_pointer);
    rewind(file_pointer);

    // Simulate network latency and packet loss
    for (int i = 0; i < file_size; i++) {
        if (rand() % 100 < 20) {
            printf("Packet lost during hash verification.\n");
            continue;
        }
        usleep(10000); // simulate 10ms latency

        char* chunk = (char*)malloc(1024 * sizeof(char));
        fread(chunk, 1, 1024, file_pointer);
        if (ferror(file_pointer)) {
            printf("Error reading file.\n");
            return NULL;
        }

        // Verify the integrity of the file by comparing the calculated hash with a provided checksum
        unsigned char* checksum = (unsigned char*)malloc(16 * sizeof(unsigned char));
        if (fread(checksum, 1, 16, file_pointer) != 16) {
            printf("Error reading checksum\n");
            return NULL;
        }

        for (int j = 0; j < 16; j++) {
            if (md5_hash[j] != checksum[j]) {
                printf("Hash verification failed: MD5 hash does not match the provided checksum.\n");
                return NULL;
            }
        }

        free(chunk);
    }

    // Log successful hash verification
    printf("MD5 hash verified successfully.\n");

    return md5_hash;
}

int main() {
    int num_structures = 100;
    void* nfa_pi_crc_indication_pdu_t_array = generate_NFAPI_CRC_INDICATION_PDU_T(num_structures);

    char* file_path = "example.txt";
    unsigned char* md5_hash = calculate_MD5_hash(file_path);

    if (md5_hash == NULL) {
        return 1;
    }

    void* verified_md5_hash = verify_MD5_hash(file_path, md5_hash);

    free(nfa_pi_crc_indication_pdu_t_array);
    free(md5_hash);
    free(verified_md5_hash);

    return 0;
}
