// Initialize a new session table with default settings
SessionTable* create_session_table(int initial_capacity) {
    SessionTable* table = (SessionTable*)malloc(sizeof(SessionTable));
    table->size = 0;
    table->capacity = initial_capacity;
    table->sessions = (Session**)calloc(initial_capacity, sizeof(Session*));
    return table;
}

// Initialize a new session with specified ID and expiration time
Session* create_session(int id, time_t expiration) {
    Session* session = (Session*)malloc(sizeof(Session));
    session->id = id;
    session->expiration = expiration;
    session->profile = NULL; // dynamically allocated user profile structure will be set later
    return session;
}

// Add a new session to the table and update garbage collection interval if necessary
void add_session(SessionTable* table, Session* session) {
    if (table->size >= table->capacity) {
        table->capacity *= 2; // double the capacity
        table->sessions = (Session**)realloc(table->sessions, table->capacity * sizeof(Session*));
    }
    table->sessions[table->size++] = session;
}

// Free all allocated memory in the session table and its sessions
void destroy_session_table(SessionTable* table) {
    for (int i = 0; i < table->size; i++) {
        Session* session = table->sessions[i];
        if (session != NULL) {
            free(session->profile); // free dynamically allocated user profile structure
            free(session);
        }
    }
    free(table->sessions);
    free(table);
}

// Iterate over the session table and invalidate expired sessions
void garbage_collect(SessionTable* table, int interval) {
    time_t current_time = time(NULL);
    for (int i = 0; i < table->size; i++) {
        Session* session = table->sessions[i];
        if (session != NULL && session->expiration <= current_time) {
            // invalidate expired session
            free(session->profile); // free dynamically allocated user profile structure
            free(session);
            memmove(&table->sessions[i], &table->sessions[i + 1], (table->size - i - 1) * sizeof(Session*));
            table->size--;
        }
    }
}

