} NetworkEvent;

void initNetworkEvents(NetworkEvent** events, int* size);
void clearNetworkEvents(NetworkEvent** events, int* size);
int iterateOverNetworkEvents(NetworkEvent** events, int size, void (*callback)(NetworkEvent*, void*), void* arg);
int filterNetworkEvents(NetworkEvent** events, int size, void (*callback)(NetworkEvent*, void*), void* arg);
void serializeNetworkEvents(FILE* file, NetworkEvent** events, int size);
int deserializeNetworkEvents(FILE* file, NetworkEvent*** events, int* size);

int main() {
    // Example usage
    NetworkEvent* events = NULL;
    int eventCount = 0;

    initNetworkEvents(&events, &eventCount);

    // Add events
    for (int i = 0; i < 5; i++) {
        NetworkEvent event;
        event.timestamp = i * 1000; // seconds
        event.type = 'A' + i % 3;
        event.description = malloc(strlen("Some description ") + 1);
        strcpy(event.description, "Some description ");
        events[eventCount++] = &event;
    }

    // Filter events
    int filteredCount = filterNetworkEvents(&events, eventCount, (void (*)(NetworkEvent*, void*))filterByTypeAndTimestamp, (void*) "A");

    // Serialize and deserialize
    FILE* file = fopen("network_events.bin", "wb");
    serializeNetworkEvents(file, &events, eventCount);
    fclose(file);

    NetworkEvent* deserializedEvents = NULL;
    int deserializedCount = 0;

    file = fopen("network_events.bin", "rb");
    deserializedCount = deserializeNetworkEvents(file, &deserializedEvents, &eventCount);
    fclose(file);

    // Iterate over and print events
    for (int i = 0; i < eventCount; i++) {
        printf("%d: %c - %s\n", events[i]->timestamp, events[i]->type, events[i]->description);
    }

    clearNetworkEvents(&events, &eventCount);

    return 0;
}

// Filter function to filter by type and timestamp
int filterByTypeAndTimestamp(NetworkEvent* event, void* arg) {
    char targetType = *(char*)arg;
    int minTimestamp = 2000; // seconds
    int maxTimestamp = 4000; // seconds

    if (event->type == targetType && event->timestamp >= minTimestamp && event->timestamp <= maxTimestamp) {
        return 1;
    }
    return 0;
}

// Filter function to filter by type
int filterByType(NetworkEvent* event, void* arg) {
    char targetType = *(char*)arg;

    if (event->type == targetType) {
        return 1;
    }
    return 0;
}

void freeNetworkEvents(NetworkEvent** events, int size) {
    for (int i = 0; i < size; i++) {
        free(events[i]->description);
        free(events[i]);
    }
}

void clearNetworkEvents(NetworkEvent** events, int* size) {
    freeNetworkEvents(events, *size);
    *size = 0;
}

int iterateOverNetworkEvents(NetworkEvent** events, int size, void (*callback)(NetworkEvent*, void*), void* arg) {
    for (int i = 0; i < size; i++) {
        callback(events[i], arg);
    }
    return size;
}

int filterNetworkEvents(NetworkEvent** events, int size, void (*callback)(NetworkEvent*, void*), void* arg) {
    int filteredCount = 0;

    iterateOverNetworkEvents(events, size, callback, arg);

    for (int i = 0; i < size; i++) {
        if (!callback(events[i], arg)) {
            events[filteredCount++] = events[i];
        } else {
            free(events[i]->description);
            free(events[i]);
        }
    }

    memmove(events, events + filteredCount, sizeof(NetworkEvent*) * (size - filteredCount));

    return filteredCount;
}

void serializeNetworkEvents(FILE* file, NetworkEvent** events, int size) {
    for (int i = 0; i < size; i++) {
        fwrite(&events[i]->timestamp, sizeof(int), 1, file);
        fwrite(&events[i]->type, sizeof(char), 1, file);
        int len = strlen(events[i]->description);
        fwrite(&len, sizeof(int), 1, file);
        fwrite(events[i]->description, sizeof(char), len + 1, file);
    }
}

int deserializeNetworkEvents(FILE* file, NetworkEvent*** events, int* size) {
    *size = 0;

    while (fread(&temp->timestamp, sizeof(int), 1, file)) {
        temp->type = fgetc(file);
        fread(&len, sizeof(int), 1, file);
        temp->description = malloc(len + 1);
        fread(temp->description, sizeof(char), len + 1, file);

        if (*size > 0) {
            NetworkEvent* prev = events[*size - 1];
            events[*size] = temp;
            free(prev->description);
            free(prev);
        } else {
            *events = malloc(sizeof(NetworkEvent));
            **events = temp;
        }
        (*size)++;
    }

    return *size;
