#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_EVENTS 1000
#define MEMORY_THRESHOLD (1024 * 1024 * 10) // 10MB

typedef struct {
    time_t timestamp;
    int type;
    char* description;
} NetworkEvent;

NetworkEvent* events = NULL;
int num_events = 0;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* serialize_events(void* ptr) {
    // Serialize the event collection to a binary file
    FILE* file = fopen("events.bin", "wb");
    if (!file) {
        perror("Failed to open events.bin for writing");
        return NULL;
    }

    fwrite(&num_events, sizeof(int), 1, file);
    for (int i = 0; i < num_events; i++) {
        NetworkEvent* event = &events[i];
        fwrite(&event->timestamp, sizeof(time_t), 1, file);
        fwrite(&event->type, sizeof(int), 1, file);
        size_t len = strlen(event->description);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(event->description, 1, len + 1, file);
    }

    fclose(file);
    return NULL;
}

void deserialize_events(void* ptr) {
    // Deserialize the event collection from a binary file
    FILE* file = fopen("events.bin", "rb");
    if (!file) {
        perror("Failed to open events.bin for reading");
        return;
    }

    int num_events_to_read;
    fread(&num_events_to_read, sizeof(int), 1, file);
    NetworkEvent* new_events = (NetworkEvent*)calloc(num_events_to_read, sizeof(NetworkEvent));
    if (!new_events) {
        perror("Failed to allocate memory for deserialized events");
        return;
    }

    for (int i = 0; i < num_events_to_read; i++) {
        time_t timestamp;
        int type;
        size_t len;
        fread(&timestamp, sizeof(time_t), 1, file);
        fread(&type, sizeof(int), 1, file);
        fread(&len, sizeof(size_t), 1, file);
        char* description = (char*)malloc(len + 1);
        fread(description, 1, len + 1, file);
        new_events[i].timestamp = timestamp;
        new_events[i].type = type;
        new_events[i].description = description;

        // Update the global event collection
        pthread_mutex_lock(&mutex);
        events = realloc(events, (num_events + i) * sizeof(NetworkEvent));
        if (!events) {
            perror("Failed to reallocate memory for updated event collection");
            return;
        }
        memcpy(&events[num_events], &new_events[i], sizeof(NetworkEvent));
        num_events += i;
        pthread_mutex_unlock(&mutex);
    }

    free(new_events);
    fclose(file);
}

void add_event(time_t timestamp, int type, const char* description) {
    // Add a new event to the collection
    if (num_events >= capacity) {
        capacity *= 2; // Dynamically resize the array
        events = realloc(events, capacity * sizeof(NetworkEvent));
    }

    NetworkEvent* event = &events[num_events++];
    event->timestamp = timestamp;
    event->type = type;
    size_t len = strlen(description);
    event->description = (char*)malloc(len + 1);
    strcpy(event->description, description);

    // Monitor and limit memory usage
    if ((size_t)num_events * sizeof(NetworkEvent) > MEMORY_THRESHOLD) {
        fprintf(stderr, "Memory threshold exceeded. Limiting further allocations.\n");
    }
}

void filter_events(int type, time_t start_time, time_t end_time) {
    // Filter events based on the specified criteria
    for (int i = 0; i < num_events; i++) {
        NetworkEvent* event = &events[i];
        if (event->type != type || event->timestamp < start_time || event->timestamp > end_time) {
            continue;
        }
        printf("Filtered event: %ld, Type: %d, Description: %s\n", event->timestamp, event->type, event->description);
    }
}

void clear_events() {
    // Clear the event collection and free allocated memory
    for (int i = 0; i < num_events; i++) {
        free(events[i].description);
    }
    free(events);
    events = NULL;
    num_events = 0;
    capacity = 0;
}

void* thread_loop(void* ptr) {
    // Simulate concurrent access to the event collection
    for (int i = 0; i < 10000; i++) {
        add_event(time(NULL), 1, "Hello");
        filter_events(1, time(NULL) - 3600, time(NULL));
    }
    return NULL;
}

int main() {
    pthread_t threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, thread_loop, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
