// Define the structure for LogEntry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define the structure for DoublyLinkedList
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the structure for DoublyLinkedList
typedef struct {
    Node* head;
    Node* tail;
} DoublyLinkedList;

// Function to initialize a doubly-linked list of LogEntry structures
DoublyLinkedList* initLogList() {
    DoublyLinkedList* log_list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    log_list->head = NULL;
    log_list->tail = NULL;
    return log_list;
}

// Function to add a new entry to the doubly-linked list
void addEntry(DoublyLinkedList* log_list, LogEntry entry) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->entry.timestamp = entry.timestamp;
    new_node->entry.level = entry.level;
    new_node->entry.message = entry.message;

    if(log_list->head == NULL) {
        log_list->head = new_node;
        log_list->tail = new_node;
    } else {
        Node* temp = log_list->head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
        new_node->prev = temp;
        log_list->tail = new_node;
    }
}

// Function to serialize the doubly-linked list to a binary format
void serializeLogList(DoublyLinkedList* log_list, FILE* file) {
    Node* current = log_list->head;
    while(current != NULL) {
        fwrite(&current->entry.timestamp, sizeof(time_t), 1, file);
        fwrite(&current->entry.level, sizeof(int), 1, file);
        size_t message_len = strlen(current->entry.message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(current->entry.message, sizeof(char), message_len + 1, file);
        current = current->next;
    }
}

// Function to deserialize the binary format back into a doubly-linked list
DoublyLinkedList* deserializeLogList(FILE* file) {
    DoublyLinkedList* log_list = initLogList();
    Node* new_node;

    while(fread(&new_node->entry.timestamp, sizeof(time_t), 1, file) == 1) {
        new_node->entry.level = fread(&new_node->entry.level, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char* message = (char*)malloc(message_len + 1);
        fread(message, sizeof(char), message_len + 1, file);
        new_node->entry.message = message;

        if(log_list->head == NULL) {
            log_list->head = new_node;
            log_list->tail = new_node;
        } else {
            Node* temp = log_list->head;
            while(temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
            new_node->prev = temp;
            log_list->tail = new_node;
        }
    }

    return log_list;
}

// Function to implement rolling log mechanism
void rollLog(DoublyLinkedList* log_list, int max_entries) {
    Node* current = log_list->head;
    while(log_list->head != NULL && log_list->head->next < max_entries) {
        free(current->entry.message);
        free(current);
        log_list->head = log_list->head->next;
    }
}

// Function to integrate with third-party monitoring service
void transmitLogs(DoublyLinkedList* log_list, char* monitoring_service_url) {
    // Implement transmission logic here
}

// Function to handle high-traffic scenarios by supporting distributed logging
void distributeLogs(DoublyLinkedList* log_list) {
    // Implement distribution logic here
}

// Function to implement garbage collection mechanism
void collectGarbage(DoublyLinkedList* log_list, int interval) {
    Node* current = log_list->head;
    while(current != NULL) {
        free(current->entry.message);
        free(current);
        current = current->next;
    }
}

// Function to support filtering logs by timestamp range and log level
void filterLogs(DoublyLinkedList* log_list, int min_timestamp, int max_timestamp, int min_level, int max_level) {
    Node* current = log_list->head;
    while(current != NULL) {
        if(current->entry.timestamp < min_timestamp || current->entry.timestamp > max_timestamp || current->entry.level < min_level || current->entry.level > max_level) {
            free(current->entry.message);
            free(current);
            current = current->next;
        } else {
            current = current->next;
        }
    }
}

// Function to implement compression algorithm for log entries during serialization
void compressLogEntries(DoublyLinkedList* log_list, FILE* file) {
    // Implement compression logic here
}

int main() {
    DoublyLinkedList* log_list = initLogList();
    // Add entries to the log list
    addEntry(log_list, ...);
    // Serialize the log list to a binary format
    serializeLogList(log_list, ...);
    // Deserialize the binary format back into a doubly-linked list
    deserializeLogList(...);
    // Implement rolling log mechanism
    rollLog(log_list, ...);
    // Integrate with third-party monitoring service
    transmitLogs(log_list, ...);
    // Handle high-traffic scenarios by supporting distributed logging
    distributeLogs(log_list);
    // Implement garbage collection mechanism
    collectGarbage(log_list, ...);
    // Support filtering logs by timestamp range and log level
    filterLogs(log_list, ..., ...);
    // Implement compression algorithm for log entries during serialization
