#define MAX_LOG_ENTRIES 10000000
#define MAX_MESSAGE_LENGTH 1024

typedef struct LogEntry {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

LogEntry* log_entries[MAX_LOG_ENTRIES];
int current_log_entry_index = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void initialize_log_system() {
    for (int i = 0; i < MAX_LOG_ENTRIES; i++) {
        log_entries[i] = NULL;
    }
}

LogEntry* add_log_entry(int timestamp, int log_level, char* message) {
    LogEntry* new_entry = malloc(sizeof(LogEntry));
    new_entry->timestamp = timestamp;
    new_entry->log_level = log_level;
    new_entry->message = message;

    pthread_mutex_lock(&lock);
    log_entries[current_log_entry_index] = new_entry;
    current_log_entry_index++;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    return new_entry;
}

void remove_log_entry(int index) {
    if (index >= 0 && index < current_log_entry_index) {
        pthread_mutex_lock(&lock);
        log_entries[index] = NULL;
        pthread_mutex_unlock(&lock);
    }
}

LogEntry* get_log_entry(int index) {
    if (index >= 0 && index < current_log_entry_index) {
        pthread_mutex_lock(&lock);
        LogEntry* entry = log_entries[index];
        pthread_mutex_unlock(&lock);
        return entry;
    } else {
        return NULL;
    }
}

void iterate_log_entries(void (*callback)(LogEntry*)) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < current_log_entry_index; i++) {
        LogEntry* entry = log_entries[i];
        if (entry) {
            callback(entry);
        }
    }

    pthread_mutex_unlock(&lock);
}

void truncate_old_entries(int days_to_keep) {
    time_t now = time(NULL);
    int index = 0;

    for (index = 0; index < current_log_entry_index; index++) {
        LogEntry* entry = log_entries[index];

        if (entry && now - entry->timestamp > (days_to_keep * 24 * 60 * 60)) {
            remove_log_entry(index);
            current_log_entry_index--;
            index--;
        }
    }
}

int main() {
    initialize_log_system();

    // Example usage
    add_log_entry(time(NULL), LOG_INFO, "Example log entry");
    iterate_log_entries((LogEntry*) => printf("%s\n", message));
    truncate_old_entries(7);

    return 0;
}
