typedef struct {
    char* filename;
    int size;
} File_Metadata;

// Define the linked list node structure
typedef struct Node {
    File_Metadata metadata;
    struct Node* next;
} Node;

// Function to initialize the dynamic linked list of File_Metadata structures
Node* init_linked_list(int max_files, int min_padding_size) {
    // Initialize the head node and allocate memory for the first node
    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) return NULL;  // Handle allocation failure

    // Set initial size of the linked list to maximum file count
    head->metadata.size = max_files;
    head->next = NULL;

    return head;
}

// Function to process each file's metadata in the linked list using a callback function
void process_linked_list(Node* head, void (*callback)(File_Metadata*)) {
    Node* current = head;
    while (current) {
        // Process the current node's metadata using the callback function
        callback(current->metadata);
        current = current->next;
    }
}

// Function to serialize the linked list into a binary format
void serialize_linked_list(Node* head, FILE* file) {
    if (!file) return;  // Handle invalid file pointer

    Node* current = head;
    while (current) {
        fwrite(&current->metadata.size, sizeof(int), 1, file);  // Serialize the metadata size
        fwrite(current->metadata.filename, strlen(current->metadata.filename) + 1, 1, file);  // Serialize the filename
        current = current->next;
    }
}

// Function to deserialize a linked list from binary data
Node* deserialize_linked_list(FILE* file) {
    if (!file) return NULL;  // Handle invalid file pointer

    Node* head = (Node*)malloc(sizeof(Node));
    if (!head) return NULL;  // Handle allocation failure

    int size;
    char filename[256];  // Temporary buffer for deserializing the filename
    fread(&size, sizeof(int), 1, file);  // Deserialize the metadata size
    while (size--) {
        head->metadata.size = size;
        fread(filename, strlen(current->metadata.filename) + 1, 1, file);  // Deserialize the filename
        head->metadata.filename = (char*)malloc(strlen(filename));  // Allocate memory for the filename
        strcpy(head->metadata.filename, filename);
        head->next = (Node*)malloc(sizeof(Node));
        if (!head->next) return NULL;  // Handle allocation failure
    }

    return head;
}

// Function to clean up the linked list and its associated memory
void cleanup_linked_list(Node* head) {
    Node* current = head;
    while (current) {
        Node* next = current->next;
        free(current->metadata.filename);  // Free the filename memory
        free(current);
        current = next;
    }
}

// Example callback function to process file metadata
