#include <stdlib.h>
#include <string.h>

typedef struct {
    char IMSI[16];
    char IP_ADDRESS[45];
    time_t LAST_ACTIVITY_TIME;
} USER_SESSION_INFO_T;

#define HASH_TABLE_SIZE 1024
#define CONCURRENCY_CONTROL_MUTEX
#define TTL_SECONDS 3600 // default TTL in seconds

// Hash table structure
typedef struct {
    USER_SESSION_INFO_T *table;
    int size;
    int count;
    pthread_mutex_t mutex;
} HASH_TABLE_T;

// Initialize and manage the hash table
void init_hash_table(HASH_TABLE_T *hash_table) {
    hash_table->size = HASH_TABLE_SIZE;
    hash_table->count = 0;
    hash_table->table = (USER_SESSION_INFO_T *)calloc(hash_table->size, sizeof(USER_SESSION_INFO_T));
    pthread_mutex_init(&hash_table->mutex, NULL);
}

// Insert a new user session into the hash table
int insert_session(HASH_TABLE_T *hash_table, USER_SESSION_INFO_T *session) {
    pthread_mutex_lock(&hash_table->mutex);

    int index = session->IMSI[0] % hash_table->size;
    for (int i = 0; i < hash_table->count; i++) {
        if (strcmp(hash_table->table[index].IMSI, session->IMSI) == 0) {
            pthread_mutex_unlock(&hash_table->mutex);
            return -1; // duplicate IMSI
        }
    }

    int new_index = hash_table->count % hash_table->size;
    memmove(&hash_table->table[new_index], &hash_table->table[index], (hash_table->count - index) * sizeof(USER_SESSION_INFO_T));
    hash_table->table[new_index] = *session;
    hash_table->count++;

    pthread_mutex_unlock(&hash_table->mutex);
    return 0; // success
}

// Delete a user session from the hash table by IMSI
int delete_session(HASH_TABLE_T *hash_table, const char *IMSI) {
    pthread_mutex_lock(&hash_table->mutex);

    int index = strcmp(imsi[0], IMSI) % hash_table->size;
    for (int i = 0; i < hash_table->count - 1; i++) {
        if (strcmp(hash_table->table[index].IMSI, IMSI) == 0) {
            memmove(&hash_table->table[index], &hash_table->table[index + 1], (hash_table->count - index - 1) * sizeof(USER_SESSION_INFO_T));
            hash_table->count--;
            break;
        }
    }

    pthread_mutex_unlock(&hash_table->mutex);
    return 0; // success
}

// Perform garbage collection to remove expired sessions
void gc_sessions(HASH_TABLE_T *hash_table, time_t now) {
    pthread_mutex_lock(&hash_table->mutex);

    for (int i = hash_table->count - 1; i >= 0; i--) {
        if ((now - hash_table->table[i].LAST_ACTIVITY_TIME) > TTL_SECONDS) {
            memmove(&hash_table->table[i], &hash_table->table[i + 1], (hash_table->count - i - 1) * sizeof(USER_SESSION_INFO_T));
            hash_table->count--;
        }
    }

    pthread_mutex_unlock(&hash_table->mutex);
}

// Reallocates the hash table to accommodate growing or shrinking loads
void resize_hash_table(HASH_TABLE_T *hash_table, int new_size) {
    pthread_mutex_lock(&hash_table->mutex);

    void *new_data = realloc(hash_table->table, new_size * sizeof(USER_SESSION_INFO_T));
    if (new_data == NULL)
        return; // failed to reallocate

    hash_table->table = new_data;
    hash_table->size = new_size;

    pthread_mutex_unlock(&hash_table->mutex);
}
