class LogEntry {
  constructor(timestamp, logLevel, message, metadata = '') {
    this.timestamp = timestamp;
    this.logLevel = logLevel;
    this.message = message;
    this.metadata = metadata;
  }
}

class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
  }

  append(entry) {
    const newNode = { prev: null, next: null, entry };
    if (!this.head) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      this.tail.next = newNode;
      newNode.prev = this.tail;
      this.tail = newNode;
    }
  }

  prepend(entry) {
    const newNode = { prev: null, next: null, entry };
    if (!this.head) {
      this.head = newNode;
      this.tail = newNode;
    } else {
      newNode.next = this.head;
      this.head.prev = newNode;
      this.head = newNode;
    }
  }

  remove(entry) {
    const current = entry;
    const prev = current.prev;
    const next = current.next;

    if (prev) prev.next = next;
    else this.head = next;
    if (next) next.prev = prev;
    else this.tail = prev;
  }

  serialize() {
    const entries = [];
    let current = this.head;
    while (current) {
      entries.push(current.entry);
      current = current.next;
    }
    return Buffer.from(JSON.stringify(entries));
  }

  deserialize(buffer) {
    const entries = JSON.parse(buffer.toString());
    for (const entry of entries) {
      this.append(entry);
    }
  }
}

async function initializeLogEntries(filePath) {
  try {
    if (!fs.existsSync(filePath)) throw new Error(`File not found: ${filePath}`);
    const fileStat = await fs.statSync(filePath);
    if (!fileStat.isFile()) throw new Error(`Invalid file type: ${filePath}`);
    const entries = [];
    let logLevelIndex = 0;
    const acceptedLogLevels = ['DEBUG', 'INFO', 'WARNING', 'ERROR', 'FATAL', 'CRITICAL', 'NOTICE', 'ALERT'];
    for await (const line of fs.readFileSync(filePath, 'utf8').split('\n')) {
      const [timestamp, logLevel, message] = line.trim().split(' ');
      const metadata = line.substring(line.indexOf(' ') + 1).trim();
      entries.push(new LogEntry(Date.now(), acceptedLogLevels[logLevelIndex], message, metadata));
      logLevelIndex++;
    }
    return new DoublyLinkedList();
  } catch (error) {
    console.error(error);
    throw error;
  }
}
