// Define a struct for log entries
typedef struct LogEntry {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Function to manage the data ingestion pipeline
int ingest_logs(char* directory_path, int batch_size) {
    // Initialize linked list head and current node
    LogEntry* head = NULL;
    LogEntry* curr = NULL;

    // Initialize error handling variables
    int err_count = 0;
    int success_count = 0;

    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return -1; // Return error code
    }

    // Iterate over log files in the specified directory
    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char file_path[256];
        sprintf(file_path, "%s/%s", directory_path, entry->d_name);

        FILE* file = fopen(file_path, "r");
        if (file == NULL) {
            perror("Failed to open log file");
            continue; // Skip to the next iteration
        }

        // Read log entries from the file and insert into linked list
        char line[1024];
        while (fgets(line, sizeof(line), file)) {
            LogEntry* new_entry = malloc(sizeof(LogEntry));

            // Parse timestamp, level, and message from log entry line
            time_t timestamp;
            int level;
            char* message;
            sscanf(line, "%lu %d %s", &timestamp, &level, &message);

            new_entry->timestamp = timestamp;
            new_entry->level = level;
            new_entry->message = message;

            // Insert the log entry into the linked list
            if (head == NULL) {
                head = new_entry;
                curr = head;
            } else {
                LogEntry* temp = head;
                while (temp->next != NULL) {
                    temp = temp->next;
                }
                temp->next = new_entry;
                curr = new_entry;
            }

            // Handle batch size limit
            if (++success_count >= batch_size) {
                break; // Exit the loop when batch size is reached
            }
        }

        fclose(file);
    }

    closedir(dir);

    // Print all log entries to a file descriptor
    FILE* output_file = fopen("output.log", "w");
    if (output_file == NULL) {
        perror("Failed to open output file");
        return -1; // Return error code
    }

    LogEntry* temp = head;
    while (temp != NULL) {
        fprintf(output_file, "%lu %d %s\n", temp->timestamp, temp->level, temp->message);
        free(temp->message); // Free allocated memory
        temp = temp->next;
    }

    fclose(output_file);

    return 0; // Return success code
}

int main() {
    int status_code = ingest_logs("/path/to/log/files", 10);
    if (status_code == -1) {
        printf("Error occurred during ingestion\n");
    } else {
        printf("Ingestion completed successfully with %d entries\n", 10); // Print success message
    }

    return 0;
}

