#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

typedef struct LinkedListNode {
    LogEntry entry;
    struct LinkedListNode* next;
} LinkedListNode;

LinkedListNode* ll_create_node(LogEntry* entry) {
    LinkedListNode* node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (!node) return NULL;
    node->entry = *entry;
    node->next = NULL;
    return node;
}

void ll_insert_node(LinkedListNode** head, LogEntry* entry) {
    LinkedListNode* new_node = ll_create_node(entry);
    if (!*head) {
        *head = new_node;
    } else {
        LinkedListNode* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void ll_free(LinkedListNode* head) {
    while (head) {
        LinkedListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

void print_entries_to_file(LinkedListNode* head, int batch_size, int fd) {
    LinkedListNode* current = head;
    int count = 0;
    while (current && (count < batch_size || !batch_size)) {
        LogEntry entry = current->entry;
        fprintf(fd, "%ld %d %s\n", entry.timestamp, entry.log_level, entry.message);
        free(entry.message);
        current = current->next;
        count++;
    }
}

int process_log_files(const char* directory_path, int batch_size, int fd) {
    DIR* dir = opendir(directory_path);
    if (!dir) return -1; // error opening directory

    LinkedListNode* head = NULL;

    pthread_t threads[5]; // adjust according to your system's capabilities
    for (int i = 0; i < 5 && (dir = readdir(dir)); i++) {
        LogEntry entry;
        char file_path[1024];
        sprintf(file_path, "%s/%s", directory_path, dir->d_name);
        FILE* file = fopen(file_path, "r");
        if (!file) continue;

        // read and process log entries
        while (fscanf(file, "%ld %d %s", &entry.timestamp, &entry.log_level, entry.message) == 3) {
            ll_insert_node(&head, &entry);
        }

        fclose(file);

        pthread_create(&threads[i], NULL, (void*)log_entry_thread_handler, &head);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    ll_free(head);
    closedir(dir);

    return 0;
}

void* log_entry_thread_handler(void* arg) {
    LinkedListNode** head = (LinkedListNode**)arg;

    // process the linked list of log entries
    while (*head) {
        LogEntry entry = (*head)->entry;
        free(entry.message); // release dynamically allocated message
        *head = (*head)->next;
    }

    return NULL;
}
