#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for LogEntry
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

// Function to initialize a doubly-linked list of LogEntry structures
LogEntry** init_log_list(int max_entries) {
    // Allocate memory for the log entries
    LogEntry** log_list = (LogEntry**)malloc(max_entries * sizeof(LogEntry*));

    // Initialize each entry with default values
    for (int i = 0; i < max_entries; i++) {
        log_list[i] = (LogEntry*)malloc(sizeof(LogEntry));
        log_list[i]->timestamp = time(NULL);
        log_list[i]->log_level = 1;
        log_list[i]->message = NULL;
    }

    return log_list;
}

// Function to free memory allocated for LogEntry
void free_log_entry(LogEntry* entry) {
    if (entry->message != NULL)
        free(entry->message);

    free(entry);
}

// Function to serialize LogEntry to binary format
int serialize_log_entry(LogEntry* entry, char** buffer, int* size) {
    // Calculate the required space for the serialized entry
    int total_size = sizeof(time_t) + sizeof(int) + strlen(entry->message) + 1;
    *size += total_size;

    // Serialize the entry and append it to the buffer
    *(time_t*)((*buffer) + (*size - sizeof(time_t))) = entry->timestamp;
    *((int*)((*buffer) + (*size - sizeof(int)))) = entry->log_level;
    memcpy((char*)(*buffer) + (*size - (strlen(entry->message) + 1)), entry->message, strlen(entry->message));
    ((char*)(*buffer))[(*size)++] = '\0';

    return total_size;
}

// Function to deserialize LogEntry from binary format
LogEntry* deserialize_log_entry(char** buffer, int size) {
    // Calculate the space required for the deserialized entry
    time_t timestamp;
    int log_level;

    if (size >= sizeof(time_t)) {
        timestamp = *(time_t*)((*buffer));
        (*buffer) += sizeof(time_t);
        size -= sizeof(time_t);

        if (size >= sizeof(int)) {
            log_level = *((int*)((*buffer)));
            (*buffer) += sizeof(int);
            size -= sizeof(int);

            // Find the end of the message
            char* message_start = *buffer;
            while ((*buffer)[0] != '\0' && size > 1) {
                (*buffer)++;
                size--;
            }

            if (size > 1)
                (*message_start)[size - 1] = '\0';

            LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
            entry->timestamp = timestamp;
            entry->log_level = log_level;
            entry->message = (char*)malloc(strlen(message_start) + 1);
            strcpy(entry->message, message_start);

            return entry;
        }
    }

    return NULL;
}

int main() {
    int max_entries = 10000; // Number of entries in the list
    LogEntry** log_list = init_log_list(max_entries);

    for (int i = 0; i < max_entries; i++) {
        // Create a new LogEntry and append it to the list
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        entry->timestamp = time(NULL);
        entry->log_level = 1;
        entry->message = NULL;

        // Serialize the entry and add it to the buffer
        char* buffer = (char*)malloc(100); // Allocate a temporary buffer
        int size = 0;
        serialize_log_entry(entry, &buffer, &size);

        // Deserialize the entry from the buffer
        LogEntry* deserialized_entry = deserialize_log_entry(&buffer, size);
        free_log_entry(deserialized_entry);

        // Free memory allocated for the original entry
        free_log_entry(entry);
    }

    return 0;
}

