void addLogEntry(Node** head, LogEntry* entry) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->entry = entry;
    newNode->next = (*head);
    newNode->prev = NULL;

    if (*head != NULL) {
        (*head)->prev = &newNode->next;
    }

    *head = &newNode;
}

// Function to remove a log entry from the list
void removeLogEntry(Node** head, LogEntry* entry) {
    Node* current = *head;
    while (current != NULL && current->entry != entry) {
        current = current->next;
    }

    if (current == NULL) {
        return; // Entry not found in the list
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        *head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    }

    free(current);
}

// Function to iterate over the log entries in the list
void iterateLogEntries(Node* head, void (*callback)(LogEntry*)) {
    while (head != NULL) {
        callback(head->entry);
        head = head->next;
    }
}
