// Function to initialize a dynamic linked list of File_Metadata structures
void init_file_metadata_list(int max_files, int min_padding_size, FILE **log_file) {
    // Initialize the head and tail pointers for the linked list
    File_Metadata *head = NULL;
    File_Metadata *tail = NULL;

    // Allocate memory for the initial number of files
    File_Metadata *files = (File_Metadata *)malloc(max_files * sizeof(File_Metadata));
    if (files == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for file metadata.\n");
        return;
    }

    // Initialize each file's metadata and add it to the linked list
    int i;
    for (i = 0; i < max_files; i++) {
        File_Metadata *file = &files[i];
        file->filename = NULL;  // Initialize filename as null for now
        file->filesize = -1;     // Initialize filesize as invalid for now

        if (head == NULL) {
            head = file;
            tail = file;
        } else {
            tail->next = file;
            tail = file;
        }
    }

    // Set the initial list size
    int current_size = max_files;

    // Implement dynamic resizing of the linked list
    void *resize_file_metadata_list(int new_max_files, FILE **log_file) {
        // Calculate the difference in the number of files
        int diff = new_max_files - current_size;

        if (diff > 0) {
            // Allocate memory for the additional files
            File_Metadata *new_files = (File_Metadata *)malloc(diff * sizeof(File_Metadata));
            if (new_files == NULL) {
                fprintf(stderr, "Error: Unable to allocate memory for file metadata.\n");
                return;
            }

            // Initialize each new file's metadata and add it to the linked list
            int j;
            for (j = 0; j < diff; j++) {
                File_Metadata *new_file = &new_files[j];
                new_file->filename = NULL;  // Initialize filename as null for now
                new_file->filesize = -1;     // Initialize filesize as invalid for now

                if (head == NULL) {
                    head = new_file;
                    tail = new_file;
                } else {
                    tail->next = new_file;
                    tail = new_file;
                }
            }

            // Update the current size and free any unnecessary memory
            current_size = new_max_files;
            FILE_Metadata *old_tail = tail;
            while (tail->next != NULL) {
                tail = tail->next;
            }
            old_tail->next = NULL;
            free(old_tail);
        } else if (diff < 0) {
            // Free memory for the excess files
            File_Metadata *current_tail = head;
            while (current_tail->next != NULL) {
                current_tail = current_tail->next;
            }
            current_tail->next = NULL;
            free(current_tail);

            // Update the current size
            current_size += diff;
        }

        return;
    }

    // Implement memory cleanup routine
    void clean_up_file_metadata_list() {
        FILE_Metadata *current = head;
        while (current != NULL) {
            FILE_Metadata *next = current->next;
            free(current);
            current = next;
        }
        head = NULL;
        tail = NULL;
        current_size = 0;
    }

    // Implement a mechanism for iterating over the linked list
    void iterate_file_metadata_list(void (*callback)(File_Metadata *)) {
        FILE_Metadata *current = head;
        while (current != NULL) {
            callback(current);
            current = current->next;
        }
    }

    // Provide a callback function for custom processing logic
    int process_file_metadata(File_Metadata *file, FILE **log_file) {
        // Process the file metadata using the provided callback function
        if (callback != NULL) {
            (*callback)(file);
        }

        return 0;
    }
}

