#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* key;
    void* value;
    time_t expiration;
    int ref_count;
} CacheEntry;

typedef struct {
    CacheEntry** entries;
    size_t capacity;
    size_t current_size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int is_empty;
} CacheManager;

CacheManager* cache_manager_init(size_t capacity) {
    CacheManager* manager = (CacheManager*)malloc(sizeof(CacheManager));
    manager->entries = (CacheEntry**)calloc(capacity, sizeof(CacheEntry*));
    manager->capacity = capacity;
    manager->current_size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->is_empty = 1;
    return manager;
}

void cache_manager_free(CacheManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        if (manager->entries[i] != NULL) {
            free(manager->entries[i]->key);
            free(manager->entries[i]->value);
            free(manager->entries[i]);
        }
    }
    free(manager->entries);
    pthread_mutex_destroy(&manager->lock);
    pthread_cond_destroy(&manager->cond);
    free(manager);
}
