#include <string.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

LogEntry* initLogList();
void printLogList(LogEntry*, int);

FILE* openFile(const char*, const char*);
int writeToFile(FILE*, LogEntry*, int);

int main() {
    // Usage example:
    LogEntry* logEntries = initLogList();
    if (logEntries) {
        FILE* file = openFile("output.log", "w");
        if (file) {
            printLogList(logEntries, 5); // Print first 5 entries
            int written = writeToFile(file, logEntries, 10); // Write last 10 entries
            fclose(file);
            printf("Wrote %d log entries.\n", written);
        }
        freeLogList(logEntries);
    }

    return 0;
}

FILE* openFile(const char* filename, const char* mode) {
    FILE* file = fopen(filename, mode);
    if (!file) {
        perror(filename);
    }
    return file;
}

int writeToFile(FILE* file, LogEntry* logEntries, int count) {
    int written = 0;
    for (LogEntry* entry = logEntries; entry && written < count; entry = entry->next) {
        if (fwrite(&entry->timestamp, sizeof(time_t), 1, file) != 1 ||
            fwrite(&entry->logLevel, sizeof(int), 1, file) != 1 ||
            fwrite(entry->message, strlen(entry->message) + 1, 1, file) != 1) {
            perror("Error writing to file");
        }
        written++;
    }
    return written;
}

void printLogList(LogEntry* logEntries, int count) {
    for (LogEntry* entry = logEntries; entry && --count > 0; entry = entry->next) {
        printf("%ld %d: %s\n", entry->timestamp, entry->logLevel, entry->message);
    }
}

LogEntry* initLogList() {
    LogEntry* head = NULL;
    LogEntry* tail = &head;
    for (int i = 0; ; i++) {
        LogEntry* newEntry = malloc(sizeof(LogEntry));
        if (!newEntry) {
            break; // Memory allocation failed
        }
        newEntry->timestamp = time(NULL);
        newEntry->logLevel = rand() % 3; // Random log level (0-2)
        asprintf(&newEntry->message, "Log entry %d", i); // Dynamically allocate message string
        if (!head) {
            head = newEntry;
            tail = &head;
        } else {
            tail->next = newEntry;
            tail = &tail->next;
        }
    }
    return head;
}

void freeLogList(LogEntry* logEntries) {
    for (LogEntry* entry = logEntries; entry; ) {
        LogEntry* next = entry->next;
        free(entry->message);
        free(entry);
        entry = next;
    }
}
