#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    char* metric_name;
    double value;
    char* unit;
} Metric;

typedef struct {
    time_t start;
    time_t end;
    Metric** metrics;
    int count;
    int capacity;
} TimeSeries;

TimeSeries* time_series_new(int initial_capacity) {
    TimeSeries* ts = (TimeSeries*)malloc(sizeof(TimeSeries));
    ts->metrics = (Metric**)calloc(initial_capacity, sizeof(Metric*));
    ts->count = 0;
    ts->capacity = initial_capacity;
    return ts;
}

void time_series_insert(TimeSeries* ts, Metric* metric) {
    if (ts->count >= ts->capacity) {
        ts->capacity *= 2;
        ts->metrics = (Metric**)realloc(ts->metrics, sizeof(Metric*) * ts->capacity);
    }
    int idx = ts->count++;
    while (idx > 0 && ts->metrics[idx-1]->timestamp <= metric->timestamp) {
        ts->metrics[idx] = ts->metrics[--idx];
    }
    ts->metrics[idx] = metric;
}

void time_series_delete(TimeSeries* ts, time_t timestamp) {
    int idx = 0;
    while (idx < ts->count && ts->metrics[idx]->timestamp <= timestamp)
        idx++;
    if (idx == ts->count || ts->metrics[idx]->timestamp > timestamp)
        return; // nothing to delete
    for (; idx < ts->count - 1; idx++) {
        ts->metrics[idx] = ts->metrics[idx+1];
    }
    free(ts->metrics[--ts->count]);
}

Metric* time_series_get(TimeSeries* ts, time_t start, time_t end) {
    Metric* result = NULL;
    int i = 0;
    while (i < ts->count && ts->metrics[i]->timestamp <= start)
        i++;
    for (; i < ts->count; i++) {
        if (ts->metrics[i]->timestamp > end)
            break;
        if (!result || ts->metrics[i]->timestamp >= start) {
            result = ts->metrics[i];
            while (i + 1 < ts->count && ts->metrics[i+1]->timestamp <= start)
                i++;
            for (; i < ts->count; i++) {
                if (ts->metrics[i]->timestamp > end)
                    break;
                if (!result || ts->metrics[i]->timestamp >= start) {
                    Metric* new_metric = (Metric*)malloc(sizeof(Metric));
                    new_metric->timestamp = ts->metrics[i]->timestamp;
                    new_metric->metric_name = strdup(ts->metrics[i]->metric_name);
                    new_metric->value = ts->metrics[i]->value;
                    new_metric->unit = strdup(ts->metrics[i]->unit);
                    result = new_metric;
                }
            }
        }
    }
    return result;
}

void time_series_free(TimeSeries* ts) {
    for (int i = 0; i < ts->count; i++)
        free(ts->metrics[i]);
    free(ts->metrics);
    free(ts);
}
