typedef struct LogEntry {
    long timestamp;
    int logLevel;
    char* message;
} LogEntry;

struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
};

struct DoublyLinkedList {
    struct Node* head;
    struct Node* tail;
    pthread_mutex_t lock;
};

void initDLL(struct DoublyLinkedList** dll) {
    *dll = (struct DoublyLinkedList*)malloc(sizeof(struct DoublyLinkedList));
    (*dll)->head = NULL;
    (*dll)->tail = NULL;
    pthread_mutex_init(&((*dll)->lock), NULL);
}

void insertEntry(struct DoublyLinkedList* dll, LogEntry entry) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->entry = entry;
    newNode->prev = NULL;
    newNode->next = dll->head;

    if(dll->head != NULL)
        dll->head->prev = &newNode->entry;
    else
        dll->tail = &newNode->entry;

    dll->head = &newNode->entry;

    pthread_mutex_unlock(&dll->lock);
}

void printDLL(struct DoublyLinkedList* dll, int fd) {
    struct Node* current = dll->head;

    while(current != NULL) {
        write(fd, &(current->entry), sizeof(LogEntry));
        current = current->next;
    }
}

void deleteEntry(struct DoublyLinkedList* dll, LogEntry entry) {
    pthread_mutex_lock(&dll->lock);

    struct Node* current = dll->head;

    while(current != NULL && (current->entry.timestamp != entry.timestamp || current->entry.logLevel != entry.logLevel)) {
        current = current->next;
    }

    if(current == NULL)
        return;

    if(current == dll->head) {
        dll->head = current->next;
    } else {
        current->prev->next = current->next;
    }

    if(current == dll->tail) {
        dll->tail = current->prev;
    } else {
        current->next->prev = current->prev;
    }

    free(current);

    pthread_mutex_unlock(&dll->lock);
}

void garbageCollect(struct DoublyLinkedList* dll, int interval) {
    // Implement memory reclamation mechanism
}

void serializeDLL(struct DoublyLinkedList* dll, FILE* file) {
    struct Node* current = dll->head;

    while(current != NULL) {
        fwrite(&(current->entry), sizeof(LogEntry), 1, file);
        current = current->next;
    }
}

LogEntry deserializeEntry(FILE* file) {
