Options get_options(int argc, char **argv) {
    Options options = {false, NULL};
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--manpage") == 0) {
            // display detailed usage instructions
        } else if (strcmp(argv[i], "-cs") == 0) {
            options.case_sensitive = true;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            options.output_file = argv[i + 1];
            i++;
        }
    }
    return options;
}

void process_file(char *filename, Options options) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        // handle file opening error
    }

    size_t chunk_size = 1024; // adjust as needed for large files
    char *chunk = (char *)malloc(chunk_size);
    size_t bytes_read;
    bool done = false;

    printf("Processing %s...\n", filename);

    while (!done) {
        fseek(file, 0, SEEK_SET); // rewind to the beginning of the file

        if ((bytes_read = fread(chunk, 1, chunk_size, file)) > 0) {
            // process the chunk
            printf("%zu/%zu bytes processed.\n", (size_t)(ftell(file)), file_size);
        } else {
            done = true;
        }
    }

    free(chunk);
    fclose(file);
}

int main(int argc, char **argv) {
