    if (argc == 1 || strcmp(argv[1], "-h") == 0) {
        // display usage information
    } else {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "-o") != 0 && strcmp(argv[i], "--manpage") != 0 && strcmp(argv[i], "-cs") != 0) {
