class ConfigurationManipulator:
    def __init__(self):
        self.lock = threading.Lock()

    def manipulate_file(self, file_path, parameters):
        try:
            with open(file_path) as f:
                content = f.read()
        except FileNotFoundError:
            return

        new_content = ''
        for line in content.splitlines():
            for placeholder, value in parameters.items():
                if f'{placeholder}=' in line:
                    new_line = line.replace(f'{placeholder}=old_value', f'{placeholder}={value}')
                    break
            else:
                new_line = line
            new_content += new_line + '\n'

        try:
            with self.lock:
                with open('new_file.txt', 'w') as f:
                    f.write(new_content)
            subprocess.run(['sed', '-i', 's/old_value/' + '/'.join(map(str, parameters.values())) + '/', file_path])
        except Exception as e:
            raise

    def determine_weaknesses(self, pokemon):
        weaknesses = ''
        for type in pokemon.types:
            if type == 'Normal':
                weaknesses += 'Fighting'
            elif type == 'Fire':
                weaknesses += 'Water'
            elif type == 'Water':
                weaknesses += 'Electric'
            elif type == 'Grass':
                weaknesses += 'Poison'
            elif type == 'Poison':
                weaknesses += 'Ground'
            elif type == 'Electric':
                weaknesses += 'Ground'
            elif type == 'Psychic':
                weaknesses += 'Dark'
            elif type == 'Fighting':
                weaknesses += 'Flying'
            elif type == 'Bug':
                weaknesses += 'Fire'
        return weaknesses

def test_configuration_manipulator():
    manipulator = ConfigurationManipulator()
    parameters = {'POKEMON_NAME': 'Pikachu', 'POKEMON_TYPE': 'Electric'}
    file_path = 'config.txt'
    try:
        with open(file_path, 'w') as f:
