def test_determine_weaknesses():
    manipulator = ConfigurationManipulator()
    pokemon = {'name': 'Pikachu', 'types': ['Electric']}
    try:
        weaknesses = manipulator.determine_weaknesses(pokemon)
        assert weaknesses == 'Ground'
    except Exception as e:
