class LogEntry {
public:
    std::time_t timestamp;
    int logLevel;
    std::unique_ptr<std::string> message;

    LogEntry(std::time_t timestamp, int logLevel, const std::string& message)
        : timestamp(timestamp), logLevel(logLevel),
          message(std::make_unique<std::string>(message)) {}
};

class LogManager {
public:
    LogManager(size_t capacity) : entries_(capacity), writeMutex_(), readerMutex_(),
                                     writerConditionVariable_(), readerConditionVariable_() {}

    void addEntry(const LogEntry& entry);
    std::vector<LogEntry> getEntries();
    void removeEntry(size_t index);

private:
    std::vector<std::unique_ptr<LogEntry>> entries_;
    std::mutex writeMutex_;
    std::mutex readerMutex_;
    std::condition_variable writerConditionVariable_;
    std::condition_variable readerConditionVariable_;
};

class LogFormatter {
public:
    virtual std::string format(const LogEntry& entry) = 0;
};

class TextLogger : public LogFormatter {
public:
    std::string format(const LogEntry& entry) override {
        return "[Timestamp: " + std::to_string(entry.timestamp) +
               ", LogLevel: " + std::to_string(entry.logLevel) +
               ", Message: " + *entry.message] + "\n";
    }
};

class HTMLLogger : public LogFormatter {
public:
    std::string format(const LogEntry& entry) override {
        return "<log_entry timestamp=\"" + std::to_string(entry.timestamp) +
               "\" log_level=\"" + std::to_string(entry.logLevel) +
               "\">" + *entry.message + "</log_entry>";
    }
};

class RealTimeMonitorService {
public:
    void sendLogEntries(const std::vector<LogEntry>& entries);
};

void LogManager::addEntry(const LogEntry& entry) {
    std::unique_lock<std::mutex> writeLock(writeMutex_);
    writerConditionVariable_.wait_for(writeLock, std::chrono::milliseconds(10));
    entries_.push_back(std::make_unique<LogEntry>(entry));
}

std::vector<LogManager::LogEntry> LogManager::getEntries() {
    std::unique_lock<std::mutex> readLock(readerMutex_);
    readerConditionVariable_.wait_for(readLock, std::chrono::milliseconds(10));
    return std::vector<LogEntry>(entries_.begin(), entries_.end());
}

void LogManager::removeEntry(size_t index) {
    std::unique_lock<std::mutex> writeLock(writeMutex_);
    writerConditionVariable_.wait_for(writeLock, std::chrono::milliseconds(10));
    if (index < entries_.size()) {
        entries_.erase(entries_.begin() + index);
    }
}

