import hashlib
import os

def calculate_hashes(file_path):
    md5_hash = hashlib.md5()
    sha256_hash = hashlib.sha256()

    chunk_size = 1024 * 1024  # 1 MB chunks
    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break

            md5_hash.update(chunk)
            sha256_hash.update(chunk)

    print(f"MD5 Hash: {md5_hash.hexdigest()}")
    print(f"SHA-256 Hash: {sha256_hash.hexdigest()}")

    progress_monitor(file_path, md5_hash, sha256_hash)


def progress_monitor(file_path, md5_hash, sha256_hash):
    chunk_size = 1024 * 1024
    with open(file_path, 'rb') as file:
        for _ in range(10):  # Monitor every 10% completion
            chunk = file.read(chunk_size)
            if not chunk:
                break

            print(f"Calculating hashes... ({_ * 10}%)")
