                return false;
            }

            string tokenType = jsonObject["token_type"].Value;
            int expiresIn = (int)jsonObject["expires_in"];

            if (tokenType != "Bearer" || expiresIn <= 0) 
            {
                Console.WriteLine("Error: Invalid OAuth2 access token response fields.");
                return false;
            }

            // Choose cipher mode based on predefined business logic, user input, and session data
            CipherMode cipherMode = CipherMode.Ecb; // default to ECB

