typedef struct {
    char* url;
    int timestamp;
    char** headers;
    char* body;
} Request;

Request* cache = NULL;
int cache_size = 0;
int max_cache_size = 10000;
int ttl = 3600; // one hour

void insert_request(Request* request) {
    if (cache_size >= max_cache_size) {
        // handle cache full
    }
    cache[cache_size] = request;
    cache_size++;
}

Request* find_request(char* url) {
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i]->url, url) == 0) {
            return cache[i];
        }
    }
    return NULL;
}

void cleanup_cache() {
    int i = 0;
    while (i < cache_size) {
        Request* request = cache[i];
        if ((time(NULL) - request->timestamp) > ttl) {
            // handle expired entry
            for (int j = i; j < cache_size - 1; j++) {
                cache[j] = cache[j + 1];
            }
            cache_size--;
        } else {
            i++;
        }
    }
}
