def fetch_user_profile(user_id):
    api_key = os.environ['API_KEY']
    api_secret = os.environ['API_SECRET']

    # Load user profile from API
    response = requests.get('https://api.example.com/user/' + str(user_id), 
                             headers={'Authorization': 'Bearer ' + api_key})

    if response.status_code == 200:
        return json.loads(response.content)
    else:
        return None

def retry_fetch_user_profile(user_id, max_retries=5):
    for i in range(max_retries):
        profile = fetch_user_profile(user_id)
        if profile is not None:
            return profile
        if i < max_retries - 1:
            print('Failed to fetch user profile. Retrying...')
        else:
            print('Failed to fetch user profile after {} retries.'.format(max_retries))
    return None
