typedef struct LinkedList {
    LogEntry* head;
    size_t size;
} LinkedList;

// Function to initialize the linked list with filter option
LinkedList* initLinkedList(int logLevelFilter, int maxLogSize) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) {
        return NULL; // Error: Out of memory
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

// Function to add a log entry to the linked list
void addLogEntry(LinkedList* list, int logLevel, const char* message) {
    LogEntry* newEntry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!newEntry) {
        // Error: Out of memory
        return;
    }
    newEntry->timestamp = time(NULL);
    newEntry->logLevel = logLevel;
    newEntry->message = strdup(message);
    if (!list->head) {
        list->head = newEntry;
    } else {
        LogEntry* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newEntry;
    }
    list->size++;
}

// Function to print log entries to a file descriptor
void printLogEntries(LinkedList* list, int fd) {
    LogEntry* current = list->head;
    while (current) {
        printf("%lu: %d - %s\n", current->timestamp, current->logLevel, current->message);
        fflush(stdout); // Ensure output is written to the file descriptor
        current = current->next;
    }
}

// Function to free allocated memory when destroying the linked list
void destroyLinkedList(LinkedList* list) {
    LogEntry* current = list->head;
    LogEntry* next;
    while (current) {
        next = current->next;
        free(current->message);
        free(current);
        current = next;
    }
    free(list);
}

// Function to filter logs based on a specified log level
void updateLogFilter(LinkedList* list, int newLogLevelFilter) {
    LogEntry* current = list->head;
    while (current) {
        if (current->logLevel > newLogLevelFilter) {
            // Remove entries with levels higher than the filter
            LogEntry* next = current->next;
            free(current->message);
            free(current);
            current = next;
            list->size--;
        } else {
            current = current->next;
        }
    }
}

