#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure representing log entry
typedef struct {
    time_t timestamp;
    int log_level;
    char* message;
} LogEntry;

// Structure for doubly-linked list nodes
typedef struct Node {
    LogEntry* entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to create a new node
Node* create_node(LogEntry* entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->entry = entry;
    node->prev = NULL;
    node->next = NULL;
    return node;
}

// Function to initialize the linked list
void init_list(Node** head, Node** tail) {
    *head = NULL;
    *tail = NULL;
}

// Function to insert a new node at the end of the list
void insert_node(Node** head, Node** tail, LogEntry* entry) {
    Node* node = create_node(entry);
    if (*head == NULL) {
        *head = node;
        *tail = node;
    } else {
        (*tail)->next = node;
        node->prev = *tail;
        *tail = node;
    }
}

// Function to print all entries to a file descriptor
void print_list_to_file(Node* head, FILE* file) {
    Node* current = head;
    while (current != NULL) {
        fprintf(file, "Timestamp: %ld, Log Level: %d, Message: %s\n",
                current->entry->timestamp, current->entry->log_level,
                current->entry->message);
        current = current->next;
    }
}

// Function to insert a new node at a specific position
void insert_node_at_position(Node** head, Node* pos, LogEntry* entry) {
    Node* node = create_node(entry);
    if (pos == NULL) {
        // Insert at the end of the list
        if (*head == NULL) {
            *head = node;
            *tail = node;
        } else {
            (*tail)->next = node;
            node->prev = *tail;
            *tail = node;
        }
    } else {
        node->next = pos->next;
        node->prev = pos;
        if (pos->next != NULL) {
            pos->next->prev = node;
        } else {
            *tail = node;
        }
        pos->next = node;
    }
}

// Function to delete a node by timestamp
void delete_node_by_timestamp(Node** head, Node* tail, time_t timestamp) {
    Node* current = *head;
    while (current != NULL) {
        if (current->entry->timestamp == timestamp) {
            if (current == *tail) {
                *tail = current->prev;
                current->next->prev = NULL;
            } else if (current == *head) {
                *head = current->next;
                current->prev->next = NULL;
            } else {
                current->prev->next = current->next;
                current->next->prev = current->prev;
            }
            free(current->entry);
            free(current);
            return;
        }
        current = current->next;
    }
}

// Function to safely destroy the entire list
void destroy_list(Node** head, Node* tail) {
    while (*head != NULL) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp->entry);
        free(temp);
    }
    free(*tail);
    *head = NULL;
    *tail = NULL;
}

int main() {
    // Initialize the linked list
    Node* head = NULL;
    Node* tail = NULL;
    init_list(&head, &tail);

    // Insert entries into the linked list
    for (int i = 0; i < 10; i++) {
        LogEntry entry;
        entry.timestamp = time(NULL);
        entry.log_level = i % 2;
        char* message = (char*)malloc(50);
        sprintf(message, "Log Entry %d", i);
        entry.message = message;
        insert_node(&head, &tail, &entry);
    }

    // Print all entries to a file descriptor
    FILE* file = fopen("log.txt", "w");
    print_list_to_file(head, file);
    fclose(file);

    // Insert new nodes at specific positions
    for (int i = 0; i < 5; i++) {
        LogEntry entry;
        entry.timestamp = time(NULL) + i;
        entry.log_level = i % 2;
        char* message = (char*)malloc(50);
        sprintf(message, "Log Entry %d", i);
        entry.message = message;
        insert_node_at_position(&head, head->next, &entry);
    }

    // Delete nodes by timestamp
    delete_node_by_timestamp(&head, tail, time(NULL) - 10);

    // Destroy the entire list
    destroy_list(&head, tail);

    return 0;
}
