typedef struct {
    char* id;
    char* ip;
    time_t timestamp;
    char** agent;
} UserSession;

typedef struct {
    int size;
    UserSession* sessions;
} SessionCollection;

void init_session_collection(SessionCollection* collection) {
    collection->size = 0;
    collection->sessions = NULL;
}

UserSession* create_user_session(char* id, char* ip, time_t timestamp, char* agent) {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    session->id = strdup(id);
    session->ip = strdup(ip);
    session->timestamp = timestamp;
    session->agent = (char**)malloc((1 + 1) * sizeof(char*));
    session->agent[0] = strdup(agent);
    return session;
}

void add_session(SessionCollection* collection, UserSession* session) {
    if(collection->size == 0 || session->timestamp < collection->sessions[collection->size - 1]->timestamp) {
        UserSession** new_sessions = (UserSession**)realloc(collection->sessions, (collection->size + 1) * sizeof(UserSession*));
        new_sessions[collection->size] = session;
        for(int i = collection->size; i > 0; --i) {
            new_sessions[i - 1] = new_sessions[i];
        }
        collection->sessions = new_sessions;
    } else {
        UserSession** new_sessions = (UserSession**)realloc(collection->sessions, (collection->size + 1) * sizeof(UserSession*));
        for(int i = collection->size; i > 0; --i) {
            if(session->timestamp < collection->sessions[i - 1]->timestamp) {
                new_sessions[i] = session;
                break;
            }
            new_sessions[i] = collection->sessions[i];
        }
        collection->sessions = new_sessions;
    }
    ++collection->size;
}

void remove_session(SessionCollection* collection, char* id) {
    for(int i = 0; i < collection->size; ++i) {
        if(strcmp(collection->sessions[i]->id, id) == 0) {
            for(int j = i; j < collection->size - 1; ++j) {
                collection->sessions[j] = collection->sessions[j + 1];
            }
            --collection->size;
            free(collection->sessions[collection->size]);
            collection->sessions[collection->size] = NULL;
            return;
        }
    }
}

void destroy_session_collection(SessionCollection* collection) {
    for(int i = 0; i < collection->size; ++i) {
        free(collection->sessions[i]->id);
        free(collection->sessions[i]->ip);
        free(collection->sessions[i]->agent[0]);
        free(collection->sessions[i]->agent);
        free(collection->sessions[i]);
    }
    free(collection->sessions);
    free(collection);
}

void export_sessions(SessionCollection* collection, int fd) {
    json_object* root = json_object_new();
    for(int i = 0; i < collection->size; ++i) {
        json_object* session = json_object_new();
        json_object_object_add(session, "id", json_object_get_string(json_object_new_str(collection->sessions[i]->id)));
        json_object_object_add(session, "ip", json_object_get_string(json_object_new_str(collection->sessions[i]->ip)));
        json_object_object_add(session, "timestamp", json_object_get_int(json_object_new_int((int)collection->sessions[i]->timestamp)));
        json_object_object_add(session, "agent", json_object_get_string(json_object_new_str(collection->sessions[i]->agent[0])));

        if(json_write_file(root, "sessions.json") < 0)
            perror("Error writing JSON file");
    }
}

void iterate_forward(SessionCollection* collection) {
    for(int i = 0; i < collection->size; ++i) {
        printf("Session ID: %s\n", collection->sessions[i]->id);
        printf("IP Address: %s\n", collection->sessions[i]->ip);
        printf("Login Timestamp: %ld\n", (long int)collection->sessions[i]->timestamp);
        printf("User Agent: %s\n", collection->sessions[i]->agent[0]);
    }
}

void iterate_reverse(SessionCollection* collection) {
    for(int i = collection->size - 1; i >= 0; --i) {
        printf("Session ID: %s\n", collection->sessions[i]->id);
