// Define structure for Transaction
typedef struct {
    int id;
    time_t timestamp;
} Transaction;

// Define structure for SessionInfo
typedef struct {
    char* clientIP;
    int port;
} SessionInfo;

// Define structure for NetworkSession
typedef struct {
    SessionInfo info;
    Transaction* transactions;
    size_t transactionCount;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NetworkSession;

// Function to create a new NetworkSession
NetworkSession* network_session_create() {
    NetworkSession* session = (NetworkSession*)malloc(sizeof(NetworkSession));
    if (!session) return NULL;
    session->transactions = NULL;
    session->transactionCount = 0;
    pthread_mutex_init(&session->mutex, NULL);
    pthread_cond_init(&session->cond, NULL);
    return session;
}

// Function to add a new Transaction to the NetworkSession
int network_session_add_transaction(NetworkSession* session, int id, time_t timestamp) {
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
    if (!transaction) return -1; // Out of memory error

    transaction->id = id;
    transaction->timestamp = timestamp;

    pthread_mutex_lock(&session->mutex);
    session->transactions = realloc(session->transactions, (session->transactionCount + 1) * sizeof(Transaction));
    if (!session->transactions) {
        free(transaction);
        pthread_mutex_unlock(&session->mutex);
        return -2; // Out of memory error
    }
    session->transactions[session->transactionCount] = *transaction;
    session->transactionCount++;
    pthread_mutex_unlock(&session->mutex);

    return 0; // Successful transaction addition
}

// Function to delete a Transaction from the NetworkSession
int network_session_delete_transaction(NetworkSession* session, int id) {
    for (size_t i = 0; i < session->transactionCount; i++) {
        if (session->transactions[i].id == id) {
            pthread_mutex_lock(&session->mutex);
            memmove(&session->transactions[i], &session->transactions[i + 1], (session->transactionCount - i - 1) * sizeof(Transaction));
            session->transactionCount--;
            free(&session->transactions[i]);
            pthread_mutex_unlock(&session->mutex);
            return 0; // Successful transaction deletion
        }
    }
    return -1; // Transaction not found error
}

// Function to iterate over the transactions in a NetworkSession
void network_session_iterate(NetworkSession* session, void (*callback)(Transaction*, size_t)) {
    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < session->transactionCount; i++) {
        callback(&session->transactions[i], i);
    }
    pthread_mutex_unlock(&session->mutex);
}

// Function to validate timestamps in the NetworkSession
int network_session_validate_timestamps(NetworkSession* session) {
    time_t min = session->transactions[0].timestamp;
    time_t max = session->transactions[0].timestamp;

    for (size_t i = 1; i < session->transactionCount; i++) {
        if (session->transactions[i].timestamp < min) min = session->transactions[i].timestamp;
        if (session->transactions[i].timestamp > max) max = session->transactions[i].timestamp;
    }

    // Validate timestamps
    time_t currentTime = time(NULL);
    if (min < 0 || max > currentTime || abs(max - min) > 3600) { // Check for valid range (less than an hour)
        return -1; // Invalid timestamp error
    }
    return 0; // Successful timestamp validation
}

// Function to free the memory used by a NetworkSession
void network_session_free(NetworkSession* session) {
    if (!session) return;

    pthread_mutex_lock(&session->mutex);
    for (size_t i = 0; i < session->transactionCount; i++) {
        free(&session->transactions[i]);
    }
    free(session->transactions);
    pthread_mutex_unlock(&session->mutex);

    pthread_cond_destroy(&session->cond);
    pthread_mutex_destroy(&session->mutex);
    free(session);
}
