#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int timestamp;
    char resourceType[16];
    int* usageValue;
} ResourceUsage;

// Linked List Node structure
typedef struct Node {
    ResourceUsage data;
    struct Node* next;
} Node;

Node* createNode(ResourceUsage data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return NULL;

    newNode->data = data;
    newNode->next = NULL;

    return newNode;
}

void freeNode(Node* node) {
    if (!node) return;

    free(node);
}

// Linked List structure
typedef struct LinkedList {
    Node* head;
    int size;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* newLinkedList = (LinkedList*)malloc(sizeof(LinkedList));
    if (!newLinkedList) return NULL;

    newLinkedList->head = NULL;
    newLinkedList->size = 0;

    return newLinkedList;
}

void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    Node* next;

    while (current) {
        next = current->next;
        freeNode(current);
        current = next;
    }

    free(list);
}

// Function to add a new node to the linked list
void append(LinkedList* list, ResourceUsage data) {
    Node* newNode = createNode(data);

    if (!list->head) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    }

    list->size++;
}

// Function to remove the first occurrence of a resource usage entry
void remove(LinkedList* list, ResourceUsage data) {
    Node* current = list->head;

    if (current && memcmp(&current->data, &data, sizeof(ResourceUsage)) == 0) {
        Node* next = current->next;
        freeNode(current);
        list->head = next;
    } else {
        while (current && memcmp(&current->data, &data, sizeof(ResourceUsage)) != 0) {
            if (!current->next) break;

            current = current->next;
        }

        if (current) {
            Node* next = current->next;
            freeNode(current);
            list->head = next;
        }
    }

    list->size--;
}

// Function to iterate over the linked list and calculate cumulative resource usage statistics
void printStatistics(LinkedList* list, int startTimestamp, int endTimestamp, char* resourceType) {
    int totalUsage = 0;
    int count = 0;

    Node* current = list->head;

    while (current) {
        if (current->data.timestamp >= startTimestamp && current->data.timestamp <= endTimestamp && 
            strcmp(current->data.resourceType, resourceType) == 0) {
            totalUsage += *current->data.usageValue;
            count++;
        }

        current = current->next;
    }

    printf("Total usage: %d\n", totalUsage);
    printf("Count: %d\n", count);
}

int main() {
    // Example usage
    LinkedList* list = createLinkedList();
    append(list, (ResourceUsage){.timestamp=1,.resourceType="CPU",.usageValue=(int*)malloc(sizeof(int))});
    append(list, (ResourceUsage){.timestamp=2,.resourceType="CPU",.usageValue=(int*)malloc(sizeof(int))});
    printStatistics(list, 1, 2, "CPU");
    freeLinkedList(list);

    return 0;
}
