int computeMD5Hash(const char *path, int chunk_size) {
    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        return -1; // error opening file
    }

    // read the file in chunks and update the hash incrementally
    unsigned char buffer[chunk_size];
    unsigned char md5_sum[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    int chunk = 0;
    while (fread(buffer, 1, chunk_size, file) > 0) {
        MD5_Update(&ctx, buffer, chunk_size);
        if (++chunk % 10 == 0) {
            // log progress every 10% completion
            printf("Processing... %d%%\n", (int)((double)chunk / 100));
        }
    }

    MD5_Final(md5_sum, &ctx);

    fclose(file);

    return *(unsigned int *)md5_sum;
}

