void populateNFACRCAndLogList(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    // Initialize head and tail of the list
    *list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    (*list)->next = NULL;
    (*list)->prev = NULL;

    for(int i=0; i<size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy(node->RX_UE_INFORMATION_TAG, "Valid_RX_UE_INFORMATION_TAG");
        node->RNTI = rand();
        strcpy(node->CRC_INDICATION_REL8_TAG, "Valid_CRC_INDICATION_REL8_TAG");
        node->CRCFLAG = rand() % 2;
        node->timestamp = time(NULL);
        node->log_level = 1;
        char* message = (char*)malloc(strlen("Random_message_") + strlen("/tmp/file_name.txt"));
