void computeMD5Hash(const char* path) {
    FILE *file = fopen(path, "rb");
    if(file == NULL) {
        printf("Error opening file %s\n", path);
        return;
    }

    unsigned char md5[16];
    MD5_CTX ctx;
    MD5_Init(&ctx);

    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    char chunk[fileSize + 1];
    int bytesRead;
    while((bytesRead = fread(chunk, 1, 1048576, file)) > 0) {
        MD5_Update(&ctx, (unsigned char*)chunk, bytesRead);
        if(bytesRead == 1048576) {
            printf("10%% of the file processed...\n");
        }
    }

    MD5_Final(md5, &ctx);

    for(int i=0; i<16; i++) {
        printf("%02x", md5[i]);
    }
}

