jstring Java_com_example_MyClass_computeMD5Hash(JNIEnv* env, jobject obj, jstring input) {
    if(input == NULL || strlen(Java_stringToString(env, input)) > 1024) {
        return "Error: Input is null or exceeds maximum length";
    }

    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] hashBytes = md.digest((input).getBytes());

    StringBuilder sb = new StringBuilder();
    for(byte b : hashBytes) {
        String hex = Integer.toHexString(0xff & b);
        if(hex.length() == 1) {
            sb.append('0');
        }
        sb.append(hex);
    }

    return sb.toString();
}

