jboolean Java_com_example_MyClass_followSymlink(JNIEnv* env, jobject obj, jstring path) {
    struct stat sb;
    if(stat(path, &sb) == -1) {
        return JNI_FALSE;
    }
    else if(S_ISLNK(sb.st_mode)) {
        char link[PATH_MAX];
        readlink(path, link, PATH_MAX);
        printf("Following symlink %s to %s\n", path, link);
        return JNI_TRUE;
    }
    else {
        return JNI_FALSE;
    }
}

