int maxThread = sysconf(_SC_NPROCESSORS_ONLN);

// Create a concurrent file scanning mechanism using POSIX threads
void* computeMD5HashThread(void* arg) {
    // Handle each file in the directory
    dir_entry_t* entry;
    DIR* dir;
    if ((dir = opendir("/path/to/directory")) != NULL) {
        while ((entry = readdir(dir)) != NULL) {
            // Skip directories and hidden files
            if (S_ISDIR(entry->d_type) || entry->d_name[0] == '.') {
                continue;
            }

            // Compute the MD5 hash for each file
            char* filePath = (char*)malloc(strlen("/path/to/directory") + strlen(entry->d_name));
            sprintf(filePath, "/path/to/directory/%s", entry->d_name);
            computeMD5Hash(filePath);

            free(filePath);
        }
    }

    closedir(dir);
}

