// Define a structure to hold network traffic data
typedef struct {
    int timestamp;
    char protocol[4];
    char src_ip[16], dst_ip[16];
    int packet_size;
    void* payload;
} NetworkTraffic;

// Define the doubly-linked list node
typedef struct Node {
    NetworkTraffic data;
    struct Node* prev, *next;
} Node;

// Function to create a new linked list node
Node* create_node(NetworkTraffic traffic) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->data = traffic;
    new_node->prev = new_node->next = NULL;
    return new_node;
}

// Function to initialize the linked list
void init_linked_list(Node** head, pthread_mutex_t* lock) {
    *head = NULL;
    *lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    if (!*lock) return;
    pthread_mutex_init(*lock, NULL);
}

// Function to insert a new node into the linked list
void insert_node(Node** head, Node* new_node) {
    pthread_mutex_lock(*head);
    if (*head) {
        new_node->next = *head;
        (*head)->prev = new_node;
        *head = new_node;
    } else {
        *head = new_node;
    }
    pthread_mutex_unlock(*head);
}

// Function to iterate over the linked list and calculate cumulative traffic statistics
void calc_traffic_stats(Node* head, int time_window, char protocol) {
    // Calculate total traffic volume and average traffic per time interval
    int total_volume = 0;
    for (Node* current = head; current; current = current->next) {
        if (current->data.protocol[0] == protocol && current->data.timestamp >= time_window) {
            total_volume += current->data.packet_size;
        }
    }
    printf("Total volume: %d bytes, Average traffic per interval: %.2f KB\n", total_volume, (double)total_volume / 1024);
}

// Function to garbage collect unused memory
void gc(Node* head) {
    Node* current = head, *prev = NULL;
    while (current) {
        prev = current;
        current = current->next;
        free(prev);
    }
    *head = NULL;
}

int main() {
    // Initialize the linked list and lock
    Node* head = NULL;
    pthread_mutex_t lock;
    init_linked_list(&head, &lock);

    // Insert nodes into the linked list
    insert_node(&head, create_node((NetworkTraffic){1, "TCP", "192.168.1.1", "8.8.8.8", 100, (void*)"Hello"}));
    insert_node(&head, create_node((NetworkTraffic){2, "UDP", "192.168.1.2", "8.8.4.4", 50, (void*)"World"}));

    // Calculate traffic statistics for a given time window and protocol
    calc_traffic_stats(head, 2, 'T');

    // Garbage collect unused memory
    gc(head);

    return 0;
}

