// Custom log entry structure
struct LogEntry {
    time_t timestamp;
    enum class LogLevel { DEBUG, INFO, WARNING, ERROR } level;
    std::unique_ptr<std::string> message;

    LogEntry(time_t timestamp, LogLevel level) : 
        timestamp(timestamp), level(level) {}
};

class LoggingSystem {
public:
    LoggingSystem(size_t memoryPoolSize) : 
        memoryPool_(memoryPoolSize), logEntries_(nullptr), currentLog_(nullptr), 
        logFile_(nullptr), fileDescriptor_(0) {}

    ~LoggingSystem() {
        if (logEntries_ != nullptr) {
            LogEntry* entry = logEntries_;
            while (entry != nullptr) {
                auto next = entry->message;
                entry->message = nullptr;
                entry = next;
            }
            delete[] logEntries_;
        }
    }

    void addLogEntry(const LogEntry& entry) {
        // Calculate memory size for new log entry
        size_t memorySize = sizeof(LogEntry) + entry.message->size();

        // Check if there is enough space in the memory pool
        if (availableMemory_ < memorySize) {
            // Resize the memory pool if necessary
            resizeMemoryPool();
        }

        // Add new log entry to the linked list
        LogEntry* newEntry = reinterpret_cast<LogEntry*>(memoryPool_.address());
        newEntry->timestamp = entry.timestamp;
        newEntry->level = entry.level;
        newEntry->message = std::move(entry.message);

        if (logEntries_ == nullptr) {
            logEntries_ = newEntry;
            currentLog_ = newEntry;
        } else {
            LogEntry* lastEntry = logEntries_;
            while (lastEntry->message != nullptr) {
                lastEntry = lastEntry->message.get();
            }
            lastEntry->message = std::move(newEntry);
        }

        // Update statistics
        totalLogEntries_++;
        averageMessageLength_ += entry.message->size();
        peakMemoryUsage_ = std::max(peakMemoryUsage_, memorySize);

        availableMemory_ -= memorySize;
    }

    void printLogEntries(std::ofstream& file) {
        LogEntry* current = logEntries_;
        while (current != nullptr) {
            file << "Timestamp: " << current->timestamp << ", Level: ";
            switch (current->level) {
                case LogLevel::DEBUG:
                    file << "DEBUG";
                    break;
                case LogLevel::INFO:
                    file << "INFO";
                    break;
                case LogLevel::WARNING:
                    file << "WARNING";
                    break;
                case LogLevel::ERROR:
                    file << "ERROR";
                    break;
            }
            file << ", Message: " << *current->message << std::endl;
            current = current->message.get();
        }
    }

    size_t getPeakMemoryUsage() const {
        return peakMemoryUsage_;
    }

    size_t getTotalLogEntries() const {
        return totalLogEntries_;
    }

    double getAverageMessageLength() const {
        return static_cast<double>(averageMessageLength_) / totalLogEntries_;
    }

private:
    std::unique_ptr<char[]> memoryPool_;
    LogEntry* logEntries_;
    LogEntry* currentLog_;
    FILE* logFile_;
    int fileDescriptor_;

    size_t availableMemory_ = 0;
    size_t totalLogEntries_ = 0;
    size_t averageMessageLength_ = 0;
    size_t peakMemoryUsage_ = 0;

    void resizeMemoryPool() {
        // Resize the memory pool
        memoryPool_.reset();
        memoryPool_.reset(new char[memoryPoolSize * 2]);
        availableMemory_ = memoryPool_.size();
    }
};

