class LogEntry {
public:
    int64_t timestamp;
    char logLevel;
    std::string message;

    LogEntry(int64_t t, char l, const std::string& m) : 
        timestamp(t), logLevel(l), message(new char[m.size() + 1]) {
            memcpy(message.get(), m.c_str(), m.size());
            message.back() = '\0';
        }

    ~LogEntry() { delete[] message.get(); }
};

class LogManager {
public:
    int64_t currentTimestamp;
    std::mutex logMutex;
    std::condition_variable logCondVar;

    LogManager(int64_t startTimestamp) : 
        currentTimestamp(startTimestamp) {}

    void writeLogEntry(LogEntry* entry, bool asyncWrite = false) {
        std::unique_lock<std::mutex> lock(logMutex);
        while (logEntries.size() >= 1000000) {
            logCondVar.wait(lock, [this] { return logEntries.size() < 1000000; });
        }
        logEntries.emplace_back(entry);
        if (!asyncWrite) {
            lock.unlock();
            std::unique_lock<std::mutex> writeLock(logMutex);
            writeLock.lock();
            lock.lock();
            logCondVar.notify_one();
            writeLock.unlock();
        }
    }

    void asyncWrite() {
        while (logEntries.size() >= 1000000) {
            logCondVar.wait_for(std::chrono::seconds(1));
        }
        for (auto& entry : logEntries) {
            delete[] entry->message.get();
        }
        logEntries.clear();
    }

private:
    std::vector<LogEntry*> logEntries;
};

int main() {
