int log_entry_new(struct LinkedList* list, int timestamp, char level, const char* message) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return -1;

    entry->timestamp = timestamp;
    entry->level = level;
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        return -1;
    }

    entry->next = list->head;
    list->head = entry;
    list->size++;
    return 0;
}

void linked_list_print(struct LinkedList* list, int fd) {
