        fprintf(fd, "Timestamp: %d, Level: %c, Message: %s\n", entry->timestamp, entry->level, entry->message);
    }
}

void linked_list_destroy(struct LinkedList* list) {
    for (LogEntry* entry = list->head; entry; ) {
        LogEntry* next = entry->next;
        log_entry_free(entry);
        entry = next;
    }
    list->size = 0;
    free(list->head); // Free the head as well
}

