typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

typedef struct Node {
    LogEntry entry;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    Node* tail;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} LinkedList;

typedef struct MemoryPool {
    void** blocks;
    size_t block_size;
    size_t num_blocks;
    pthread_mutex_t mutex;
} MemoryPool;

void log_init(LinkedList* list, MemoryPool* pool);
void log_add(LinkedList* list, LogEntry entry);
void log_delete(LinkedList* list);
void log_free(LinkedList* list);
int log_iterate(LinkedList* list, int (*callback)(LogEntry));
