// Implementation details

void log_init(LinkedList* list, MemoryPool* pool) {
    pthread_mutex_init(&list->mutex, NULL);
    list->head = NULL;
    list->tail = NULL;
    list->capacity = 1000;
    list->size = 0;

    pool->block_size = sizeof(char*) * 10;
    pool->num_blocks = (200000000 / pool->block_size) + 1;
    pool->blocks = (void**)malloc(pool->num_blocks * sizeof(void*));

    for(size_t i = 0; i < pool->num_blocks; i++) {
        pool->blocks[i] = NULL;
    }
}

void log_add(LinkedList* list, LogEntry entry) {
    Node* node = (Node*)malloc(sizeof(Node));
    if(node == NULL) {
        perror("Memory allocation failed");
        return;
    }

    node->entry.timestamp = entry.timestamp;
    node->entry.logLevel = entry.logLevel;
    node->entry.message = malloc(strlen(entry.message) + 1);
    strcpy(node->entry.message, entry.message);

    pthread_mutex_lock(&list->mutex);
    if(list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        list->tail = node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void log_delete(LinkedList* list) {
    Node* current = list->head;
    while(current != NULL) {
        Node* next = current->next;
        free(current->entry.message);
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
}

void log_free(LinkedList* list) {
    log_delete(list);
    pthread_mutex_destroy(&list->mutex);
}

int log_iterate(LinkedList* list, int (*callback)(LogEntry)) {
    Node* current = list->head;
    while(current != NULL) {
        callback(current->entry);
        current = current->next;
    }
    return 0;
}

size_t log_stats(LinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    size_t size = list->size;
    pthread_mutex_unlock(&list->mutex);
    return size;
}
