class LogEntry {
public:
    time_t timestamp;
    int logLevel;
    std::string* message;

    LogEntry(time_t timestamp, int logLevel) : timestamp(timestamp), logLevel(logLevel) {
        this->message = new std::string();
    }
};

class LogManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::list<LogEntry*> logEntries;
    std::unordered_map<int, LogEntry*> logLevels;

public:
    void addLogEntry(LogEntry* entry) {
        std::unique_lock<std::mutex> lock(mtx);
        logEntries.push_back(entry);
        cv.notify_one();
    }

    void removeLogEntry(int index) {
        std::unique_lock<std::mutex> lock(mtx);
        if (index < 0 || index >= logEntries.size()) {
            return;
        }
        logEntries.erase(logEntries.begin() + index);
    }

    void printLogEntries() {
        std::unique_lock<std::mutex> lock(mtx);
        for (const auto& entry : logEntries) {
            std::cout << "Timestamp: " << entry->timestamp << ", Log Level: " << entry->logLevel << ", Message: " << *entry->message << std::endl;
        }
    }

    void printLogLevels() {
        std::unique_lock<std::mutex> lock(mtx);
        for (const auto& level : logLevels) {
            std::cout << "Log Level: " << level.first << ", Message: " << *level.second->message << std::endl;
        }
    }

    void printStatistics() {
        std::unique_lock<std::mutex> lock(mtx);
        int totalSize = 0;
        int count = 0;
        for (const auto& entry : logEntries) {
