// Define a structure for metric sample data
typedef struct {
    time_t timestamp;
    char* metric_name;
    double* value;
} MetricSample;

// Function to initialize circular buffer of MetricSample structures
MetricSample** init_circular_buffer(int capacity) {
    MetricSample** buffer = (MetricSample**)malloc(sizeof(MetricSample*) * capacity);
    for (int i = 0; i < capacity; i++) {
        buffer[i] = (MetricSample*)malloc(sizeof(MetricSample));
        buffer[i]->timestamp = time(NULL);
        // dynamically allocate memory for value
        buffer[i]->value = (double*)malloc(sizeof(double));
    }
    return buffer;
}

// Function to insert a new sample into the circular buffer
void insert_sample(MetricSample** buffer, int capacity, MetricSample* sample) {
    int idx = rand() % capacity;
    // shift existing samples
    for (int i = capacity - 1; i > idx; i--) {
        buffer[i] = buffer[i - 1];
    }
    buffer[idx] = sample;
}

// Function to compute aggregate statistics (min, max, avg)
void compute_aggregates(MetricSample** buffer, int capacity) {
    double min_val = DBL_MAX;
    double max_val = -DBL_MAX;
    double sum = 0.0;

    for (int i = 0; i < capacity; i++) {
        if (buffer[i]->value[0] > max_val)
            max_val = buffer[i]->value[0];
        if (buffer[i]->value[0] < min_val)
            min_val = buffer[i]->value[0];
        sum += buffer[i]->value[0];
    }
    double avg = sum / capacity;

    printf("Min: %f, Max: %f, Avg: %f\n", min_val, max_val, avg);
}

// Function to serialize the buffer to a compact binary format
void serialize_buffer(MetricSample** buffer, int capacity) {
    FILE* file = fopen("buffer.bin", "wb");
    for (int i = 0; i < capacity; i++) {
        fwrite(&buffer[i]->timestamp, sizeof(time_t), 1, file);
        fwrite(buffer[i]->metric_name, strlen(buffer[i]->metric_name) + 1, 1, file);
        fwrite(&buffer[i]->value[0], sizeof(double), 1, file);
    }
    fclose(file);
}

// Function to deserialize the buffer from a compact binary format
void deserialize_buffer(MetricSample** buffer, int capacity) {
    FILE* file = fopen("buffer.bin", "rb");
    for (int i = 0; i < capacity; i++) {
        fread(&buffer[i]->timestamp, sizeof(time_t), 1, file);
        // read metric name and dynamically allocate memory
        char* temp_name = (char*)malloc(strlen(buffer[i]->metric_name) + 1);
        fread(temp_name, strlen(buffer[i]->metric_name) + 1, 1, file);
        buffer[i]->metric_name = temp_name;
        fread(&buffer[i]->value[0], sizeof(double), 1, file);
    }
    fclose(file);
}

// Define a function to handle filtering by time range and metric name
void filter_metrics(MetricSample** buffer, int capacity) {
    // implement custom aggregation functions for different clients
}

int main() {
    int capacity = 1000000;
    MetricSample** buffer = init_circular_buffer(capacity);
    // add sample data to the buffer
    for (int i = 0; i < capacity; i++) {
        MetricSample* sample = (MetricSample*)malloc(sizeof(MetricSample));
        sample->timestamp = time(NULL);
        sample->value = (double*)malloc(sizeof(double));
        // insert the sample into the circular buffer
        insert_sample(buffer, capacity, sample);
    }
    // compute aggregate statistics for all metrics
    compute_aggregates(buffer, capacity);

    // serialize the buffer to a compact binary format
    serialize_buffer(buffer, capacity);

    // deserialize the buffer from the compact binary format
    MetricSample** deserialized_buffer = init_circular_buffer(capacity);
    deserialize_buffer(deserialized_buffer, capacity);

    return 0;
}
