// Define the Doubly-Linked List
typedef struct {
    DLLNode *head;
    DLLNode *tail;
    pthread_mutex_t lock;
    int size;
    time_t last_gc;
    int gc_interval;
} DLL;

// Function to initialize a new LogEntry structure and allocate memory for its message
LogEntry* log_entry_init(char *message) {
    LogEntry *entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = 1; // Assuming default log level is 1
    entry->message = strdup(message);
    return entry;
}

// Function to add a new LogEntry to the Doubly-Linked List
void dll_add(DLL *list, LogEntry *entry) {
    DLLNode *new_node = (DLLNode *)malloc(sizeof(DLLNode));
    new_node->log_entry = *entry;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head != NULL) {
        list->head->prev = &new_node->log_entry;
    } else {
        list->tail = &new_node->log_entry;
    }

    list->head = &new_node->log_entry;
    list->size++;
}

// Function to print all LogEntries in the Doubly-Linked List
void dll_print(DLL *list, int fd) {
    DLLNode *curr = list->head;
    while (curr != NULL) {
        printf("%lu %d %s\n", curr->log_entry.timestamp, curr->log_entry.level, curr->log_entry.message);
        curr = curr->next;
    }
}

// Function to free all memory allocated for the Doubly-Linked List
void dll_free(DLL *list) {
    DLLNode *curr = list->head;
    while (curr != NULL) {
        DLLNode *temp = curr;
        curr = curr->next;
        free(temp);
    }
    free(list);
}

// Function to serialize the Doubly-Linked List to a file
void dll_serialize(DLL *list, FILE *file) {
    fwrite(&list->size, sizeof(int), 1, file);
    DLLNode *curr = list->head;
    while (curr != NULL) {
        LogEntry entry = curr->log_entry;
        fwrite(&entry.timestamp, sizeof(time_t), 1, file);
        fwrite(&entry.level, sizeof(int), 1, file);
        size_t message_len = strlen(entry.message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(entry.message, sizeof(char), message_len, file);
        curr = curr->next;
    }
}

// Function to deserialize the Doubly-Linked List from a file
DLL* dll_deserialize(FILE *file) {
    DLL *list = (DLL *)malloc(sizeof(DLL));
    int size;
    fread(&size, sizeof(int), 1, file);
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    for (int i = 0; i < size; i++) {
        LogEntry entry;
        fread(&entry.timestamp, sizeof(time_t), 1, file);
        fread(&entry.level, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        char *message = (char *)malloc((message_len + 1) * sizeof(char));
        fread(message, sizeof(char), message_len, file);
        message[message_len] = '\0';
        entry.message = message;
        dll_add(list, &entry);
    }
    return list;
}

// Function to implement a garbage collection mechanism
void dll_gc(DLL *list) {
    // Implement the garbage collection logic here
}

int main() {
    // Initialize the Doubly-Linked List
    DLL *list = (DLL *)malloc(sizeof(DLL));
    pthread_mutex_init(&list->lock, NULL);

    // Add log entries to the list
    for (int i = 0; i < 10; i++) {
        LogEntry entry;
        entry.timestamp = time(NULL);
        entry.level = 1;
        char *message = (char *)malloc(100 * sizeof(char));
        sprintf(message, "This is log entry %d", i);
        dll_add(list, &entry);
    }

