['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// LogEntry structure definition
typedef struct {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Doubly-linked list node definition
typedef struct Node {
    LogEntry entry;
    struct Node* prev;
    struct Node* next;
} Node;

// Doubly-linked list definition
typedef struct {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int garbageCollectionInterval; // in seconds
} LinkedList;

// Function to initialize the doubly-linked list
LinkedList* initLinkedList(int garbageCollectionInterval) {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    list->garbageCollectionInterval = garbageCollectionInterval;
    return list;
}

// Function to free the doubly-linked list
void freeLinkedList(LinkedList* list) {
    Node* current = list->head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

// Function to print log entries from the list
void printLogEntries(LinkedList* list, int startTimestamp, int endTimestamp, int logLevel) {
    Node* current = list->head;
    while (current != NULL) {
        if ((startTimestamp <= current->entry.timestamp && current->entry.timestamp <= endTimestamp) &&
            (logLevel == -1 || current->entry.logLevel == logLevel)) {
            printf("%ld %d %s\n", current->entry.timestamp, current->entry.logLevel, current->entry.message);
        }
        current = current->next;
    }
}

// Function to add a new log entry to the list
void addLogEntry(LinkedList* list, time_t timestamp, int logLevel, char* message) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->entry.timestamp = timestamp;
    newNode->entry.logLevel = logLevel;
    newNode->entry.message = message;
    newNode->prev = NULL;
    newNode->next = list->head;
    if (list->head != NULL) {
        list->head->prev = newNode;
    } else {
        list->tail = newNode;
    }
    list->head = newNode;

    // Trigger garbage collection
    pthread_mutex_lock(&list->mutex);
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

// Function to periodically reclaim unused memory in the list
void garbageCollect(LinkedList* list) {
    Node* current = list->tail;
    while (current != NULL) {
        if ((time(NULL) - current->entry.timestamp) > list->garbageCollectionInterval * 60) { // 1 minute interval
            Node* next = current->next;
            free(current);
            current = next;
        } else {
            break;
        }
    }
}

// Function to load the log history from a file
void loadLogHistory(LinkedList* list, FILE* file) {
    char buffer[1024];
    while (fread(buffer, 1, 1024, file) > 0) {
        LogEntry entry;
        sscanf(buffer, "%ld %d %s", &entry.timestamp, &entry.logLevel, &entry.message);
        addLogEntry(list, entry.timestamp, entry.logLevel, strdup(entry.message));
    }
}

// Function to save the log history to a file
void saveLogHistory(LinkedList* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "%ld %d %s\n", current->entry.timestamp, current->entry.logLevel, current->entry.message);
        free(current->entry.message);
        current = current->next;
    }
}

// Function to get statistics about the log entries
void getStatistics(LinkedList* list) {
    int numEntries = 0;
    long totalSize = 0;
    int averageMessageLength = 0;
    Node* current = list->head;
    while (current != NULL) {
        numEntries++;
        totalSize += strlen(current->entry.message);
        averageMessageLength += strlen(current->entry.message);
        current = current->next;
    }
    printf("Number of log entries: %d\n", numEntries);
    printf("Total size of log data in bytes: %ld\n", totalSize);
    printf("Average message length: %d\n", averageMessageLength / numEntries);
}
