#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

typedef struct LoggingSystem {
    LogEntry* head;
    LogEntry* tail;
    pthread_mutex_t lock;
    size_t allocatedMemory;
    size_t garbageThreshold;
    pthread_cond_t gcCondition;
    pthread_t gcThread;
} LoggingSystem;

void initLoggingSystem(LoggingSystem* loggingSystem, size_t initialCapacity) {
    loggingSystem->head = NULL;
    loggingSystem->tail = NULL;
    pthread_mutex_init(&loggingSystem->lock, NULL);
    loggingSystem->allocatedMemory = 0;
    loggingSystem->garbageThreshold = initialCapacity * sizeof(LogEntry);
}

void addLogEntry(LoggingSystem* loggingSystem, LogEntry* entry) {
    pthread_mutex_lock(&loggingSystem->lock);

    if (loggingSystem->tail == NULL) {
        loggingSystem->head = entry;
        loggingSystem->tail = entry;
    } else {
        entry->next = NULL;
        entry->prev = loggingSystem->tail;
        loggingSystem->tail->next = entry;
        loggingSystem->tail = entry;
    }

    pthread_mutex_unlock(&loggingSystem->lock);
}

void printLogEntries(LoggingSystem* loggingSystem, int fd) {
    LogEntry* current = loggingSystem->head;
    while (current != NULL) {
        write(fd, &(current->message), strlen(current->message));
        current = current->next;
    }
}

void garbageCollect(LoggingSystem* loggingSystem) {
    pthread_mutex_lock(&loggingSystem->lock);

    if (loggingSystem->allocatedMemory > loggingSystem->garbageThreshold) {
        LogEntry* current = loggingSystem->head;
        while (current != NULL) {
            LogEntry* next = current->next;
            free(current->message);
            free(current);
            current = next;
        }
        loggingSystem->head = NULL;
        loggingSystem->tail = NULL;
        loggingSystem->allocatedMemory = 0;
    }

    pthread_mutex_unlock(&loggingSystem->lock);

    pthread_cond_signal(&loggingSystem->gcCondition);
}

void* gcThreadFunction(void* arg) {
    LoggingSystem* loggingSystem = (LoggingSystem*)arg;

    while (1) {
        pthread_mutex_lock(&loggingSystem->lock);
        pthread_cond_wait(&loggingSystem->gcCondition, &loggingSystem->lock);

        garbageCollect(loggingSystem);
        pthread_mutex_unlock(&loggingSystem->lock);
    }
}

int main() {
    LoggingSystem loggingSystem;
    initLoggingSystem(&loggingSystem, 1000);

    // Add log entries
    addLogEntry(&loggingSystem, ...);

    // Print log entries
    printLogEntries(&loggingSystem, fd);

    return 0;
}
