// Define the structure for LogEntry
typedef struct {
    int timestamp;
    int level;
    char* message;
} LogEntry;

// Define the structure for DoublyLinkedList
typedef struct node {
    LogEntry* data;
    struct node* next;
    struct node* prev;
} Node;

// Function to initialize the linked list
Node* create_list(int size) {
    // Initialize the head and tail of the list
    Node* head = NULL;
    Node* tail = NULL;

    // Allocate memory for each LogEntry and link them together
    for (int i = 0; i < size; i++) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        entry->timestamp = i;
        entry->level = i % 2;
        char* message = (char*)malloc((i + 1) * sizeof(char));
        strcpy(message, "Message ");
        sprintf(message + strlen(message), "%d", i);
        entry->message = message;
        if (head == NULL) {
            head = (Node*)malloc(sizeof(Node));
            tail = head;
        } else {
            Node* new_node = (Node*)malloc(sizeof(Node));
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    return head;
}

// Function to free the linked list
void free_list(Node* head) {
    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Function to print the log entries to a file descriptor
void print_log(Node* head, int fd) {
    while (head != NULL) {
        LogEntry* entry = head->data;
        write(fd, &entry->timestamp, sizeof(int));
        write(fd, &entry->level, sizeof(int));
        size_t len = strlen(entry->message);
        write(fd, &len, sizeof(size_t));
        write(fd, entry->message, len);
        head = head->next;
    }
}

// Function to serialize the log entries to a file
void serialize_log(Node* head, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;

    Node* current = head;
    while (current != NULL) {
        LogEntry* entry = current->data;
        fwrite(&entry->timestamp, sizeof(int), 1, file);
        fwrite(&entry->level, sizeof(int), 1, file);
        size_t len = strlen(entry->message);
        fwrite(&len, sizeof(size_t), 1, file);
        fwrite(entry->message, len, 1, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize the log entries from a file
Node* deserialize_log(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return NULL;

    Node* head = NULL;
    Node* tail = NULL;
    LogEntry* entry;
    while (fread(&entry->timestamp, sizeof(int), 1, file) == 1 &&
           fread(&entry->level, sizeof(int), 1, file) == 1 &&
           fread(&len, sizeof(size_t), 1, file) == 1) {
        entry->message = (char*)malloc((len + 1) * sizeof(char));
        fread(entry->message, len, 1, file);
        entry->message[len] = '\0';

        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data = entry;
        if (head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }
    }

    fclose(file);
    return head;
}
