    int logLevel;
    char* message;
};

class Logger {
public:
    // Initialize the logger with a specified file path and size limit
    void initialize(const std::string& filePath, size_t fileSizeLimit) {
        // Create a file lock to ensure exclusive access to the file
        fileLock = std::lock_guard<std::mutex>(fileMutex);
        logFile.open(filePath, std::ios_base::app | std::ios_base::binary);

        if (!logFile) {
            throw std::runtime_error("Failed to open log file: " + filePath);
        }

        // Set the file size limit
        fileSizeLimit_ = fileSizeLimit;
    }

    // Log an entry with a given timestamp, log level, and message
    void logEntry(const std::time_t& timestamp, int logLevel, const char* message) {
        // Create a new log entry
        LogEntry entry;
        entry.timestamp = timestamp;
        entry.logLevel = logLevel;
        entry.message = strdup(message);

        // Acquire the file lock to ensure exclusive access to the file
        fileLock = std::lock_guard<std::mutex>(fileMutex);

        // Write the log entry to the file
        logFile.write(reinterpret_cast<const char*>(&entry), sizeof(LogEntry));
    }

    // Flush the log entries and close the file
    void flushAndClose() {
        // Acquire the file lock to ensure exclusive access to the file
        fileLock = std::lock_guard<std::mutex>(fileMutex);

        // Flush the log entries and close the file
        logFile.flush();
        logFile.close();

        // Release any outstanding locks
        fileLock.unlock();
    }

private:
    std::mutex fileMutex;
    std::lock_guard<std::mutex> fileLock;
    std::ofstream logFile;
    size_t fileSizeLimit_;
};

// Define a function to calculate the MD5 and SHA-256 hashes of files up to 8 GB in size
std::map<std::string, std::pair<std::string, std::string>> calculateHashes(const std::vector<std::string>& filePaths) {
    std::map<std::string, std::pair<std::string, std::string>> fileHashes;

    for (const auto& filePath : filePaths) {
        // Open the file and check if it exists
        std::ifstream file(filePath);
        if (!file) {
            fileHashes[filePath] = {"", ""};
            continue;
        }

        // Calculate the MD5 hash of the file
        std::string md5Hash;
        {
            std::hash<std::uint8_t> hasher;
            size_t fileSize = 0;
            std::uint8_t buffer[1024];

            while (file.read(reinterpret_cast<char*>(buffer), sizeof(buffer))) {
                for (size_t i = 0; i < sizeof(buffer); ++i) {
                    size_t bytesToRead = sizeof(buffer) - i;
                    if (bytesToRead > file.gcount()) {
                        bytesToRead = file.gcount();
                    }

                    std::memcpy(&hasher, buffer + i, bytesToRead);
                    fileSize += bytesToRead;
                }
            }

            // Calculate the MD5 hash
            std::string md5Buffer(32, '\0');
            for (size_t i = 0; i < 16; ++i) {
                std::memcpy(&md5Buffer[i * 2], &hasher, sizeof(hasher));
            }
            md5Hash = md5Buffer;
        }

        // Calculate the SHA-256 hash of the file
        std::string sha256Hash;
        {
            std::sha256 hash;
            size_t fileSize = 0;

            while (file.read(reinterpret_cast<char*>(buffer), sizeof(buffer))) {
                for (size_t i = 0; i < sizeof(buffer); ++i) {
                    size_t bytesToRead = sizeof(buffer) - i;
                    if (bytesToRead > file.gcount()) {
                        bytesToRead = file.gcount();
                    }

                    std::memcpy(&hash, buffer + i, bytesToRead);
                    fileSize += bytesToRead;
                }
            }

            // Calculate the SHA-256 hash
            std::string sha256Buffer(64, '\0');
            for (size_t i = 0; i < 32; ++i) {
                std::memcpy(&sha256Buffer[i * 2], &hash, sizeof(hash));
            }
            sha256Hash = sha256Buffer;
        }

        fileHashes[filePath] = {md5Hash, sha256Hash};
    }

    return fileHashes;
}

int main() {
    try {
        // Initialize the logger with a specified file path and size limit
        Logger logger("log.txt", 10000000);

        // Log an entry with a given timestamp, log level, and message
        std::time_t timestamp = std::time(nullptr);
        int logLevel = 1;
        const char* message = "This is a test log entry.";
        logger.logEntry(timestamp, logLevel, message);

        // Flush the log entries and close the file
        logger.flushAndClose();

        // Calculate the MD5 and SHA-256 hashes of files up to 8 GB in size
        std::vector<std::string> filePaths = {"file1.txt", "file2.txt"};
        std::map<std::string, std::pair<std::string, std::string>> fileHashes = calculateHashes(filePaths);

        // Print the MD5 and SHA-256 hashes of each file
        for (const auto& entry : fileHashes) {
            std::cout << "File: " << entry.first << ", MD5 Hash: " << entry.second.first << ", SHA-256 Hash: " << entry.second.second << std::endl;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}

