#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>

// Define structure for log entry
typedef struct {
    time_t timestamp;
    int level;
    char* message;
} LogEntry;

// Define data structure to hold log entries
typedef struct {
    int size;
    LogEntry** entries;
} LogDatabase;

// Initialize log database with given capacity
LogDatabase* init_log_database(int capacity) {
    LogDatabase* db = (LogDatabase*)malloc(sizeof(LogDatabase));
    db->size = 0;
    db->entries = (LogEntry**)calloc(capacity, sizeof(LogEntry*));
    return db;
}

// Insert new log entry into database with synchronization
void insert_log_entry(LogDatabase* db, int level, const char* message) {
    pthread_mutex_lock(&db->mutex);

    // Dynamically allocate memory for new log entry
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);

    // Insert entry into database, expanding if necessary
    if (db->size == db->entries->size) {
        db->entries = (LogEntry**)realloc(db->entries, 2 * (db->size + 1) * sizeof(LogEntry*));
    }
    db->entries[db->size] = entry;
    db->size++;

    pthread_mutex_unlock(&db->mutex);
}

// Delete log entry from database with synchronization
void delete_log_entry(LogDatabase* db, int index) {
    pthread_mutex_lock(&db->mutex);

    // Check if the given index is valid
    if (index >= 0 && index < db->size) {
        LogEntry* to_delete = db->entries[index];
        free(to_delete->message);
        free(to_delete);
        memmove(db->entries + index, db->entries + index + 1, (db->size - index - 1) * sizeof(LogEntry*));
    }

    pthread_mutex_unlock(&db->mutex);
}

// Serialize log entries into binary format
void serialize_log_entries(LogDatabase* db, FILE* file) {
    fwrite(&db->size, sizeof(int), 1, file);
    for (int i = 0; i < db->size; i++) {
        LogEntry* entry = db->entries[i];
        fwrite(&entry->timestamp, sizeof(time_t), 1, file);
        fwrite(&entry->level, sizeof(int), 1, file);
        size_t message_len = strlen(entry->message);
        fwrite(&message_len, sizeof(size_t), 1, file);
        fwrite(entry->message, 1, message_len + 1, file);
    }
}

// Deserialize log entries from binary format
void deserialize_log_entries(LogDatabase* db, FILE* file) {
    int size;
    fread(&size, sizeof(int), 1, file);

    for (int i = 0; i < size; i++) {
        LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
        fread(&entry->timestamp, sizeof(time_t), 1, file);
        fread(&entry->level, sizeof(int), 1, file);
        size_t message_len;
        fread(&message_len, sizeof(size_t), 1, file);
        entry->message = (char*)malloc(message_len + 1);
        fread(entry->message, 1, message_len + 1, file);

        db->entries[db->size] = entry;
        db->size++;
    }
}

// Garbage collection mechanism
void garbage_collect(LogDatabase* db) {
    for (int i = 0; i < db->size; i++) {
        LogEntry* entry = db->entries[i];
        if (entry->message && strlen(entry->message) == 0) {
            free(entry->message);
            free(entry);
            memmove(db->entries + i, db->entries + i + 1, (db->size - i - 1) * sizeof(LogEntry*));
            db->size--;
        }
    }
}

// Statistics for log data
void print_statistics(LogDatabase* db) {
    printf("Number of entries: %d\n", db->size);
    printf("Total size: %zu bytes\n", (size_t)(db->size * (sizeof(LogEntry*) + sizeof(time_t) + sizeof(int) + (size_t)strlen(db->entries[0]->message))));
    printf("Average message length: %.2f bytes\n", (double)strlen(db->entries[0]->message) / db->size);
}

int main() {
    // Initialize log database with capacity 1000000
    LogDatabase* db = init_log_database(1000000);

    // Thread-safe operations for concurrent read and write access
    pthread_mutex_init(&db->mutex, NULL);

    // Insert log entries
    insert_log_entry(db, LOG_INFO, "Initial message");
    insert_log_entry(db, LOG_ERROR, "Error message");
    garbage_collect(db);
    print_statistics(db);

    return 0;
}

