void validate_timestamps() {
    for (int i = 0; i < num_sessions; i++) {
        NetworkSession* session = &sessions[i];
        pthread_mutex_lock(&session->transaction_lock);
        for (int j = 0; j < session->num_transactions; j++) {
            Transaction* transaction = session->transactions[j];
            if (transaction->timestamp < MIN_TIMESTAMP || transaction->timestamp > MAX_TIMESTAMP) {
                printf("Invalid timestamp found in session %d\n", i);
                exit(1);
            }
        }
        pthread_mutex_unlock(&session->transaction_lock);
    }
}

void finalize_transactions() {
    for (int i = 0; i < num_sessions; i++) {
        NetworkSession* session = &sessions[i];
        pthread_mutex_lock(&session->transaction_lock);
        int finalized_transactions = 0;
        for (int j = 0; j < session->num_transactions; j++) {
            Transaction* transaction = session->transactions[j];
            if (transaction->status == UNFINALIZED_TRANSACTION_STATUS) {
                printf("Transaction %d in session %d has not been finalized\n", transaction->transaction_id, i);
                exit(1);
            }
            finalized_transactions++;
        }
        if (finalized_transactions < session->num_transactions) {
            printf("Not all transactions have been finalized in session %d\n", i);
            exit(1);
        }
        pthread_mutex_unlock(&session->transaction_lock);
    }
}

void cleanup_stale_sessions() {
    pthread_mutex_lock(&cleanup_lock);
    for (int i = 0; i < num_sessions; i++) {
        NetworkSession* session = &sessions[i];
        if (time(NULL) - sessions[i].last_activity_time > 3600 * 2) { // 2 hours
            printf("Removing stale session %d\n", i);
            for (int j = 0; j < session->num_transactions; j++) {
                Transaction* transaction = session->transactions[j];
                free(transaction);
            }
            free(session);
        }
    }
    num_sessions = 0;
    pthread_mutex_unlock(&cleanup_lock);
}

void query_session_stats() {
    int total_sessions = num_sessions;
    int total_unfinalized_transactions = 0;
    long total_duration = 0;
    for (int i = 0; i < num_sessions; i++) {
        NetworkSession* session = &sessions[i];
        pthread_mutex_lock(&session->transaction_lock);
        int unfinalized_transactions = 0;
        long duration = 0;
        for (int j = 0; j < session->num_transactions; j++) {
            Transaction* transaction = session->transactions[j];
            if (transaction->status == UNFINALIZED_TRANSACTION_STATUS) {
                unfinalized_transactions++;
            }
            duration += time(NULL) - transaction->timestamp;
        }
        pthread_mutex_unlock(&session->transaction_lock);
        total_unfinalized_transactions += unfinalized_transactions;
        total_duration += duration;
    }
    printf("Total sessions: %d\n", total_sessions);
    printf("Unfinalized transactions: %d\n", total_unfinalized_transactions);
