#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    char srcIP[16];
    char destIP[16];
    int protocol;
    int size;
    int seqNum;
} NetworkPacket;

typedef struct {
    NetworkPacket* packets;
    int capacity;
    int used;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} CircularBuffer;

CircularBuffer* bufferCreate(int capacity) {
    CircularBuffer* buffer = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    buffer->packets = (NetworkPacket*)malloc(capacity * sizeof(NetworkPacket));
    buffer->capacity = capacity;
    buffer->used = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
    pthread_cond_init(&buffer->cond, NULL);
    return buffer;
}

void bufferDestroy(CircularBuffer* buffer) {
    if (buffer == NULL)
        return;

    free(buffer->packets);
    pthread_mutex_destroy(&buffer->mutex);
    pthread_cond_destroy(&buffer->cond);
    free(buffer);
}

NetworkPacket* bufferFront(CircularBuffer* buffer) {
    NetworkPacket* front = NULL;
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->used > 0) {
        front = &buffer->packets[0];
    }
    pthread_mutex_unlock(&buffer->mutex);
    return front;
}

void bufferAdd(CircularBuffer* buffer, NetworkPacket* packet) {
    pthread_mutex_lock(&buffer->mutex);
    int tail = (buffer->used + 1) % buffer->capacity;
    if (tail == 0)
        buffer->packets[tail] = *packet;
    else
        buffer->packets[tail - 1] = *packet;
    buffer->used++;
    pthread_mutex_unlock(&buffer->mutex);
}

void bufferRemove(CircularBuffer* buffer) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->used > 0) {
        int head = 0;
        NetworkPacket* packet = &buffer->packets[head];
        buffer->packets[head] = *packet; // Move the first element to the end
        buffer->used--;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

int main() {
    CircularBuffer* buffer = bufferCreate(10);

    // Add some packets
    NetworkPacket packet1 = {1, "192.168.1.1", "192.168.2.2", 6, 100, 1};
    NetworkPacket packet2 = {2, "192.168.3.3", "192.168.4.4", 17, 50, 2};

    bufferAdd(buffer, &packet1);
    bufferAdd(buffer, &packet2);

    // Remove some packets
    bufferRemove(buffer);

    return 0;
}
