#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>

// Define a struct to represent a log entry
typedef struct {
    time_t timestamp;
    int level; // Log level (e.g., 0 for debug, 1 for info, etc.)
    char* message;
} LogEntry;

// Define a struct to represent the log management system
typedef struct {
    pthread_mutex_t lock; // Read-write lock for concurrent access
    size_t capacity; // Capacity of the log entries array
    size_t size; // Current number of log entries
    LogEntry** entries; // Array of log entries
} LogManager;

// Initialize the log management system
void initializeLogManager(LogManager* manager, size_t initialCapacity) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = initialCapacity;
    manager->size = 0;
    manager->entries = (LogEntry**)malloc(initialCapacity * sizeof(LogEntry*));
}

// Add a new log entry to the system
void addLogEntry(LogManager* manager, int level, const char* message) {
    pthread_mutex_lock(&manager->lock);

    // Dynamically allocate memory for the log entry
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->level = level;
    entry->message = strdup(message);

    // Insert the log entry at the end of the array
    if (manager->size >= manager->capacity) {
        size_t newSize = manager->capacity * 2; // Double the capacity
        LogEntry** newEntries = (LogEntry**)realloc(manager->entries, newSize * sizeof(LogEntry*));
        for (size_t i = manager->size; i < newSize; i++) {
            newEntries[i] = NULL;
        }
        manager->entries = newEntries;
        manager->capacity = newSize;
    }
    manager->entries[manager->size++] = entry;

    pthread_mutex_unlock(&manager->lock);
}

// Serialize a log entry to a binary format
