#include <iostream>
#include <unordered_map>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>

class Cache {
public:
    Cache(size_t capacity) : capacity_(capacity), size_(0) {}

    void insert(const std::string& key, const std::string& value, time_t expiration) {
        // Synchronize access to the cache
        std::unique_lock<std::mutex> lock(mutex_);
        while (size_ >= capacity_) {
            // Wait until a spot becomes available
            cond_.wait(lock);
        }

        auto it = entries_.emplace(key, Entry{value, expiration});
        if (!it.second) {
            // Update the existing entry's timestamp and value
            it.first->second = {value, expiration};
        } else {
            ++size_;
        }

        // Check for expired entries
        if (auto it = entries_.begin(); it != entries_.end()) {
            if (it->second.expiration <= std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::seconds>(0))) {
                entries_.erase(it);
                --size_;
            }
        }

        lock.unlock();
    }

    void remove(const std::string& key) {
        // Synchronize access to the cache
        std::unique_lock<std::mutex> lock(mutex_);

        auto it = entries_.find(key);
        if (it != entries_.end()) {
            size_--;
            entries_.erase(it);
        }
    }

    void get(const std::string& key, const callback& cb) {
        // Synchronize access to the cache
        std::unique_lock<std::mutex> lock(mutex_);

        auto it = entries_.find(key);
        if (it != entries_.end()) {
            // Check for expired entries
            if (it->second.expiration <= std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::seconds>(0))) {
                entries_.erase(it);
                --size_;
            } else {
                cb(it->first, it->second.value);
            }
        } else {
            cb(key, "");
        }
    }

private:
    struct Entry {
        std::string value;
        time_t expiration;
    };

    std::unordered_map<std::string, Entry> entries_;
    size_t capacity_;
    size_t size_;
    std::mutex mutex_;
    std::condition_variable cond_;
};

int main() {
    // Create a cache with a capacity of 10 million
    Cache cache(10000000);

    // Insert some sample data
    cache.insert("key1", "value1", std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::seconds>(60)));
    cache.insert("key2", "value2", std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::seconds>(120)));
    cache.insert("key3", "value3", std::chrono::time_point<std::chrono::system_clock>(std::chrono::duration_cast<std::chrono::seconds>(60)));

    // Retrieve some sample data
    cache.get("key1", [](const std::string& key, const std::string& value) {
        std::cout << "Retrieved: " << key << ": " << value << std::endl;
    });

    return 0;
}
