#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to hold log entry information
typedef struct LogEntry {
    time_t timestamp;
    int logLevel;
    char* message;
} LogEntry;

// Define a linked list node structure
typedef struct Node {
    LogEntry* data;
    struct Node* next;
} Node;

// Function prototypes
void initLogList(Node** head, FILE* outputFD);
void insertLogEntry(Node** head, int logLevel, const char* message);
void removeLogEntry(Node** head);
void printLogEntries(Node* head, FILE* outputFD);
void destroyLogList(Node** head);

int main() {
    Node* head = NULL;
    FILE* outputFD = fopen("log_file.txt", "w");
    initLogList(&head, outputFD);

    // Example usage: insert log entries
    insertLogEntry(&head, 1, "Error: This is an error message.");
    insertLogEntry(&head, 2, "Warning: This is a warning message.");
    insertLogEntry(&head, 3, "Info: This is an information message.");

    // Example usage: print log entries
    printLogEntries(head, outputFD);

    // Example usage: remove log entry
    removeLogEntry(&head);

    // Example usage: destroy log list
    destroyLogList(&head);

    return 0;
}

void initLogList(Node** head, FILE* outputFD) {
    *head = NULL;
    pthread_mutex_init(&mutex, NULL); // Initialize the mutex for thread safety
    setvbuf(outputFD, NULL, _IOLBF, BUFSIZ); // Set up the file descriptor for concurrent access
}

void insertLogEntry(Node** head, int logLevel, const char* message) {
    LogEntry* entry = malloc(sizeof(LogEntry)); // Allocate memory for the new log entry
    if (entry == NULL) {
        fprintf(stderr, "Error allocating memory.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex); // Lock the mutex to ensure thread safety

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        free(entry);
        fprintf(stderr, "Error allocating node memory.\n");
        exit(EXIT_FAILURE);
    }

    newNode->data = entry;
    newNode->next = *head;
    *head = newNode; // Insert the new log entry at the head of the list

    pthread_mutex_unlock(&mutex); // Unlock the mutex to allow other threads access
}

void removeLogEntry(Node** head) {
    Node* current = *head;
    Node* previous = NULL;

    while (current != NULL) {
        previous = current;
        current = current->next;
    }

    free(previous->data);
    free(previous); // Free the memory associated with the removed log entry
}

void printLogEntries(Node* head, FILE* outputFD) {
    Node* current = head;

    while (current != NULL) {
        fwrite(current->data->message, sizeof(char), strlen(current->data->message), outputFD);
        free(current->data->message); // Free the memory associated with each log entry
        current = current->next;
    }
}

void destroyLogList(Node** head) {
    Node* current = *head;
    Node* next;

    while (current != NULL) {
        next = current->next;
        free(current->data->message); // Free the memory associated with each log entry
        free(current->data);
        free(current);
        current = next;
    }

    *head = NULL; // Set the head to null after destroying the list
}
