HashTable* init_hash_table(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->entries = (CacheEntry**)malloc(capacity * sizeof(CacheEntry*));
    for (int i = 0; i < capacity; i++) {
        table->entries[i] = NULL;
    }
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to free the resources used by a hash table
void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]->file->data);
            free(table->entries[i]->file);
            free(table->entries[i]);
        }
    }
    free(table->entries);
    pthread_mutex_destroy(&table->mutex);
    free(table);
