        fwrite(head->entry.message, strlen(head->entry.message) + 1, 1, fd);

        head = head->next;
    }
}

// Function to insert a new node at the beginning of the list
void insert_node(Node** head_ref, Node* node) {
    if (*head_ref == NULL || node->entry.timestamp < (*head_ref)->entry.timestamp) {
        node->prev = *head_ref;
        node->next = (*head_ref)->next;
        (*head_ref)->next = node;
        if (node->prev != NULL)
            node->prev->next = node;

        *head_ref = node;
    } else {
        Node* current = *head_ref;
        while (current->next != NULL && current->entry.timestamp <= node->entry.timestamp) {
            current = current->next;
        }

        if (node->entry.timestamp < current->entry.timestamp)
            current->prev->next = node;
        else
            current->next->prev = node;

        node->next = current->next;
        node->prev = current;
        current->next = node;
    }
}

// Function to delete a node from the list
void delete_node(Node** head_ref, Node* node) {
    if (node == *head_ref)
        *head_ref = (*head_ref)->next;

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        *head_ref = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
