    char name[MAX_KEY_LENGTH];
    int section_num;
    Setting settings[MAX_SETTINGS_PER_SECTION];
} Section;

void* load_config_file(void* arg);
void* update_config_file(void* arg);
void* delete_config_file(void* arg);
void* query_config_file(void* arg);

pthread_t threads[MAX_SECTIONS];

int main(int argc, char** argv) {
    // Initialize configuration file
    FILE *fp = fopen("config.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    // Create sections and settings
    Section* sections = (Section*)malloc(MAX_SECTIONS * sizeof(Section));
    Setting* settings = (Setting*)malloc(MAX_SETTINGS_PER_SECTION * sizeof(Setting));

    pthread_create(&threads[0], NULL, load_config_file, &sections);
    pthread_create(&threads[1], NULL, update_config_file, &settings);
    pthread_create(&threads[2], NULL, delete_config_file, &settings);
    pthread_create(&threads[3], NULL, query_config_file, &sections);

    // Wait for all threads to finish
    for (int i = 0; i < MAX_SECTIONS; i++) {
        pthread_join(threads[i], NULL);
    }

    free(sections);
    free(settings);
    fclose(fp);
}

