#include <iostream>
#include <fstream>
#include <mutex>
#include <thread>
#include <chrono>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

class LogEntry {
public:
    std::time_t timestamp;
    int logLevel;
    char* message;

    LogEntry(std::time_t ts, int level, const char* msg) : 
        timestamp(ts), logLevel(level), message(new char[strlen(msg) + 1]) {
        strcpy(message, msg);
    }

    ~LogEntry() { delete[] message; }
};

class LoggingSystem {
public:
    LoggingSystem(size_t maxEntriesPerFile = 1000000) : 
        maxEntriesPerFile(maxEntriesPerFile), entries(), files(), fileIndex(0), fileEntries(0) {}

    void log(LogEntry entry) {
        std::lock_guard<std::mutex> lock(mutex);
        if (entries.size() >= maxEntriesPerFile) {
            flush();
        }
        entries.push_back(entry);
    }

    void flush() {
        std::string filename = "log_" + std::to_string(fileIndex++) + ".bin";
        std::ofstream file(filename, std::ios::binary | std::ios::app);

        if (!file) {
            std::cerr << "Error writing to file: " << filename << std::endl;
            return;
        }

        for (const auto& entry : entries) {
            file.write(reinterpret_cast<char*>(&entry), sizeof(LogEntry));
        }

        entries.clear();
    }

private:
