```python
import subprocess
import json

def modify_kickstart_config(config_file, placeholders, actual_values):
    with open(config_file, 'r') as f:
        config = f.read()

    for placeholder, value in actual_values.items():
        if placeholder not in placeholders:
            raise ValueError(f"Placeholder '{placeholder}' is not found in the configuration file.")
        sed_command = f'sed -i "s|{placeholder}|{value}|" {config_file}'
        try:
            subprocess.run(sed_command.split(' '), check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f"Failed to replace placeholder '{placeholder}' with value '{value}'. Error: {e}")

    new_config = config
    password = 'encrypted_password'
    sed_command = f'sed -i "1a{password}" {config_file}'
    try:
        subprocess.run(sed_command.split(' '), check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to add the new line with encrypted password. Error: {e}")

    return new_config
